window.AZ104_BANK = {"sources": [{"test": 1, "questions": 90}, {"test": 2, "questions": 90}, {"test": 3, "questions": 88}, {"test": 4, "questions": 90}], "questions": [{"id": "T1-Q1", "test": 1, "num": 1, "domain": "compute", "stem": [{"p": "You manage an Azure App Service application called PortalApp."}, {"p": "The development team plans to publish updates to PortalApp using Web Deploy. They must be able to authenticate using their Microsoft Entra ID accounts when deploying the application."}, {"p": "The solution must follow the principle of least privilege and avoid granting excessive permissions."}, {"p": "Which action should you take?"}], "options": ["Grant the developers the Owner role on the web app.", "Set up application-level FTPS credentials.", "Configure user-specific FTPS credentials.", "Assign the Website Contributor role to the developers."], "correct": [3], "multi": false, "explanation": [{"p": "Assign the Website Contributor role to the developers is the correct answer here. The Website Contributor role provides the necessary permissions to manage the web app, including deploying content, without giving the developers excessive privileges such as those granted by the Owner role. This ensures the solution follows the principle of least privilege."}, {"p": "Grant the developers the Owner role on the web app is incorrect because the Owner role gives full control over the resource, including the ability to delete or modify access permissions, which violates the principle of least privilege."}, {"p": "Set up application-level FTPS credentials is incorrect  because using app-level credentials does not involve using Microsoft Entra credentials and does not follow the principle of least privilege."}, {"p": "Configure user-specific FTPS credentials is incorrect  because this does not involve using Microsoft Entra credentials and provides too much access for just deploying content."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#website-contributor"], "group": "G1"}, {"id": "T1-Q2", "test": 1, "num": 2, "domain": "storage", "stem": [{"p": "You have an Azure subscription named Meridian that contains several blob containers, organized as follows."}, {"p": "The storagenorth storage account contains:"}, {"p": "A container named archive, holding a blob named file1.dat"}, {"p": "A container named media, holding a blob named file2.dat"}, {"p": "The storagesouth storage account contains:"}, {"p": "A container named archive, holding a blob named file3.dat"}, {"p": "Two users, Priya and Sam, exist in the subscription. Both are currently assigned the Reader role at the Meridian subscription scope."}, {"p": "You define a condition named RuleAlpha. RuleAlpha is satisfied under either of the following circumstances: the requested operation is not a blob-read action, OR the target container is named archive."}, {"p": "You define a second condition named RuleBeta. RuleBeta is satisfied under either of the following circumstances: the requested operation is not a blob-write action, OR the blob's path contains the value 2."}, {"p": "You then assign roles as follows:"}, {"p": "Priya is granted the Storage Blob Data Reader role at the Meridian subscription scope, with RuleAlpha applied."}, {"p": "Sam is granted the Storage Blob Data Owner role at the storagenorth account scope, with RuleBeta applied."}, {"p": "True or False:"}, {"p": "\"Priya can read file2.dat.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because Priya is assigned the Storage Blob Data Reader role at the Meridian scope with RuleAlpha, which restricts access to the blobs unless certain conditions are met. RuleAlpha specifies that Priya can only read blobs within containers named archive. Since file2.dat is in container media, Priya cannot read it due to the condition restricting access to containers named archive."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/conditions-overview", "https://learn.microsoft.com/en-us/azure/role-based-access-control/conditions-format", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G2"}, {"id": "T1-Q3", "test": 1, "num": 3, "domain": "storage", "stem": [{"p": "You have an Azure subscription named Meridian that contains several blob containers, organized as follows."}, {"p": "The storagenorth storage account contains:"}, {"p": "A container named archive, holding a blob named file1.dat"}, {"p": "A container named media, holding a blob named file2.dat"}, {"p": "The storagesouth storage account contains:"}, {"p": "A container named archive, holding a blob named file3.dat"}, {"p": "Two users, Priya and Sam, exist in the subscription. Both are currently assigned the Reader role at the Meridian subscription scope."}, {"p": "You define a condition named RuleAlpha. RuleAlpha is satisfied under either of the following circumstances: the requested operation is not a blob-read action, OR the target container is named archive."}, {"p": "You define a second condition named RuleBeta. RuleBeta is satisfied under either of the following circumstances: the requested operation is not a blob-write action, OR the blob's path contains the value 2."}, {"p": "You then assign roles as follows:"}, {"p": "Priya is granted the Storage Blob Data Reader role at the Meridian subscription scope, with RuleAlpha applied."}, {"p": "Sam is granted the Storage Blob Data Owner role at the storagenorth account scope, with RuleBeta applied."}, {"p": "True or False:"}, {"p": "\"Priya can read file3.dat.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because, based on the conditions set in RuleAlpha, Priya is restricted from reading any blob outside of the archive container. Although file3.dat is in a different container (archive in storagesouth), the condition will allow Priya to access it. The condition in RuleAlpha only allows Priya to read blobs from the archive container in any storage account in that subscription."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/conditions-format"], "group": "G2"}, {"id": "T1-Q4", "test": 1, "num": 4, "domain": "storage", "stem": [{"p": "You have an Azure subscription named Meridian that contains several blob containers, organized as follows."}, {"p": "The storagenorth storage account contains:"}, {"p": "A container named archive, holding a blob named file1.dat"}, {"p": "A container named media, holding a blob named file2.dat"}, {"p": "The storagesouth storage account contains:"}, {"p": "A container named archive, holding a blob named file3.dat"}, {"p": "Two users, Priya and Sam, exist in the subscription. Both are currently assigned the Reader role at the Meridian subscription scope."}, {"p": "You define a condition named RuleAlpha. RuleAlpha is satisfied under either of the following circumstances: the requested operation is not a blob-read action, OR the target container is named archive."}, {"p": "You define a second condition named RuleBeta. RuleBeta is satisfied under either of the following circumstances: the requested operation is not a blob-write action, OR the blob's path contains the value 2."}, {"p": "You then assign roles as follows:"}, {"p": "Priya is granted the Storage Blob Data Reader role at the Meridian subscription scope, with RuleAlpha applied."}, {"p": "Sam is granted the Storage Blob Data Owner role at the storagenorth account scope, with RuleBeta applied."}, {"p": "True or False:"}, {"p": "\"Sam can read file1.dat.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct. Sam is assigned the Storage Blob Data Owner role at the storagenorth scope, which includes file1.dat and grants permissions to read and write blob data, subject to RuleBeta."}, {"p": "RuleBeta evaluates to true when either the requested action is not a blob write operation or the blob path contains the value 2. Because reading file1.dat is not a write operation, the first clause evaluates to true. Although file1.dat's path does not contain 2, the complete expression evaluates as true OR false, which is true."}, {"p": "Therefore, RuleBeta permits the read operation, and Sam can read file1.dat. The blob-path requirement would only restrict write operations, because for a write operation the first clause would evaluate to false."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/conditions-format"], "group": "G2"}, {"id": "T1-Q5", "test": 1, "num": 5, "domain": "network", "stem": [{"p": "You have two Azure virtual machines, each running a different operating system, with both private and public IP addresses assigned, and each connected to the same virtual network. One virtual machine has a DNS suffix configured in the operating system, while the other does not."}, {"img": "az104/img/t1_image1.webp"}, {"p": "You then create the following Azure DNS resources:"}, {"p": "A public DNS zone named northwind.com"}, {"p": "A private DNS zone named coldharbor.net"}, {"p": "You perform the following actions:"}, {"p": "For coldharbor.net, you create a virtual network link to vnetProd and enable automatic registration."}, {"p": "For northwind.com, you assign the Owner role to both coreapp1 and coreapp2."}, {"p": "True or False:"}, {"p": "\"The DNS A record for coreapp1 is created in northwind.com and resolves to the IP address 52.183.40.10.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct correct because the northwind.com zone is a public DNS zone, not a private DNS zone. Automatic registration for DNS records is supported only for private DNS zones when linked to virtual networks. Since northwind.com is a public DNS zone and automatic registration is not enabled for public zones, a DNS A record for coreapp1 will not be automatically added with its public IP address of 52.183.40.10."}, {"p": "Additionally, the assignment of the Owner role to coreapp1 and coreapp2 does not influence DNS auto registration, as that pertains to role-based access control (RBAC) and not DNS management."}], "refs": ["https://learn.microsoft.com/en-us/azure/dns/private-dns-autoregistration"], "group": "G3"}, {"id": "T1-Q6", "test": 1, "num": 6, "domain": "network", "stem": [{"p": "You have two Azure virtual machines, each running a different operating system, with both private and public IP addresses assigned, and each connected to the same virtual network. One virtual machine has a DNS suffix configured in the operating system, while the other does not."}, {"img": "az104/img/t1_image1.webp"}, {"p": "You then create the following Azure DNS resources:"}, {"p": "A public DNS zone named northwind.com"}, {"p": "A private DNS zone named coldharbor.net"}, {"p": "You perform the following actions:"}, {"p": "For coldharbor.net, you create a virtual network link to vnetProd and enable automatic registration."}, {"p": "For northwind.com, you assign the Owner role to both coreapp1 and coreapp2."}, {"p": "True or False:"}, {"p": "\"The DNS A record for coreapp1 is created in coldharbor.net and resolves to the IP address 10.1.0.4.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because coldharbor.net is a private DNS zone, and since auto-registration is enabled for vnetProd, the private IP address (10.1.0.4) of coreapp1 will be automatically added as an A record to the coldharbor.net private DNS zone. Auto-registration is supported for private DNS zones, and linking the virtual network ensures that virtual machines connected to the network can have their private IP addresses automatically registered in the private DNS zone."}], "refs": ["https://learn.microsoft.com/en-us/azure/dns/private-dns-autoregistration"], "group": "G3"}, {"id": "T1-Q7", "test": 1, "num": 7, "domain": "network", "stem": [{"p": "You have two Azure virtual machines, each running a different operating system, with both private and public IP addresses assigned, and each connected to the same virtual network. One virtual machine has a DNS suffix configured in the operating system, while the other does not."}, {"img": "az104/img/t1_image1.webp"}, {"p": "You then create the following Azure DNS resources:"}, {"p": "A public DNS zone named northwind.com"}, {"p": "A private DNS zone named coldharbor.net"}, {"p": "You perform the following actions:"}, {"p": "For coldharbor.net, you create a virtual network link to vnetProd and enable automatic registration."}, {"p": "For northwind.com, you assign the Owner role to both coreapp1 and coreapp2."}, {"p": "True or False:"}, {"p": "\"The DNS A record for coreapp2 is created in coldharbor.net and resolves to the IP address 10.1.0.5.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because coldharbor.net is an Azure Private DNS zone that is linked to vnetProd with automatic registration enabled. When automatic registration is enabled, Azure automatically creates DNS A records for all virtual machines connected to the linked virtual network."}, {"p": "coreapp2 is connected to vnetProd and has a private IP address of 10.1.0.5, so Azure automatically registers an A record for coreapp2.coldharbor.net that resolves to the private IP address."}, {"p": "The operating system type of coreapp2 and the absence of a DNS suffix configured inside the operating system do not affect Azure Private DNS auto-registration, as the registration is handled by the Azure platform."}, {"p": "The public DNS zone northwind.com and the assignment of the Owner role to the virtual machines are not relevant to Private DNS auto-registration and do not influence the creation of records in the coldharbor.net private DNS zone."}], "refs": ["https://learn.microsoft.com/en-us/azure/dns/private-dns-autoregistration"], "group": "G3"}, {"id": "T1-Q8", "test": 1, "num": 8, "domain": "identity", "stem": [{"p": "You have two Azure subscriptions named Falcon and Osprey. Falcon belongs to a management group named CorpMG. Osprey belongs to a management group named OpsMG."}, {"p": "The following resource groups exist:"}, {"p": "rg-falcon, in the Falcon subscription"}, {"p": "rg-osprey, in the Osprey subscription"}, {"p": "The following virtual machines are deployed:"}, {"p": "webVM, in rg-falcon"}, {"p": "dbVM, in rg-osprey"}, {"p": "cacheVM, in rg-osprey"}, {"p": "You assign roles to users as follows:"}, {"p": "Jordan is granted the Virtual Machine Contributor role at the CorpMG scope."}, {"p": "Jordan is granted the Virtual Machine User Login role at the Osprey subscription scope."}, {"p": "Taylor is granted the Virtual Machine Contributor role at the OpsMG scope."}, {"p": "Taylor is granted the Virtual Machine User Login role at the Falcon subscription scope."}, {"p": "Taylor is granted the Virtual Machine User Login role at the cacheVM scope."}, {"p": "True or False:"}, {"p": "\"Jordan can sign in to webVM.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because Jordan does not have the \"Virtual Machine User Login\" role assigned for webVM or at the scope of Falcon. While Jordan has the \"Virtual Machine Contributor\" role for management group CorpMG, which includes Falcon, the \"Virtual Machine Contributor\" role alone does not grant login permissions. The \"Virtual Machine User Login\" role is required to allow the user to sign in to the virtual machine, and this role is not assigned to Jordan for webVM, Falcon, or rg-falcon."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G4"}, {"id": "T1-Q9", "test": 1, "num": 9, "domain": "identity", "stem": [{"p": "You have two Azure subscriptions named Falcon and Osprey. Falcon belongs to a management group named CorpMG. Osprey belongs to a management group named OpsMG."}, {"p": "The following resource groups exist:"}, {"p": "rg-falcon, in the Falcon subscription"}, {"p": "rg-osprey, in the Osprey subscription"}, {"p": "The following virtual machines are deployed:"}, {"p": "webVM, in rg-falcon"}, {"p": "dbVM, in rg-osprey"}, {"p": "cacheVM, in rg-osprey"}, {"p": "You assign roles to users as follows:"}, {"p": "Jordan is granted the Virtual Machine Contributor role at the CorpMG scope."}, {"p": "Jordan is granted the Virtual Machine User Login role at the Osprey subscription scope."}, {"p": "Taylor is granted the Virtual Machine Contributor role at the OpsMG scope."}, {"p": "Taylor is granted the Virtual Machine User Login role at the Falcon subscription scope."}, {"p": "Taylor is granted the Virtual Machine User Login role at the cacheVM scope."}, {"p": "True or False:"}, {"p": "\"Taylor can manage disks and disk snapshots of webVM.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because Taylor has the \"Virtual Machine Contributor\" role assigned to management group OpsMG, which includes Osprey, but webVM is located in Falcon. Therefore, Taylor does not have the necessary permissions to manage the disks or disk snapshots for webVM. The \"Virtual Machine Contributor\" role assigned at OpsMG does not apply to resources in Falcon, including webVM. As a result, Taylor cannot manage disks or snapshots of webVM."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G4"}, {"id": "T1-Q10", "test": 1, "num": 10, "domain": "identity", "stem": [{"p": "You have two Azure subscriptions named Falcon and Osprey. Falcon belongs to a management group named CorpMG. Osprey belongs to a management group named OpsMG."}, {"p": "The following resource groups exist:"}, {"p": "rg-falcon, in the Falcon subscription"}, {"p": "rg-osprey, in the Osprey subscription"}, {"p": "The following virtual machines are deployed:"}, {"p": "webVM, in rg-falcon"}, {"p": "dbVM, in rg-osprey"}, {"p": "cacheVM, in rg-osprey"}, {"p": "You assign roles to users as follows:"}, {"p": "Jordan is granted the Virtual Machine Contributor role at the CorpMG scope."}, {"p": "Jordan is granted the Virtual Machine User Login role at the Osprey subscription scope."}, {"p": "Taylor is granted the Virtual Machine Contributor role at the OpsMG scope."}, {"p": "Taylor is granted the Virtual Machine User Login role at the Falcon subscription scope."}, {"p": "Taylor is granted the Virtual Machine User Login role at the cacheVM scope."}, {"p": "True or False:"}, {"p": "\"Taylor can manage disks and disk snapshots of cacheVM.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because the \"Virtual Machine Contributor\" role allows users to manage virtual machines and attached disks but does not grant permissions to manage disk snapshots. Managing disk snapshots requires specific permissions, such as those granted by the \"Disk Snapshot Contributor\" role. Since Taylor only has the \"Virtual Machine Contributor\" role, they can manage disks but cannot manage snapshots for cacheVM."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G4"}, {"id": "T1-Q11", "test": 1, "num": 11, "domain": "storage", "stem": [{"p": "You manage an Azure Storage account named dataarchive01, which contains a blob container called images. This container holds a a large collection of image files."}, {"p": "You plan to deploy an Azure Resource Manager (ARM) template to configure a blob inventory rule named inventoryRule1."}, {"p": "The configuration must ensure that a daily inventory report is generated in CSV format and stored in the images container. The report must include only those blobs whose names start with the prefix “finance”."}, {"p": "You need to complete the configuration of rule1, shown below."}, {"img": "az104/img/t1_image2.webp"}, {"p": "Which value should you choose for Code Segment A?"}], "options": ["appendBlob", "blockBlob", "pageBlob"], "correct": [1], "multi": false, "explanation": [{"p": "blockBlob is the correct answer. Block blobs are designed to store large amounts of unstructured data, such as images or backups, which is the use case described here with thousands of image files. Additionally, block blobs are more suitable for use cases where data needs to be frequently accessed, stored, or replaced (such as in a daily CSV file). This fits the requirements for the blob inventory rule where you need to filter blobs whose names start with \"finance.\""}, {"p": "appendBlob is incorrect because it is generally used for log data where the need is to continuously append new data. It is not optimized for image storage or daily CSV storage."}, {"p": "pageBlob is incorrect because page blobs are typically used for storing virtual hard disks (VHDs) for Azure virtual machines, not for storing images or daily CSV files."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction", "https://learn.microsoft.com/en-us/rest/api/storageservices/understanding-block-blobs--append-blobs--and-page-blobs"], "group": "G5"}, {"id": "T1-Q12", "test": 1, "num": 12, "domain": "storage", "stem": [{"p": "You manage an Azure Storage account named dataarchive01, which contains a blob container called images. This container holds a a large collection of image files."}, {"p": "You plan to deploy an Azure Resource Manager (ARM) template to configure a blob inventory rule named inventoryRule1."}, {"p": "The configuration must ensure that a daily inventory report is generated in CSV format and stored in the images container. The report must include only those blobs whose names start with the prefix “finance”."}, {"p": "You need to complete the configuration of rule1, shown below."}, {"img": "az104/img/t1_image2.webp"}, {"p": "Which value should you choose for Code Segment B?"}], "options": ["images/*", "images/finance", "finance"], "correct": [1], "multi": false, "explanation": [{"p": "images/finance is the correct answer. According to the documentation, the prefix match string in a blob policy must always start with the container name followed by the desired blob name prefix. In this case, \"images\" is the container, and \"finance\" is the required blob prefix, making images/finance the appropriate match string for blobs starting with the word \"finance.\""}, {"img": "az104/img/t1_image3.webp"}, {"p": "images/* is incorrect because it would match all blobs within the container and not only those starting with \"finance.\""}, {"p": "finance is incorrect because it does not include the container name as required by the blob policy format."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blob-faq#the-blob-prefix-match-string-didn-t-apply-the-policy-to-the-expected-blobs"], "group": "G5"}, {"id": "T1-Q13", "test": 1, "num": 13, "domain": "storage", "stem": [{"p": "You manage an Azure Storage account called mediafiles01 that contains a collection of image blobs."}, {"p": "You plan to provision an additional storage account and configure object replication to copy the existing images from mediafiles01 to the new account."}, {"p": "After creating and configuring the destination storage account, you need to determine the appropriate object type that must be created within it to support object replication."}, {"p": "Which object type should you create in the destination storage account?"}], "options": ["Container", "File share", "Table", "Queue"], "correct": [0], "multi": false, "explanation": [{"p": "Container is the correct answer here. Azure Object Replication is a feature of Azure Blob Storage, and it works at the container level. To replicate blobs from one storage account to another, you must configure object replication policies between source and destination containers. This means that in the new storage account, you must create a container, as it's the fundamental object that holds blobs (such as images in this case). Without a container, the replication policy cannot be configured or function."}, {"p": "File share is incorrect because object replication does not support Azure Files. File shares are used in Azure Files, which is a completely separate service from Blob Storage, and is not part of object replication capabilities."}, {"p": "Table is incorrect because Azure Table storage is used for NoSQL structured data, and again, object replication only applies to block blobs in containers, not table data."}, {"p": "Queue is incorrect because Azure Queue Storage is designed for messaging between application components. It is not related to blob storage or object replication and cannot be used for replicating blob data."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/object-replication-overview", "https://learn.microsoft.com/en-us/azure/storage/blobs/object-replication-configure?tabs=portal", "https://learn.microsoft.com/en-us/azure/storage/queues/storage-queues-introduction", "https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction", "https://learn.microsoft.com/en-us/azure/storage/tables/table-storage-overview"], "group": "G6"}, {"id": "T1-Q14", "test": 1, "num": 14, "domain": "storage", "stem": [{"p": "You manage an Azure Storage account called mediafiles01 that contains a collection of image blobs."}, {"p": "You plan to provision an additional storage account and configure object replication to copy the existing images from mediafiles01 to the new account."}, {"p": "After creating and configuring the destination storage account, you need to determine the appropriate object type that must be created within it to support object replication."}, {"p": "Which account type should you create in the destination storage account?"}], "options": ["StorageV2 only", "StorageV2 or FileStorage only", "StorageV2 or BlobStorage only", "StorageV2, BlobStorage, or FileStorage"], "correct": [2], "multi": false, "explanation": [{"p": "StorageV2 or BlobStorage only is correct because object replication is supported by both general-purpose v2 storage accounts (StorageV2) and premium block blob storage accounts (BlobStorage). These account types meet the requirements for object replication, allowing replication of blobs between the source and destination accounts."}, {"p": "StorageV2 only is incorrect because while StorageV2 supports object replication, premium block blob storage accounts (BlobStorage) also support object replication, and they should not be excluded from the correct answer."}, {"p": "StorageV2 or FileStorage only and StorageV2, BlobStorage, or FileStorage are incorrect because FileStorage accounts do not support blob storage, which is necessary for object replication."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/object-replication-overview"], "group": "G6"}, {"id": "T1-Q15", "test": 1, "num": 15, "domain": "compute", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You manage an Azure Container Registry named corpRegistry that contains a container image called webappimage."}, {"p": "When you try to deploy an Azure Container Instance using webappimage, the deployment process fails with an error."}, {"p": "You must ensure that a container instance can be deployed successfully using the image stored in corpRegistry."}, {"p": "Proposed solution: Configure a private endpoint for corpRegistry."}, {"p": "Does this solution meet the requirement?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is correct because while a private endpoint connection allows secure access to the container registry over a private network, it does not resolve all potential issues with deploying a container instance. The error might be related to permissions, image availability, or networking configuration rather than the absence of a private endpoint. Other issues like missing Azure Container Instance permissions, registry access policies, or image tags could prevent deployment."}, {"p": "A more appropriate solution would be ensuring that the container instance has the proper permissions to pull images from the registry. This can be done by checking if the container instance has the necessary identities (system-assigned or user-assigned) and permissions to access the container registry."}], "refs": ["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-private-link"], "group": "G7"}, {"id": "T1-Q16", "test": 1, "num": 16, "domain": "compute", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You manage an Azure Container Registry named corpRegistry that contains a container image called webappimage."}, {"p": "When you try to deploy an Azure Container Instance using webappimage, the deployment process fails with an error."}, {"p": "You must ensure that a container instance can be deployed successfully using the image stored in corpRegistry."}, {"p": "Proposed solution: Enable the Use dedicated data endpoint setting for corpRegistry."}, {"p": "Does this solution meet the requirement?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is correct because selecting \"Use dedicated data endpoint\" for Registry1 is primarily used to isolate data plane traffic from management plane traffic in a container registry. While it improves network security and performance, it does not directly address issues related to deploying a container instance using an image. The error message could be caused by other factors, such as missing permissions, improper image tags, or incorrect access configurations for the Azure Container Instance. Using a dedicated data endpoint does not resolve these issues."}, {"p": "A more suitable solution would involve verifying the necessary access permissions and configurations to ensure the container instance can pull the image from the registry."}], "refs": ["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-private-link"], "group": "G7"}, {"id": "T1-Q17", "test": 1, "num": 17, "domain": "compute", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You manage an Azure Container Registry named corpRegistry that contains a container image called webappimage."}, {"p": "When you try to deploy an Azure Container Instance using webappimage, the deployment process fails with an error."}, {"p": "You must ensure that a container instance can be deployed successfully using the image stored in corpRegistry."}, {"p": "Proposed solution: You assign the AcrPull role to ACR-Tasks-Network for Registry1."}, {"p": "Does this solution meet the requirement?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is correct because assigning the AcrPull role to ACR-Tasks-Network does not resolve the error when deploying a container instance. The AcrPull role allows a service or identity to pull images from the container registry, but ACR-Tasks-Network is typically used for managing tasks within the Azure Container Registry (ACR). This role is unrelated to the container instance’s ability to pull images from the registry. The container instance itself or the identity running the container instance should have the AcrPull role assigned for successful image deployment."}, {"p": "A better solution would involve assigning the AcrPull role to the identity or service principal running the container instance, ensuring it has permission to pull images from the registry."}], "refs": ["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-roles?tabs=azure-cli", "https://learn.microsoft.com/en-us/azure/container-instances/container-instances-managed-identity"], "group": "G7"}, {"id": "T1-Q18", "test": 1, "num": 18, "domain": "compute", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You manage an Azure Container Registry named corpRegistry that contains a container image called webappimage."}, {"p": "When you try to deploy an Azure Container Instance using webappimage, the deployment process fails with an error."}, {"p": "You must ensure that a container instance can be deployed successfully using the image stored in corpRegistry."}, {"p": "Proposed solution: You set Admin user to Enable for corpRegistry."}, {"p": "Does this solution meet the requirement?"}], "options": ["Yes", "No"], "correct": [0], "multi": false, "explanation": [{"p": "Yes is correct because enabling the Admin user on the Azure container registry provides credentials (username and password) that can be used to authenticate and pull images from the registry. This can resolve authentication issues when deploying a container instance, as the container instance can use the admin credentials to access the registry and pull image1. This is a quick solution to grant access, especially when other identity-based methods, such as Microsoft Entra, are not configured."}], "refs": ["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-authentication?tabs=azure-cli", "https://learn.microsoft.com/en-us/azure/container-instances/container-instances-using-azure-container-registry"], "group": "G7"}, {"id": "T1-Q19", "test": 1, "num": 19, "domain": "network", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You manage an Azure Storage account named datastore01."}, {"p": "A user named UserA must be granted permissions to view (list) the storage account access keys and regenerate those keys when necessary."}, {"p": "Proposed solution: Assign the Storage Account Encryption Scope Contributor role to UserA at the scope of datastore01."}, {"p": "Does this solution achieve the objective?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is correct because the Storage Account Encryption Scope Contributor role does not grant permissions to list or regenerate storage account keys. To enable a user to list and regenerate storage account keys, the user needs to have the Storage Account Key Operator Service Role or Storage Account Contributor role. These roles specifically allow the management of storage account keys, which is not covered by the Storage Account Encryption Scope Contributor role."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G8"}, {"id": "T1-Q20", "test": 1, "num": 20, "domain": "storage", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You manage an Azure Storage account named datastore01."}, {"p": "A user named UserA must be granted permissions to view (list) the storage account access keys and regenerate those keys when necessary."}, {"p": "Proposed solution: You assign the Storage Account Key Operator Service Role to UserA."}, {"p": "Does this solution achieve the objective?"}], "options": ["Yes", "No"], "correct": [0], "multi": false, "explanation": [{"p": "Yes is correct because the Storage Account Key Operator Service Role grants the necessary permissions to list and regenerate storage account keys without providing broader access to the storage account's data. This role is specifically designed for key management tasks, allowing the user to perform actions related to storage account keys."}, {"p": "Assigning this role to UserA will enable them to list and regenerate the keys for storage1 as required."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-account-key-operator-service-role", "https://learn.microsoft.com/en-us/azure/storage/common/storage-account-keys-manage?tabs=azure-portal"], "group": "G8"}, {"id": "T1-Q21", "test": 1, "num": 21, "domain": "identity", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You manage an Azure Storage account named datastore01."}, {"p": "A user named UserA must be granted permissions to view (list) the storage account access keys and regenerate those keys when necessary."}, {"p": "Proposed solution: You assign the Storage Account Contributor role to UserA."}, {"p": "Does this solution achieve the objective?"}], "options": ["Yes", "No"], "correct": [0], "multi": false, "explanation": [{"p": "Yes is correct because the Storage Account Contributor role provides the necessary permissions to manage storage accounts, including listing and regenerating storage account keys. This role covers both the management of the storage account itself and the associated keys, which meets the requirement stated in the scenario."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G8"}, {"id": "T1-Q22", "test": 1, "num": 22, "domain": "storage", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You manage an Azure Storage account named datastore01."}, {"p": "A user named UserA must be granted permissions to view (list) the storage account access keys and regenerate those keys when necessary."}, {"p": "Proposed solution: You assign the Reader and Data Access role to UserA."}, {"p": "Does this solution achieve the objective?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is correct because the Reader and Data Access role allows a user to view storage account data and metadata but does not provide the necessary permissions to list or regenerate storage account keys. To achieve the goal of allowing UserA to list and regenerate storage account keys, the appropriate role would be the Storage Account Key Operator Service Role or a more privileged role like Contributor."}, {"p": "The Reader and Data Access role is insufficient for key management tasks."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-account-key-operator-service-role"], "group": "G8"}, {"id": "T1-Q23", "test": 1, "num": 23, "domain": "compute", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You manage an Azure virtual machine named ShireenVM, which was deployed using a custom Azure Resource Manager template called deployVM.json."}, {"p": "You receive an alert stating that ShireenVM will be affected by a scheduled platform maintenance event."}, {"p": "You must immediately relocate ShireenVM to another host to avoid the upcoming maintenance impact."}, {"p": "Proposed solution: From the ShireenVM Updates blade, select One-time update."}, {"p": "Does this solution meet the requirement?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is correct because the One-time update option applies maintenance updates to the virtual machine, but it doesn't guarantee moving the VM to a new host to avoid impending maintenance."}, {"p": "To immediately move the VM to a different host, you would need to Redeploy the virtual machine, which moves it to a new host within the same region."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-machines/maintenance-configurations"], "group": "G9"}, {"id": "T1-Q24", "test": 1, "num": 24, "domain": "compute", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You manage an Azure virtual machine named ShireenVM, which was deployed using a custom Azure Resource Manager template called deployVM.json."}, {"p": "You receive an alert stating that ShireenVM will be affected by a scheduled platform maintenance event."}, {"p": "You must immediately relocate ShireenVM to another host to avoid the upcoming maintenance impact."}, {"p": "Proposed solution: From the Overview blade, move ShireenVM to another subscription"}, {"p": "Does this solution meet the requirement?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is correct. The Overview blade provides the details of the VM. Moving a VM to another subscription is a logical change and does not affect the underlying physical infrastructure. To move VM1 to a different host to avoid maintenance impacts, you should redeploy the VM instead."}, {"img": "az104/img/t1_image4.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-machines/maintenance-configurations", "https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/move-resource-group-and-subscription"], "group": "G9"}, {"id": "T1-Q25", "test": 1, "num": 25, "domain": "compute", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You manage an Azure virtual machine named ShireenVM, which was deployed using a custom Azure Resource Manager template called deployVM.json."}, {"p": "You receive an alert stating that ShireenVM will be affected by a scheduled platform maintenance event."}, {"p": "You must immediately relocate ShireenVM to another host to avoid the upcoming maintenance impact."}, {"p": "Proposed solution: Move the VM to a different resource group from the Overview balde."}, {"p": "Does this solution meet the requirement?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is the correct answer here. Moving a virtual machine to a different resource group does not change the physical host on which the VM is running. The operation is a metadata-level move within Azure Resource Manager, and the underlying compute resources (including the physical host) remain unchanged."}, {"p": "Since the goal is to move ShireenVM to a different host immediately (e.g., to avoid upcoming planned maintenance), simply moving the VM to a different resource group does not meet the requirement."}, {"p": "To move a VM to a different host, you must perform an operation that redeploys the VM, such as using the Redeploy option from the Azure portal or running the az vm redeploy command. This action will provision the VM on a new physical host."}], "refs": ["https://learn.microsoft.com/en-us/troubleshoot/azure/virtual-machines/windows/redeploy-to-new-node-windows"], "group": "G9"}, {"id": "T1-Q26", "test": 1, "num": 26, "domain": "compute", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You manage an Azure virtual machine named ShireenVM, which was deployed using a custom Azure Resource Manager template called deployVM.json."}, {"p": "You receive an alert stating that ShireenVM will be affected by a scheduled platform maintenance event."}, {"p": "You must immediately relocate ShireenVM to another host to avoid the upcoming maintenance impact."}, {"p": "Proposed solution: From the Updates blade, you click Enable."}, {"p": "Does this solution meet the requirement?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is the correct answer here. Clicking Enable from the Updates blade typically refers to enabling automatic VM guest patching or maintenance control features, depending on the context. However, this action does not immediately move the VM to a different host."}, {"img": "az104/img/t1_image5.webp"}, {"p": "The goal is to move ShireenVM to a different physical host immediately to avoid potential impact from scheduled maintenance. The correct action to achieve that is to use the Redeploy option, which reprovisions the virtual machine onto a new physical host in the same region."}], "refs": ["https://learn.microsoft.com/en-us/troubleshoot/azure/virtual-machines/windows/redeploy-to-new-node-windows"], "group": "G9"}, {"id": "T1-Q27", "test": 1, "num": 27, "domain": "compute", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You manage an Azure virtual machine named ShireenVM, which was deployed using a custom Azure Resource Manager template called deployVM.json."}, {"p": "You receive an alert stating that ShireenVM will be affected by a scheduled platform maintenance event."}, {"p": "You must immediately relocate ShireenVM to another host to avoid the upcoming maintenance impact."}, {"p": "Proposed solution: From the ShireenVM Redeploy + reapply blade, you click Redeploy."}, {"p": "Does this solution meet the requirement?"}], "options": ["Yes", "No"], "correct": [0], "multi": false, "explanation": [{"p": "Yes is the correct answer here. Clicking Redeploy from the Redeploy + reapply blade of ShireenVM moves the virtual machine to a new physical host within the same Azure region. This operation is specifically designed to address issues related to the underlying host, including planned maintenance, host failures, or performance degradation."}, {"p": "When you redeploy a VM:"}, {"p": "The OS and data disks are preserved."}, {"p": "The VM is moved to a different host."}, {"p": "The public IP (if static) and other configurations remain unchanged."}], "refs": ["https://learn.microsoft.com/en-us/troubleshoot/azure/virtual-machines/windows/redeploy-to-new-node-windows"], "group": "G9"}, {"id": "T1-Q28", "test": 1, "num": 28, "domain": "compute", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You manage an Azure virtual machine named ShireenVM, which was deployed using a custom Azure Resource Manager template called deployVM.json."}, {"p": "You receive an alert stating that ShireenVM will be affected by a scheduled platform maintenance event."}, {"p": "You must immediately relocate ShireenVM to another host to avoid the upcoming maintenance impact."}, {"p": "Proposed solution: Move ShireenVM to another resource group from the RG blade."}, {"p": "Does this solution meet the requirement?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is the correct answer here. Moving ShireenVM to another resource group from the resource group blade is a logical metadata move within Azure Resource Manager. It does not involve changing the physical host on which the virtual machine runs. The VM’s underlying infrastructure including the compute host remains the same."}, {"p": "The correct action would be to redeploy the virtual machine using the Redeploy option, which moves the VM to a new physical host."}], "refs": ["https://learn.microsoft.com/en-us/troubleshoot/azure/virtual-machines/windows/redeploy-to-new-node-windows"], "group": "G9"}, {"id": "T1-Q29", "test": 1, "num": 29, "domain": "compute", "stem": [{"p": "You manage an Azure subscription that uses Azure Container Instances."}, {"p": "Your workstation has both the Azure Command-Line Interface (CLI) and Docker installed. On this machine, you build a container image named invoiceservice-img."}, {"p": "You need to create a new Azure container registry and push invoiceservice-img to it."}, {"p": "Which command accomplishes creating the new container registry?"}], "options": ["az acr build", "az acr create", "az container create", "docker create", "az acr login"], "correct": [1], "multi": false, "explanation": [{"p": "az acr create is the correct answer here. This command is used to create a new Azure Container Registry (ACR). Once the container registry is created, you can push your container images (such as image1) to the registry. This satisfies the requirement of provisioning a new Azure Container Registry."}, {"p": "az acr build is incorrect because this command is used to build and push a Docker container image to an Azure Container Registry, but it does not provision the registry itself."}, {"p": "az container create is incorrect because this command is used to create a container instance, not a container registry."}, {"p": "docker create is incorrect because this Docker command is used to create a new container from an image on your local machine, not to provision a container registry in Azure."}, {"p": "az acr login is incorrect because this command authenticates the CLI session against an existing Azure Container Registry so you can push or pull images. It does not create a new registry."}], "refs": ["https://learn.microsoft.com/en-us/cli/azure/acr?view=azure-cli-latest"], "group": "G10"}, {"id": "T1-Q30", "test": 1, "num": 30, "domain": "compute", "stem": [{"p": "You manage an Azure subscription that uses Azure Container Instances."}, {"p": "Your workstation has both the Azure Command-Line Interface (CLI) and Docker installed. On this machine, you build a container image named invoiceservice-img."}, {"p": "You need to create a new Azure container registry and push invoiceservice-img to it."}, {"p": "Which command accomplishes adding invoiceservice-img to the registry?"}], "options": ["az acr create", "az container create", "docker pull", "docker push", "docker tag"], "correct": [3], "multi": false, "explanation": [{"p": "docker push is the correct answer here. This command is used to upload (push) your locally built Docker container image, such as image1, to a container registry. Once the Azure Container Registry has been created, you use the docker push command to push the image to the registry."}, {"p": "az acr create is incorrect because this command is used to create a new Azure Container Registry, not to upload an image."}, {"p": "az container create is incorrect because this command is used to create a container instance in Azure, not to push an image to a registry."}, {"p": "docker pull is incorrect because this command is used to download (pull) an image from a registry, not to upload (push) an image."}, {"p": "docker tag is incorrect because this command only assigns a repository name and tag to a local image, typically to prepare it for pushing. It does not upload the image to the registry."}], "refs": ["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-get-started-docker-cli?tabs=azure-cli", "https://docs.docker.com/reference/cli/docker/image/push/"], "group": "G10"}, {"id": "T1-Q31", "test": 1, "num": 31, "domain": "compute", "stem": [{"p": "Your Azure subscription includes a container group named PodGroup1. PodGroup1 hosts two Azure container instances, organized as follows."}, {"p": "svc-api has a resource request of 2 CPUs and a resource limit of 2 CPUs."}, {"p": "svc-worker has a resource request of 3 CPUs and a resource limit of 4 CPUs."}, {"p": "You need to ensure that svc-worker can use CPU resources without negatively affecting svc-api."}, {"p": "What should you do?"}], "options": ["Increase the resource limit of svc-api to three CPUs.", "Increase the resource limit of svc-worker to six CPUs.", "Remove the resource limit for both containers.", "Decrease the resource limit of svc-worker to two CPUs.", "Move svc-worker to a separate container group with its own resource allocation."], "correct": [2], "multi": false, "explanation": [{"p": "Remove the resource limit for both containers is the correct answer. Azure Container Instances allocates CPU resources to a container group based on the sum of the containers' resource requests. If no resource limit is specified for a container, its maximum CPU usage is equal to its resource request. Therefore, after removing the limits, svc-api cannot use more than its requested 2 CPUs, and svc-worker cannot use more than its requested 3 CPUs. This ensures that neither container can consume CPU resources beyond its request and that svc-worker cannot use additional shared CPU resources at the expense of svc-api."}, {"p": "Increase the resource limit of svc-api to three CPUs is incorrect because this would allow svc-api to consume more CPU than its requested 2 CPUs. It would not ensure that each container is restricted to its resource request and could increase resource contention within the group."}, {"p": "Increase the resource limit of svc-worker to six CPUs is incorrect because a container's resource limit cannot exceed the total CPU resources allocated to the container group. The group is allocated 5 CPUs based on the combined requests of svc-api and svc-worker. Increasing svc-worker's limit would also work against the requirement to prevent it from consuming more CPU than it requests."}, {"p": "Decrease the resource limit of svc-worker to two CPUs is incorrect because a container's resource limit must be equal to or greater than its resource request. Since svc-worker requests 3 CPUs, its limit cannot be reduced to 2 CPUs."}, {"p": "Move svc-worker to a separate container group with its own resource allocation is incorrect because moving a container out of the group changes the deployment's architecture and is not required to solve the resource contention issue. The problem can be resolved within the existing container group simply by adjusting the resource limits, without splitting the containers apart."}], "refs": ["https://learn.microsoft.com/en-us/azure/container-instances/container-instances-container-groups"], "group": "G11"}, {"id": "T1-Q32", "test": 1, "num": 32, "domain": "identity", "stem": [{"p": "Your organization manages a Microsoft Entra tenant."}, {"p": "Whenever a new Microsoft 365 group gets created, you need its name to automatically take on this format:"}, {"p": "<Office><RequestedName>"}, {"p": "To achieve this, which three actions should you carry out, in order, from the Microsoft Entra admin center?"}, {"p": "ACTIONS"}, {"p": "Set Add suffix to Attribute."}, {"p": "Create a group naming policy."}, {"p": "Set Add prefix to Attribute."}, {"p": "Set Add suffix to String."}, {"p": "Set Add prefix to String."}, {"p": "Set Select type to Office."}, {"p": "Customize the company branding."}], "options": ["3-4-7", "2-3-6", "1-2-6", "4-3-2", "6-1-5"], "correct": [1], "multi": false, "explanation": [{"p": "2-3-6 is the correct sequence of actions."}, {"p": "(Action 2) Create a group naming policy: You need to create a group naming policy in the Microsoft Entra admin center to enforce a specific naming convention."}, {"p": "(Action 3) Set Add prefix to Attribute: In the group naming policy, set Add prefix to Attribute and choose Office as the attribute. This ensures that the office name is added as a prefix to the group name."}, {"p": "(Action 6) Set Select type to Office: Finally, ensure that you set Select type to Office to specify that the office attribute should be used when creating the group name."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/users/groups-naming-policy"], "group": "G12"}, {"id": "T1-Q33", "test": 1, "num": 33, "domain": "identity", "stem": [{"p": "Your organization's Microsoft Entra tenant is linked to the subscriptions shown below."}, {"p": "NovaSub is under the Tenant Root Group, with no parent management group."}, {"p": "AtlasSub is under Global-MG1, whose parent is the Tenant Root Group."}, {"p": "ZenithSub is under Global-MG2, whose parent is the Tenant Root Group."}, {"p": "The following resource groups exist:"}, {"p": "rg-data, in NovaSub, contains a storage account named storeA1."}, {"p": "rg-app, in AtlasSub, contains an Azure App Service named webapp-fin."}, {"p": "rg-vm, in ZenithSub, contains a virtual machine named vm-prod1."}, {"p": "You assign roles to users as follows:"}, {"p": "Morgan is granted the Contributor role at the Global-MG2 scope."}, {"p": "Riley is granted the Storage Account Contributor role at the storeA1 scope."}, {"p": "Casey is granted the User Access Administrator role at the Tenant Root Group scope."}, {"p": "True or False:"}, {"p": "\"Morgan can resize vm-prod1.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because Morgan has the Contributor role assigned at the Global-MG2 management group level, which includes ZenithSub. Since ZenithSub contains rg-vm, and rg-vm has vm-prod1, the Contributor role grants Morgan full management rights over all resources within this scope. The Contributor role allows actions such as resizing virtual machines, making Morgan capable of resizing vm-prod1."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles", "https://learn.microsoft.com/en-us/azure/governance/management-groups/overview"], "group": "G13"}, {"id": "T1-Q34", "test": 1, "num": 34, "domain": "identity", "stem": [{"p": "Your organization's Microsoft Entra tenant is linked to the subscriptions shown below."}, {"p": "NovaSub is under the Tenant Root Group, with no parent management group."}, {"p": "AtlasSub is under Global-MG1, whose parent is the Tenant Root Group."}, {"p": "ZenithSub is under Global-MG2, whose parent is the Tenant Root Group."}, {"p": "The following resource groups exist:"}, {"p": "rg-data, in NovaSub, contains a storage account named storeA1."}, {"p": "rg-app, in AtlasSub, contains an Azure App Service named webapp-fin."}, {"p": "rg-vm, in ZenithSub, contains a virtual machine named vm-prod1."}, {"p": "You assign roles to users as follows:"}, {"p": "Morgan is granted the Contributor role at the Global-MG2 scope."}, {"p": "Riley is granted the Storage Account Contributor role at the storeA1 scope."}, {"p": "Casey is granted the User Access Administrator role at the Tenant Root Group scope."}, {"p": "True or False:"}, {"p": "\"Riley can create a new storage account in rg-data.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because Riley has the Storage Account Contributor role assigned specifically to storeA1, not to the entire resource group (rg-data). The Storage Account Contributor role allows Riley to manage the specific storage account (storeA1) but does not provide the ability to create new storage accounts or manage other resources within rg-data."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-account-contributor"], "group": "G13"}, {"id": "T1-Q35", "test": 1, "num": 35, "domain": "identity", "stem": [{"p": "Your organization's Microsoft Entra tenant is linked to the subscriptions shown below."}, {"p": "NovaSub is under the Tenant Root Group, with no parent management group."}, {"p": "AtlasSub is under Global-MG1, whose parent is the Tenant Root Group."}, {"p": "ZenithSub is under Global-MG2, whose parent is the Tenant Root Group."}, {"p": "The following resource groups exist:"}, {"p": "rg-data, in NovaSub, contains a storage account named storeA1."}, {"p": "rg-app, in AtlasSub, contains an Azure App Service named webapp-fin."}, {"p": "rg-vm, in ZenithSub, contains a virtual machine named vm-prod1."}, {"p": "You assign roles to users as follows:"}, {"p": "Morgan is granted the Contributor role at the Global-MG2 scope."}, {"p": "Riley is granted the Storage Account Contributor role at the storeA1 scope."}, {"p": "Casey is granted the User Access Administrator role at the Tenant Root Group scope."}, {"p": "True or False:"}, {"p": "\"Casey can assign Morgan the Owner role for rg-vm.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because Casey has the User Access Administrator role assigned at the Tenant Root Group scope. This role allows Casey to manage access and assign roles at any level within the tenant, including management groups, subscriptions, and resource groups. Since rg-vm is within the tenant, Casey can assign roles such as the Owner role to Morgan for rg-vm."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#user-access-administrator", "https://learn.microsoft.com/en-us/azure/governance/management-groups"], "group": "G13"}, {"id": "T1-Q36", "test": 1, "num": 36, "domain": "monitor", "stem": [{"p": "An Azure subscription contains two backup-related services:"}, {"p": "An Azure Backup vault named VaultA"}, {"p": "A Recovery Services vault named VaultB"}, {"p": "The subscription includes the following deployed resources:"}, {"p": "VM01 - Virtual machine"}, {"p": "Disk01 - Disk"}, {"p": "WebApp01 - Azure App Service web application"}, {"p": "SQLDB01 - Azure SQL Database"}, {"p": "You plan to configure backup protection for these resources."}, {"p": "Which of the listed resources can be backed up using VaultA (the Azure Backup vault)?"}], "options": ["WebApp01", "SQLDB01", "Disk01", "VM01"], "correct": [2], "multi": false, "explanation": [{"p": "Disk01 is correct because Azure managed disks are backed up using Azure Disk Backup, which requires an Azure Backup vault. This allows disks to be backed up independently without backing up the entire virtual machine."}, {"p": "VM01 could also be backed up, but the backup would include the entire virtual machine, not just the disk. The question specifically focuses on backing up a resource like Disk1."}, {"p": "WebApp01 (Azure App Service web app) and SQLDB01 (Azure SQL Database) have different built-in backup features and are not backed up directly using Azure Backup."}, {"img": "az104/img/t1_image6.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-overview", "https://learn.microsoft.com/en-us/azure/backup/backup-support-matrix"], "group": "G14"}, {"id": "T1-Q37", "test": 1, "num": 37, "domain": "monitor", "stem": [{"p": "An Azure subscription contains two backup-related services:"}, {"p": "An Azure Backup vault named VaultA"}, {"p": "A Recovery Services vault named VaultB"}, {"p": "The subscription includes the following deployed resources:"}, {"p": "VM01 - Virtual machine"}, {"p": "Disk01 - Disk"}, {"p": "WebApp01 - Azure App Service web application"}, {"p": "SQLDB01 - Azure SQL Database"}, {"p": "You plan to configure backup protection for these resources."}, {"p": "Which of the listed resources can be backed up using VaultB (the Recovery Services vault)?"}], "options": ["WebApp01", "SQLDB01", "Disk01", "VM01"], "correct": [3], "multi": false, "explanation": [{"p": "VM01 is the correct answer because a Recovery Services vault (like VaultB) is used to back up entire virtual machines (VMs) in Azure. Azure Backup supports backing up the operating system, data disks, and attached resources of the VM using a Recovery Services vault."}, {"p": "Disk01: While individual disks can be backed up as part of a VM backup, they are not directly backed up independently to a Recovery Services vault."}, {"p": "WebApp01 (Azure App Service web app) and SQLDB01 (Azure SQL Database) are not backed up using Azure Backup through a Recovery Services vault. They have their own specific backup mechanisms."}, {"img": "az104/img/t1_image6.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-overview", "https://learn.microsoft.com/en-us/azure/backup/backup-support-matrix"], "group": "G14"}, {"id": "T1-Q38", "test": 1, "num": 38, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant with the following characteristics:"}, {"p": "Tenant name: Default Directory"}, {"p": "License type: Microsoft Entra ID Free"}, {"p": "Primary domain: an onmicrosoft.com domain"}, {"p": "The tenant includes these identities:"}, {"p": "UserA - User account"}, {"p": "SecGroup01 - Security group"}, {"p": "M365Group01 - Microsoft 365 group"}, {"p": "You purchase a Microsoft Fabric license."}, {"p": "Which of the listed identities can be assigned the Microsoft Fabric license?"}], "options": ["UserA only", "UserA and SecGroup01 only", "UserA and M365Group01 only", "UserA, SecGroup01, and M365Group01"], "correct": [0], "multi": false, "explanation": [{"p": "UserA only is correct because in a free Microsoft Entra ID tenant, you can only assign licenses to individual users like UserA. Group-based licensing (for SecGroup01 or M365Group01) requires a paid version of Microsoft Entra ID (such as P1 or P2)."}, {"p": "UserA and SecGroup01 only is incorrect because, in the free version, SecGroup01 (a security group) cannot be assigned licenses."}, {"p": "UserA and M365Group01 only is incorrect for the same reason. Group-based licensing (whether it's a security group or a Microsoft 365 group) is not supported in the free tier."}, {"p": "UserA, SecGroup01, and M365Group01 is incorrect since neither SecGroup01 nor M365Group01 can have licenses assigned in the free tenant."}], "refs": ["https://learn.microsoft.com/en-us/entra/fundamentals/concept-group-based-licensing"], "group": "G15"}, {"id": "T1-Q39", "test": 1, "num": 39, "domain": "identity", "stem": [{"p": "You have an Azure subscription that includes the following Microsoft Entra identities:"}, {"p": "UserA - A User"}, {"p": "SecGroup01 -  A Security group"}, {"p": "M365Group01 - A Microsoft 365 group"}, {"p": "You plan to enable Self-Service Password Reset (SSPR) using the Azure portal."}, {"p": "For which of the listed identities can SSPR be enabled?"}], "options": ["UserA only", "SecGroup01 only", "UserA and SecGroup01 only", "SecGroup01 and M365Group01 only", "UserA, SecGroup01, and M365Group01"], "correct": [3], "multi": false, "explanation": [{"p": "SecGroup01 and M365Group01 only is correct because SSPR can be directly assigned only to a group of users or to ALL users but not to individual users. The setting is then applicable on all the users in that group. You can select individual users in a group if you do not want to enable the setting for all the users in that group."}, {"img": "az104/img/t1_image7.webp"}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/authentication/tutorial-enable-sspr"], "group": "G16"}, {"id": "T1-Q40", "test": 1, "num": 40, "domain": "network", "stem": [{"p": "Your Azure environment includes two virtual networks, spoke-east and spoke-west, configured with virtual network peering."}, {"p": "A Network Virtual Appliance named fw-appliance1 is deployed in the environment."}, {"p": "You must ensure that all network traffic flowing from spoke-east to spoke-west is routed through fw-appliance1 so that it can be inspected before reaching its destination."}, {"p": "Which option should you implement to meet this requirement?"}], "options": ["Configure a local network gateway.", "a route table that has custom routes", "Enable a service endpoint.", "Configure IP address reservations.", "Configure a network security group with a deny rule."], "correct": [1], "multi": false, "explanation": [{"p": "A route table that has custom routes is the correct answer here. To ensure that the traffic from VNet1 to VNet2 is inspected by NetVA1, you need to use a custom route in the route table. You can create a route that forces traffic from VNet1 to pass through the Network Virtual Appliance (NetVA1) for inspection before it reaches VNet2. This is achieved by setting the next hop in the custom route to the IP address of NetVA1."}, {"p": "Configure a local network gateway is incorrect because it is used for configuring connections between an Azure virtual network and an on-premises network, not for routing traffic between peered virtual networks."}, {"p": "Enable a service endpoint is incorrect because service endpoints provide secure access to Azure services but are not used for routing traffic through a Network Virtual Appliance."}, {"p": "Configure IP address reservations is incorrect because IP reservations are used to reserve public IP addresses, and they do not help with routing or traffic inspection between virtual networks."}, {"p": "Configure a network security group with a deny rule is incorrect because an NSG can only allow or block traffic based on rules, it cannot redirect traffic through an appliance for inspection. Redirecting traffic requires a route table with a custom route, not an NSG."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview", "https://learn.microsoft.com/en-us/azure/virtual-wan/scenario-route-through-nva"], "group": "G17"}, {"id": "T1-Q41", "test": 1, "num": 41, "domain": "identity", "stem": [{"p": "An Azure subscription contains several resources distributed across two resource groups, as detailed in the table below. The resources include a container app and multiple Azure Key Vault instances deployed in different regions."}, {"img": "az104/img/t1_image8.webp"}, {"p": "You intend to use an Azure Key Vault to securely supply a secret to checkout-app."}, {"p": "What should you create so that checkout-app can authenticate and retrieve the secret from the key vault?"}], "options": ["A Managed identity", "A Shared access signature (SAS) token", "A Private endpoint", "A Service principal", "A User account"], "correct": [0], "multi": false, "explanation": [{"p": "A Managed identity is the correct answer. To securely provide a secret from an Azure Key Vault to checkout-app, you should create a managed identity for checkout-app. Managed identities allow Azure resources to securely access other Azure services (like Key Vault) without needing to manage credentials. Once the managed identity is created, it can be granted the necessary permissions to access the Key Vault and retrieve secrets."}, {"p": "A Shared access signature (SAS) token is incorrect because SAS tokens are a mechanism used to grant delegated access to Azure Storage resources. Azure Key Vault does not use SAS tokens for authentication, so this cannot be used to let checkout-app retrieve the secret."}, {"p": "A Private endpoint is incorrect because this is used for securing the network access to the Key Vault but does not handle authentication for accessing secrets."}, {"p": "A Service principal is incorrect because while service principals can be used to access resources, using a managed identity is a simpler and more secure method for Azure resources."}, {"p": "A User account is incorrect because user accounts are not typically used for resource-to-resource access in Azure."}], "refs": ["https://learn.microsoft.com/en-us/azure/key-vault/general/assign-access-policy?tabs=azure-portal", "https://learn.microsoft.com/en-us/entra/identity/managed-identities-azure-resources/overview"], "group": "G18"}, {"id": "T1-Q42", "test": 1, "num": 42, "domain": "identity", "stem": [{"p": "An Azure subscription contains several resources distributed across two resource groups, as detailed in the table below. The resources include a container app and multiple Azure Key Vault instances deployed in different regions."}, {"img": "az104/img/t1_image8.webp"}, {"p": "You intend to use an Azure Key Vault to securely supply a secret to checkout-app."}, {"p": "Which Azure Key Vault can be used to supply the secret?"}], "options": ["kv-primary only", "kv-primary and kv-secondary only", "kv-primary and kv-archive only", "kv-primary, kv-secondary, or kv-archive"], "correct": [3], "multi": false, "explanation": [{"p": "kv-primary, kv-secondary, or kv-archive is correct because there are no Azure-imposed barriers that prevent checkout-app from accessing Key Vaults located in different regions or resource groups. While it is generally recommended to use a Key Vault in the same region as the resource for performance and latency considerations, the question does not specify best practices, only whether the secret can be used. Therefore, checkout-app can access all three Key Vaults with appropriate permissions."}], "refs": ["https://learn.microsoft.com/en-us/azure/key-vault/general/disaster-recovery-guidance", "https://learn.microsoft.com/en-us/azure/key-vault/general/best-practices"], "group": "G18"}, {"id": "T1-Q43", "test": 1, "num": 43, "domain": "identity", "stem": [{"p": "You are working with an Azure subscription."}, {"p": "A user-defined route table named RouteTablePrimary has been created."}, {"p": "You must add a route to RouteTablePrimary that requires specifying an IP address for the next hop."}, {"p": "Which next hop option should you choose when configuring the route?"}], "options": ["Internet", "Virtual network gateway", "Virtual network", "Virtual appliance"], "correct": [3], "multi": false, "explanation": [{"p": "Virtual appliance is the correct answer here. When adding a route to a routing table and specifying a next hop IP address, the correct next hop type is Virtual appliance. A virtual appliance refers to a Network Virtual Appliance (NVA), such as a firewall or load balancer, which inspects or processes network traffic. By choosing Virtual appliance, you can specify the IP address of the NVA that will handle the routed traffic."}, {"p": "Internet is incorrect because it routes traffic directly to the public internet without specifying a next hop IP address."}, {"p": "Virtual network gateway is incorrect because it is used to route traffic to an Azure VPN gateway for on-premises connectivity."}, {"p": "Virtual network is incorrect because it routes traffic within the same virtual network and does not require specifying a next hop IP address."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview"], "group": "G19"}, {"id": "T1-Q44", "test": 1, "num": 44, "domain": "storage", "stem": [{"p": "You are planning to provision an Azure Storage account named storage1."}, {"p": "The storage account must satisfy the following conditions:"}, {"p": "It must be compatible with Azure Data Lake Storage capabilities."}, {"p": "It should be optimized to reduce costs for data that is accessed infrequently."}, {"p": "Data must be replicated automatically to another Azure region for resiliency."}, {"p": "Which three options should you configure for storage1?"}], "options": ["geo-redundant storage (GRS)", "hierarchical namespace", "zone-redundant storage (ZRS)", "the Hot access tier", "the Cool tier"], "correct": [0, 1, 4], "multi": true, "explanation": [{"p": "geo-redundant storage (GRS) is correct because the requirement states that data must automatically replicate to a secondary Azure region. GRS provides this replication capability, ensuring redundancy across regions."}, {"p": "hierarchical namespace is correct because enabling the hierarchical namespace is necessary to support Azure Data Lake Storage, which uses this feature to organize data in a directory-based structure."}, {"p": "the Cool tier is correct because the Cool access tier minimizes costs for infrequently accessed data. This is aligned with the requirement to reduce costs for such data usage scenarios."}, {"p": "zone-redundant storage (ZRS) is incorrect because ZRS replicates data only within a single region across availability zones and does not provide cross-region replication, which is a requirement in this scenario."}, {"p": "the Hot access tier is incorrect because the Hot tier is optimized for frequently accessed data, which would result in higher costs for infrequently accessed data, contradicting the requirement to minimize costs."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/storage-account-options", "https://learn.microsoft.com/en-us/azure/storage/blobs/data-lake-storage-introduction"], "group": "G20"}, {"id": "T1-Q45", "test": 1, "num": 45, "domain": "identity", "stem": [{"p": "Your Azure subscription named CorpSub1 includes a virtual network called vnet-hub1."}, {"p": "The following users are assigned roles within the subscription:"}, {"p": "Dana is assigned the Owner role."}, {"p": "Priya is assigned the Security Admin role."}, {"p": "Sam is assigned the Network Contributor role."}, {"p": "Which user is permitted to create a new subnet within vnet-hub1?"}], "options": ["Dana only", "Sam only", "Dana and Sam only", "Priya and Sam only", "Dana, Priya, and Sam", "None of the users, because subnet creation requires the Global Administrator role in Microsoft Entra"], "correct": [2], "multi": false, "explanation": [{"p": "Dana and Sam only is correct because the Owner role (Dana) has full permissions, including managing resources and configurations like adding a subnet to vnet-hub1. The Network Contributor role (Sam) also has sufficient permissions to manage the network, which includes adding subnets."}, {"p": "Dana only is incorrect because Sam (Network Contributor) also has the required permissions to add a subnet."}, {"p": "Sam only is incorrect because Dana (Owner) also has the required permissions to add a subnet, since the Owner role includes full control over all resources in the subscription."}, {"p": "Priya and Sam only is incorrect because although Sam (Network Contributor) has the required permissions, Priya with the Security Admin role does not have permissions to modify or add subnets in a virtual network."}, {"p": "Dana, Priya, and Sam is incorrect because Priya (Security Admin) does not have permissions to manage network resources like subnets."}, {"p": "None of the users, because subnet creation requires the Global Administrator role in Microsoft Entra is incorrect because subnet creation is an Azure resource-level permission governed by Azure RBAC roles such as Owner or Network Contributor. It has no dependency on Microsoft Entra directory roles like Global Administrator, which govern identity and directory management, not Azure resource operations."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G21"}, {"id": "T1-Q46", "test": 1, "num": 46, "domain": "identity", "stem": [{"p": "Your Azure subscription named CorpSub1 includes a virtual network called vnet-hub1."}, {"p": "The following users are assigned roles within the subscription:"}, {"p": "Dana is assigned the Owner role."}, {"p": "Priya is assigned the Security Admin role."}, {"p": "Sam is assigned the Network Contributor role."}, {"p": "Which user can assign another user the Reader role to vnet-hub1?"}], "options": ["Dana only", "Priya only", "Sam only", "Dana and Priya only", "Priya and Sam only", "Dana, Priya, and Sam"], "correct": [0], "multi": false, "explanation": [{"p": "Dana only is correct because the Owner role provides full access to manage vnet-hub1 and its access, including assigning roles such as the Reader role to vnet-hub1. The Owner role allows complete control over the resource, including RBAC permissions."}, {"p": "Priya only is incorrect because the Security Admin role is focused on managing security-related policies and configurations but does not grant the ability to manage access to a VNet."}, {"p": "Sam only is incorrect because the Network Contributor role allows management of networking resources, such as creating or modifying VNets and subnets, but does not allow role assignments or access management for the VNet."}, {"p": "Dana and Priya only is incorrect because the Security Admin role does not include permissions to manage RBAC for the VNet."}, {"p": "Priya and Sam only is incorrect because neither the Security Admin nor the Network Contributor roles allow assigning roles to the VNet."}, {"p": "Dana, Priya, and Sam is incorrect because only the Owner role (Dana) has the necessary permissions to assign roles to vnet-hub1."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G21"}, {"id": "T1-Q47", "test": 1, "num": 47, "domain": "storage", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "You are configuring Azure Backup to satisfy the technical requirements for data1 and docs1."}, {"p": "For the data1 resource, which backup frequency should you configure?"}], "options": ["Every hour", "Every 4 hours", "Every 6 hours", "Every 12 hours", "Daily"], "correct": [4], "multi": false, "explanation": [{"p": "Daily is correct. The data1 resource is a blob container. For Azure Blob vaulted backup, Azure Backup supports scheduled backups with a daily or weekly frequency. Because the technical requirements specify that data1 must be backed up as often as Azure Backup allows, Daily is the most frequent supported scheduled vaulted backup option."}, {"p": "Every hour, Every 4 hours, Every 6 hours, and Every 12 hours are incorrect because these frequencies are not available for scheduled vaulted backup of Azure Blobs."}, {"p": "Azure Files supports multiple backups per day, but that capability applies to file shares such as docs1, not to the blob container data1."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/blob-backup-configure-manage?tabs=operational-backup#create-a-backup-policy"], "group": "G22"}, {"id": "T1-Q48", "test": 1, "num": 48, "domain": "storage", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "You are configuring Azure Backup to satisfy the technical requirements for data1 and docs1."}, {"p": "For the docs1 resource, which backup frequency should you configure?"}], "options": ["Every hour", "Every 4 hours", "Every 6 hours", "Every 12 hours", "Daily"], "correct": [1], "multi": false, "explanation": [{"p": "Every hour is correct because Azure Backup for Azure Files supports configuring up to 24 scheduled snapshots per day. If backups are scheduled throughout a 24-hour period, this allows a snapshot to be taken as frequently as once every hour."}, {"p": "The case study requires docs1 to be backed up as often as Azure Backup allows. Because docs1 is an Azure file share and Azure Backup supports up to 24 scheduled snapshots per day, Every hour provides the highest supported backup frequency among the available options."}, {"p": "Every 4 hours, Every 6 hours, Every 12 hours, and Daily are incorrect because each would result in fewer scheduled snapshots per day and therefore would not satisfy the requirement to back up docs1 as frequently as the service allows."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-azure-files?tabs=backup-center"], "group": "G22"}, {"id": "T1-Q49", "test": 1, "num": 49, "domain": "identity", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "Implementing the planned change for AttribTag1 is required."}, {"p": "True or False:"}, {"p": "\"AttribTag1 can be assigned to Cohort1 by Priya Shah.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because Microsoft Entra custom security attributes can only be assigned to users, service principals, and managed identities. Groups are not supported as assignment targets."}, {"p": "By default, Global Administrators and most other admin roles do not automatically have permissions to read, define, or assign custom security attributes. These permissions are granted through specialized roles such as Attribute Definition Administrator and Attribute Assignment Administrator. However, even if Priya Shah (a Global Administrator) were delegated those roles, the action described, assigning AttribTag1 to a group, would still not be possible due to the limitation on supported object types."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/enterprise-apps/custom-security-attributes-apps?pivots=portal", "https://learn.microsoft.com/en-us/entra/identity/role-based-access-control/permissions-reference#attribute-assignment-administrator"], "group": "G22"}, {"id": "T1-Q50", "test": 1, "num": 50, "domain": "identity", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "Implementing the planned change for AttribTag1 is required."}, {"p": "True or False:"}, {"p": "\"Derek Nguyen can assign AttribTag1 to Carlos Vega.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because Derek Nguyen holds the Attribute Definition Administrator role, and that role does not carry enough privilege to assign custom security attribute values. Attribute Definition Administrator only covers creating and managing attribute sets and attribute definitions. Assigning a defined attribute to an object requires the separate Attribute Assignment Administrator role."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/enterprise-apps/custom-security-attributes-apps?pivots=portal", "https://learn.microsoft.com/en-us/entra/identity/role-based-access-control/permissions-reference#attribute-assignment-administrator"], "group": "G22"}, {"id": "T1-Q51", "test": 1, "num": 51, "domain": "identity", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "Implementing the planned change for AttribTag1 is required."}, {"p": "True or False:"}, {"p": "\"Lena Osei can assign AttribTag1 to Cohort2.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because Microsoft Entra custom security attributes cannot be applied to any type of group object, including Microsoft 365 groups, mail-enabled security groups, and standard security groups. Attributes can only be assigned to users, service principals, and managed identities."}, {"p": "Even though Lena Osei holds the Attribute Assignment Administrator role, which does have sufficient rights to assign attributes generally, the limitation here is about which object types support attributes at all, not about her permissions."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/enterprise-apps/custom-security-attributes-apps?pivots=portal", "https://learn.microsoft.com/en-us/entra/identity/role-based-access-control/permissions-reference#attribute-assignment-administrator"], "group": "G22"}, {"id": "T1-Q52", "test": 1, "num": 52, "domain": "identity", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "You need to satisfy the technical requirements associated with the key encryption key (KEK)."}, {"p": "Which PowerShell cmdlet should you run, and which key should you specify?"}], "options": ["Set-AzVMDiskEncryptionExtension and Key2", "Set-AzDiskDiskEncryptionKey and Key1", "Set-AzVMDiskEncryptionExtension and Key1", "Set-AzDiskEncryptionKey and Key2"], "correct": [2], "multi": false, "explanation": [{"p": "Set-AzVMDiskEncryptionExtension and Key1 is the correct choice because Azure Disk Encryption requires a key encryption key (KEK) based on RSA for encrypting virtual machines. Key1 is an RSA key with a size of 4096, which is supported for this purpose. Hence this is the correct option."}, {"p": "Set-AzVMDiskEncryptionExtension and Key2 is incorrect because Key2 is an elliptic curve (EC) key, which is not supported for Azure Disk Encryption. Hence this is not the correct option."}, {"p": "Set-AzDiskDiskEncryptionKey and Key1 is incorrect because the correct cmdlet for setting disk encryption on virtual machines is Set-AzVMDiskEncryptionExtension, not Set-AzDiskDiskEncryptionKey. Hence this is not the correct option."}, {"p": "Set-AzDiskEncryptionKey and Key2 is incorrect for two reasons: First, as mentioned, the Set-AzDiskEncryptionKey cmdlet does not exist, and second, Key2 is an EC key, which is not suitable for this purpose. Hence this is not the correct option."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-machines/windows/disk-encryption-windows"], "group": "G22"}, {"id": "T1-Q53", "test": 1, "num": 53, "domain": "identity", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "Encryption for the virtual machines needs to be configured. The solution has to satisfy the technical requirements."}, {"p": "Which virtual machines qualify for encryption?"}], "options": ["Node2 and Node4", "Node2 and Node3", "Node4 and Node5", "Node1 and Node3"], "correct": [1], "multi": false, "explanation": [{"p": "Node2 and Node3 is the correct answer. Azure Disk Encryption works for virtual machines that meet specific disk type and operating system compatibility requirements:"}, {"p": "Node2 uses Windows Server 2022 with a basic volume, which is compatible with Azure Disk Encryption."}, {"p": "Node3 uses Ubuntu Server 22.04 LTS with standard SSDs. Ubuntu 22.04-LTS is on the current list of Azure-endorsed distributions that support Azure Disk Encryption for both OS and data disks."}, {"p": "Node2 and Node4 is incorrect because although Node2 is compatible, Node4 uses Write Accelerator disks, which Azure Disk Encryption does not support."}, {"p": "Node4 and Node5 is incorrect because Node4 uses Write Accelerator disks and Node5 uses a dynamic volume, neither of which Azure Disk Encryption supports."}, {"p": "Node1 and Node3 is incorrect because although Node3 is compatible, Node1 uses ephemeral OS disks, which Azure Disk Encryption does not support."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-machines/disk-encryption", "https://learn.microsoft.com/en-us/azure/virtual-machines/linux/disk-encryption-overview"], "group": "G22"}, {"id": "T1-Q54", "test": 1, "num": 54, "domain": "storage", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "The planned configuration changes for data2 have been applied."}, {"p": "What is the maximum number of additional stored access policies that can still be created for data2?"}], "options": ["0", "1", "2", "3", "4", "5"], "correct": [2], "multi": false, "explanation": [{"p": "2 is the correct answer here. Azure Storage accounts allow a maximum of five stored access policies per container. Since data2 already has three stored access policies (Policy1, Policy2, and Policy3), you can create two additional stored access policies to reach the limit of five."}, {"p": "0 is incorrect because data2 does not already have five stored access policies."}, {"p": "1 is incorrect because there are two slots available, not just one."}, {"p": "3, 4, 5 are incorrect because only two more stored access policies can be created before reaching the maximum limit of five."}], "refs": ["https://learn.microsoft.com/en-us/rest/api/storageservices/define-stored-access-policy"], "group": "G22"}, {"id": "T1-Q55", "test": 1, "num": 55, "domain": "storage", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "The planned configuration changes for data2 have been applied."}, {"p": "For data2, what is the maximum number of additional immutable blob stored policies you're able to create?"}], "options": ["0", "1", "2", "3", "4", "5"], "correct": [1], "multi": false, "explanation": [{"p": "1 is the correct answer here. In Azure Blob Storage, you can create up to two immutable blob stored access policies per container, one time-based retention policy and one legal hold. Since data2 already has a legal hold configured, this consumes one of the two available policy slots, leaving you with the option to create one more, a time-based retention policy."}, {"img": "az104/img/t1_image9.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/immutable-storage-overview"], "group": "G22"}, {"id": "T1-Q56", "test": 1, "num": 56, "domain": "storage", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "The planned changes for the storage account content need to be implemented."}, {"p": "Across which containers and file shares can this content be organized?"}], "options": ["docs1 only", "data1 and docs1 only", "docs1 and docs2 only", "data1, docs1, and docs2 only", "data1, data2, docs1, and docs2"], "correct": [3], "multi": false, "explanation": [{"p": "data1, docs1, and docs2 only is the correct answer here. While data1 in datastore1 has a hierarchical namespace enabled, file shares like docs1 and docs2 do not require hierarchical namespace to organize content. File shares can organize content using directories regardless of whether the storage account supports a hierarchical namespace. Therefore, data1, docs1, and docs2 are all valid options for organizing content."}, {"p": "docs1 only is incorrect because file shares can also organize content using directories, and hierarchical namespace is not required for file shares, but this option leaves out docs2 and data1, both of which are also usable."}, {"p": "data1 and docs1 only is incorrect because docs2 can also be used to organize content, as it is a file share."}, {"p": "docs1 and docs2 only is incorrect because it leaves out data1, which is eligible since it sits in an account with hierarchical namespace enabled."}, {"p": "data1, data2, docs1, and docs2 is incorrect because data2 is in datastore2, which does not have hierarchical namespace enabled, and this limits its ability to organize content as per the planned changes."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/data-lake-storage-namespace", "https://learn.microsoft.com/en-us/azure/storage/files/storage-how-to-use-files-portal?tabs=azure-portal"], "group": "G22"}, {"id": "T1-Q57", "test": 1, "num": 57, "domain": "compute", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "AppSvc1 needs to be configured to meet the technical requirements."}, {"p": "Which certificate from SecVault1 is usable for this?"}], "options": ["TlsCert1 only", "TlsCert1 or TlsCert2 only", "TlsCert1 or TlsCert3 only", "TlsCert3 or TlsCert4 only", "TlsCert1, TlsCert2, TlsCert3, or TlsCert4"], "correct": [1], "multi": false, "explanation": [{"p": "TlsCert1 or TlsCert2 only is the correct answer here because both certificates are in the PKCS#12 format, which is the format Azure App Service requires when importing a certificate from Key Vault. Azure App Service only supports importing PKCS#12 (PFX) certificates from Key Vault, so TlsCert1 and TlsCert2 are the only two objects in SecVault1 that App Service can actually use."}, {"p": "TlsCert3 and TlsCert4 are in the PEM format. App Service does not accept PEM-format certificates for a direct Key Vault import, so neither is usable here without first converting it, which falls outside what this scenario calls for."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/configure-ssl-certificate?tabs=apex%2CRBAC", "https://learn.microsoft.com/en-us/azure/key-vault/certificates/about-certificates"], "group": "G22"}, {"id": "T1-Q58", "test": 1, "num": 58, "domain": "monitor", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "The planned changes for CollectRule1 need to be implemented."}, {"p": "Which type of query should be used?"}], "options": ["KQL", "XPath", "WQL", "T-SQL"], "correct": [1], "multi": false, "explanation": [{"p": "XPath is the correct answer because Data Collection Rules (DCRs) use XPath expressions to filter Windows Event Logs at the ingestion level. In this case, to collect only system events with a specific Event ID (4648) from Node2 and Node4, you must define the filter using xPathQueries in the DCR. KQL is not used in the DCR to define what gets collected from Windows Event Logs; it is used later for querying already collected data in Log Analytics."}, {"p": "KQL is incorrect because Kusto Query Language is used for querying data once it's already been ingested into Log Analytics. It is not used inside the DCR to define what gets collected from Windows Event Logs."}, {"p": "WQL is incorrect because Windows Query Language is associated with WMI and not used in Azure Monitor DCRs for collecting event logs."}, {"p": "T-SQL is incorrect because Transact-SQL is used for querying relational databases such as SQL Server or Azure SQL Database, and has no relevance in defining data collection rules for Azure Monitor."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-monitor/vm/data-collection?tabs=portal#filter-events-using-xpath-queries"], "group": "G22"}, {"id": "T1-Q59", "test": 1, "num": 59, "domain": "identity", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "Implementing the planned changes for Carlos Vega requires action."}, {"p": "Which role(s) should be assigned to Carlos Vega?"}], "options": ["Contributor only", "Network Contributor only", "Private DNS Zone Contributor only", "Network Contributor and Private DNS Zone Contributor only"], "correct": [3], "multi": false, "explanation": [{"p": "Network Contributor and Private DNS Zone Contributor only is the correct answer because linking a private DNS zone (corezone1.com) to a virtual network (NetVnet1) requires permissions on both the private DNS zone and the virtual network. The Private DNS Zone Contributor role grants permissions to create and manage virtual network links within the DNS zone, while the Network Contributor role provides the required Microsoft.Network/virtualNetworks/join/action permission on the virtual network. Assigning these roles at the specific resource scopes satisfies the requirement and adheres to the principle of least privilege."}, {"p": "Contributor only is incorrect because it provides full access to all resource types at the assigned scope, which exceeds the permissions required for this task and violates the principle of least privilege."}, {"p": "Network Contributor only is incorrect because it grants permissions on virtual network resources but does not include rights to manage private DNS zones or create DNS virtual network links. Therefore, it cannot be used to link the DNS zone to the virtual network."}, {"p": "Private DNS Zone Contributor only is incorrect because although this role allows management of private DNS zones and creation of virtual network links, it does not grant sufficient permissions on the target virtual network resource. Without the virtualNetworks/join/action permission at the VNet scope, the link operation fails."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#private-dns-zone-contributor", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#network-contributor", "https://learn.microsoft.com/en-us/azure/private-link/private-endpoint-dns"], "group": "G22"}, {"id": "T1-Q60", "test": 1, "num": 60, "domain": "identity", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "Implementing the planned changes for Carlos Vega requires action."}, {"p": "For which resource(s) should the role be assigned to Carlos Vega?"}], "options": ["CoreRG2 only", "CoreRG3 only", "NetVnet1 only", "corezone1.com only", "NetVnet1 and corezone1.com only", "CoreRG2 and CoreRG3 only"], "correct": [4], "multi": false, "explanation": [{"p": "NetVnet1 and corezone1.com only is correct because Carlos Vega needs permissions to create a virtual network link between the Azure Private DNS zone corezone1.com and the virtual network NetVnet1. The required permissions apply to the private DNS zone and the virtual network involved in the link."}, {"p": "The case study requires the principle of least privilege and specifies that permissions must be granted only at the scope actually required. Therefore, the required role assignments should be scoped directly to NetVnet1 and corezone1.com, rather than to their parent resource groups."}, {"p": "CoreRG2 only is incorrect because CoreRG2 contains NetVnet1 but does not contain corezone1.com. Assigning the role only to CoreRG2 would not provide the required permissions on the private DNS zone."}, {"p": "CoreRG3 only is incorrect because CoreRG3 contains corezone1.com but does not contain NetVnet1. Assigning the role only to CoreRG3 would not provide the required permissions on the virtual network."}, {"p": "NetVnet1 only is incorrect because Carlos also requires permissions on the private DNS zone, corezone1.com, to create and manage the virtual network link."}, {"p": "corezone1.com only is incorrect because Carlos also requires the necessary permissions on NetVnet1 to link the virtual network to the private DNS zone."}, {"p": "CoreRG2 and CoreRG3 only is incorrect because assigning the role at both resource group scopes would grant permissions to resources other than NetVnet1 and corezone1.com. This would provide broader access than necessary and would violate the case study requirement to grant permissions only at the scope actually required."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/best-practices#least-privilege", "https://learn.microsoft.com/en-us/azure/private-link/private-endpoint-dns"], "group": "G22"}, {"id": "T1-Q61", "test": 1, "num": 61, "domain": "storage", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "The planned changes for EncScope1 have been applied. EncScope1 needs to satisfy all the specified technical requirements."}, {"p": "Which resources can be encrypted by using EncScope1?"}], "options": ["containers and blobs in datastore2 only", "containers and blobs in datastore1 and datastore2", "containers, blobs, and file shares in datastore2 only", "containers, blobs, and file shares in datastore1 and datastore2", "containers, blobs, file shares, queues, and tables in datastore2 only"], "correct": [0], "multi": false, "explanation": [{"p": "containers and blobs in datastore2 only is correct. Encryption scopes in Azure are designed to apply to Blob storage, specifically to containers and individual blobs within a storage account. Since file shares, queues, and tables are not supported within encryption scopes, EncScope1 will only be able to encrypt containers and blobs in datastore2. This aligns with the requirements specified, where EncScope1 should be used to ensure encryption for relevant storage resources in datastore2, limited to containers and blobs."}, {"img": "az104/img/t1_image10.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/encryption-scope-overview"], "group": "G22"}, {"id": "T1-Q62", "test": 1, "num": 62, "domain": "compute", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "The planned updates for the newly created containers are being applied."}, {"p": "Which Azure services support WinImg1?"}], "options": ["Azure Container Apps only", "Azure Container Instances only", "Azure Container Apps or Azure Container Instances only", "App Service or Azure Container Apps only", "App Service or Azure Container Instances only", "App Service, Azure Container Apps, or Azure Container Instances"], "correct": [4], "multi": false, "explanation": [{"p": "App Service or Azure Container Instances only is the correct answer here. Since WinImg1 is based on Windows Server, it can only be deployed using services that support Windows-based containers. App Service and Azure Container Instances both support Windows-based containers, making them suitable for deploying WinImg1. Azure Container Apps only supports Linux-based containers, so it cannot be used for WinImg1."}, {"p": "Azure Container Apps only is incorrect because Azure Container Apps does not support Windows-based containers, only Linux-based containers."}, {"p": "Azure Container Instances only is incorrect because, although it supports Windows-based containers, App Service is also a valid option for deploying WinImg1."}, {"p": "Azure Container Apps or Azure Container Instances only is incorrect because Azure Container Apps does not support Windows-based containers, so it cannot be used for WinImg1."}, {"p": "App Service or Azure Container Apps only is incorrect because Azure Container Apps cannot be used for deploying Windows-based containers."}, {"p": "App Service, Azure Container Apps, or Azure Container Instances is incorrect because Azure Container Apps does not support Windows-based containers, making it unsuitable for WinImg1."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/containers/", "https://learn.microsoft.com/en-us/azure/container-instances/", "https://learn.microsoft.com/en-us/azure/container-apps/"], "group": "G22"}, {"id": "T1-Q63", "test": 1, "num": 63, "domain": "compute", "stem": [{"p": "Refer to the ApexCore Consulting case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1MgNQ5vq7ijED84FRhJF3OF0_GFAc_C0JjZ0-p7YhoEg/edit?usp=sharing"}, {"p": "The planned updates related to the newly created containers are being applied."}, {"p": "Which Azure services support LinuxImg1?"}], "options": ["Azure Container Apps only", "Azure Container Instances only", "Azure Container Apps or Azure Container Instances only", "App Service or Azure Container Apps only", "App Service or Azure Container Instances only", "App Service, Azure Container Apps, or Azure Container Instances"], "correct": [5], "multi": false, "explanation": [{"p": "App Service, Azure Container Apps, or Azure Container Instances is the correct answer because LinuxImg1 is based on Linux, which allows for deployment across multiple Azure services that support Linux-based containers. Azure App Service, Azure Container Apps, and Azure Container Instances all support Linux-based containers, providing flexibility in deployment options for LinuxImg1."}, {"p": "Azure Container Apps only is incorrect because, although it supports Linux-based containers, it is not the only option for running LinuxImg1."}, {"p": "Azure Container Instances only is incorrect because, while it supports Linux-based containers, App Service and Azure Container Apps are also valid options for deploying LinuxImg1."}, {"p": "Azure Container Apps or Azure Container Instances only is incorrect because App Service is also capable of running Linux-based containers, making this option too restrictive."}, {"p": "App Service or Azure Container Apps only is incorrect because Azure Container Instances is also a suitable option for running Linux-based containers, making this choice incomplete."}, {"p": "App Service or Azure Container Instances only is incorrect because it excludes Azure Container Apps, which also supports Linux-based containers."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/containers/", "https://learn.microsoft.com/en-us/azure/container-apps/", "https://learn.microsoft.com/en-us/azure/container-instances/"], "group": "G22"}, {"id": "T1-Q64", "test": 1, "num": 64, "domain": "identity", "stem": [{"p": "You have an Azure subscription that contains a user named Priya and the following resources:"}, {"p": "rg-network, a resource group"}, {"p": "nic-web01, a virtual network interface"}, {"p": "nsg-web01, a network security group (NSG)"}, {"p": "The network security group nsg-web01 is linked to nic-web01."}, {"p": "Priya has role assignments for nsg-web01 as follows:"}, {"p": "Contributor at this resource (nsg-web01)"}, {"p": "Reader at the subscription scope (inherited)"}, {"p": "Storage Account Contributor at the resource group scope (inherited)"}, {"p": "True of False:"}, {"p": "\"Priya is able to create a storage account within rg-network.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer because even though the question states that Priya has role assignments on nsg-web01, the Storage Account Contributor role is assigned at the Resource Group (rg-network) level, as shown in the role assignments table. This means Priya inherits the permissions provided by that role for all resources within rg-network."}, {"p": "The Storage Account Contributor role allows full management of storage accounts, including the ability to create them. Since this role is applied at the rg-network scope, Priya can create storage accounts anywhere within that resource group regardless of her other roles at narrower scopes like nsg-web01."}, {"p": "The mention of role assignments for nsg-web01 in the question context simply lists additional roles that Priya has, but those do not restrict or override the broader permissions granted at the resource group level. RBAC in Azure is additive by design, meaning Priya's permissions accumulate across scopes."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles", "https://learn.microsoft.com/en-us/azure/role-based-access-control/role-assignments-portal", "https://learn.microsoft.com/en-us/azure/role-based-access-control/overview"], "group": "G23"}, {"id": "T1-Q65", "test": 1, "num": 65, "domain": "network", "stem": [{"p": "You have an Azure subscription that contains a user named Priya and the following resources:"}, {"p": "rg-network, a resource group"}, {"p": "nic-web01, a virtual network interface"}, {"p": "nsg-web01, a network security group (NSG)"}, {"p": "The network security group nsg-web01 is linked to nic-web01."}, {"p": "Priya has role assignments for nsg-web01 as follows:"}, {"p": "Contributor at this resource (nsg-web01)"}, {"p": "Reader at the subscription scope (inherited)"}, {"p": "Storage Account Contributor at the resource group scope (inherited)"}, {"p": "True of False:"}, {"p": "\"Priya can modify the DNS settings of nic-web01.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because the Contributor role is assigned only at the nsg-web01 resource scope. Azure RBAC permissions apply only to the scope at which they are assigned and to child resources beneath that scope. Since nic-web01 is not a child resource of nsg-web01 (it is a separate resource that nsg-web01 is merely associated with), the Contributor permission on nsg-web01 does not grant rights over the network interface."}, {"p": "The Reader role at the subscription level is insufficient because it provides read-only access and does not allow modifying DNS settings."}, {"p": "The Storage Account Contributor role at the resource group level is not applicable because it grants permissions only for storage account resources and does not include rights to modify network interfaces."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles", "https://learn.microsoft.com/en-us/azure/role-based-access-control/overview", "https://learn.microsoft.com/en-us/azure/role-based-access-control/role-assignments-portal"], "group": "G23"}, {"id": "T1-Q66", "test": 1, "num": 66, "domain": "network", "stem": [{"p": "You have an Azure subscription that contains a user named Priya and the following resources:"}, {"p": "rg-network, a resource group"}, {"p": "nic-web01, a virtual network interface"}, {"p": "nsg-web01, a network security group (NSG)"}, {"p": "The network security group nsg-web01 is linked to nic-web01."}, {"p": "Priya has role assignments for nsg-web01 as follows:"}, {"p": "Contributor at this resource (nsg-web01)"}, {"p": "Reader at the subscription scope (inherited)"}, {"p": "Storage Account Contributor at the resource group scope (inherited)"}, {"p": "True of False:"}, {"p": "\"Priya has sufficient permissions to add a rule to nsg-web01 that blocks a specific range of incoming IP addresses from reaching nic-web01.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because Priya has the Contributor role explicitly assigned to nsg-web01 (Network Security Group). The Contributor role allows full management permissions over the NSG, including the ability to create, modify, and delete inbound and outbound security rules to control traffic flow."}, {"p": "Since nsg-web01 is associated with nic-web01, any inbound security rules configured on nsg-web01 will apply to nic-web01. Therefore, Priya has the required permissions to add a rule to nsg-web01 that blocks a specific range of incoming IP addresses from reaching nic-web01."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles", "https://learn.microsoft.com/en-us/azure/role-based-access-control/overview", "https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"], "group": "G23"}, {"id": "T1-Q67", "test": 1, "num": 67, "domain": "identity", "stem": [{"p": "You have configured the custom role definition shown below."}, {"p": "{"}, {"p": "\"properties\": {"}, {"p": "\"roleName\": \"vmOperatorRole\","}, {"p": "\"description\": \"\","}, {"p": "\"roleType\": \"true\","}, {"p": "\"assignableScopes\": ["}, {"p": "\"/subscriptions/5a91e01f-0a3f-4bb3-8f6d-2ca9b81c7e35/\""}, {"p": "],"}, {"p": "\"permissions\": ["}, {"p": "{"}, {"p": "\"actions\": ["}, {"p": "\"Microsoft.Authorization/*/read\","}, {"p": "\"Microsoft.Compute/availabilitySets/*\","}, {"p": "\"Microsoft.Compute/locations/*\","}, {"p": "\"Microsoft.Compute/virtualMachines/*\","}, {"p": "\"Microsoft.Compute/virtualMachineScaleSets/*\","}, {"p": "\"Microsoft.Compute/disks/write\","}, {"p": "\"Microsoft.Compute/disks/read\","}, {"p": "\"Microsoft.Compute/disks/delete\","}, {"p": "\"Microsoft.Network/locations/*\","}, {"p": "\"Microsoft.Network/networkInterfaces/*\","}, {"p": "\"Microsoft.Network/networkSecurityGroups/join/action\","}, {"p": "\"Microsoft.Network/networkSecurityGroups/read\","}, {"p": "\"Microsoft.Network/publicIPAddresses/join/action\","}, {"p": "\"Microsoft.Network/publicIPAddresses/read\","}, {"p": "\"Microsoft.Network/virtualNetworks/read\","}, {"p": "\"Microsoft.Network/virtualNetworks/subnets/join/action\","}, {"p": "\"Microsoft.Resources/deployments/*\","}, {"p": "\"Microsoft.Resources/subscriptions/resourceGroups/read\","}, {"p": "\"Microsoft.Support/*\""}, {"p": "],"}, {"p": "\"notActions\": [],"}, {"p": "\"dataActions\": [],"}, {"p": "\"notDataActions\": []"}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "Which section of this role definition must you update so that users can sign in to virtual machines assigned vmOperatorRole?"}], "options": ["actions", "roletype", "notActions", "dataActions", "notDataActions", "assignableScopes"], "correct": [3], "multi": false, "explanation": [{"p": "dataActions is the correct option because permissions like \"Microsoft.Compute/virtualMachines/login/action\" or \"Microsoft.Compute/virtualMachines/loginAsAdmin/action\" are categorized as data plane operations. These permissions determine access to the operational level of the virtual machine, such as signing in or interacting with its data, and should therefore be placed in the dataActions section."}, {"p": "actions is incorrect because this section controls management-level (control plane) operations, such as creating, updating, or deleting resources. Signing in to a virtual machine does not fall under this category."}, {"p": "roleType is incorrect because it specifies the type of role (e.g., built-in or custom) and does not influence permission assignments."}, {"p": "notActions is incorrect because it is used to exclude specific control plane operations from a role rather than granting access."}, {"p": "notDataActions is incorrect because it is used to exclude specific data plane operations, not to define permissions for logging into virtual machines."}, {"p": "assignableScopes is incorrect because this section only determines where the role can be assigned (e.g., subscription, resource group) and does not directly grant or restrict resource-level permissions."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/custom-roles", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#virtual-machine-administrator-login"], "group": "G24"}, {"id": "T1-Q68", "test": 1, "num": 68, "domain": "identity", "stem": [{"p": "You have configured the custom role definition shown below."}, {"p": "{"}, {"p": "\"properties\": {"}, {"p": "\"roleName\": \"vmOperatorRole\","}, {"p": "\"description\": \"\","}, {"p": "\"roleType\": \"true\","}, {"p": "\"assignableScopes\": ["}, {"p": "\"/subscriptions/5a91e01f-0a3f-4bb3-8f6d-2ca9b81c7e35/\""}, {"p": "],"}, {"p": "\"permissions\": ["}, {"p": "{"}, {"p": "\"actions\": ["}, {"p": "\"Microsoft.Authorization/*/read\","}, {"p": "\"Microsoft.Compute/availabilitySets/*\","}, {"p": "\"Microsoft.Compute/locations/*\","}, {"p": "\"Microsoft.Compute/virtualMachines/*\","}, {"p": "\"Microsoft.Compute/virtualMachineScaleSets/*\","}, {"p": "\"Microsoft.Compute/disks/write\","}, {"p": "\"Microsoft.Compute/disks/read\","}, {"p": "\"Microsoft.Compute/disks/delete\","}, {"p": "\"Microsoft.Network/locations/*\","}, {"p": "\"Microsoft.Network/networkInterfaces/*\","}, {"p": "\"Microsoft.Network/networkSecurityGroups/join/action\","}, {"p": "\"Microsoft.Network/networkSecurityGroups/read\","}, {"p": "\"Microsoft.Network/publicIPAddresses/join/action\","}, {"p": "\"Microsoft.Network/publicIPAddresses/read\","}, {"p": "\"Microsoft.Network/virtualNetworks/read\","}, {"p": "\"Microsoft.Network/virtualNetworks/subnets/join/action\","}, {"p": "\"Microsoft.Resources/deployments/*\","}, {"p": "\"Microsoft.Resources/subscriptions/resourceGroups/read\","}, {"p": "\"Microsoft.Support/*\""}, {"p": "],"}, {"p": "\"notActions\": [],"}, {"p": "\"dataActions\": [],"}, {"p": "\"notDataActions\": []"}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "Which section of this role definition must you modify so that vmOperatorRole can only be assigned to a resource group named rg-compute-ops?"}], "options": ["actions", "roletype", "notActions", "dataActions", "notDataActions", "assignableScopes"], "correct": [5], "multi": false, "explanation": [{"p": "assignableScopes is the correct option because this section defines where a role can be assigned within Azure. By specifying the resource group scope (e.g., /subscriptions/{subscriptionId}/resourceGroups/rg-compute-ops) in the assignableScopes section, the custom role vmOperatorRole can be restricted to be assigned only to rg-compute-ops."}, {"p": "This ensures that the role cannot be assigned to other subscriptions, resource groups, or resources outside the specified scope."}, {"p": "actions is incorrect because it defines control plane permissions for resource management but does not restrict where the role can be assigned."}, {"p": "roleType is incorrect because it only specifies whether the role is built-in or custom and does not affect the scope of assignment."}, {"p": "notActions is incorrect because it is used to exclude specific actions from the role, not to define assignment scope."}, {"p": "dataActions is incorrect because it controls data-level permissions, not role assignment scope."}, {"p": "notDataActions is incorrect because it specifies excluded data-level operations and does not define assignment scope."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#virtual-machine-administrator-login"], "group": "G24"}, {"id": "T1-Q69", "test": 1, "num": 69, "domain": "identity", "stem": [{"p": "You have an Azure policy configured as shown below."}, {"p": "SCOPE"}, {"p": "Scope: CorpSub1 (subscription)"}, {"p": "Exclusions: CorpSub1/rg-finance"}, {"p": "BASICS"}, {"p": "Policy definition: Not allowed resource types"}, {"p": "Assignment name: Not allowed resource types"}, {"p": "Assignment ID: /subscriptions/9c4d7e21-8b6a-4f19-a3c5-1e70bd928d4f/providers/Microsoft.Authorization/policyAssignments/2f8a1c93bd4e5f16"}, {"p": "Assigned by: dana.morgan@corpsub.com"}, {"p": "PARAMETERS"}, {"p": "Not allowed resource types: Microsoft.Storage/storageAccounts"}, {"p": "What is the effect of this policy?"}], "options": ["You can create storage accounts in any resource group within CorpSub1.", "You are prevented from creating storage accounts anywhere in CorpSub1.", "You can create storage accounts in rg-finance only.", "You are prevented from creating storage accounts in rg-finance only.", "You can create storage accounts anywhere in CorpSub1, but only Owners can do so."], "correct": [2], "multi": false, "explanation": [{"p": "You can create storage accounts in rg-finance only is correct because the policy defines a Not allowed resource types rule for Microsoft.Storage/storageAccounts at the CorpSub1 scope. However, the rg-finance resource group is explicitly excluded from this policy. This means that while creating storage accounts is blocked across the entire subscription, rg-finance is exempt from this restriction, allowing storage accounts to be created there."}, {"img": "az104/img/t1_image11.webp"}, {"p": "You can create storage accounts in any resource group within CorpSub1 is incorrect because the policy explicitly prevents creating storage accounts at the CorpSub1 level, except for the excluded resource group rg-finance."}, {"p": "You are prevented from creating storage accounts anywhere in CorpSub1 is incorrect because the exclusion for rg-finance allows creating storage accounts specifically in that resource group, overriding the subscription-wide restriction."}, {"p": "You are prevented from creating storage accounts in rg-finance only is incorrect because rg-finance is explicitly excluded from the policy, making it the only place where creating storage accounts is permitted."}, {"p": "You can create storage accounts anywhere in CorpSub1, but only Owners can do so is incorrect because Azure Policy governs what resources can be deployed within a scope, not who can deploy them. Restricting an action to a specific role (such as Owner) is a function of Azure RBAC, not Azure Policy, so this option misattributes a role-based access concept to a policy-based restriction."}], "refs": ["https://docs.microsoft.com/en-us/azure/governance/policy/overview#policy-definition"], "group": "G25"}, {"id": "T1-Q70", "test": 1, "num": 70, "domain": "storage", "stem": [{"p": "You have an Azure subscription with an existing Azure Storage account."}, {"p": "You plan to upload an on-premises virtual machine image to a blob container named vmimages."}, {"p": "Before uploading the image, you must create the required container in the storage account."}, {"p": "To do this, you intend to run an AzCopy command, as shown below."}, {"p": "https://mystorageaccount.<service>.core.windows.net/vmimages"}, {"p": "Which command should you run?"}], "options": ["azcopy sync ‘https://mystorageacount. blob .core.windows.net/vmimages’", "azcopy make ‘https://mystorageacount.queue.core.windows.net/vmimages’", "azcopy copy ‘https://mystorageacount.table.core.windows.net/vmimages’", "azcopy sync ‘https://mystorageacount.dfs.core.windows.net/vmimages’", "azcopy make ‘https://mystorageacount.blob.core.windows.net/vmimages’", "azcopy copy ‘https://mystorageacount.images.core.windows.net/vmimages’"], "correct": [4], "multi": false, "explanation": [{"p": "azcopy make ‘https://mystorageaccount.blob.core.windows.net/vmimages’ is correct because the make command in AzCopy is specifically used to create a new container in an Azure Blob Storage account."}, {"p": "The blob endpoint (blob.core.windows.net) is the correct endpoint for creating containers in Blob Storage."}, {"p": "The container name vmimages indicates that it is intended for storing blobs, which aligns with the blob endpoint."}, {"p": "The correct syntax for creating a new blob container using AzCopy is:"}, {"p": "azcopy make 'https://<storage-account-name>.blob.core.windows.net/<container-name>'"}, {"p": "azcopy sync ‘https://mystorageaccount.blob.core.windows.net/vmimages’"}, {"p": "Sync is used to synchronize data between a source and a destination, not to create a container."}, {"p": "azcopy make ‘https://mystorageaccount.queue.core.windows.net/vmimages’"}, {"p": "The queue endpoint is for Azure Queue Storage, not Blob Storage."}, {"p": "azcopy copy ‘https://mystorageaccount.table.core.windows.net/vmimages’"}, {"p": "The table endpoint is for Azure Table Storage, not Blob Storage."}, {"p": "azcopy sync ‘https://mystorageaccount.dfs.core.windows.net/vmimages’"}, {"p": "The dfs endpoint is for Azure Data Lake Storage, not Blob Storage."}, {"p": "azcopy copy ‘https://mystorageaccount.images.core.windows.net/vmimages’"}, {"p": "The images endpoint is invalid in Azure Storage."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/storage-ref-azcopy-make"], "group": "G26"}, {"id": "T1-Q71", "test": 1, "num": 71, "domain": "compute", "stem": [{"p": "You provision an Azure virtual machine named VM1 that runs Windows Server 2019."}, {"p": "The current configuration of VM1 is shown in the below exhibit."}, {"img": "az104/img/t1_image12.webp"}, {"p": "You are required to enable Desired State Configuration (DSC) for ShireenVM."}, {"p": "What is the first action you should take?"}], "options": ["Assign a DNS name to ShireenVM.", "Establish a connection to ShireenVM.", "Power on ShireenVM.", "Capture a snapshot of ShireenVM."], "correct": [2], "multi": false, "explanation": [{"p": "Power on ShireenVM is correct because Desired State Configuration (DSC) requires the virtual machine to be in a running state to enable and configure it. In the exhibit, ShireenVM is currently stopped (deallocated), which means it is not operational. DSC operates by configuring the state of an actively running VM, and it cannot perform any operations on a stopped or deallocated VM."}, {"p": "Assign a DNS name to ShireenVM is incorrect because assigning a DNS name is related to external name resolution and not a requirement for enabling DSC."}, {"p": "Establish a connection to ShireenVM is incorrect because without starting the VM, you cannot establish a remote connection to perform DSC configuration."}, {"p": "Capture a snapshot of ShireenVM is incorrect because snapshots are primarily used for backup or creating new VMs, not for enabling DSC."}], "refs": ["https://learn.microsoft.com/en-us/azure/automation/automation-dsc-overview", "https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/dsc-overview"], "group": "G27"}, {"id": "T1-Q72", "test": 1, "num": 72, "domain": "identity", "stem": [{"p": "You have defined a custom security attribute named Attr1 in your Microsoft Entra tenant."}, {"p": "The tenant includes a user account, a security group, and a service principal, as shown below."}, {"p": "UserA - User"}, {"p": "SecGroup01 - Security group"}, {"p": "AppPrincipal01 - Service principal"}, {"p": "You want to apply Attr1 to every identity type that supports custom security attributes."}, {"p": "To which identities can you assign Attr1?"}], "options": ["UserA only", "SecGroup01 only", "UserA and SecGroup01 only", "UserA and AppPrincipal01 only", "UserA, SecGroup01, and AppPrincipal01"], "correct": [3], "multi": false, "explanation": [{"p": "UserA and AppPrincipal011 only is correct because custom security attributes in Microsoft Entra ID can only be assigned to users and service principals (enterprise applications). Security groups are not supported objects for custom security attributes."}, {"img": "az104/img/t1_image13.webp"}], "refs": ["https://learn.microsoft.com/en-us/entra/fundamentals/custom-security-attributes-overview"], "group": "G28"}, {"id": "T1-Q73", "test": 1, "num": 73, "domain": "identity", "stem": [{"p": "You have an Azure subscription named CorpSub1 that contains two users named Priya and Sam."}, {"p": "You must assign Azure role-based access control (RBAC) roles to both users so they can perform the following actions within CorpSub1:"}, {"p": "Priya must view the data in any storage account."}, {"p": "Sam must assign users the Contributor role for storage accounts."}, {"p": "The assignment must follow the principle of least privilege."}, {"p": "Which RBAC role should you assign to Priya?"}], "options": ["Owner", "Contributor", "Reader and Data Access", "Storage Account Contributor", "User Access Administrator", "Storage Blob Data Reader"], "correct": [2], "multi": false, "explanation": [{"p": "Reader and Data Access is the correct role to assign to Priya. This role provides read-only access to management operations (like the standard Reader role), but also adds the ability to read the data inside Azure Storage containers and blobs, queues, tables, and files. This aligns perfectly with the requirement that Priya must be able to view the data in any storage account, without allowing write or management capabilities. It also adheres to the principle of least privilege, as it grants exactly what is required and nothing more."}, {"p": "Owner is incorrect because it grants full access to manage all resources, including access management permissions. This is far more than what Priya needs just to view storage data, and violates the principle of least privilege."}, {"p": "Contributor is incorrect because while it allows full management of resources, it does not grant access to the underlying data in storage accounts (like reading blob contents). So it's not sufficient for Priya's data access requirement, and it overgrants permissions on the management plane."}, {"p": "Storage Account Contributor is incorrect because it provides management access to storage accounts (e.g., configuring settings, managing firewalls), but it does not grant data plane access (like reading blobs or files). Therefore, this role does not meet Priya's requirement to view the data inside storage accounts."}, {"p": "User Access Administrator is incorrect because it allows managing role assignments, not accessing data. This role is relevant for Sam's requirement, but not for Priya. It provides no data access or management access to storage resources, so it is not applicable here."}, {"p": "Storage Blob Data Reader is incorrect because it only grants read access to blob containers and data, not to other storage services such as queues, tables, and files. Since the requirement is to view the data in any storage account, this role is too narrow in scope compared to Reader and Data Access."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles/storage#reader-and-data-access", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#owner", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#contributor", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-account-contributor", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#user-access-administrator"], "group": "G29"}, {"id": "T1-Q74", "test": 1, "num": 74, "domain": "identity", "stem": [{"p": "You have an Azure subscription named CorpSub1 that contains two users named Priya and Sam."}, {"p": "You must assign Azure role-based access control (RBAC) roles to both users so they can perform the following actions within CorpSub1:"}, {"p": "Priya must view the data in any storage account."}, {"p": "Sam must assign users the Contributor role for storage accounts."}, {"p": "The assignment must follow the principle of least privilege."}, {"p": "Which RBAC role should you assign to Sam?"}], "options": ["Owner", "Contributor", "Reader and Data Access", "Storage Account Contributor", "User Access Administrator", "Role Based Access Control Administrator"], "correct": [5], "multi": false, "explanation": [{"p": "Role Based Access Control Administrator is correct because Sam needs to assign the Contributor role to users for storage accounts within CorpSub1. The Role Based Access Control Administrator role provides permissions to manage Azure RBAC role assignments without granting permissions to manage Azure resources directly."}, {"p": "This role includes permissions such as Microsoft.Authorization/roleAssignments/write and Microsoft.Authorization/roleAssignments/delete, allowing Sam to create and remove role assignments at the scope where his role is assigned."}, {"p": "Compared to User Access Administrator, Role Based Access Control Administrator has a more limited set of permissions and is specifically designed for managing Azure RBAC role assignments. Therefore, it is the more appropriate choice under the principle of least privilege."}, {"p": "For even more restrictive delegation, Azure RBAC conditions can be applied to limit which roles Sam can assign. For example, Sam could be restricted to assigning only the Contributor role."}, {"p": "Owner is incorrect because this role grants extensive permissions over Azure resources, including the ability to create, modify, and delete resources and manage access to them. Although Owner would allow Sam to assign the Contributor role, it provides significantly more permissions than required and violates the principle of least privilege."}, {"p": "Contributor is incorrect because this role allows users to create, modify, and delete Azure resources but does not grant permissions to manage Azure RBAC role assignments. Therefore, Sam would not be able to assign the Contributor role to other users."}, {"p": "Reader and Data Access is incorrect because this role provides read access to Azure resources and, for supported storage accounts, access to storage account keys for viewing data. It does not grant permissions to create or manage Azure RBAC role assignments. Therefore, it cannot fulfill Sam's requirement."}, {"p": "Storage Account Contributor is incorrect because this role allows users to manage storage accounts, including their configuration and management operations. However, it does not grant permissions to create Azure RBAC role assignments. Therefore, Sam could manage storage accounts but could not assign the Contributor role to other users."}, {"p": "User Access Administrator is incorrect under the principle of least privilege because, although it allows Sam to assign the Contributor role, it provides broader access-management permissions than Role Based Access Control Administrator."}, {"p": "User Access Administrator includes additional permissions beyond managing Azure RBAC role assignments. Since Sam only needs to manage role assignments, Role Based Access Control Administrator is the more narrowly scoped permission set and therefore the better choice."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#user-access-administrator", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#owner", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#contributor", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#reader-and-data-access", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-account-contributor"], "group": "G29"}, {"id": "T1-Q75", "test": 1, "num": 75, "domain": "storage", "stem": [{"p": "You have an Azure subscription that includes a storage account hosting website content."}, {"p": "You need to ensure that users accessing the website are routed through the Microsoft point-of-presence (POP) that is geographically closest to them."}, {"p": "What configuration should you implement to meet this requirement?"}], "options": ["Load balancing", "Routing preference", "Azure Firewall rules", "private endpoints"], "correct": [1], "multi": false, "explanation": [{"p": "Routing preference is the correct answer. In Azure Storage, the routing preference setting allows you to specify how user traffic reaches your storage account; either through the Microsoft global network or over the public internet. To ensure that inbound user traffic uses the Microsoft point-of-presence (POP) closest to the user’s location, you should configure the routing preference to use Microsoft network routing (also called \"Microsoft edge network\"). This ensures that user traffic enters the Microsoft network at the POP closest to the user's location and is routed through Microsoft's backbone to the storage account, optimizing performance and reducing latency."}, {"img": "az104/img/t1_image14.webp"}, {"p": "Load balancing is incorrect because while Azure Load Balancer distributes traffic across virtual machines and services, it does not apply to Azure Storage accounts or influence the routing behavior of traffic to them."}, {"p": "Azure Firewall rules is incorrect because Azure Firewall is used for controlling and monitoring traffic to/from Azure resources, based on configured rules. It is not responsible for routing user traffic through the Microsoft POPs or determining how traffic enters the Microsoft network."}, {"p": "Private endpoints is incorrect because they are used to provide private connectivity to Azure services over a virtual network. While they enhance security by avoiding public internet exposure, they do not control whether traffic is routed through the Microsoft edge network or influence the POP usage."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/network-routing-preference#microsoft-global-network-versus-internet-routing", "https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security", "https://learn.microsoft.com/en-us/azure/firewall/overview", "https://learn.microsoft.com/en-us/azure/private-link/private-endpoint-overview"], "group": "G30"}, {"id": "T1-Q76", "test": 1, "num": 76, "domain": "storage", "stem": [{"p": "You have an Azure subscription that includes a storage account named StorageA."}, {"p": "You intend to apply role-based access control (RBAC) role assignments to storage1 by using conditional access expressions."}, {"p": "Which services within StorageA allow RBAC role assignments to be configured with conditions?"}], "options": ["containers only", "file shares only", "tables only", "queues only", "containers and queues only", "files shares and tables only"], "correct": [4], "multi": false, "explanation": [{"p": "containers and queues only is the correct answer. Azure supports Azure role assignment conditions for Blob Storage containers and Queue Storage. This means you can apply conditional access controls—such as limiting access by IP address, resource tags, or actions—when assigning RBAC roles to these services. This feature enhances fine-grained access control, enabling you to enforce least privilege principles more effectively."}, {"img": "az104/img/t1_image15.webp"}, {"p": "file shares only is incorrect because Azure Files currently does not support role assignment conditions. You can assign roles, but not with conditional logic."}, {"p": "tables only is incorrect because Azure Table storage does not support RBAC role assignment conditions. Access is typically controlled through account-level keys or Shared Access Signatures (SAS), not conditional RBAC."}, {"p": "queues only is incorrect because while queue services support conditional role assignments, selecting this option alone ignores the fact that containers (Blob storage) are also supported."}, {"p": "containers only is incorrect for the same reason—it's incomplete. Both containers and queues support conditional role assignments, so the correct answer must include both."}, {"p": "file shares and tables only is incorrect because neither of those services supports conditional access using RBAC role assignments."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/conditions-format#actions", "https://learn.microsoft.com/en-us/azure/storage/blobs/assign-azure-role-data-access?tabs=azure-portal", "https://learn.microsoft.com/en-us/azure/storage/queues/assign-azure-role-data-access?tabs=portal"], "group": "G31"}, {"id": "T1-Q77", "test": 1, "num": 77, "domain": "identity", "stem": [{"p": "You have an Azure subscription called Sub1 that includes the resource groups, as shown in the table below."}, {"img": "az104/img/t1_image16.webp"}, {"p": "Each resource group is associated with a specific Azure region and has an Azure Policy assigned to it."}, {"p": "A web app named CustomerWeb01 exists in ResGrp1 and is deployed in the West Europe region."}, {"p": "You move CustomerWeb01 to ResGrp2."}, {"p": "What happens as a result of this move?"}], "options": ["The App Service plan for CustomerWeb01 moves to North Europe. Pol2 applies to CustomerWeb01.", "The App Service plan for CustomerWeb01 remains in West Europe. Pol1 applies to CustomerWeb01.", "The App Service plan for CustomerWeb01 remains in West Europe. Pol2 applies to CustomerWeb01.", "The App Service plan for CustomerWeb01 moves to North Europe. Pol1 applies to CustomerWeb01."], "correct": [2], "multi": false, "explanation": [{"p": "The App Service plan for CustomerWeb01 remains in West Europe. Pol2 applies to CustomerWeb01 is the correct answer here. When you move a resource like a web app to a different resource group, the region of the resource does not change—it stays in the same physical location unless explicitly redeployed. Therefore, CustomerWeb01 and its App Service plan will remain in West Europe."}, {"p": "However, after the move, the policy assigned to the destination resource group (ResGrp2) will now govern CustomerWeb01. Since CustomerWeb01 is now in ResGrp2, Pol2 applies to it."}, {"img": "az104/img/t1_image17.webp"}, {"p": "The App Service plan for CustomerWeb01 moves to North Europe. Pol2 applies to CustomerWeb01 is incorrect because the App Service plan does not change regions automatically during a resource group move."}, {"p": "The App Service plan for CustomerWeb01 remains in West Europe. Pol1 applies to CustomerWeb01 is incorrect because although the location remains unchanged, the applied policy comes from the new resource group (ResGrp2), not the original one."}, {"p": "The App Service plan for CustomerWeb01 moves to North Europe. Pol1 applies to CustomerWeb01 is incorrect for both reasons—the region doesn’t change, and the policy from the original group doesn’t carry over."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/move-resource-group-and-subscription", "https://learn.microsoft.com/en-us/azure/governance/policy/overview", "https://learn.microsoft.com/en-us/azure/governance/policy/concepts/definition-structure-basics", "https://learn.microsoft.com/en-us/azure/app-service/app-service-plan-manage"], "group": "G32"}, {"id": "T1-Q78", "test": 1, "num": 78, "domain": "identity", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You have three Azure subscriptions named Sub1, Sub2, and Sub3, all associated with a single Microsoft Entra tenant."}, {"p": "The tenant includes a user named User1, a security group named Group1, and a management group named MG1. User1 is a member of Group1."}, {"p": "Both Sub1 and Sub2 are assigned to MG1."}, {"p": "Sub1 contains a resource group named RG1, and RG1 hosts five Azure Functions."}, {"p": "The following role assignments are configured at the MG1 scope:"}, {"p": "Group1 is assigned the Reader role"}, {"p": "User1 is assigned the User Access Administrator role"}, {"p": "Additionally:"}, {"p": "User1 is assigned the Virtual Machine Contributor role on Sub1 and Sub2"}, {"p": "User1 is assigned the Contributor role on RG1"}, {"p": "True or False:"}, {"p": "“Members of Group1 can view the configuration settings of the Azure Functions.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer here. The members of Group1 can view the configurations of the Azure functions because Group1 has been assigned the Reader role at the management group level (MG1). Since Sub1 and Sub2 are members of MG1, and RG1 (which contains the Azure Functions) is part of Sub1, the Reader role cascades down from MG1 to Sub1 and RG1."}, {"p": "The Reader role allows users to view all resources, including their configurations, but does not permit any modifications. Therefore, even without direct permissions at the resource group or subscription level, Group1 members inherit read-only access and can view the Azure Functions in RG1."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#reader", "https://learn.microsoft.com/en-us/azure/governance/management-groups/overview"], "group": "G33"}, {"id": "T1-Q79", "test": 1, "num": 79, "domain": "identity", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You have three Azure subscriptions named Sub1, Sub2, and Sub3, all associated with a single Microsoft Entra tenant."}, {"p": "The tenant includes a user named User1, a security group named Group1, and a management group named MG1. User1 is a member of Group1."}, {"p": "Both Sub1 and Sub2 are assigned to MG1."}, {"p": "Sub1 contains a resource group named RG1, and RG1 hosts five Azure Functions."}, {"p": "The following role assignments are configured at the MG1 scope:"}, {"p": "Group1 is assigned the Reader role"}, {"p": "User1 is assigned the User Access Administrator role"}, {"p": "Additionally:"}, {"p": "User1 is assigned the Virtual Machine Contributor role on Sub1 and Sub2"}, {"p": "User1 is assigned the Contributor role on RG1"}, {"p": "True or False:"}, {"p": "\"User1 can assign the Owner role for RG1.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer here. User1 is assigned the User Access Administrator role at the management group (MG1) level. This role grants the ability to manage role assignments (i.e., grant or remove access) on resources within that scope and all its child scopes—including subscriptions and resource groups beneath MG1. Since Sub1 is part of MG1, and RG1 is inside Sub1, the User Access Administrator permission applies to RG1 as well."}, {"p": "While Contributor alone does not allow role assignment, the User Access Administrator role is specifically designed to allow assigning any RBAC role, including Owner, as long as the user has this role at the appropriate level—which User1 does in this case."}, {"p": "Therefore, User1 can assign the Owner role for RG1, even if they are not currently an Owner themselves."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#user-access-administrator", "https://learn.microsoft.com/en-us/azure/role-based-access-control/elevate-access-global-admin", "https://learn.microsoft.com/en-us/azure/role-based-access-control/role-assignments-portal#prerequisites-for-role-assignments", "https://learn.microsoft.com/en-us/azure/role-based-access-control/role-assignments-portal-subscription-admin#prerequisites"], "group": "G33"}, {"id": "T1-Q80", "test": 1, "num": 80, "domain": "identity", "stem": [{"p": "Note: This question is part of a set of related questions that use the same scenario. Each question proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You have three Azure subscriptions named Sub1, Sub2, and Sub3, all associated with a single Microsoft Entra tenant."}, {"p": "The tenant includes a user named User1, a security group named Group1, and a management group named MG1. User1 is a member of Group1."}, {"p": "Both Sub1 and Sub2 are assigned to MG1."}, {"p": "Sub1 contains a resource group named RG1, and RG1 hosts five Azure Functions."}, {"p": "The following role assignments are configured at the MG1 scope:"}, {"p": "Group1 is assigned the Reader role"}, {"p": "User1 is assigned the User Access Administrator role"}, {"p": "Additionally:"}, {"p": "User1 is assigned the Virtual Machine Contributor role on Sub1 and Sub2"}, {"p": "User1 is assigned the Contributor role on RG1"}, {"p": "True or False:"}, {"p": "\"User1 can create a new resource group and deploy a virtual machine to the new group.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer here. Although User1 has the Virtual Machine Contributor role assigned at the Sub1 and Sub2 subscription levels, and the Contributor role for RG1, they do not have permissions to create a new resource group unless they are granted Owner or Contributor at the subscription level where they want to create that new resource group."}, {"p": "The Virtual Machine Contributor role allows managing virtual machines, but does not grant permissions to create resource groups. Additionally, the Contributor role assigned at RG1 only provides permissions within RG1, not at the subscription level needed to create new resource groups."}, {"p": "Therefore, User1 cannot create a new resource group, and thus, cannot deploy a VM to a new resource group."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#virtual-machine-contributor", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#contributor", "https://learn.microsoft.com/en-us/azure/role-based-access-control/role-assignments-portal#prerequisites-for-role-assignments", "https://learn.microsoft.com/en-us/azure/role-based-access-control/role-assignments-steps"], "group": "G33"}, {"id": "T1-Q81", "test": 1, "num": 81, "domain": "monitor", "stem": [{"p": "You have an Azure subscription named Subscription1 and an on-premises deployment of Microsoft System Center Service Manager."}, {"p": "Within Subscription1, there is a virtual machine named VM1."}, {"p": "You must ensure that Service Manager generates an alert whenever the available memory on VM1 drops below 10 percent."}, {"p": "What should you do first?"}], "options": ["Create an automation runbook", "Deploy a function app", "Deploy the IT Service Management Connector (ITSM)", "Create a notification"], "correct": [2], "multi": false, "explanation": [{"p": "Deploy the IT Service Management Connector (ITSM) is the correct answer here. The IT Service Management Connector (ITSM) allows you to integrate Azure Monitor with IT service management tools such as System Center Service Manager (SCSM). This connector enables alerts from Azure (e.g., when VM1's available memory drops below a threshold) to automatically generate incidents or alerts within Service Manager."}, {"p": "Before you can generate alerts or trigger incidents in Service Manager based on Azure metrics, you must first deploy and configure the ITSM connector in Azure. Only then can you map Azure alerts (like memory thresholds) to corresponding actions in Service Manager."}, {"p": "Create an automation runbook is incorrect because automation runbooks are used for remediating or performing actions based on alerts, not for integrating with Service Manager directly."}, {"p": "Deploy a function app is incorrect as it’s generally used for executing custom serverless logic—not necessary in this scenario where a built-in integration exists via ITSM Connector."}, {"p": "Create a notification is incorrect because notifications are used to inform users via email or SMS, but not to trigger actions or alerts in Service Manager."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/itsmc-overview", "https://learn.microsoft.com/en-in/azure/azure-functions/functions-overview?pivots=programming-language-csharp", "https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/action-groups"], "group": "G34"}, {"id": "T1-Q82", "test": 1, "num": 82, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes the following resources, all deployed in the East US region:"}, {"p": "10 virtual machines"}, {"p": "A key vault named Vault1"}, {"p": "A network security group named NSG1"}, {"p": "All virtual machines are protected by using NSG1, which is configured to deny all outbound internet traffic."}, {"p": "You must allow the virtual machines to access Vault1. The solution must follow the principle of least privilege and require minimal ongoing administration."}, {"p": "Which destination should you specify in the outbound security rule for NSG1?"}], "options": ["a service tag", "an application security group", "an IP address range"], "correct": [0], "multi": false, "explanation": [{"p": "a service tag is the correct answer here. To allow the virtual machines to access Vault1 (which is an Azure Key Vault resource) while keeping outbound internet access blocked, you should configure the NSG outbound rule to allow traffic only to the AzureKeyVault service tag."}, {"p": "Service tags represent a group of IP address prefixes for specific Azure services and are automatically maintained by Microsoft, which minimizes administrative effort and adheres to the principle of least privilege. By using the AzureKeyVault service tag, you allow access only to Key Vault endpoints and nothing else on the internet, satisfying both security and operational requirements."}, {"p": "an application security group is incorrect because ASGs are used to group VMs and simplify NSG rules within a virtual network, not for allowing access to Azure services like Key Vault."}, {"p": "an IP address range is incorrect because allowing access via public IP ranges to Key Vault would require you to manage and update the ranges manually, which increases administrative overhead and violates the principle of least privilege."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/service-tags-overview", "https://learn.microsoft.com/en-us/azure/key-vault/general/network-security", "https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"], "group": "G35"}, {"id": "T1-Q83", "test": 1, "num": 83, "domain": "network", "stem": [{"p": "You have an Azure subscription that contains the following virtual machines, all deployed in the same virtual network (VNET1):"}, {"p": "VM-A"}, {"p": "OS: Windows Server"}, {"p": "Subnet: SubnetA"}, {"p": "VM-B"}, {"p": "OS: Windows Server"}, {"p": "Subnet: SubnetB"}, {"p": "VM-C"}, {"p": "OS: Red Hat Enterprise Linux"}, {"p": "Subnet: SubnetC"}, {"p": "Each virtual machine’s network interface is configured with the following DNS settings:"}, {"p": "VM-A -> No DNS server configured"}, {"p": "VM-B -> 192.168.10.15"}, {"p": "VM-C -> 192.168.10.15"}, {"p": "At the virtual network level, custom DNS settings are configured with the following DNS server:"}, {"p": "193.77.134.10"}, {"p": "All virtual machines can successfully reach both DNS servers (192.168.10.15 and 193.77.134.10)."}, {"p": "True or False:"}, {"p": "“VM-A connects to 193.77.134.10 for DNS queries.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because VM-A does not have a custom DNS server configured at the network interface level. In such cases, Azure virtual machines inherit their DNS server settings from the virtual network (VNET) they are connected to. From the information provided, VNET1 is configured with a single custom DNS server: 193.77.134.10. Therefore, VM-A uses 193.77.134.10 for DNS queries. The DNS server 192.168.10.15 is manually configured only for VM-B and VM-C at their respective NIC level and is not part of the VNET-wide configuration. Since VM-A lacks its own DNS override, it relies solely on the VNET1 configuration."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-name-resolution-for-vms-and-role-instances", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-faq#can-i-specify-a-custom-dns-server", "https://learn.microsoft.com/en-us/azure/dns/dns-overview"], "group": "G36"}, {"id": "T1-Q84", "test": 1, "num": 84, "domain": "network", "stem": [{"p": "You have an Azure subscription that contains the following virtual machines, all deployed in the same virtual network (VNET1):"}, {"p": "VM-A"}, {"p": "OS: Windows Server"}, {"p": "Subnet: SubnetA"}, {"p": "VM-B"}, {"p": "OS: Windows Server"}, {"p": "Subnet: SubnetB"}, {"p": "VM-C"}, {"p": "OS: Red Hat Enterprise Linux"}, {"p": "Subnet: SubnetC"}, {"p": "Each virtual machine’s network interface is configured with the following DNS settings:"}, {"p": "VM-A -> No DNS server configured"}, {"p": "VM-B -> 192.168.10.15"}, {"p": "VM-C -> 192.168.10.15"}, {"p": "At the virtual network level, custom DNS settings are configured with the following DNS server:"}, {"p": "193.77.134.10"}, {"p": "All virtual machines can successfully reach both DNS servers (192.168.10.15 and 193.77.134.10)."}, {"p": "True or False:"}, {"p": "“VM-B connects to 193.77.134.10 for DNS queries”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer because VM-B is explicitly configured with a custom DNS server: 192.168.10.15 on its network interface."}, {"p": "When a virtual machine has a DNS server manually set at the NIC level, this custom setting overrides the DNS settings inherited from the virtual network (VNET1)."}, {"p": "As a result, VM-B will only use 192.168.10.15 for DNS resolution, and it will not use the secondary DNS server (193.77.134.10) defined at the VNET level unless 193.77.134.10 is manually added as a secondary DNS server on the NIC itself."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-name-resolution-for-vms-and-role-instances", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-faq#can-i-specify-a-custom-dns-server", "https://learn.microsoft.com/en-us/azure/dns/dns-overview"], "group": "G36"}, {"id": "T1-Q85", "test": 1, "num": 85, "domain": "network", "stem": [{"p": "You have an Azure subscription that contains the following virtual machines, all deployed in the same virtual network (VNET1):"}, {"p": "VM-A"}, {"p": "OS: Windows Server"}, {"p": "Subnet: SubnetA"}, {"p": "VM-B"}, {"p": "OS: Windows Server"}, {"p": "Subnet: SubnetB"}, {"p": "VM-C"}, {"p": "OS: Red Hat Enterprise Linux"}, {"p": "Subnet: SubnetC"}, {"p": "Each virtual machine’s network interface is configured with the following DNS settings:"}, {"p": "VM-A -> No DNS server configured"}, {"p": "VM-B -> 192.168.10.15"}, {"p": "VM-C -> 192.168.10.15"}, {"p": "At the virtual network level, custom DNS settings are configured with the following DNS server:"}, {"p": "193.77.134.10"}, {"p": "All virtual machines can successfully reach both DNS servers (192.168.10.15 and 193.77.134.10)."}, {"p": "True or False:"}, {"p": "“VM-C connects to 192.168.10.15 for DNS queries.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer because VM-C is explicitly configured with the DNS server 192.168.10.15 on its network interface."}, {"p": "In Azure, when a virtual machine’s NIC is manually configured with a DNS server IP, it overrides the DNS server settings configured at the virtual network level. As a result, VM-C will use 192.168.10.15 for all DNS queries unless that server is unreachable and multiple DNS servers are configured on the NIC (which is not shown in this case)."}, {"p": "Therefore, VM-C connects to 192.168.10.15 for DNS resolution."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-name-resolution-for-vms-and-role-instances", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-faq#can-i-specify-a-custom-dns-server", "https://learn.microsoft.com/en-us/azure/dns/dns-overview"], "group": "G36"}, {"id": "T1-Q86", "test": 1, "num": 86, "domain": "network", "stem": [{"p": "You have an Azure subscription that contains the following virtual networks:"}, {"p": "VNet-West (Region: West Europe)"}, {"p": "VNet-Asia (Region: Southeast Asia)"}, {"p": "VNet-US (Region: South Central US)"}, {"p": "The subscription also includes the following subnets:"}, {"p": "Subnet-A"}, {"p": "Virtual network: VNet-West"}, {"p": "Service endpoint: None"}, {"p": "Subnet-B"}, {"p": "Virtual network: VNet-Asia"}, {"p": "Service endpoint: Microsoft.Storage"}, {"p": "Subnet-C"}, {"p": "Virtual network: VNet-US"}, {"p": "Service endpoint: Microsoft.Storage"}, {"p": "Subnet-D"}, {"p": "Virtual network: VNet-US"}, {"p": "Service endpoint: None"}, {"p": "Additionally, the following storage accounts exist:"}, {"p": "storagewest01"}, {"p": "Region: West Europe"}, {"p": "Kind: StorageV2"}, {"p": "storageus01"}, {"p": "Region: South Central US"}, {"p": "Kind: BlobStorage"}, {"p": "storageasia01"}, {"p": "Region: Southeast Asia"}, {"p": "Kind: StorageV2"}, {"p": "You create a service endpoint policy named StoragePolicy01 in the South Central US region. The policy is configured to allow access to all storage accounts in the subscription."}, {"p": "True or False:"}, {"p": "“StoragePolicy01 can be applied to Subnet-C.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer because Subnet-C is in VNet-US, which is located in the South Central US region, the same region in which the service endpoint policy (StoragePolicy01) was created."}, {"p": "For a service endpoint policy to be applied to a subnet:"}, {"p": "The subnet must have a matching service endpoint (in this case, Microsoft.Storage)."}, {"p": "The subnet and the service endpoint policy must be in the same region."}, {"p": "Since Subnet3 has a Microsoft.Storage endpoint enabled and is located in the South Central US region (same as StoragePolicy01), it meets both conditions and therefore Policy1 can be applied to Subnet3."}, {"img": "az104/img/t1_image18.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies-overview#limitations", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoints-overview"], "group": "G37"}, {"id": "T1-Q87", "test": 1, "num": 87, "domain": "network", "stem": [{"p": "You have an Azure subscription that contains the following virtual networks:"}, {"p": "VNet-West (Region: West Europe)"}, {"p": "VNet-Asia (Region: Southeast Asia)"}, {"p": "VNet-US (Region: South Central US)"}, {"p": "The subscription also includes the following subnets:"}, {"p": "Subnet-A"}, {"p": "Virtual network: VNet-West"}, {"p": "Service endpoint: None"}, {"p": "Subnet-B"}, {"p": "Virtual network: VNet-Asia"}, {"p": "Service endpoint: Microsoft.Storage"}, {"p": "Subnet-C"}, {"p": "Virtual network: VNet-US"}, {"p": "Service endpoint: Microsoft.Storage"}, {"p": "Subnet-D"}, {"p": "Virtual network: VNet-US"}, {"p": "Service endpoint: None"}, {"p": "Additionally, the following storage accounts exist:"}, {"p": "storagewest01"}, {"p": "Region: West Europe"}, {"p": "Kind: StorageV2"}, {"p": "storageus01"}, {"p": "Region: South Central US"}, {"p": "Kind: BlobStorage"}, {"p": "storageasia01"}, {"p": "Region: Southeast Asia"}, {"p": "Kind: StorageV2"}, {"p": "You create a service endpoint policy named StoragePolicy01 in the South Central US region. The policy is configured to allow access to all storage accounts in the subscription."}, {"p": "True or False:"}, {"p": "“Only storagewest01 and storageus01 can be accessed from VNet-Asia.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer because Subnet-B in VNet-Asia has the Microsoft.Storage service endpoint enabled, and no service endpoint policy is associated with that subnet. When a subnet has a Storage service endpoint enabled and no endpoint policy restricting access, it can connect to any Azure Storage account that allows access through service endpoints, regardless of the region."}, {"p": "In this scenario:"}, {"p": "VNet-Asia is in Southeast Asia"}, {"p": "Subnet-B has the Microsoft.Storage service endpoint enabled"}, {"p": "No service endpoint policy is applied to Subnet-B"}, {"p": "Therefore, Subnet-B can access all storage accounts that permit service endpoint traffic, including:"}, {"p": "storagewest01 (West Europe)"}, {"p": "storageus01 (South Central US)"}, {"p": "storageasia01 (Southeast Asia)"}, {"p": "The service endpoint policy StoragePolicy01 does not affect Subnet-B because it is not associated with that subnet."}, {"p": "The statement is incorrect because access is not limited to only storagewest01 and storageus01. The subnet can also access storageasia01."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies-overview#limitations", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoints-overview"], "group": "G37"}, {"id": "T1-Q88", "test": 1, "num": 88, "domain": "network", "stem": [{"p": "You have an Azure subscription that contains the following virtual networks:"}, {"p": "VNet-West (Region: West Europe)"}, {"p": "VNet-Asia (Region: Southeast Asia)"}, {"p": "VNet-US (Region: South Central US)"}, {"p": "The subscription also includes the following subnets:"}, {"p": "Subnet-A"}, {"p": "Virtual network: VNet-West"}, {"p": "Service endpoint: None"}, {"p": "Subnet-B"}, {"p": "Virtual network: VNet-Asia"}, {"p": "Service endpoint: Microsoft.Storage"}, {"p": "Subnet-C"}, {"p": "Virtual network: VNet-US"}, {"p": "Service endpoint: Microsoft.Storage"}, {"p": "Subnet-D"}, {"p": "Virtual network: VNet-US"}, {"p": "Service endpoint: None"}, {"p": "Additionally, the following storage accounts exist:"}, {"p": "storagewest01"}, {"p": "Region: West Europe"}, {"p": "Kind: StorageV2"}, {"p": "storageus01"}, {"p": "Region: South Central US"}, {"p": "Kind: BlobStorage"}, {"p": "storageasia01"}, {"p": "Region: Southeast Asia"}, {"p": "Kind: StorageV2"}, {"p": "You create a service endpoint policy named StoragePolicy01 in the South Central US region. The policy is configured to allow access to all storage accounts in the subscription."}, {"p": "True or False:"}, {"p": "\"Only storageus01 can be accessed from VNet-US.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer because VNet-US is in the South Central US region, and both Subnet-C and Subnet-D belong to VNet-US. While Subnet-C has a Microsoft.Storage service endpoint and StoragePolicy01 applied, Subnet-D does not have any service endpoint or policy."}, {"p": "Here's what that means:"}, {"p": "Subnet-C can access only storage accounts allowed by StoragePolicy01, which includes storagewest01, storageus01, and storageasia01 (all storage accounts in the subscription), even though it is in South Central US."}, {"p": "Subnet-D, which has no service endpoint configured, can still access public endpoints of any storage account over the internet if firewall rules and access configurations allow it."}, {"p": "Therefore, it is incorrect to say that only storageus01 can be accessed from VNet-US. In fact, storagewest01, storageus01, and storageasia01 can all potentially be accessed depending on which subnet the traffic originates from and whether it goes through the service endpoint or over the public internet."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies-overview#limitations", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoints-overview"], "group": "G37"}, {"id": "T1-Q89", "test": 1, "num": 89, "domain": "identity", "stem": [{"p": "You manage an Azure subscription."}, {"p": "You need to create a custom Azure RBAC role with the following requirements:"}, {"p": "The assigned users must be able to perform all management operations for a virtual network."}, {"p": "The permissions must adhere to the principle of least privilege, meaning no unnecessary access beyond what is required to manage the virtual network."}, {"p": "Which permissions should you specify in the role definition to meet these requirements?"}], "options": ["\"Microsoft.Network/virtualNetworks/*\"", "\"Microsoft.Network/virtualNetworks/delete\"", "\"Microsoft.Network/virtualNetworks/write\""], "correct": [0], "multi": false, "explanation": [{"p": "\"Microsoft.Network/virtualNetworks/*\" is the correct answer because it grants permission to perform all actions on virtual networks, including read, write, delete, and other operations such as joining subnets or modifying settings. The asterisk * is a wildcard that encompasses all actions under the Microsoft.Network/virtualNetworks resource provider. This meets the requirement that users must be able to perform all actions on a virtual network."}, {"p": "\"Microsoft.Network/virtualNetworks/delete\" is incorrect because it grants only the ability to delete virtual networks and does not include permissions to read, write, or manage other aspects of the virtual network."}, {"p": "\"Microsoft.Network/virtualNetworks/write\" is incorrect because it only provides write access (e.g., create or update) but not read or delete access, and therefore does not fulfill the requirement of allowing all actions."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/custom-roles", "https://learn.microsoft.com/en-us/azure/role-based-access-control/resource-provider-operations", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"], "group": "G38"}, {"id": "T1-Q90", "test": 1, "num": 90, "domain": "identity", "stem": [{"p": "You manage an Azure subscription."}, {"p": "You need to create a custom Azure RBAC role with the following requirements:"}, {"p": "Users must be able to view the configuration settings of a storage account."}, {"p": "The permissions must adhere to the principle of least privilege, meaning no unnecessary access beyond what is required to manage the virtual network."}, {"p": "Which permissions should you specify in the role definition to meet these requirements?"}, {"p": "\"Microsoft.Storage/StorageAccounts/*\""}], "options": ["\"Microsoft.Storage/StorageAccounts/read\"", "\"Microsoft.Storage/StorageAccounts/blobServices/containers/blob/read\""], "correct": [0], "multi": false, "explanation": [{"p": "\"Microsoft.Storage/storageAccounts/read\" is the correct answer because it grants users read-only access to the configuration and metadata of the storage account (such as properties, settings, keys, and networking configurations), without allowing any modifications or access to the actual data stored in blobs, queues, or files. This fully aligns with the principle of least privilege and the stated requirement to view configuration data only."}, {"p": "\"Microsoft.Storage/storageAccounts/*\" is incorrect because it grants all permissions on the storage account, including write and delete operations, which violates the principle of least privilege."}, {"p": "\"Microsoft.Storage/storageAccounts/blobServices/containers/blobs/read\" is incorrect because it only provides read access to blob data, not to the configuration settings of the storage account itself."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/resource-provider-operations", "https://learn.microsoft.com/en-us/azure/storage/common/storage-account-overview", "https://learn.microsoft.com/en-us/azure/role-based-access-control/custom-roles"], "group": "G39"}, {"id": "T2-Q1", "test": 2, "num": 1, "domain": "storage", "stem": [{"p": "An Azure subscription contains three virtual machines. Each VM has an assigned public IP address and is connected to a subnet within VNet1."}, {"p": "The configuration is as follows:"}, {"p": "VM1 – Public IP: 131.107.10.10 – Connected to VNet1/Subnet1"}, {"p": "VM2 – Public IP: 150.120.10.10 – Connected to VNet1/Subnet2"}, {"p": "VM3 – Public IP: 170.20.10.10 – Connected to VNet1/Subnet1"}, {"p": "The subscription also contains a storage account named contoso2024, which is configured with network access restrictions as shown in the exhibit."}, {"img": "az104/img/t2_image1.webp"}, {"p": "Based on the current firewall and virtual network settings of the storage account, evaluate the following statement."}, {"p": "True or False:"}, {"p": "\"VM1 can connect to contoso2024 by using 131.107.10.10.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because VM1 can connect to the contoso2024 storage account using the IP address 131.107.10.10. The storage account's firewall settings allow access from selected IP addresses, and 131.107.10.10, the public IP address of VM1, is explicitly listed as an allowed address. Additionally, VM1 is connected to VNet1/Subnet1, and the storage account is configured to accept traffic from VNet1/Subnet1 as well."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security?tabs=azure-portal", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"], "group": "G40"}, {"id": "T2-Q2", "test": 2, "num": 2, "domain": "storage", "stem": [{"p": "An Azure subscription contains three virtual machines. Each VM has an assigned public IP address and is connected to a subnet within VNet1."}, {"p": "The configuration is as follows:"}, {"p": "VM1 – Public IP: 131.107.10.10 – Connected to VNet1/Subnet1"}, {"p": "VM2 – Public IP: 150.120.10.10 – Connected to VNet1/Subnet2"}, {"p": "VM3 – Public IP: 170.20.10.10 – Connected to VNet1/Subnet1"}, {"p": "The subscription also contains a storage account named contoso2024, which is configured with network access restrictions as shown in the exhibit."}, {"img": "az104/img/t2_image1.webp"}, {"p": "Based on the current firewall and virtual network settings of the storage account, evaluate the following statement."}, {"p": "True or False:"}, {"p": "\"VM2 can connect to contoso2024 by using 150.120.10.10.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because VM2 has the public IP address 150.120.10.10, which is explicitly listed in the firewall rules of the contoso2024 storage account. While VM2 is connected to VNet1/Subnet2 (a different subnet than Subnet1), the public IP address being listed in the firewall allows VM2 to connect to the storage account, regardless of its subnet within VNet1."}, {"p": "Therefore, VM2 can still connect to contoso2024 using its public IP address."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security?tabs=azure-portal", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"], "group": "G40"}, {"id": "T2-Q3", "test": 2, "num": 3, "domain": "storage", "stem": [{"p": "An Azure subscription contains three virtual machines. Each VM has an assigned public IP address and is connected to a subnet within VNet1."}, {"p": "The configuration is as follows:"}, {"p": "VM1 – Public IP: 131.107.10.10 – Connected to VNet1/Subnet1"}, {"p": "VM2 – Public IP: 150.120.10.10 – Connected to VNet1/Subnet2"}, {"p": "VM3 – Public IP: 170.20.10.10 – Connected to VNet1/Subnet1"}, {"p": "The subscription also contains a storage account named contoso2024, which is configured with network access restrictions as shown in the exhibit."}, {"img": "az104/img/t2_image1.webp"}, {"p": "Based on the current firewall and virtual network settings of the storage account, evaluate the following statement."}, {"p": "True or False:"}, {"p": "\"VM3 must use its private IP address to connect to contoso2024.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because although VM3 is in VNet1/Subnet1, which is allowed in the storage account’s virtual network rules, the firewall configuration also explicitly permits VM3’s public IP address. This means VM3 is not strictly forced to use its private IP for connectivity. The word “must” makes the statement incorrect: VM3 can connect using its private IP via the service endpoint, but it could also connect using its public IP since that IP is in the firewall allowlist."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security?tabs=azure-portal", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"], "group": "G40"}, {"id": "T2-Q4", "test": 2, "num": 4, "domain": "compute", "stem": [{"p": "You have an Azure App Service plan named AppServicePlanA that is configured with the Standard pricing tier."}, {"p": "You need to configure the plan so that it automatically increases its instance count whenever the web app’s CPU utilization exceeds 80 percent."}, {"p": "Which configuration setting should you enable for AppServicePlanA to achieve this behavior?"}], "options": ["Automatic scaling configured in the Scale out settings", "Rule-based scaling configured in the Scale out settings", "Premium P1 selected under the Scale up (App Service plan) settings", "Standard S1 selected under the Scale up (App Service plan) settings", "Manual scaling configured in the Scale out settings"], "correct": [1], "multi": false, "explanation": [{"p": "Rule-based scaling configured in the Scale out settings is the correct answer here. By selecting Rules Based, you can configure specific conditions for automatic scaling, such as when CPU usage exceeds 80 percent. This allows AppServicePlanA to automatically add more instances when the CPU utilization goes above the defined threshold. In this case, a rule can be created to automatically scale out based on CPU performance, which satisfies the requirement."}, {"p": "Automatic scaling configured in the Scale out settings is incorrect because it doesn't allow setting specific scaling conditions, such as CPU thresholds."}, {"p": "Manual scaling configured in the Scale out settings is incorrect because it requires manual intervention to scale, which does not meet the requirement of automatic scaling when CPU usage exceeds 80 percent."}, {"p": "Premium P1 selected under the Scale up (App Service plan) settings and"}, {"p": "Standard S1 selected under the Scale up (App Service plan) settings are incorrect because these refer to scaling up (increasing the resources of the plan itself), not scaling out (adding more instances) based on a specific condition like CPU usage."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/manage-scale-up", "https://learn.microsoft.com/en-us/training/modules/scale-apps-app-service/2-autoscale-factors"], "group": "G41"}, {"id": "T2-Q5", "test": 2, "num": 5, "domain": "network", "stem": [{"p": "You have an Azure virtual network named VNet1 with the following configuration:"}, {"p": "The IPv4 address space is 172.16.10.0/24"}, {"p": "A subnet named Subnet1 exists within the virtual network"}, {"p": "Subnet1 uses the address range 172.16.10.0/25"}, {"p": "Based on this configuration, what is the maximum number of virtual machines that can be deployed and connected to Subnet1?"}], "options": ["24", "25", "123", "128", "251"], "correct": [2], "multi": false, "explanation": [{"p": "123 is the correct answer. The subnet 172.16.10.0/25 has a total of 128 IP addresses. However, Azure reserves the first four and the last IP address in every subnet for internal use. Therefore, the available IP addresses for virtual machines are:"}, {"p": "128 (total IP addresses) - 5 (reserved addresses) = 123 usable IP addresses."}, {"p": "These 123 addresses can be assigned to virtual machines or other resources within the subnet."}, {"p": "172.16.10.0/25 means the subnet has 128 total IP addresses (2^7 = 128)."}, {"p": "Azure reserves five IP addresses in each subnet:"}, {"p": "The first IP is the network address."}, {"p": "The second through fourth IP addresses are reserved for Azure services."}, {"p": "The last IP address is reserved for the broadcast address."}, {"p": "Thus, 123 addresses remain available for virtual machines."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-faq"], "group": "G42"}, {"id": "T2-Q6", "test": 2, "num": 6, "domain": "identity", "stem": [{"p": "Your environment includes an on-premises Active Directory Domain Services (AD DS) domain with the identities listed below:"}, {"p": "User1 is a user account located in OU2."}, {"p": "User2 is a user account located in OU1."}, {"p": "Group1 is a global security group that includes User1 and is located in OU1."}, {"p": "You have an Azure subscription that contains a storage account named storage1."}, {"p": "The Azure Files shares in storage1 use AD DS as the identity source, and the default share-level permissions are configured to allow access for all authenticated users and groups."}, {"p": "You create an Azure Files share named share1 and assign the following roles:"}, {"p": "User2 is assigned the Storage File Data SMB Share Reader role."}, {"p": "Group1 is assigned the Storage File Data SMB Share Contributor role."}, {"p": "You also have a Microsoft Entra tenant that includes a cloud-only user named User3."}, {"p": "Microsoft Entra Connect is configured to synchronize OU1 from the on-premises AD DS domain to the Microsoft Entra tenant."}, {"p": "True or False:"}, {"p": "“User1 is able to access the data stored in share1.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer because User1 can access share1 by using AD DS authentication, even though User1 is not synchronized to Microsoft Entra ID."}, {"p": "The storage account uses AD DS as the identity source, and default share-level permissions are enabled for all authenticated users and groups. For Azure Files with AD DS authentication, Microsoft states that when a default share-level permission is configured, on-premises AD DS identities do not need to be synchronized to Microsoft Entra ID. The identity only needs to authenticate against the AD DS deployment associated with the storage account."}, {"p": "In addition, User1 is a member of Group1 in the on-premises AD DS domain. Group1 is located in OU1, is synchronized to Microsoft Entra ID, and has the Storage File Data SMB Share Contributor role on share1. Microsoft states that for AD DS authentication, non-synchronized users can still access Azure file shares through membership in a synchronized AD DS group. Azure Files reads the group SIDs from the user’s Kerberos ticket and applies the matching RBAC role assignments."}, {"p": "Therefore, User1 can access the data in share1, assuming the applicable NTFS/file-level permissions do not deny access. Azure Files evaluates both share-level permissions and Windows ACLs, and the most restrictive permission applies."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-ad-ds-assign-permissions?tabs=azure-portal", "https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-assign-share-level-permissions?tabs=azure-portal", "https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-configure-file-level-permissions"], "group": "G43"}, {"id": "T2-Q7", "test": 2, "num": 7, "domain": "identity", "stem": [{"p": "Your environment includes an on-premises Active Directory Domain Services (AD DS) domain with the identities listed below:"}, {"p": "User1 is a user account located in OU2."}, {"p": "User2 is a user account located in OU1."}, {"p": "Group1 is a global security group that includes User1 and is located in OU1."}, {"p": "You have an Azure subscription that contains a storage account named storage1."}, {"p": "The Azure Files shares in storage1 use AD DS as the identity source, and the default share-level permissions are configured to allow access for all authenticated users and groups."}, {"p": "You create an Azure Files share named share1 and assign the following roles:"}, {"p": "User2 is assigned the Storage File Data SMB Share Reader role."}, {"p": "Group1 is assigned the Storage File Data SMB Share Contributor role."}, {"p": "You also have a Microsoft Entra tenant that includes a cloud-only user named User3."}, {"p": "Microsoft Entra Connect is configured to synchronize OU1 from the on-premises AD DS domain to the Microsoft Entra tenant."}, {"p": "True or False:"}, {"p": "\"User2 can access content in share1.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct."}, {"p": "User2 can access share1 because User2 is located in OU1, and OU1 is synchronized to Microsoft Entra ID. User2 is also explicitly assigned the Storage File Data SMB Share Reader role on share1, which grants read access at the Azure Files share level."}, {"p": "Additionally, the question states that the default share-level permissions are configured to allow access for all authenticated users and groups. Therefore, even without the explicit RBAC assignment, User2 could still be allowed at the share level if User2 can authenticate against the associated AD DS domain and the default permission grants sufficient access."}, {"p": "However, Azure Files access is controlled by both share-level permissions and NTFS file/directory permissions. Therefore, actual access to the content also depends on the applicable NTFS ACLs. In this question, no restrictive NTFS ACL is mentioned, so User2 can access the content in share1."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-ad-ds-assign-permissions?tabs=azure-portal"], "group": "G43"}, {"id": "T2-Q8", "test": 2, "num": 8, "domain": "identity", "stem": [{"p": "Your environment includes an on-premises Active Directory Domain Services (AD DS) domain with the identities listed below:"}, {"p": "User1 is a user account located in OU2."}, {"p": "User2 is a user account located in OU1."}, {"p": "Group1 is a global security group that includes User1 and is located in OU1."}, {"p": "You have an Azure subscription that contains a storage account named storage1."}, {"p": "The Azure Files shares in storage1 use AD DS as the identity source, and the default share-level permissions are configured to allow access for all authenticated users and groups."}, {"p": "You create an Azure Files share named share1 and assign the following roles:"}, {"p": "User2 is assigned the Storage File Data SMB Share Reader role."}, {"p": "Group1 is assigned the Storage File Data SMB Share Contributor role."}, {"p": "You also have a Microsoft Entra tenant that includes a cloud-only user named User3."}, {"p": "Microsoft Entra Connect is configured to synchronize OU1 from the on-premises AD DS domain to the Microsoft Entra tenant."}, {"p": "True or False:"}, {"p": "\"User3 can access content in share1.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct. For AD DS-based Azure Files authentication, Azure Files uses Kerberos through the configured identity source, and Microsoft states that only hybrid identities that exist in both on-premises AD DS and Microsoft Entra ID can be authenticated and authorized for Azure file share access. Also, a storage account can use only one identity source for SMB identity-based authentication, so cloud-only access would require a different identity source such as Microsoft Entra Kerberos, not AD DS."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-ad-ds-assign-permissions?tabs=azure-portal"], "group": "G43"}, {"id": "T2-Q9", "test": 2, "num": 9, "domain": "network", "stem": [{"p": "You manage two Azure subscriptions, Sub1 and Sub2. Each subscription is linked to a separate Microsoft Entra tenant."}, {"p": "The environment includes the following virtual networks:"}, {"p": "VNet1 – Located in East US – Associated with Sub1"}, {"p": "VNet2 – Located in East US – Associated with Sub1"}, {"p": "VNet3 – Located in West US – Associated with Sub1"}, {"p": "VNet4 – Located in East US – Associated with Sub2"}, {"p": "VNet5 – Located in Central US – Associated with Sub2"}, {"p": "You want to establish virtual network peering from VNet1."}, {"p": "Which of the listed virtual networks are eligible to be peered with VNet1?"}], "options": ["VNet2 only", "VNet2 and VNet3 only", "VNet2 and VNet4 only", "VNet2, VNet3, and VNet4 only", "VNet2, VNet3, VNet4, and VNet5"], "correct": [4], "multi": false, "explanation": [{"p": "VNet1 can peer with VNet2, VNet3, VNet4, and VNet5 because global virtual network peering allows you to peer virtual networks across different regions and subscriptions, even when they are linked to different Microsoft Entra tenants."}, {"p": "VNet2: Same region (East US), same subscription (Sub1)."}, {"p": "VNet3: Different region (West US), same subscription (Sub1)."}, {"p": "VNet4: Same region (East US), different subscription (Sub2)."}, {"p": "VNet5: Different region (Central US), different subscription (Sub2)."}, {"p": "With global VNet peering, you can enable communication between virtual networks in different regions and subscriptions, as long as the necessary permissions are configured."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview"], "group": "G44"}, {"id": "T2-Q10", "test": 2, "num": 10, "domain": "storage", "stem": [{"p": "You have an Azure subscription that includes a storage account named storage1."}, {"p": "You want to restrict access to storage1 so that it is reachable only from specific networks and from your home office. The approach must require the least amount of ongoing administrative effort."}, {"p": "What is the first configuration change you should make for storage1?"}], "options": ["Create a private endpoint for the storage account.", "Update the public network access configuration for the storage account.", "Configure the storage account to use internet-based routing.", "Change the role-based access control (IAM) settings."], "correct": [1], "multi": false, "explanation": [{"p": "Update the public network access configuration for the storage account is the correct answer here. To allow access to storage1 from selected networks and your home office while minimizing administrative effort, you should first modify the Public network access settings. By selecting the option to allow access only from selected virtual networks and IP addresses, you can define specific networks and IP addresses, such as your home office's public IP address, without needing to configure more complex solutions like private endpoints."}, {"p": "Create a private endpoint for the storage account is incorrect because private endpoints require additional setup and would only allow access through a private network, not minimizing administrative effort."}, {"p": "Configure the storage account to use internet-based routing is incorrect because this would open the storage account to access from the internet, which doesn't fulfill the requirement of limiting access to selected networks and your home office."}, {"p": "Change the role-based access control (IAM) settings is incorrect because IAM controls user and group permissions for accessing resources but does not control network access."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security?tabs=azure-portal", "https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security?tabs=azure-portal#public-network-access"], "group": "G45"}, {"id": "T2-Q11", "test": 2, "num": 11, "domain": "compute", "stem": [{"p": "An Azure subscription contains three Azure Container Registry (ACR) instances. Each registry is configured with a different pricing tier:"}, {"p": "ContReg1 – Service tier: Premium"}, {"p": "ContReg2 – Service tier: Standard"}, {"p": "ContReg3 – Service tier: Basic"}, {"p": "You plan to use Azure Container Registry (ACR) Tasks and also require support for private endpoint connections."}, {"p": "Which of the listed container registries can be used to run ACR Tasks?"}], "options": ["ContReg1 only", "ContReg1 and ContReg2 only", "ContReg1, ContReg2, and ContReg3"], "correct": [2], "multi": false, "explanation": [{"p": "ContReg1, ContReg2, and ContReg3 is the correct answer here. ACR Tasks are supported in all service tiers: Basic, Standard, and Premium. While there are performance and feature differences across the tiers (such as the number of concurrent tasks or webhook triggers), ACR Tasks functionality is available in all three tiers, including Basic."}, {"img": "az104/img/t2_image2.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-skus"], "group": "G46"}, {"id": "T2-Q12", "test": 2, "num": 12, "domain": "compute", "stem": [{"p": "An Azure subscription contains three Azure Container Registry (ACR) instances. Each registry is configured with a different pricing tier:"}, {"p": "ContReg1 – Service tier: Premium"}, {"p": "ContReg2 – Service tier: Standard"}, {"p": "ContReg3 – Service tier: Basic"}, {"p": "You plan to use Azure Container Registry (ACR) Tasks and also require support for private endpoint connections."}, {"p": "Which of the container registries can be configured to use private endpoints?"}], "options": ["ContReg1 only", "ContReg1 and ContReg2 only", "ContReg1, ContReg2, and ContReg3"], "correct": [0], "multi": false, "explanation": [{"p": "ContReg1 only is the correct answer because only the Premium tier of Azure Container Registry supports private endpoints. ContReg1 is configured with the Premium tier, which allows the use of private endpoints. Standard and Basic tiers, as seen in ContReg2 and ContReg3, do not support private endpoints."}, {"img": "az104/img/t2_image3.webp"}, {"p": "ContReg1 and ContReg2 only is incorrect because the Standard tier (used by ContReg2) does not support private endpoints."}, {"p": "ContReg1, ContReg2, and ContReg3 is incorrect because neither the Standard nor Basic tiers (used by ContReg2 and ContReg3) support private endpoints."}], "refs": ["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-skus"], "group": "G46"}, {"id": "T2-Q13", "test": 2, "num": 13, "domain": "compute", "stem": [{"p": "You have an Azure container registry named contoso2023 as shown below."}, {"img": "az104/img/t2_image4.webp"}, {"p": "You want to configure contoso2023 so that it uses a dedicated data endpoint for data operations."}, {"p": "Which two configuration settings must you enable or modify on contoso2023 to meet this requirement?"}], "options": ["Overview", "Properties", "Networking", "Tasks", "Access control (IAM)", "Events"], "correct": [1, 2], "multi": true, "explanation": [{"p": "To enable contoso2023 to use a dedicated data endpoint, you need to configure the following two settings:"}, {"p": "Properties: This is where you can enable and configure the dedicated data endpoint for your Azure container registry. From this blade, you must first change the pricing plan from Standard to Premium. This setting is crucial for routing all data plane operations through a dedicated endpoint."}, {"p": "Networking: After the registry is upgraded to Premium, you must go to Networking and enable the dedicated data endpoint setting. Dedicated data endpoints provide registry-specific data endpoint URLs, such as <registry-name>.<region>.data.azurecr.io, for data operations."}, {"p": "Overview, Tasks, Access control (IAM), and Events are NOT relevant for enabling or configuring a dedicated data endpoint."}], "refs": ["https://learn.microsoft.com/en-gb/azure/container-registry/container-registry-firewall-access-rules#enable-dedicated-data-endpoints", "https://learn.microsoft.com/en-us/azure/container-registry/container-registry-private-link"], "group": "G47"}, {"id": "T2-Q14", "test": 2, "num": 14, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant named contoso.com."}, {"p": "You work with an external organization that uses the domain fabrikam.com."}, {"p": "You plan to invite external users from fabrikam.com into the contoso.com tenant."}, {"p": "You must ensure that invitations can be sent exclusively to users from fabrikam.com and not to users from any other external domains."}, {"p": "What configuration should you perform in the Microsoft Entra admin center?"}], "options": ["From Cross-tenant access settings, configure the Tenant restrictions settings.", "From Cross-tenant access settings, configure the Microsoft cloud settings.", "From External collaboration settings, configure the Guest user access restrictions settings.", "From External collaboration settings, configure the Collaboration restrictions settings."], "correct": [3], "multi": false, "explanation": [{"p": "From External collaboration settings, configure the Collaboration restrictions settings is the correct answer. In Microsoft Entra, you can restrict who can be invited as a guest by configuring Collaboration restrictions. By specifying the allowed domains, such as fabrikam.com, you can ensure that invitations can only be sent to users from that domain."}, {"p": "From Cross-tenant access settings, configure the Tenant restrictions settings is incorrect because tenant restrictions are used to control which tenants users can access, not to restrict guest invitations."}, {"p": "From Cross-tenant access settings, configure the Microsoft cloud settings is incorrect because these settings are used for managing cross-tenant access policies between Microsoft cloud environments, not for restricting guest user invitations."}, {"p": "From External collaboration settings, configure the Guest user access restrictions settings is incorrect because this setting controls what guest users can do once they are in your tenant, not who can be invited."}], "refs": ["https://learn.microsoft.com/en-us/entra/external-id/external-collaboration-settings-configure"], "group": "G48"}, {"id": "T2-Q15", "test": 2, "num": 15, "domain": "compute", "stem": [{"p": "You have an Azure subscription that includes three virtual machines named VM1, VM2, and VM3. All three virtual machines are deployed in the same availability set called AVSet1."}, {"p": "You want to resize VM1 to a larger virtual machine size. However, the target size is currently not available."}, {"p": "What action should you take first?"}], "options": ["Create a proximity placement group and associate it with the virtual machines.", "Deallocate VM1.", "Convert AvSet1 into a managed availability set.", "Power off VM2 and VM3."], "correct": [1], "multi": false, "explanation": [{"p": "Deallocate VM1 is the correct answer here. When a specific virtual machine size is unavailable for a VM that is part of an availability set (like AVSet1), the first step is to deallocate the virtual machine. Deallocating the VM releases the hardware allocation, potentially freeing up capacity for the new VM size. Once the VM is deallocated, you can attempt to resize it."}, {"p": "Create a proximity placement group and associate it with the virtual machines is incorrect because proximity placement groups are used to ensure low-latency placement of VMs but have no direct impact on resizing availability."}, {"p": "Convert AVSet1 into a managed availability set is incorrect because the availability set is already managed by default when using managed disks, and this action wouldn't resolve the size availability issue."}, {"p": "Power off VM2 and VM3 is incorrect because shutting down the other VMs in the availability set does not affect the resizing of VM1."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-machines/sizes/resize-vm?tabs=portal"], "group": "G49"}, {"id": "T2-Q16", "test": 2, "num": 16, "domain": "network", "stem": [{"p": "An Azure subscription contains the following resources:"}, {"p": "VM1 – Virtual machine"}, {"p": "VNet1 – Virtual network"}, {"p": "NIC1 – Network interface"}, {"p": "LB1 – Load balancer"}, {"p": "VPN1 – Virtual network gateway"}, {"p": "You create a new public IP address named IP1."}, {"p": "Which two of the listed resources can be linked to IP1?"}], "options": ["VM1", "LB1", "NIC1", "VPN1", "VNet1"], "correct": [1, 2], "multi": true, "explanation": [{"p": "LB1 (Load balancer) and NIC1 (Network interface) are the correct answers. Public IP addresses can be associated with a load balancer or a network interface to enable external communication with resources like virtual machines or services behind the load balancer."}, {"p": "LB1: A public IP can be associated with a load balancer to distribute incoming traffic across multiple backend resources, such as virtual machines."}, {"p": "NIC1: A public IP can also be associated with a network interface, allowing a virtual machine to have direct access to the internet."}, {"p": "VM1 is incorrect because public IP addresses are associated with network interfaces (like NIC1) rather than directly with virtual machines."}, {"p": "VPN1 is incorrect because virtual network gateways use their own public IPs but are not directly associated with manually created public IPs."}, {"p": "VNet1 is incorrect because virtual networks themselves do not have public IP addresses directly associated with them."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/public-ip-addresses", "https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview"], "group": "G50"}, {"id": "T2-Q17", "test": 2, "num": 17, "domain": "network", "stem": [{"p": "You have an Azure subscription with two virtual networks, VNet1 and VNet2, that are peered with each other."}, {"p": "VNet1 includes a VPN gateway that is configured to use static routing."}, {"p": "The on-premises network has a VPN connection that uses the VPN gateway of VNet1."}, {"p": "You need to enable users from the on-premises network to access a virtual machine hosted in VNet2. The solution must be cost-effective."}, {"p": "Which connectivity approach should you implement?"}], "options": ["Deploy Azure Firewall and route traffic through its private IP address", "Use service chaining together with user-defined routes (UDRs)", "Deploy an Azure Application Gateway", "Provision an ExpressRoute circuit connected to VNet2"], "correct": [1], "multi": false, "explanation": [{"p": "Use service chaining together with user-defined routes (UDRs) is the correct answer. By using service chaining and configuring user-defined routes (UDRs), you can route traffic from the on-premises network, through the VPN gateway on VNet1, to VNet2. This setup leverages the existing peering between VNet1 and VNet2 without requiring additional costly infrastructure like Azure Firewall or ExpressRoute, thereby minimizing costs. UDRs will ensure that the traffic is directed through the correct paths."}, {"p": "Deploy Azure Firewall and route traffic through its private IP address is incorrect because while it could provide routing and security, it is more costly than using UDRs and is not necessary for this scenario."}, {"p": "Deploy an Azure Application Gateway is incorrect because this is primarily used for managing and load balancing web traffic, not for routing network traffic between VNets or from on-premises networks."}, {"p": "Provision an ExpressRoute circuit connected to VNet2 is incorrect because ExpressRoute is a high-cost solution that provides private connectivity between on-premises and Azure, which is not required since you already have a VPN gateway in place for the on-premises connection."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview"], "group": "G51"}, {"id": "T2-Q18", "test": 2, "num": 18, "domain": "storage", "stem": [{"p": "You have an Azure subscription that contains a storage account named storage1."}, {"p": "You want to make sure that the access keys for storage1 are rotated automatically."}, {"p": "Which configuration should you set up?"}], "options": ["Configure a backup vault", "Configure redundancy settings for storage1", "Configure lifecycle management for storage1", "Configure an Azure Key Vault", "Configure a Recovery Services vault"], "correct": [3], "multi": false, "explanation": [{"p": "Configure an Azure Key Vault is the correct answer. To ensure that the access keys for storage1 rotate automatically, you should store the keys in Azure Key Vault and enable key rotation policies. Key Vault allows for the secure storage of secrets, including storage account access keys, and provides the ability to configure automatic key rotation."}, {"p": "Configure a backup vault and Configure a Recovery Services vault are incorrect because these are used for backing up data and managing disaster recovery, not for rotating access keys."}, {"p": "Configure redundancy settings for storage1 is incorrect because this deals with the replication of storage data across different locations for high availability, not key management."}, {"p": "Configure lifecycle management for storage1 is incorrect because this manages data retention policies, not access key rotation."}], "refs": ["https://learn.microsoft.com/en-us/azure/key-vault/general/overview", "https://learn.microsoft.com/en-us/azure/storage/common/storage-account-keys-manage?tabs=azure-portal"], "group": "G52"}, {"id": "T2-Q19", "test": 2, "num": 19, "domain": "identity", "stem": [{"p": "You have an Azure subscription that includes a storage account named storage1, which stores blob data."}, {"p": "You must assign a role to a user named User1 so that the user can access the blob data in storage1. The role assignment must support Azure role assignment conditions."}, {"p": "Which two roles are suitable for assigning to User1?"}], "options": ["Owner", "Storage Account Contributor", "Storage Account Backup Contributor", "Storage Blob Data Contributor", "Storage Blob Data Owner", "Storage Blob Delegator"], "correct": [3, 4], "multi": true, "explanation": [{"p": "Storage Blob Data Contributor is the correct answer because this role allows the user to read, write, and delete blob data within a storage account. This role supports conditions, which can help control access based on specific criteria like time, IP address, or other factors."}, {"p": "Storage Blob Data Owner is the correct answer because this role grants full control over blob data, including setting access policies and modifying blob content. It also supports conditions for access."}, {"p": "Owner is incorrect because while this role gives full administrative access to the storage account, it does not allow direct blob data access, nor does it support conditions for blob-level data access."}, {"p": "Storage Account Contributor is incorrect because it grants management access to the storage account but does not provide direct access to blob data."}, {"p": "Storage Account Backup Contributor is incorrect because this role is designed for backup and recovery operations but doesn't provide direct access to blob data."}, {"p": "Storage Blob Delegator is incorrect because this role is used to delegate access through OAuth 2.0 on behalf of a user or service and is not intended for direct blob data access."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-blob-data-contributor", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-blob-data-owner"], "group": "G53"}, {"id": "T2-Q20", "test": 2, "num": 20, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant."}, {"p": "You plan to import a large number of user accounts at once."}, {"p": "You must ensure that newly imported users are automatically added to a specific group based on the value of their department attribute. The solution should require minimal ongoing administrative effort."}, {"p": "Which two actions should you take?"}], "options": ["Create groups that use the Assigned membership type.", "Create an Azure Resource Manager (ARM) template.", "Create groups that use the Dynamic User membership type.", "Write a PowerShell script that parses an import file.", "Create an XML file that contains user information and the appropriate attributes.", "Create a CSV file that contains user information and the appropriate attributes."], "correct": [2, 5], "multi": true, "explanation": [{"p": "Create groups that use the Dynamic User membership type is the correct answer because dynamic membership rules allow users to be automatically added to groups based on specific attributes, such as department. This minimizes administrative effort since the users will be automatically placed into the correct group based on their department attribute without manual intervention."}, {"img": "az104/img/t2_image5.webp"}, {"p": "Create a CSV file that contains user information and the appropriate attributes is the correct answer because CSV is the supported format for bulk importing users into Microsoft Entra. The CSV file will contain the necessary user information, including department attributes, which are used to assign users to the appropriate dynamic groups."}, {"p": "Create groups that use the Assigned membership type is incorrect because assigned groups require manual assignment of users, which does not minimize administrative effort."}, {"p": "Create an Azure Resource Manager (ARM) template is incorrect because ARM templates are used to deploy Azure resources, not for user or group management."}, {"p": "Write a PowerShell script that parses an import file is incorrect because while it can be used, it would increase administrative effort, which is against the goal of minimizing effort."}, {"p": "Create an XML file that contains user information and the appropriate attributes is incorrect because CSV is the recommended format for bulk user import, not XML."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/users/groups-dynamic-membership", "https://learn.microsoft.com/en-us/entra/identity/users/groups-bulk-import-members"], "group": "G54"}, {"id": "T2-Q21", "test": 2, "num": 21, "domain": "identity", "stem": [{"p": "You have an Azure subscription that contains an Azure Container Registry named RegistryProd01, which is currently configured with the Standard pricing tier."}, {"p": "You need to enable support for geo-replication for RegistryProd01."}, {"p": "What is the first step you should perform on RegistryProd01 to meet this requirement?"}], "options": ["Enable the admin user for the registry.", "Create a scope map for the registry.", "Configure an automation task.", "Define a cache rule.", "Change the registry to a higher SKU tier."], "correct": [4], "multi": false, "explanation": [{"p": "Change the registry to a higher SKU tier is the correct answer here. Geo-replication in Azure Container Registry is only supported in the Premium SKU. Since RegistryProd01 is currently using the Standard SKU, the first step to enable geo-replication is to upgrade the SKU to Premium. Once the SKU is upgraded, you can configure geo-replication across multiple regions."}, {"p": "Enable the admin user for the registry is incorrect because this is related to authentication and does not enable geo-replication."}, {"p": "Create a scope map for the registry is incorrect because scope maps are used for defining permissions for tokens, not for geo-replication."}, {"p": "Configure an automation task is incorrect because automation tasks are used for building and pushing images, not for geo-replication."}, {"p": "Define a cache rule is incorrect because cache rules are unrelated to geo-replication."}], "refs": ["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-geo-replication", "https://learn.microsoft.com/en-us/azure/container-registry/container-registry-skus"], "group": "G55"}, {"id": "T2-Q22", "test": 2, "num": 22, "domain": "storage", "stem": [{"p": "You have an Azure subscription that includes a storage account named storage1 which contains a blob used to store images."}, {"p": "Access to storage1 is provided to clients by using a shared access signature (SAS)."}, {"p": "You want users to see a warning whenever they create a SAS with an expiration period longer than seven days."}, {"p": "What configuration should you apply to the storage account?"}], "options": ["Enable a read-only resource lock on the storage account.", "Create and configure an alert rule.", "Add a lifecycle management policy.", "Set Allow recommended upper limit for shared access signature (SAS) expiry interval to Enabled."], "correct": [3], "multi": false, "explanation": [{"p": "Set Allow recommended upper limit for shared access signature (SAS) expiry interval to Enabled is the correct answer. By enabling this setting, Azure will enforce a recommended upper limit for SAS token expiry (in this case, seven days). Users will receive a warning if they try to create a SAS token that exceeds the defined limit, helping to maintain secure access practices."}, {"p": "Enable a read-only resource lock on the storage account is incorrect because locks are used to prevent modification or deletion of resources, not for configuring SAS expiry limits."}, {"p": "Create and configure an alert rule is incorrect because alert rules are used for monitoring and alerting on events, but do not directly enforce or warn about SAS expiry time."}, {"p": "Add a lifecycle management policy is incorrect because lifecycle management is used to manage blob storage tiers and deletion policies, not SAS expiry intervals."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/storage-sas-overview"], "group": "G56"}, {"id": "T2-Q23", "test": 2, "num": 23, "domain": "identity", "stem": [{"p": "You have an Azure subscription linked to a hybrid Microsoft Entra tenant. The tenant includes the users listed below:"}, {"p": "User1: Not enabled for on-premises synchronization"}, {"p": "User2: Enabled for on-premises synchronization"}, {"p": "You create the following Azure Files shares:"}, {"p": "share1 in storage account contoso2025"}, {"p": "share2 in storage account contoso2025"}, {"p": "share3 in storage account contoso2026"}, {"p": "You configure identity-based access for contoso2025 by enabling Active Directory Domain Services (AD DS) as the identity source and setting the default share-level permissions to allow access for all authenticated users and groups."}, {"img": "az104/img/t2_image6.webp"}, {"p": "True or False:"}, {"p": "\"User1 can access the content in share1.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because User1 does not have on-premises synchronization enabled, as indicated. According to the identity-based access configuration shown in the exhibit, only users synchronized from on-premises AD DS or those with hybrid identities can access the file shares. User1 is not synced from an on-premises AD DS environment and is therefore not eligible for access to share1, despite the permissions being enabled for authenticated users."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-auth-active-directory-enable"], "group": "G57"}, {"id": "T2-Q24", "test": 2, "num": 24, "domain": "identity", "stem": [{"p": "You have an Azure subscription linked to a hybrid Microsoft Entra tenant. The tenant includes the users listed below:"}, {"p": "User1: Not enabled for on-premises synchronization"}, {"p": "User2: Enabled for on-premises synchronization"}, {"p": "You create the following Azure Files shares:"}, {"p": "share1 in storage account contoso2025"}, {"p": "share2 in storage account contoso2025"}, {"p": "share3 in storage account contoso2026"}, {"p": "You configure identity-based access for contoso2025 by enabling Active Directory Domain Services (AD DS) as the identity source and setting the default share-level permissions to allow access for all authenticated users and groups."}, {"img": "az104/img/t2_image6.webp"}, {"p": "True or False:"}, {"p": "\"User2 can access the content in share2.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because User2 has on-premises sync enabled, as indicated, and the identity-based access configuration for contoso2025 (which contains share2) is set to allow permissions for authenticated users and groups. Since User2 is synchronized from on-premises AD DS, they are eligible to access the content in share2."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-auth-active-directory-enable"], "group": "G57"}, {"id": "T2-Q25", "test": 2, "num": 25, "domain": "identity", "stem": [{"p": "You have an Azure subscription linked to a hybrid Microsoft Entra tenant. The tenant includes the users listed below:"}, {"p": "User1: Not enabled for on-premises synchronization"}, {"p": "User2: Enabled for on-premises synchronization"}, {"p": "You create the following Azure Files shares:"}, {"p": "share1 in storage account contoso2025"}, {"p": "share2 in storage account contoso2025"}, {"p": "share3 in storage account contoso2026"}, {"p": "You configure identity-based access for contoso2025 by enabling Active Directory Domain Services (AD DS) as the identity source and setting the default share-level permissions to allow access for all authenticated users and groups."}, {"img": "az104/img/t2_image6.webp"}, {"p": "True or False:"}, {"p": "\"User2 can access the content in share3.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because share3 is part of the contoso2026 storage account, which is not configured for identity-based access (according to the provided information and exhibit, only contoso2025 has identity-based access enabled). Since User2 is synced and can access shares in contoso2025, they would not have access to share3 in contoso2026 unless identity-based access is configured similarly for contoso2026."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/files/storage-files-identity-auth-active-directory-enable"], "group": "G57"}, {"id": "T2-Q26", "test": 2, "num": 26, "domain": "identity", "stem": [{"p": "A Microsoft Entra tenant contains the following users:"}, {"p": "User1"}, {"p": "Member of: Group1"}, {"p": "Assigned license: Microsoft Entra ID P2"}, {"p": "User2"}, {"p": "Member of: Group2"}, {"p": "Assigned license: None"}, {"p": "User3"}, {"p": "Member of: No groups"}, {"p": "Assigned license: Microsoft Entra ID P2"}, {"p": "User4"}, {"p": "Member of: No groups"}, {"p": "Assigned license: None"}, {"p": "The tenant also contains the following groups and group relationships:"}, {"p": "Group1"}, {"p": "Member of: No groups"}, {"p": "Assigned license: None"}, {"p": "Group2"}, {"p": "Member of: Group3"}, {"p": "Assigned license: Microsoft Entra ID P2"}, {"p": "Group3"}, {"p": "Member of: Group4"}, {"p": "Assigned license: None"}, {"p": "Group4"}, {"p": "Member of: No groups"}, {"p": "Assigned license: Microsoft Entra ID P2"}, {"p": "Based on the tenant configuration shown above, which users are eligible to be deleted from Microsoft Entra ID?"}], "options": ["User4 only", "User3 and User4 only", "User2 and User4 only", "User1, User2, User3, and User4"], "correct": [3], "multi": false, "explanation": [{"p": "User1, User2, User3, and User4 can all be deleted. In Microsoft Entra ID, users can be deleted regardless of whether they have licenses assigned directly or through group membership. When a user is deleted, any licenses assigned to them will be freed for reassignment."}], "refs": ["https://learn.microsoft.com/en-us/entra/fundamentals/how-to-create-delete-users"], "group": "G58"}, {"id": "T2-Q27", "test": 2, "num": 27, "domain": "identity", "stem": [{"p": "A Microsoft Entra tenant contains the following users:"}, {"p": "User1"}, {"p": "Member of: Group1"}, {"p": "Assigned license: Microsoft Entra ID P2"}, {"p": "User2"}, {"p": "Member of: Group2"}, {"p": "Assigned license: None"}, {"p": "User3"}, {"p": "Member of: No groups"}, {"p": "Assigned license: Microsoft Entra ID P2"}, {"p": "User4"}, {"p": "Member of: No groups"}, {"p": "Assigned license: None"}, {"p": "The tenant also contains the following groups and group relationships:"}, {"p": "Group1"}, {"p": "Member of: No groups"}, {"p": "Assigned license: None"}, {"p": "Group2"}, {"p": "Member of: Group3"}, {"p": "Assigned license: Microsoft Entra ID P2"}, {"p": "Group3"}, {"p": "Member of: Group4"}, {"p": "Assigned license: None"}, {"p": "Group4"}, {"p": "Member of: No groups"}, {"p": "Assigned license: Microsoft Entra ID P2"}, {"p": "Based on the tenant configuration shown above, which groups are eligible to be deleted from Microsoft Entra ID?"}], "options": ["Group1 only", "Group4 only", "Group1 and Group3 only", "Group1, Group2, Group3, and Group4"], "correct": [2], "multi": false, "explanation": [{"p": "Group1 and Group3 only is the correct answer because both groups do not have any licenses directly assigned to them. According to Microsoft Entra documentation, a group cannot be deleted if it has licenses directly assigned. Group1 and Group3 meet the criteria for deletion: Group1 has no assigned license, and Group3 is only a member of another group but does not itself have any license directly assigned."}, {"p": "Group4 only is incorrect because Group4 has a Microsoft Entra ID P2 license assigned directly, which prevents it from being deleted until the license is removed."}, {"p": "Group1 only is incorrect because while Group1 can be deleted, Group3 can also be deleted, so this answer is incomplete."}, {"p": "Group1, Group2, Group3, and Group4 is incorrect because Group2 and Group4 both have licenses directly assigned, which disqualifies them from deletion until those licenses are removed."}], "refs": ["https://learn.microsoft.com/en-us/entra/fundamentals/how-to-create-delete-users", "https://learn.microsoft.com/en-us/entra/fundamentals/licensing-groups-resolve-problems#when-a-licensed-group-is-deleted"], "group": "G58"}, {"id": "T2-Q28", "test": 2, "num": 28, "domain": "storage", "stem": [{"p": "You have an Azure subscription named ProdSubscription that contains the following resources:"}, {"img": "az104/img/t2_image7.webp"}, {"p": "You plan to configure Azure Backup reports for RSVault1."}, {"p": "While configuring diagnostic settings for the AzureBackupReports log category, you must choose a storage account as the destination."}, {"p": "Which storage accounts are eligible to store the Azure Backup reports for RSVault1?"}], "options": ["dataStore1 only", "dataStore2 only", "dataStore3 only", "dataStore1, dataStore2, and dataStore3"], "correct": [2], "multi": false, "explanation": [{"p": "dataStore3 only is correct because Azure Backup requires that the storage account used for diagnostic settings (like Azure Backup reports) be in the same region as the Recovery Services vault (RSVault1). Since RSVault1 is in the West Europe region, only dataStore3, located in West Europe, meets this requirement."}, {"img": "az104/img/t2_image8.webp"}, {"p": "dataStore1 only is incorrect because dataStore1 is in the East US region, which does not match the West Europe region of Vault1."}, {"p": "dataStore2 only is incorrect because dataStore2 is in the West US region, which also does not match the West Europe region of Vault1."}, {"p": "dataStore1, dataStore2, and dataStore3 is incorrect because only dataStore3 is in the same region as Vault1. dataStore1 and dataStore2 are in East US and West US, respectively, and therefore cannot be used."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-azure-files?tabs=backup-center", "https://docs.microsoft.com/en-us/azure/backup/backup-create-rs-vault"], "group": "G59"}, {"id": "T2-Q29", "test": 2, "num": 29, "domain": "monitor", "stem": [{"p": "You have an Azure subscription named ProdSubscription that contains the following resources:"}, {"img": "az104/img/t2_image7.webp"}, {"p": "You plan to configure Azure Backup reports for RSVault1."}, {"p": "While configuring diagnostic settings for the AzureBackupReports log category, you must choose a storage account as the destination."}, {"p": "Which Log Analytics workspaces can you use for the Azure Backup reports of RSVault1?"}], "options": ["LogWorkspace1 only", "LogWorkspace2 only", "LogWorkspace3 only", "LogWorkspace1, LogWorkspace2, and LogWorkspace3"], "correct": [3], "multi": false, "explanation": [{"p": "LogWorkspace1, LogWorkspace2, and LogWorkspace3 is correct because, as per the documentation, the location of the Log Analytics workspace does not need to match the location of the Recovery Services vault. Therefore, all three workspaces LogWorkspace1, LogWorkspace2, and LogWorkspace3, can be used to store the Azure Backup reports for Vault1."}, {"img": "az104/img/t2_image9.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/configure-reports?tabs=recovery-services-vaults#1-create-a-log-analytics-workspace-or-use-an-existing-one"], "group": "G59"}, {"id": "T2-Q30", "test": 2, "num": 30, "domain": "monitor", "stem": [{"p": "You have an on-premises network and an Azure subscription that includes three peered virtual networks named VNET1, VNET2, and VNET3. All three virtual networks are connected to the on-premises network."}, {"p": "The subscription contains the following virtual machines:"}, {"p": "VM1 and VM2, located in West US and connected to VNET1"}, {"p": "VM3, located in West US and connected to VNET2"}, {"p": "VM4, located in Central US and connected to VNET3"}, {"p": "You want to monitor network connectivity between the virtual machines and the on-premises network by using Connection Monitor."}, {"p": "What is the minimum number of Connection Monitor instances that you must deploy?"}], "options": ["1", "2", "3", "4"], "correct": [1], "multi": false, "explanation": [{"p": "2 is correct because Azure Network Watcher's Connection Monitor requires that the source virtual machine and the Connection Monitor instance reside in the same Azure region. In the table:"}, {"p": "VM1, VM2, and VM3 are in the West US region."}, {"p": "VM4 is in the Central US region."}, {"p": "You will need:"}, {"p": "One Connection Monitor in West US to monitor VM1, VM2, and VM3's connectivity to the on-premises network."}, {"p": "One Connection Monitor in Central US to monitor VM4’s connectivity to the on-premises network."}, {"p": "You cannot use a single connection monitor to monitor VMs across regions, hence two are required."}], "refs": ["https://learn.microsoft.com/en-us/azure/network-watcher/connection-monitor-overview"], "group": "G60"}, {"id": "T2-Q31", "test": 2, "num": 31, "domain": "compute", "stem": [{"p": "An Azure subscription contains two virtual machines with the following configurations:"}, {"p": "VM1"}, {"p": "Operating system: Windows Server 2019"}, {"p": "Connected to: Subnet1"}, {"p": "VM2"}, {"p": "Operating system: Windows Server 2019"}, {"p": "Connected to: Subnet2"}, {"p": "Both VM1 and VM2 have public IP addresses, and inbound Remote Desktop (RDP) access is enabled on each virtual machine."}, {"p": "Subnet1 and Subnet2 belong to the same virtual network named VNET1."}, {"p": "The subscription contains two network security groups (NSGs):"}, {"p": "NSG1 contains only the default security rules."}, {"p": "NSG2 contains the default rules and an additional inbound rule with the following configuration:"}, {"p": "Priority: 100"}, {"p": "Name: Rule1"}, {"p": "Protocol: TCP"}, {"p": "Port: 3389"}, {"p": "Source: Any"}, {"p": "Destination: Any"}, {"p": "Action: Allow"}, {"p": "NSG1 is associated with Subnet1, and NSG2 is associated with the network interface of VM2."}, {"p": "True or False:"}, {"p": "“You can connect to VM1 from the internet using Remote Desktop.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because VM1 is associated with NSG1, which only has the default rules. By default, NSGs deny inbound traffic from the internet unless there is an explicit rule to allow it. Since NSG1 does not have any custom rule allowing inbound Remote Desktop Protocol (RDP) traffic on port 3389 from the internet, VM1 cannot be accessed via RDP from the internet."}, {"img": "az104/img/t2_image10.webp"}, {"img": "az104/img/t2_image11.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"], "group": "G61"}, {"id": "T2-Q32", "test": 2, "num": 32, "domain": "compute", "stem": [{"p": "An Azure subscription contains two virtual machines with the following configurations:"}, {"p": "VM1"}, {"p": "Operating system: Windows Server 2019"}, {"p": "Connected to: Subnet1"}, {"p": "VM2"}, {"p": "Operating system: Windows Server 2019"}, {"p": "Connected to: Subnet2"}, {"p": "Both VM1 and VM2 have public IP addresses, and inbound Remote Desktop (RDP) access is enabled on each virtual machine."}, {"p": "Subnet1 and Subnet2 belong to the same virtual network named VNET1."}, {"p": "The subscription contains two network security groups (NSGs):"}, {"p": "NSG1 contains only the default security rules."}, {"p": "NSG2 contains the default rules and an additional inbound rule with the following configuration:"}, {"p": "Priority: 100"}, {"p": "Name: Rule1"}, {"p": "Protocol: TCP"}, {"p": "Port: 3389"}, {"p": "Source: Any"}, {"p": "Destination: Any"}, {"p": "Action: Allow"}, {"p": "NSG1 is associated with Subnet1, and NSG2 is associated with the network interface of VM2."}, {"p": "True or False:"}, {"p": "“From the internet, you can connect to VM2 by using Remote Desktop.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because NSG2, which is associated with VM2’s network interface, has a custom rule (Rule1) that allows inbound traffic on port 3389 (TCP) from any source. This rule enables Remote Desktop Protocol (RDP) connections from the internet to VM2."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups"], "group": "G61"}, {"id": "T2-Q33", "test": 2, "num": 33, "domain": "compute", "stem": [{"p": "An Azure subscription contains two virtual machines with the following configurations:"}, {"p": "VM1"}, {"p": "Operating system: Windows Server 2019"}, {"p": "Connected to: Subnet1"}, {"p": "VM2"}, {"p": "Operating system: Windows Server 2019"}, {"p": "Connected to: Subnet2"}, {"p": "Both VM1 and VM2 have public IP addresses, and inbound Remote Desktop (RDP) access is enabled on each virtual machine."}, {"p": "Subnet1 and Subnet2 belong to the same virtual network named VNET1."}, {"p": "The subscription contains two network security groups (NSGs):"}, {"p": "NSG1 contains only the default security rules."}, {"p": "NSG2 contains the default rules and an additional inbound rule with the following configuration:"}, {"p": "Priority: 100"}, {"p": "Name: Rule1"}, {"p": "Protocol: TCP"}, {"p": "Port: 3389"}, {"p": "Source: Any"}, {"p": "Destination: Any"}, {"p": "Action: Allow"}, {"p": "NSG1 is associated with Subnet1, and NSG2 is associated with the network interface of VM2."}, {"p": "True or False:"}, {"p": "“From VM1, you can connect to VM2 by using Remote Desktop.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because VM1 is in Subnet1 and VM2 is in Subnet2, both of which are part of the same virtual network, VNET1. Azure automatically routes traffic between subnets within the same virtual network, allowing connectivity between VMs across subnets by default. Additionally, NSG2, which is associated with VM2's network interface, has a custom rule (Rule1) that permits inbound RDP traffic on port 3389 from any source, which includes VM1."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/tutorial-create-route-table-powershell", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"], "group": "G61"}, {"id": "T2-Q34", "test": 2, "num": 34, "domain": "compute", "stem": [{"p": "You have an Azure virtual network named VNet1, as shown in the exhibit."}, {"p": "VNet1 has an address space of 10.2.0.0/16, and currently no devices are connected to it."}, {"img": "az104/img/t2_image12.webp"}, {"p": "You plan to create a virtual network peering between VNet1 and another virtual network named VNet2. VNet2 also uses the address space 10.2.0.0/16."}, {"p": "You need to establish the peering between the two virtual networks."}, {"p": "What action should you perform first?"}], "options": ["Add a gateway subnet to VNet1.", "Create a subnet on VNet1 and VNet2.", "Modify the address space of VNet1.", "Configure a service endpoint on VNet2."], "correct": [2], "multi": false, "explanation": [{"p": "Modify the address space of VNet1 is correct because the address spaces of two virtual networks being peered must not overlap. In this case, both VNet1 and VNet2 have the address space 10.2.0.0/16, which causes an overlap and prevents peering. To enable peering, you would first need to modify the address space of VNet1 to a non-overlapping range."}, {"img": "az104/img/t2_image13.webp"}, {"p": "Add a gateway subnet to VNet1 is incorrect because a gateway subnet is only required for VPN Gateway connections, not for simple VNet peering."}, {"p": "Create a subnet on VNet1 and VNet2 is incorrect because the presence of subnets is not a requirement for VNet peering. The issue here is the overlapping address space, which must be resolved first."}, {"p": "Configure a service endpoint on VNet2 is incorrect because service endpoints are used to secure access to Azure services and are not related to VNet peering configuration."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-manage-peering"], "group": "G62"}, {"id": "T2-Q35", "test": 2, "num": 35, "domain": "network", "stem": [{"p": "You have an Azure subscription named ProductionSub."}, {"p": "You are designing a multi-tier application with the following architecture:"}, {"p": "Web tier"}, {"p": "Internet-facing: Yes"}, {"p": "Number of virtual machines: 10"}, {"p": "Application/Business tier"}, {"p": "Internet-facing: No"}, {"p": "Number of virtual machines: 100"}, {"p": "Database tier (SQL Server)"}, {"p": "Internet-facing: No"}, {"p": "Number of virtual machines: 5"}, {"p": "You must recommend a networking solution that ensures traffic from the web tier to the application tier is evenly distributed across all virtual machines in the application tier."}, {"p": "Which Azure resource should you recommend to meet this requirement?"}], "options": ["an application gateway that uses the Standard tier", "an application gateway that uses the WAF tier", "an internal load balancer", "a network security group (NSG)", "a public load balancer"], "correct": [2], "multi": false, "explanation": [{"p": "An internal load balancer is correct because an internal load balancer in Azure is designed to distribute network traffic within a virtual network (VNet) across virtual machines (VMs) without exposing them to the internet. In this scenario, it can be used to balance the load between the front-end web servers and the business logic tier, ensuring that traffic spreads equally across the VMs in the business logic tier. Since the business logic tier is not accessible from the internet, an internal load balancer is the appropriate solution."}, {"p": "An application gateway that uses the Standard tier is incorrect because an application gateway is primarily designed for web traffic (HTTP/HTTPS) and is typically used in internet-facing scenarios or for application layer load balancing, which is not specified here."}, {"p": "An application gateway that uses the WAF tier is incorrect for the same reason as above. Additionally, the WAF tier is designed to protect applications from web vulnerabilities, which is unnecessary for internal load balancing between tiers in this setup."}, {"p": "A network security group (NSG) is incorrect because NSGs are used for filtering network traffic based on security rules and do not provide load balancing capabilities."}, {"p": "A public load balancer is incorrect because it is used to distribute traffic from the internet to VMs within a VNet. Since the business logic tier is not accessible from the internet, a public load balancer is not suitable."}], "refs": ["https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview"], "group": "G63"}, {"id": "T2-Q36", "test": 2, "num": 36, "domain": "network", "stem": [{"p": "You have an Azure subscription named ProductionSub."}, {"p": "You are designing a multi-tier application with the following architecture:"}, {"p": "Web tier"}, {"p": "Internet-facing: Yes"}, {"p": "Number of virtual machines: 10"}, {"p": "Application/Business tier"}, {"p": "Internet-facing: No"}, {"p": "Number of virtual machines: 100"}, {"p": "Database tier (SQL Server)"}, {"p": "Internet-facing: No"}, {"p": "Number of virtual machines: 5"}, {"p": "You must recommend a networking solution that protects the web tier from SQL injection attacks originating from the internet."}, {"p": "Which Azure resource should you recommend to meet this requirement?"}], "options": ["an application gateway that uses the Standard tier", "an application gateway that uses the WAF tier", "an internal load balancer", "a network security group (NSG)", "a public load balancer"], "correct": [1], "multi": false, "explanation": [{"p": "An application gateway that uses the WAF tier is correct because the Web Application Firewall (WAF) tier of Azure Application Gateway provides built-in protection against common web vulnerabilities, including SQL injection attacks. By placing an application gateway with WAF in front of the web servers, you can protect them from SQL injection and other security threats."}, {"p": "An application gateway that uses the Standard tier is incorrect because the Standard tier does not include WAF functionality, which is required to protect against SQL injection."}, {"p": "An internal load balancer is incorrect because load balancers are used to distribute network traffic and do not offer protection against SQL injection or other web vulnerabilities."}, {"p": "A network security group (NSG) is incorrect because NSGs control access through rules but do not provide protection against specific types of attacks like SQL injection."}, {"p": "A public load balancer is incorrect because, like an internal load balancer, it only distributes traffic and does not protect against web vulnerabilities."}], "refs": ["https://learn.microsoft.com/en-us/azure/web-application-firewall/ag/ag-overview"], "group": "G63"}, {"id": "T2-Q37", "test": 2, "num": 37, "domain": "network", "stem": [{"p": "You have a virtual network named VNet1 with an address space of 10.2.0.0/16 and a single subnet configured as 10.2.0.0/24."}, {"img": "az104/img/t2_image14.webp"}, {"p": "You plan to deploy a virtual machine in VNet1 and assign it an IP address from the 192.168.1.0/24 address range."}, {"p": "Before the virtual machine can receive an IP address from 192.168.1.0/24, what must you do first?"}], "options": ["add a network interface", "add a subnet", "add an address space", "delete a subnet", "delete an address space"], "correct": [2], "multi": false, "explanation": [{"p": "Add an address space is correct because the existing address space of VNet1 is configured as 10.2.0.0/16. To allow virtual machines on VNet1 to receive an IP address from 192.168.1.0/24, you must first add this new address space to VNet1. Azure virtual networks support multiple address spaces, but they must be added explicitly."}, {"img": "az104/img/t2_image15.webp"}, {"p": "Add a network interface is incorrect because a network interface allows a VM to connect to a subnet but does not affect the IP range available within the virtual network."}, {"p": "Add a subnet is incorrect because adding a new subnet would require an available address space in the 192.168.1.0/24 range, which is not currently defined within VNet1."}, {"p": "Delete a subnet is incorrect because deleting a subnet will not allow adding the desired IP range."}, {"p": "Delete an address space is incorrect because the action required is to add a new address space, not remove an existing one."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/virtual-networks-static-private-ip-arm-pportal"], "group": "G64"}, {"id": "T2-Q38", "test": 2, "num": 38, "domain": "network", "stem": [{"p": "You have a virtual network named VNet1 with an address space of 10.2.0.0/16 and a single subnet configured as 10.2.0.0/24."}, {"img": "az104/img/t2_image14.webp"}, {"p": "Based on the current address space and subnet configuration, a virtual machine deployed in VNet1 must be assigned an IP address from the 10.2.1.0/24 range."}, {"p": "What must you do before the virtual machine can receive an IP address from this range?"}], "options": ["add a network interface", "add a subnet", "add an address space", "delete a subnet", "delete an address space"], "correct": [1], "multi": false, "explanation": [{"p": "Add a subnet is correct because the current address space for VNet1 is 10.2.0.0/16, which already includes the 10.2.1.0/24 range. However, there is only one existing subnet (default) configured with the 10.2.0.0/24 address prefix. To assign IP addresses from 10.2.1.0/24, you would need to create a new subnet using this address range within the existing address space."}, {"p": "Add a network interface is incorrect because a network interface allows a VM to connect to a subnet but does not create a new address range or subnet."}, {"p": "Add an address space is incorrect because 10.2.1.0/24 is already part of the existing 10.2.0.0/16 address space, so adding a new address space is unnecessary."}, {"p": "Delete a subnet is incorrect because removing an existing subnet does not help in assigning a new IP range."}, {"p": "Delete an address space is incorrect because deleting an address space would reduce the IP range available, which is not required here."}], "refs": ["https://docs.microsoft.com/en-us/microsoft-365/solutions/cloud-architecture-models?view=o365-worldwide", "https://docs.microsoft.com/en-us/azure/virtual-network/virtual-networks-static-private-ip-arm-pportal"], "group": "G64"}, {"id": "T2-Q39", "test": 2, "num": 39, "domain": "identity", "stem": [{"p": "An Azure subscription is associated with a Microsoft Entra tenant named contoso.com. The tenant is synchronized with an on-premises Active Directory domain."}, {"p": "The domain includes the following users and assigned roles:"}, {"p": "SecAdmin1 – Role: Security Administrator"}, {"p": "BillAdmin1 – Role: Billing Administrator"}, {"p": "User1 – Role: Reports Reader"}, {"p": "Self-service password reset (SSPR) is enabled for all users and configured with the following settings:"}, {"p": "Two authentication methods are required to reset a password."}, {"p": "Available authentication methods are Mobile phone and Security questions."}, {"p": "Users must register three security questions."}, {"p": "Users must correctly answer three security questions during password reset."}, {"p": "The following security questions are configured:"}, {"p": "What is your favorite food?"}, {"p": "In what city was your first job?"}, {"p": "What was the name of your first pet?"}, {"p": "True or False:"}, {"p": "“During a self-service password reset, SecAdmin1 must answer the security question ‘In what city was your first job?’”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because, although self-service password reset (SSPR) is enabled for all users, the regular SSPR policy does not apply to users in administrative roles, such as Security Administrator. Administrators must go through a two-gate policy to reset their password, which differs from the standard SSPR process configured for non-admin users. Since SecAdmin1 is in an administrative role, they are excluded from using security questions and instead must follow the enhanced SSPR process that applies to Microsoft Entra ID administrators. Additionally, SSPR is enabled by default for admin roles."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-deploy", "https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-policy#administrator-password-policy-differences", "https://docs.microsoft.com/en-us/azure/active-directory/authentication/concept-sspr-policy#administrator-reset-policy-differences"], "group": "G65"}, {"id": "T2-Q40", "test": 2, "num": 40, "domain": "identity", "stem": [{"p": "An Azure subscription is associated with a Microsoft Entra tenant named contoso.com. The tenant is synchronized with an on-premises Active Directory domain."}, {"p": "The domain includes the following users and assigned roles:"}, {"p": "SecAdmin1 – Role: Security Administrator"}, {"p": "BillAdmin1 – Role: Billing Administrator"}, {"p": "User1 – Role: Reports Reader"}, {"p": "Self-service password reset (SSPR) is enabled for all users and configured with the following settings:"}, {"p": "Two authentication methods are required to reset a password."}, {"p": "Available authentication methods are Mobile phone and Security questions."}, {"p": "Users must register three security questions."}, {"p": "Users must correctly answer three security questions during password reset."}, {"p": "The following security questions are configured:"}, {"p": "What is your favorite food?"}, {"p": "In what city was your first job?"}, {"p": "What was the name of your first pet?"}, {"p": "True or False:"}, {"p": "“During a self-service password reset, BillAdmin1 must answer the security question ‘What is your favorite food?’”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because BillAdmin1 has been assigned the Billing Administrator role, which falls under the category of administrative roles in Microsoft Entra. By default, Azure applies a two-gate password reset policy for all administrator accounts. This two-gate policy requires two pieces of authentication data, such as an email address, authenticator app, or phone number, and does not permit the use of security questions for administrators. Therefore, BillAdmin1 would not be prompted to answer a security question, such as \"What is your favorite food?\" during the password reset process."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-deploy", "https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-policy#administrator-password-policy-differences", "https://docs.microsoft.com/en-us/azure/active-directory/authentication/concept-sspr-policy#administrator-reset-policy-differences"], "group": "G65"}, {"id": "T2-Q41", "test": 2, "num": 41, "domain": "identity", "stem": [{"p": "An Azure subscription is associated with a Microsoft Entra tenant named contoso.com. The tenant is synchronized with an on-premises Active Directory domain."}, {"p": "The domain includes the following users and assigned roles:"}, {"p": "SecAdmin1 – Role: Security Administrator"}, {"p": "BillAdmin1 – Role: Billing Administrator"}, {"p": "User1 – Role: Reports Reader"}, {"p": "Self-service password reset (SSPR) is enabled for all users and configured with the following settings:"}, {"p": "Two authentication methods are required to reset a password."}, {"p": "Available authentication methods are Mobile phone and Security questions."}, {"p": "Users must register three security questions."}, {"p": "Users must correctly answer three security questions during password reset."}, {"p": "The following security questions are configured:"}, {"p": "What is your favorite food?"}, {"p": "In what city was your first job?"}, {"p": "What was the name of your first pet?"}, {"p": "True or False:"}, {"p": "“During a self-service password reset, User1 must answer the security question ‘What was the name of your first pet?’”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because User1 has the Reports Reader role, which is not an administrative role in Microsoft Entra. As a standard user, User1 will follow the regular self-service password reset (SSPR) policy that applies to non-admin users. Since security questions are enabled as an authentication method for SSPR, User1 can be prompted to answer questions like \"What was the name of your first pet?\" as part of the password reset process."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-deploy", "https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-policy#administrator-password-policy-differences", "https://docs.microsoft.com/en-us/azure/active-directory/authentication/concept-sspr-policy#administrator-reset-policy-differences"], "group": "G65"}, {"id": "T2-Q42", "test": 2, "num": 42, "domain": "monitor", "stem": [{"p": "You have an Azure subscription that contains the following resources:"}, {"p": "VM1 – Virtual machine"}, {"p": "storage1 – Storage account"}, {"p": "Workspace1 – Log Analytics workspace"}, {"p": "DB1 – Azure SQL database"}, {"p": "You plan to create a data collection rule named DCR1 in Azure Monitor."}, {"p": "Which of the listed resources can you configure as data sources in DCR1?"}], "options": ["VM1 only", "VM1 and storage1 only", "VM1, storage1, and DB1 only", "VM1, storage1, Workspace1, and DB1"], "correct": [0], "multi": false, "explanation": [{"p": "VM1 only is the correct answer because Azure Monitor data collection rules (DCRs) can only collect data from specific resources, primarily virtual machines, as data sources. In this case, VM1 is a virtual machine and is eligible to be set as a data source in DCR1."}, {"p": "VM1 and storage1 only is incorrect because storage accounts, like storage1, cannot be used directly as data sources for data collection rules in Azure Monitor."}, {"p": "VM1, storage1, and DB1 only is incorrect because DB1 (an Azure SQL database) and storage1 are not supported as data sources for data collection rules in Azure Monitor."}, {"p": "VM1, storage1, Workspace1, and DB1 is incorrect because Workspace1 (a Log Analytics workspace), storage1, and DB1 cannot be used as data sources in a data collection rule. Only VM1 is valid."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-monitor/essentials/data-collection-rule-overview", "https://learn.microsoft.com/en-us/azure/azure-monitor/agents/data-sources-windows-events"], "group": "G66"}, {"id": "T2-Q43", "test": 2, "num": 43, "domain": "monitor", "stem": [{"p": "You have an Azure subscription that contains the following resources:"}, {"p": "VM1 – Virtual machine"}, {"p": "storage1 – Storage account"}, {"p": "Workspace1 – Log Analytics workspace"}, {"p": "DB1 – Azure SQL database"}, {"p": "You plan to create a data collection rule named DCR1 in Azure Monitor."}, {"p": "Which of the listed resources can you set as destinations in DCR1?"}], "options": ["storage1 only", "Workspace1 only", "Workspace1 and storage1 only", "Workspace1, storage1, and DB1 only"], "correct": [1], "multi": false, "explanation": [{"p": "Workspace1 only is the correct answer. In Azure Monitor, a Data Collection Rule (DCR) defines how data is collected from sources and where it is sent. The valid destinations for a DCR are Log Analytics workspaces, which store monitoring data for query and analysis, and are the standard supported target for the Azure Monitor Agent. Other destinations such as Azure Storage accounts or Event Hubs can be used with diagnostic settings, but they are not supported destinations when configuring a DCR directly. Similarly, Azure SQL databases are not valid targets for monitoring data."}, {"p": "In the given scenario, this means that only Workspace1 can be set as a destination in DCR1. Storage1 and DB1 are not valid choices for a DCR destination, as the DCR framework is designed to work with Log Analytics workspaces for centralized monitoring and analytics."}, {"img": "az104/img/t2_image16.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-monitor/essentials/data-collection-rule-structure#valid-destinations"], "group": "G66"}, {"id": "T2-Q44", "test": 2, "num": 44, "domain": "monitor", "stem": [{"p": "You have an Azure Linux virtual machine that is protected by Azure Backup."}, {"p": "Two files were deleted from the virtual machine one week ago."}, {"p": "You need to restore the deleted files to an on-premises computer in the shortest possible time."}, {"p": "Which four actions should you perform in sequence?"}, {"p": "ACTIONS"}, {"p": "From the Azure portal, click Restore VM from the vault."}, {"p": "Mount a VHD."}, {"p": "From the Azure portal, click File Recovery from the vault."}, {"p": "Copy the files by using AZCopy."}, {"p": "Select a restore point that contains the deleted files."}, {"p": "Copy the files by using File Explorer."}, {"p": "Download and run the script to mount a drive on the local computer."}], "options": ["2-3-5-7", "1-5-2-6", "3-5-7-6", "6-4-7-2", "4-5-1-3", "2-4-7-3"], "correct": [2], "multi": false, "explanation": [{"p": "3-5-7-6 is the correct sequence of actions."}, {"p": "(Action 3) From the Azure portal, click File Recovery from the vault – To begin the file recovery process, navigate to the File Recovery option in the vault associated with the backup."}, {"p": "(Action 5) Select a restore point that contains the deleted files – Choose a restore point from a date prior to the deletion of the files to ensure they are available in the backup."}, {"p": "(Action 7) Download and run the script to mount a drive on the local computer – This step mounts the backup as a drive on the local computer, allowing access to the files in the backup."}, {"p": "(Action 6) Copy the files by using File Explorer – Using File Explorer provides a straightforward way to restore the files to an on-premises Windows Server computer quickly."}, {"p": "(Action 2) Mount a VHD is not applicable in this context, as the File Recovery option does not involve VHDs directly for individual file restoration."}, {"p": "(Action 4) Copy the files by using AZCopy is unnecessary as File Explorer is sufficient once the drive is mounted. Also, File explorer will be faster than AzCopy."}, {"p": "(Action 3) From the Azure portal, click Restore VM from the vault would initiate a full VM restore, which is not required for individual file recovery."}], "refs": ["https://docs.microsoft.com/en-us/azure/backup/backup-azure-restore-files-from-vm", "https://docs.microsoft.com/en-us/azure/storage/common/storage-use-azcopy"], "group": "G67"}, {"id": "T2-Q45", "test": 2, "num": 45, "domain": "monitor", "stem": [{"p": "You configure a Recovery Services vault backup policy named Policy1 with the following settings:"}, {"img": "az104/img/t2_image17.webp"}, {"p": "Based on the information provided, select the answer choice that completes the following statement correctly."}, {"p": "“The backup that occurs on Sunday, March 1, will be retained for ___________.”"}], "options": ["30 days", "10 weeks", "36 months", "10 years"], "correct": [3], "multi": false, "explanation": [{"p": "10 years is the correct answer because the backup policy specifies retention of yearly backup points. Since the backup occurring on Sunday, March 1, aligns with the yearly retention schedule (March 1), it will be retained for the maximum period defined under the yearly backup retention, which is 10 years."}, {"p": "30 days is incorrect because this retention applies only to daily backup points, not yearly backups."}, {"p": "10 weeks is incorrect because this retention applies to weekly backup points, not yearly backups."}, {"p": "36 months is incorrect because this retention applies to monthly backup points, not yearly backups."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-introduction", "https://learn.microsoft.com/en-us/azure/backup/backup-azure-recovery-services-vault-overview"], "group": "G68"}, {"id": "T2-Q46", "test": 2, "num": 46, "domain": "monitor", "stem": [{"p": "You configure a Recovery Services vault backup policy named Policy1 with the following settings:"}, {"img": "az104/img/t2_image17.webp"}, {"p": "Based on the information provided, select the answer choice that completes the following statement correctly."}, {"p": "“The backup that occurs on Sunday, November 1, will be retained for _____________.”"}], "options": ["30 days", "10 weeks", "36 months", "10 years"], "correct": [2], "multi": false, "explanation": [{"p": "36 months is the correct answer because the backup that occurs on Sunday, November 1, aligns with both the weekly and monthly retention schedules. Given that the monthly backup point retention is set to 36 months and the weekly retention is 10 weeks, Azure’s retention policy dictates that the backup will be retained for the longest period in case of overlap. Therefore, this backup will be retained for 36 months."}, {"img": "az104/img/t2_image18.webp"}, {"p": "10 weeks is incorrect because, although the backup aligns with the weekly retention schedule, the 36-month retention period for the monthly backup point takes precedence due to Azure’s policy of selecting the longest retention period."}, {"p": "10 years is incorrect because yearly retention is not applicable for this backup, as it is not taken on March 1."}, {"p": "30 days is incorrect because this applies only to daily backup points, which are irrelevant for this specific backup."}], "refs": ["https://learn.microsoft.com/en-us/purview/retention?view=o365-worldwide&tabs=table-overriden", "https://learn.microsoft.com/en-us/azure/backup/backup-azure-recovery-services-vault-overview"], "group": "G68"}, {"id": "T2-Q47", "test": 2, "num": 47, "domain": "monitor", "stem": [{"p": "You purchase a new Azure subscription named Subscription1."}, {"p": "Within Subscription1, you deploy a virtual machine named VM1. VM1 is currently not protected by Azure Backup."}, {"p": "You need to configure Azure Backup for VM1. The backups must run daily at 01:00 and be retained for a period of 30 days."}, {"p": "Where should the backups be stored?"}], "options": ["A blob container", "A file share", "A Recovery Services vault", "A storage account"], "correct": [2], "multi": false, "explanation": [{"p": "A Recovery Services vault is the correct answer because Azure Backup requires a Recovery Services vault to store backup data for virtual machines. The Recovery Services vault provides backup management and retention policies, allowing backups of VM1 to be created at the specified time (01:00) and retained for 30 days."}, {"img": "az104/img/t2_image19.webp"}, {"p": "A blob container is incorrect because blob containers in Azure Storage accounts are not directly used for Azure VM backups. Azure Backup does not store VM backups in blob containers."}, {"p": "A file share is incorrect because Azure file shares are meant for file-level storage and sharing, not for storing VM backups using Azure Backup."}, {"p": "A storage account is incorrect because, although storage accounts are part of the Azure storage infrastructure, VM backups using Azure Backup require a Recovery Services vault rather than a generic storage account."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-overview", "https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-first-look-arm"], "group": "G69"}, {"id": "T2-Q48", "test": 2, "num": 48, "domain": "monitor", "stem": [{"p": "You purchase a new Azure subscription named Subscription1."}, {"p": "Within Subscription1, you deploy a virtual machine named VM1. VM1 is currently not protected by Azure Backup."}, {"p": "You need to configure Azure Backup for VM1. The backups must run daily at 01:00 and be retained for a period of 30 days."}, {"p": "Which object should you use to configure backup protection for VM1?"}], "options": ["A backup policy", "A batch job", "A batch schedule", "A recovery plan"], "correct": [0], "multi": false, "explanation": [{"p": "A backup policy is the correct answer because Azure Backup uses backup policies to define the schedule and retention settings for protecting resources, such as virtual machines. To configure the protection for VM1, you would create a backup policy that specifies the backup time (01:00) and the retention period (30 days)."}, {"img": "az104/img/t2_image20.webp"}, {"p": "A batch job is incorrect because batch jobs are typically used in Azure Batch to execute large-scale parallel and high-performance computing tasks, not for configuring backups."}, {"p": "A batch schedule is incorrect because it is not related to Azure Backup. Batch schedules are relevant in the context of Azure Batch, not for VM backup configuration."}, {"p": "A recovery plan is incorrect because recovery plans are used in Azure Site Recovery for orchestrating failover and recovery of applications, not for scheduling and managing backups."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-introduction", "https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-first-look-arm"], "group": "G69"}, {"id": "T2-Q49", "test": 2, "num": 49, "domain": "monitor", "stem": [{"p": "You manage an Azure subscription that contains several virtual machines connected to a virtual network named CorpVNet."}, {"p": "You plan to enable Azure Monitor and use VM Insights to monitor the virtual machines."}, {"p": "You must ensure that all communication between the virtual machines and Azure Monitor occurs only through CorpVNet, without using the public internet."}, {"p": "What should you create first to meet this requirement?"}], "options": ["a private endpoint", "an Azure Monitor Private Link Scope (AMPLS)", "a data collection rule (DCR)", "a Log Analytics workspace"], "correct": [1], "multi": false, "explanation": [{"p": "an Azure Monitor Private Link Scope (AMPLS) is the correct answer because to ensure that virtual machines only communicate with Azure Monitor through the specified virtual network (CorpVNet), you need to set up a private link connection. An Azure Monitor Private Link Scope (AMPLS) allows you to create a private endpoint that enables secure communication between your virtual machines and Azure Monitor over the virtual network."}, {"img": "az104/img/t2_image21.webp"}, {"p": "a private endpoint is incorrect because, while it is part of the setup, it must be associated with an AMPLS to connect the virtual machines to Azure Monitor privately. AMPLS is the primary requirement for establishing private connectivity."}, {"p": "a data collection rule (DCR) is incorrect because DCRs are used to define which data to collect from resources for Azure Monitor but do not control network connectivity or enable private communication with Azure Monitor."}, {"p": "a Log Analytics workspace is incorrect because, while required for Azure Monitor for VM Insights, it does not enable private connectivity with Azure Monitor. The AMPLS is necessary to restrict communication through CorpVNet."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-monitor/logs/private-link-security#advantages"], "group": "G70"}, {"id": "T2-Q50", "test": 2, "num": 50, "domain": "compute", "stem": [{"p": "You have an Azure subscription and plan to deploy a virtual machine by using an Azure Resource Manager (ARM) template."}, {"p": "The virtual machine must be created with multiple data disks."}, {"p": "You need to complete the template shown in the below."}, {"img": "az104/img/t2_image22.webp"}, {"p": "What should you choose for Code Segment A?"}], "options": ["\"copy\":[", "\"copyIndex\":[", "\"dependsOn\":["], "correct": [0], "multi": false, "explanation": [{"p": "\"copy\":[ is correct because the \"copy\" property is used in ARM templates to define an array of resources or properties that need to be created multiple times. In this case, the data disks need to be created dynamically based on the value of the numberOfDataDisks parameter. Using \"copy\":[ allows iterating over the required number of disks and defining their properties in the ARM template."}, {"img": "az104/img/t2_image23.webp"}, {"p": "\"copyIndex\":[ is incorrect because \"copyIndex\" is a function used within the \"copy\" property to get the current iteration index. It cannot replace the \"copy\" property itself."}, {"p": "\"dependsOn\":[ is incorrect because \"dependsOn\" is used to specify dependencies between resources in an ARM template to ensure that certain resources are created before others. It does not help in defining multiple instances of a resource or property."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/copy-resources"], "group": "G71"}, {"id": "T2-Q51", "test": 2, "num": 51, "domain": "compute", "stem": [{"p": "You have an Azure subscription and plan to deploy a virtual machine by using an Azure Resource Manager (ARM) template."}, {"p": "The virtual machine must be created with multiple data disks."}, {"p": "You need to complete the template shown in the below."}, {"img": "az104/img/t2_image22.webp"}, {"p": "What should you choose for Code Segment B?"}], "options": ["\"[copy", "\"[copyIndex", "\"[dependsOn"], "correct": [1], "multi": false, "explanation": [{"p": "\"[copyIndex\" is correct because the copyIndex() function is used to generate a unique index for each iteration of the copy property in an ARM template. This is particularly useful when you need to create multiple instances of a resource or property, as in this case, where each data disk is assigned a unique Logical Unit Number (LUN). By using \"[copyIndex]\", the LUN property dynamically assigns a unique index to each data disk being created."}, {"p": "\"[copy\" is incorrect because \"copy\" is a property used to define the array creation logic in an ARM template. It cannot be used directly as a value in this context."}, {"p": "\"[dependsOn\" is incorrect because \"dependsOn\" is used to specify dependencies between resources in an ARM template. It does not apply to the dynamic generation of unique indices for resources."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/copy-resources"], "group": "G71"}, {"id": "T2-Q52", "test": 2, "num": 52, "domain": "storage", "stem": [{"p": "You have an Azure subscription that contains the following resources:"}, {"p": "A virtual machine named VM1, located in East US"}, {"p": "A storage account named storage1, located in West US"}, {"p": "You must ensure that all data transfers between VM1 and storage1 occur entirely over the Azure private network and do not traverse the public internet."}, {"p": "What should you configure for storage1 to meet this requirement?"}], "options": ["a shared access signature (SAS)", "data protection", "a private endpoint", "Public network access in the Firewalls and virtual networks settings"], "correct": [2], "multi": false, "explanation": [{"p": "a private endpoint is correct because configuring a private endpoint for storage1 ensures that data transfers between VM1 and storage1 occur entirely within the Azure virtual network. A private endpoint maps the storage account to a private IP address in the virtual network, preventing traffic from traversing the internet and providing a secure connection."}, {"img": "az104/img/t2_image24.webp"}, {"p": "a shared access signature (SAS) is incorrect because an SAS provides granular access to resources in a storage account but does not ensure that the data transfer stays within the Azure virtual network."}, {"p": "data protection is incorrect because it relates to enabling recovery options and configuring soft delete features for protecting data but does not control the network path used for data transfer."}, {"p": "Public network access in the Firewalls and virtual networks settings is incorrect because disabling public network access would block all internet-based traffic but does not ensure that traffic is routed privately within Azure."}], "refs": ["https://learn.microsoft.com/en-us/azure/private-link/private-endpoint-overview", "https://learn.microsoft.com/en-us/azure/storage/common/storage-private-endpoints"], "group": "G72"}, {"id": "T2-Q53", "test": 2, "num": 53, "domain": "storage", "stem": [{"p": "You are configuring Microsoft Entra ID–based authentication for an Azure Storage account named storage1."}, {"p": "You must ensure that users who are members of a security group named Group1 can upload files to the storage account by using the Azure portal."}, {"p": "The access configuration must follow the principle of least privilege, granting only the minimum permissions required to perform the upload operation."}, {"p": "Which two roles should you assign to Group1 to meet these requirements?"}], "options": ["Reader", "Storage Blob Data Reader", "Storage Blob Data Contributor", "Storage Account Contributor", "Contributor"], "correct": [0, 2], "multi": true, "explanation": [{"p": "Reader is correct because it grants management-plane read access to the storage account. Although this role does not allow users to upload files, it enables them to discover and navigate the storage account and its containers in the Azure portal. When using Microsoft Entra ID based authentication through the Azure portal, this role is required so users can access the storage account interface without being granted administrative permissions."}, {"p": "Storage Blob Data Contributor is correct because it grants the data-plane permissions required to read, write, modify, and delete blob data. This is the role that actually allows members of Group1 to upload files to blob storage."}, {"p": "Storage Blob Data Reader is incorrect because it only grants read access to blob data. Users can view blobs but cannot upload, modify, or delete them."}, {"p": "Storage Account Contributor is incorrect because it grants management permissions over the storage account, such as configuring storage account settings. These administrative permissions are unnecessary for uploading files and violate the principle of least privilege."}, {"p": "Contributor is incorrect because it provides broad management access to Azure resources, including the storage account. This exceeds the permissions required for uploading files and does not follow the principle of least privilege."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#storage-blob-data-contributor", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#reader"], "group": "G73"}, {"id": "T2-Q54", "test": 2, "num": 54, "domain": "storage", "stem": [{"p": "You manage an Azure Storage account named datastore01."}, {"p": "The account includes a blob container named archivecontainer."}, {"p": "You must ensure that any new blobs uploaded to archivecontainer cannot be altered or deleted for a period of one year after they are created."}, {"p": "Which configuration should you apply to meet this requirement?"}], "options": ["The Access control (IAM) settings", "An access policy", "The access level", "The access tier"], "correct": [1], "multi": false, "explanation": [{"p": "An access policy is the correct answer because immutable storage in Azure Blob Storage is configured using immutability policies (such as time-based retention or legal hold), which are set at the container level. Although technically this is not the same as a \"stored access policy\" used with SAS tokens, the term \"access policy\" here refers to the immutability policy configuration under the container’s \"Access policy\" settings in the Azure portal. By configuring a time-based retention policy under these settings, you can ensure that any new blobs added to the container cannot be modified or deleted for one year, thereby satisfying the requirement for data immutability."}, {"p": "The Access control (IAM) settings is incorrect because IAM controls role-based access to storage resources, defining who can read, write, or manage resources, but it does not enforce data immutability or retention policies."}, {"p": "The access level is incorrect because it defines whether the container and blobs can be publicly accessed (e.g., private, blob, or container level), but it has no impact on the ability to modify or retain content."}, {"p": "The access tier is incorrect because it specifies the performance and cost model of the blob data (Hot, Cool, Cold, or Archive). It does not prevent modifications or define retention behavior."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/immutable-storage-overview", "https://docs.microsoft.com/en-us/azure/storage/blobs/immutable-time-based-retention-policy-overview"], "group": "G74"}, {"id": "T2-Q55", "test": 2, "num": 55, "domain": "monitor", "stem": [{"p": "You have an Azure subscription named ProdSub1 that contains the following resources:"}, {"p": "RegGrp1 – A resource group"}, {"p": "Action1 – An action group configured to send an email notification to admin1@apexcore.com"}, {"p": "The subscription includes an alert rule with the following configuration:"}, {"p": "Name: Alert1"}, {"p": "Scope: All resource groups in ProdSub1, including any resource groups created in the future"}, {"p": "Condition: All administrative operations"}, {"p": "Action: Action1"}, {"p": "The subscription also includes an alert processing rule with the following settings:"}, {"p": "Name: Rule1"}, {"p": "Scope: ProdSub1"}, {"p": "Rule type: Suppress notifications"}, {"p": "Schedule:"}, {"p": "Start: September 10, 2024"}, {"p": "End: September 13, 2024"}, {"p": "True or False:"}, {"p": "\"If you create a resource group in ProdSub1 on September 11, 2024, Alert1 is listed in the Azure portal.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because Alert1 has a scope that includes all resource groups in ProdSub1. It also includes all future resources. This means that any resource group created in ProdSub1, regardless of when it's created, will fall under the scope of Alert1. So, if a new resource group is created in ProdSub1 on September 11, 2024, Alert1 would be listed in the Azure portal for that resource group."}], "refs": ["https://docs.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview", "https://docs.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-create", "https://docs.microsoft.com/en-us/azure/azure-monitor/platform/action-groups", "https://docs.microsoft.com/en-us/azure/azure-monitor/platform/alerts-action-rules"], "group": "G75"}, {"id": "T2-Q56", "test": 2, "num": 56, "domain": "monitor", "stem": [{"p": "You have an Azure subscription named ProdSub1 that contains the following resources:"}, {"p": "RegGrp1 – A resource group"}, {"p": "Action1 – An action group configured to send an email notification to admin1@apexcore.com"}, {"p": "The subscription includes an alert rule with the following configuration:"}, {"p": "Name: Alert1"}, {"p": "Scope: All resource groups in ProdSub1, including any resource groups created in the future"}, {"p": "Condition: All administrative operations"}, {"p": "Action: Action1"}, {"p": "The subscription also includes an alert processing rule with the following settings:"}, {"p": "Name: Rule1"}, {"p": "Scope: ProdSub1"}, {"p": "Rule type: Suppress notifications"}, {"p": "Schedule:"}, {"p": "Start: September 10, 2024"}, {"p": "End: September 13, 2024"}, {"p": "True or False:"}, {"p": "\"If you create a resource group in ProdSub1 on September 12, 2024, an email message is sent to admin1@apexcore.com.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because, although Alert1 is configured to send an email to admin1@apexcore.com for all administrative operations, there is an alert processing rule (Rule1) in place that suppresses notifications between September 10, 2024 and September 13, 2024. Therefore, despite a new resource group being created in ProdSub1 on September 12, 2024, which is an administrative operation, the suppress rule will prevent the email notification from being sent to admin1@apexcore.com."}], "refs": ["https://docs.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview", "https://docs.microsoft.com/en-us/azure/azure-monitor/platform/action-groups", "https://docs.microsoft.com/en-us/azure/azure-monitor/platform/alerts-action-rules"], "group": "G75"}, {"id": "T2-Q57", "test": 2, "num": 57, "domain": "monitor", "stem": [{"p": "You have an Azure subscription named ProdSub1 that contains the following resources:"}, {"p": "RegGrp1 – A resource group"}, {"p": "Action1 – An action group configured to send an email notification to admin1@apexcore.com"}, {"p": "The subscription includes an alert rule with the following configuration:"}, {"p": "Name: Alert1"}, {"p": "Scope: All resource groups in ProdSub1, including any resource groups created in the future"}, {"p": "Condition: All administrative operations"}, {"p": "Action: Action1"}, {"p": "The subscription also includes an alert processing rule with the following settings:"}, {"p": "Name: Rule1"}, {"p": "Scope: ProdSub1"}, {"p": "Rule type: Suppress notifications"}, {"p": "Schedule:"}, {"p": "Start: September 10, 2024"}, {"p": "End: September 13, 2024"}, {"p": "True or False:"}, {"p": "“If you add a tag to RG1 on September 15, 2022, an email message is sent to admin1@apexcore.com.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer because the alert rule, Alert1, is set to monitor all administrative operations, and adding a tag to a resource is considered an administrative operation in Azure. Since the alert applies to all resource groups in ProdSub1, including future resources, and the suppression rule (which suppresses notifications) only applies between September 10, 2024, and September 13, 2024, the action group linked to Alert1 will trigger an email to admin1@apexcore.com when the tag is added on September 15, 2024."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview", "https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/action-groups"], "group": "G75"}, {"id": "T2-Q58", "test": 2, "num": 58, "domain": "monitor", "stem": [{"p": "You have an Azure subscription that contains a virtual machine named VM1."}, {"p": "You need to configure backups for VM1. The solution must ensure that the backup data is stored across three availability zones within the primary Azure region."}, {"p": "Which three actions should you perform in sequence?"}, {"p": "ACTIONS"}, {"p": "Configure a replication policy."}, {"p": "Create a Recovery Services vault."}, {"p": "Set the vault replication type to Zone-redundant storage (ZRS)."}, {"p": "Set the vault replication type to Locally-redundant storage (LRS)."}, {"p": "Create a backup policy for VM1 and enable backup for the virtual machine."}], "options": ["2-5-3", "2-3-5", "5-3-2", "3-5-2"], "correct": [1], "multi": false, "explanation": [{"p": "(Action 2) Create a Recovery Services vault is the first step because the Recovery Services vault is where backup data is stored, and it supports multiple types of replication, including zone-redundant storage (ZRS) which is necessary for availability across three zones."}, {"p": "(Action 3) Set the vault replication type to Zone-redundant storage (ZRS) is the second step. After creating the vault, you must configure it to use zone-redundant storage, ensuring that the backups are replicated across three availability zones for higher availability."}, {"p": "(Action 5) Create a backup policy for VM1 and enable backup for the virtual machine is the final step. After the vault is created and configured, you need to create a backup policy and link it to VM1 to manage backup schedules and retention."}, {"p": "(Action 1) Configure a replication policy is incorrect because the backup replication type (ZRS) is set as part of the vault configuration, not a separate policy."}, {"p": "(Action 4) Set the vault replication type to Locally-redundant storage (LRS) is incorrect because LRS only replicates within a single data center, not across multiple availability zones, and thus does not meet the requirement of storing backups across three zones."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-create-recovery-services-vault", "https://learn.microsoft.com/en-us/azure/backup/quick-backup-vm-portal"], "group": "G76"}, {"id": "T2-Q59", "test": 2, "num": 59, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant named adatum.com."}, {"p": "The tenant contains the following security groups:"}, {"p": "Group1"}, {"p": "Type: Security"}, {"p": "Member of: None"}, {"p": "Group2"}, {"p": "Type: Security"}, {"p": "Member of: Group1"}, {"p": "The tenant also contains the following users:"}, {"p": "User1"}, {"p": "Member of: Group1"}, {"p": "User2"}, {"p": "Member of: Group2"}, {"p": "You assign a Microsoft Entra ID P2 license to Group1."}, {"p": "The license is configured so that the Microsoft Entra ID P2 service plan is enabled."}, {"img": "az104/img/t2_image25.webp"}, {"p": "Group2 is not directly assigned any licenses."}, {"p": "True or False:"}, {"p": "“You can remove the Microsoft Entra ID P2 license from User1.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because User1 received the Microsoft Entra ID P2 license through group-based licensing via Group1. Licenses assigned through a group cannot be removed directly from an individual user. To revoke the license from User1, you must either remove User1 from Group1 or unassign the license from Group1 entirely."}, {"p": "Group-based licensing enforces inheritance, meaning individual license removal is not possible for users who inherit their license through a group assignment."}], "refs": ["https://learn.microsoft.com/en-us/entra/fundamentals/concept-group-based-licensing"], "group": "G77"}, {"id": "T2-Q60", "test": 2, "num": 60, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant named adatum.com."}, {"p": "The tenant contains the following security groups:"}, {"p": "Group1"}, {"p": "Type: Security"}, {"p": "Member of: None"}, {"p": "Group2"}, {"p": "Type: Security"}, {"p": "Member of: Group1"}, {"p": "The tenant also contains the following users:"}, {"p": "User1"}, {"p": "Member of: Group1"}, {"p": "User2"}, {"p": "Member of: Group2"}, {"p": "You assign a Microsoft Entra ID P2 license to Group1."}, {"p": "The license is configured so that the Microsoft Entra ID P2 service plan is enabled."}, {"img": "az104/img/t2_image25.webp"}, {"p": "Group2 is not directly assigned any licenses."}, {"p": "True or False:"}, {"p": "“User2 is assigned the Microsoft Entra ID P2 license.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer because Microsoft Entra group-based licensing does not support nested group inheritance. In this scenario, although Group1 has been assigned the Microsoft Entra ID P2 license, User2 is only a member of Group2, which is a child of Group1. Because nested groups are not supported for license propagation, User2 will not receive the license via Group1 unless Group2 is directly licensed or the license is directly assigned to User2."}], "refs": ["https://learn.microsoft.com/en-us/entra/fundamentals/concept-group-based-licensing", "https://learn.microsoft.com/en-gb/entra/identity/users/licensing-group-advanced"], "group": "G77"}, {"id": "T2-Q61", "test": 2, "num": 61, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant named adatum.com."}, {"p": "The tenant contains the following security groups:"}, {"p": "Group1"}, {"p": "Type: Security"}, {"p": "Member of: None"}, {"p": "Group2"}, {"p": "Type: Security"}, {"p": "Member of: Group1"}, {"p": "The tenant also contains the following users:"}, {"p": "User1"}, {"p": "Member of: Group1"}, {"p": "User2"}, {"p": "Member of: Group2"}, {"p": "You assign a Microsoft Entra ID P2 license to Group1."}, {"p": "The license is configured so that the Microsoft Entra ID P2 service plan is enabled."}, {"img": "az104/img/t2_image25.webp"}, {"p": "Group2 is not directly assigned any licenses."}, {"p": "True or False:"}, {"p": "“You can assign User1 the Microsoft Defender for Cloud Apps Discovery license.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer because when a license is assigned to a group, the licensing options are inherited by all members of the group, and individual users cannot modify or enable specific license features that were disabled at the group level."}, {"p": "User1 is a member of Group1, which has the Microsoft Entra ID P2 license assigned."}, {"p": "- If specific features within the license, such as Microsoft Defender for Cloud Apps Discovery, were disabled when assigning the license to Group1, they remain disabled for all members."}, {"p": "- License settings inherited from a group cannot be modified at the user level."}, {"p": "Group-based licensing controls all assigned features."}, {"p": "- Microsoft Entra ID group-based licensing ensures that individual users cannot override settings configured at the group level."}, {"p": "- If an admin wants to enable a feature, the change must be made at the group level, not for individual users."}, {"p": "User-level modifications are restricted."}, {"p": "- Since User1’s license is inherited from Group1, they cannot be manually assigned the Microsoft Defender for Cloud Apps Discovery license unless Group1’s settings are updated to enable it."}], "refs": ["https://docs.microsoft.com/en-us/azure/active-directory/fundamentals/active-directory-licensing-whatis-azure-portal", "https://docs.microsoft.com/en-us/cloud-app-security/manage-admins"], "group": "G77"}, {"id": "T2-Q62", "test": 2, "num": 62, "domain": "compute", "stem": [{"p": "You have an Azure subscription named Subscription1 that has the following vCPU quotas in the West US region:"}, {"p": "Standard BS Family vCPUs: 20 (0 currently used)"}, {"p": "Standard D Family vCPUs: 20 (0 currently used)"}, {"p": "Total Regional vCPUs: 20 (0 currently used)"}, {"p": "The subscription currently contains the following virtual machines deployed in West US:"}, {"p": "VM1"}, {"p": "Size: Standard_B2ms"}, {"p": "vCPUs: 2"}, {"p": "Status: Running"}, {"p": "VM2"}, {"p": "Size: Standard_B16ms"}, {"p": "vCPUs: 16"}, {"p": "Status: Stopped (Deallocated)"}, {"p": "You now plan to deploy the following additional virtual machines:"}, {"img": "az104/img/t2_image26.webp"}, {"p": "True or False:"}, {"p": "“You can deploy VM3 to West US.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct. In this scenario, VM1 is running and uses 2 vCPUs. VM2 is in a Stopped (Deallocated) state, but it still counts against the vCPU quota because Azure reserves resources for any provisioned (even if deallocated) VM. This brings the current vCPU usage to:"}, {"p": "VM1: 2 vCPUs"}, {"p": "VM2: 16 vCPUs"}, {"p": "Total usage: 18 out of 20 vCPUs (under the Total Regional vCPU quota)"}, {"p": "VM3 requires 2 vCPUs, which would increase total usage to exactly 20, matching the quota but not exceeding it. Therefore, the deployment is allowed."}, {"p": "Additionally, the Standard BS Family vCPU quota is 20. VM2 (Standard_B16ms) is a B-series VM, so it counts toward this quota too, alongside VM1. Current usage is therefore 18 vCPUs (VM1's 2 + VM2's 16). Adding VM3 (2 vCPUs from the same family) brings it to exactly 20, which is also allowed."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-machines/quotas?tabs=cli", "https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/azure-subscription-service-limits"], "group": "G78"}, {"id": "T2-Q63", "test": 2, "num": 63, "domain": "compute", "stem": [{"p": "You have an Azure subscription named Subscription1 that has the following vCPU quotas in the West US region:"}, {"p": "Standard BS Family vCPUs: 20 (0 currently used)"}, {"p": "Standard D Family vCPUs: 20 (0 currently used)"}, {"p": "Total Regional vCPUs: 20 (0 currently used)"}, {"p": "The subscription currently contains the following virtual machines deployed in West US:"}, {"p": "VM1"}, {"p": "Size: Standard_B2ms"}, {"p": "vCPUs: 2"}, {"p": "Status: Running"}, {"p": "VM2"}, {"p": "Size: Standard_B16ms"}, {"p": "vCPUs: 16"}, {"p": "Status: Stopped (Deallocated)"}, {"p": "You now plan to deploy the following additional virtual machines:"}, {"img": "az104/img/t2_image26.webp"}, {"p": "True or False:"}, {"p": "“You can deploy VM4 to West US.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct as the Total Regional vCPUs quota in West US is capped at 20 vCPUs. This quota represents the maximum total vCPUs across all VM sizes, regardless of whether a virtual machine is running or stopped (deallocated)."}, {"p": "In the current scenario:"}, {"p": "VM1 is consuming 2 vCPUs (Running)."}, {"p": "VM2 is Stopped (Deallocated) but still counts towards the total regional vCPU quota with 16 vCPUs reserved."}, {"p": "This results in:"}, {"p": "2 vCPUs (VM1) + 16 vCPUs (VM2) = 18 vCPUs"}, {"p": "This leaves only 2 vCPUs available under the regional quota."}, {"p": "VM4 requires 4 vCPUs, which would bring the total to:"}, {"p": "2 vCPUs (VM1) + 16 vCPUs (VM2) + 4 vCPUs (VM4) = 22 vCPUs"}, {"p": "This exceeds the total regional vCPU quota of 20 vCPUs, making the deployment of VM4 impossible under the current quota limits."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-machines/quotas?tabs=cli", "https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/azure-subscription-service-limits"], "group": "G78"}, {"id": "T2-Q64", "test": 2, "num": 64, "domain": "compute", "stem": [{"p": "You have an Azure subscription named Subscription1 that has the following vCPU quotas in the West US region:"}, {"p": "Standard BS Family vCPUs: 20 (0 currently used)"}, {"p": "Standard D Family vCPUs: 20 (0 currently used)"}, {"p": "Total Regional vCPUs: 20 (0 currently used)"}, {"p": "The subscription currently contains the following virtual machines deployed in West US:"}, {"p": "VM1"}, {"p": "Size: Standard_B2ms"}, {"p": "vCPUs: 2"}, {"p": "Status: Running"}, {"p": "VM2"}, {"p": "Size: Standard_B16ms"}, {"p": "vCPUs: 16"}, {"p": "Status: Stopped (Deallocated)"}, {"p": "You now plan to deploy the following additional virtual machines:"}, {"img": "az104/img/t2_image26.webp"}, {"p": "True or False:"}, {"p": "“You can deploy VM5 to West US.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because the Total Regional vCPU quota in the West US region is 20 vCPUs. This quota accounts for all allocated and deallocated virtual machines in the region."}, {"p": "The current vCPU usage is as follows:"}, {"p": "VM1: 2 vCPUs (Running)"}, {"p": "VM2: 16 vCPUs (Stopped/Deallocated)"}, {"p": "Even though VM2 is deallocated, its 16 vCPUs still count toward the regional vCPU quota because Azure reserves these resources for the VM."}, {"p": "This means the total vCPU usage stands at:"}, {"p": "2 vCPUs (VM1) + 16 vCPUs (VM2) = 18 vCPUs"}, {"p": "VM5 requires 16 vCPUs. Adding these would result in:"}, {"p": "2 vCPUs (VM1) + 16 vCPUs (VM2) + 16 vCPUs (VM5) = 34 vCPUs"}, {"p": "This far exceeds the 20 vCPU quota for the West US region, making it impossible to deploy VM5 without increasing the quota or deallocating other virtual machines."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-machines/quotas?tabs=cli", "https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/azure-subscription-service-limits"], "group": "G78"}, {"id": "T2-Q65", "test": 2, "num": 65, "domain": "identity", "stem": [{"p": "You manage a Microsoft Entra tenant named ironclad.com."}, {"p": "The tenant contains the following groups:"}, {"p": "Group1"}, {"p": "Group type: Security"}, {"p": "Membership type: Dynamic user"}, {"p": "Rule: Users where city starts with “m”"}, {"p": "Group2"}, {"p": "Group type: Microsoft 365"}, {"p": "Membership type: Dynamic user"}, {"p": "Rule: Users whose department is not “human resources”"}, {"p": "Group3"}, {"p": "Group type: Microsoft 365"}, {"p": "Membership type: Assigned"}, {"p": "No dynamic rule configured"}, {"p": "You then create two users with the following attributes:"}, {"p": "User1"}, {"p": "City: Montreal"}, {"p": "Department: Human resources"}, {"p": "Microsoft 365 license assigned: Yes"}, {"p": "User2"}, {"p": "City: Melbourne"}, {"p": "Department: Marketing"}, {"p": "Microsoft 365 license assigned: No"}, {"p": "Based on the configured dynamic membership rules and user properties, which group or groups does User1 belong to?"}], "options": ["Group1 only", "Group2 only", "Group3 only", "Group1 and Group2 only", "Group1 and Group3 only", "Group1, Group2, and Group3"], "correct": [0], "multi": false, "explanation": [{"p": "Group1 only is correct because User1 meets the dynamic membership rule for Group1 but does not meet the membership criteria for Group2 or Group3."}, {"p": "Group1 (Dynamic user): The rule specifies that users whose city starts with \"m\" are added to this group."}, {"p": "User1's city is Montreal, which starts with \"M.\" Therefore, User1 is a member of Group1."}, {"p": "Group2 (Dynamic user): The rule excludes users whose department is \"human resources.\""}, {"p": "User1's department is \"Human resources,\" so User1 is excluded from Group2."}, {"p": "Group3 (Assigned membership): Membership is manually assigned."}, {"p": "User1 is not manually assigned to Group3, so User1 is not a member of Group3."}, {"p": "Therefore, User1 is only a member of Group1."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/users/groups-dynamic-membership", "https://learn.microsoft.com/en-us/entra/identity/users/groups-create-rule"], "group": "G79"}, {"id": "T2-Q66", "test": 2, "num": 66, "domain": "identity", "stem": [{"p": "You manage a Microsoft Entra tenant named ironclad.com."}, {"p": "The tenant contains the following groups:"}, {"p": "Group1"}, {"p": "Group type: Security"}, {"p": "Membership type: Dynamic user"}, {"p": "Rule: Users where city starts with “m”"}, {"p": "Group2"}, {"p": "Group type: Microsoft 365"}, {"p": "Membership type: Dynamic user"}, {"p": "Rule: Users whose department is not “human resources”"}, {"p": "Group3"}, {"p": "Group type: Microsoft 365"}, {"p": "Membership type: Assigned"}, {"p": "No dynamic rule configured"}, {"p": "You then create two users with the following attributes:"}, {"p": "User1"}, {"p": "City: Montreal"}, {"p": "Department: Human resources"}, {"p": "Microsoft 365 license assigned: Yes"}, {"p": "User2"}, {"p": "City: Melbourne"}, {"p": "Department: Marketing"}, {"p": "Microsoft 365 license assigned: No"}, {"p": "Based on the configured dynamic membership rules and user properties, which group or groups does User2 belong to?"}], "options": ["Group1 only", "Group2 only", "Group3 only", "Group1 and Group2 only", "Group1 and Group3 only", "Group2 and Group3 only"], "correct": [3], "multi": false, "explanation": [{"p": "Group1 and Group2 only is correct because User2 meets the membership rules for both Group1 and Group2 based on their city and department attributes."}, {"p": "Group1 (Dynamic user): The membership rule specifies that users are added if their city starts with \"m\"."}, {"p": "User2's city is Melbourne, which starts with \"M\". Therefore, User2 satisfies the rule for Group1."}, {"p": "Group2 (Dynamic user): The membership rule specifies that users whose department is not \"human resources\" are included."}, {"p": "User2's department is Marketing, which satisfies the notIn [\"human resources\"] rule. Therefore, User2 is included in Group2."}, {"p": "Group3 (Assigned membership): Membership is manually assigned."}, {"p": "User2 has not been manually added to Group3, so they are not a member of Group3."}, {"p": "Additionally, the Microsoft 365 license does not impact group membership. Licenses are only for accessing services and do not affect dynamic or assigned group memberships."}, {"p": "Therefore, User2 is a member of Group1 and Group2 only."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/users/groups-dynamic-membership", "https://learn.microsoft.com/en-us/entra/identity/users/groups-create-rule"], "group": "G79"}, {"id": "T2-Q67", "test": 2, "num": 67, "domain": "compute", "stem": [{"p": "You have an Azure subscription that contains a virtual machine running Windows 10."}, {"p": "You need to join the virtual machine to an Active Directory domain by using the below Azure Resource Manager (ARM) template."}, {"img": "az104/img/t2_image27.webp"}, {"p": "Which value should you choose for Code Segment A?"}], "options": ["\"Extensions\",", "\"Microsoft.Compute/VirtualMachines\",", "\"Microsoft.Compute/virtualMachines/extensions\","], "correct": [2], "multi": false, "explanation": [{"p": "\"Microsoft.Compute/virtualMachines/extensions\" is correct because. This namespace specifies that the resource being managed is an extension applied to an Azure virtual machine."}, {"img": "az104/img/t2_image28.webp"}, {"p": "\"Extensions\" is incorrect because it is not a valid Azure Resource Manager resource type."}, {"p": "\"Microsoft.Compute/VirtualMachines\" is incorrect because it refers to virtual machines themselves, not their extensions."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/overview", "https://learn.microsoft.com/en-us/azure/templates/microsoft.compute/virtualmachines/extensions", "https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/dsc-template#domain-join"], "group": "G80"}, {"id": "T2-Q68", "test": 2, "num": 68, "domain": "compute", "stem": [{"p": "You have an Azure subscription that contains a virtual machine running Windows 10."}, {"p": "You need to join the virtual machine to an Active Directory domain by using the below Azure Resource Manager (ARM) template."}, {"img": "az104/img/t2_image27.webp"}, {"p": "Which value should you choose for Code Segment B?"}], "options": ["\"ProtectedSettings\": {", "\"Settings\": {", "\"Statuses\": {"], "correct": [0], "multi": false, "explanation": [{"p": "\"ProtectedSettings\": { is correct because in an Azure Resource Manager (ARM) template, sensitive information like passwords or secrets, such as the domainPassword, should always be placed in the ProtectedSettings section. This ensures that the sensitive values are securely encrypted and not exposed in plaintext when viewed or logged."}, {"img": "az104/img/t2_image29.webp"}, {"p": "\"Settings\": { is incorrect because it is used for general configuration settings and does not handle sensitive information securely."}, {"p": "\"Statuses\": { is incorrect because it is used to report the status of an extension deployment, not for passing configuration parameters."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/domain-join", "https://learn.microsoft.com/en-us/azure/templates/microsoft.compute/virtualmachines/extensions", "https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/dsc-template#domain-join"], "group": "G80"}, {"id": "T2-Q69", "test": 2, "num": 69, "domain": "network", "stem": [{"p": "You have an Azure subscription that hosts several resources accessed by users from two locations:"}, {"p": "Users working from home connect to Azure by using a point-to-site (P2S) VPN."}, {"p": "Users at customer locations connect to Azure by using site-to-site (S2S) VPNs."}, {"p": "There is a line-of-business application named App1 that runs on multiple Azure virtual machines."}, {"p": "All the virtual machines run Windows Server 2016."}, {"p": "You must ensure that incoming connections to App1 are evenly distributed across all the virtual machines."}, {"p": "Which two Azure services can you use to meet this requirement?"}], "options": ["an internal load balancer", "a public load balancer", "an Azure Content Delivery Network (CDN)", "Traffic Manager", "an Azure Application Gateway"], "correct": [0, 4], "multi": true, "explanation": [{"p": "an internal load balancer is the correct answer because it distributes incoming traffic evenly across virtual machines within the same virtual network. Internal Load Balancers are used when applications are accessed only internally and do not require public internet exposure. This matches the scenario where users are connecting through VPNs, either point-to-site or site-to-site, and need internal routing of traffic to backend virtual machines hosting App1."}, {"p": "an Azure Application Gateway is also correct because it is a layer-7 (application layer) load balancer that can intelligently route traffic based on HTTP/HTTPS requests. It is suitable for web applications like App1, providing features such as URL-based routing, SSL termination, and session affinity, ensuring optimized and secure delivery of requests to the virtual machines hosting App1."}, {"p": "a public load balancer is incorrect because it distributes incoming traffic from public IP addresses. In this scenario, the application is accessed internally through VPN connections rather than from the public internet."}, {"p": "an Azure Content Delivery Network (CDN) is incorrect because CDN is designed to cache and deliver static content like images, videos, and scripts globally. It does not handle traffic distribution to backend virtual machines for business applications like App1."}, {"p": "Traffic Manager is incorrect because it operates at the DNS level and is used to direct users to different endpoints based on rules like geographic location or endpoint health. It does not distribute traffic across virtual machines within the same virtual network."}], "refs": ["https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview", "https://learn.microsoft.com/en-us/azure/application-gateway/overview", "https://learn.microsoft.com/en-us/azure/cdn/cdn-overview", "https://learn.microsoft.com/en-us/azure/traffic-manager/traffic-manager-overview"], "group": "G81"}, {"id": "T2-Q70", "test": 2, "num": 70, "domain": "identity", "stem": [{"p": "You have an Azure subscription that includes a user named User1."}, {"p": "You must grant User1 permissions to:"}, {"p": "Create and manage virtual machines"}, {"p": "Create and manage virtual networks"}, {"p": "The permissions assigned must follow the principle of least privilege."}, {"p": "Which role-based access control (RBAC) role should you assign to User1?"}], "options": ["Owner", "Virtual Machine Contributor", "Contributor", "Virtual Machine Administrator Login"], "correct": [2], "multi": false, "explanation": [{"p": "Contributor is the correct answer because this role grants full access to manage all Azure resources, including virtual machines and virtual networks, but does not allow access to assign roles in Azure RBAC. This aligns with the requirement to deploy virtual machines and manage virtual networks while following the principle of least privilege, as the role does not grant unnecessary permissions such as role assignment."}, {"p": "Owner is incorrect because the Owner role has full access to all resources, including the ability to assign roles in RBAC. This exceeds the principle of least privilege since User1 does not require role assignment capabilities."}, {"p": "Virtual Machine Contributor is incorrect because this role grants permissions only for managing virtual machines, but it does not include the ability to manage virtual networks, which is explicitly required in the scenario."}, {"p": "Virtual Machine Administrator Login is incorrect because this role only allows a user to log in to virtual machines with administrator privileges. It does not provide permissions to deploy virtual machines or manage virtual networks."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles", "https://learn.microsoft.com/en-us/azure/role-based-access-control/role-definitions", "https://learn.microsoft.com/en-us/azure/role-based-access-control/overview"], "group": "G82"}, {"id": "T2-Q71", "test": 2, "num": 71, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes the following resources:"}, {"p": "VNET1: A virtual network in resource group RG1"}, {"p": "VM1: A virtual machine in resource group RG1"}, {"p": "A Not allowed resource types Azure Policy is assigned to RG1 with enforcement enabled. The policy blocks the following resource types:"}, {"p": "Microsoft.Network/virtualNetworks"}, {"p": "Microsoft.Compute/virtualMachines"}, {"p": "You need to deploy a new virtual machine named VM2 in RG1 and connect it to VNET1."}, {"p": "What action must you take first?"}], "options": ["Remove Microsoft.Compute/virtualMachines from the policy.", "Add a subnet to VNET1.", "Remove Microsoft.Network/virtualNetworks from the policy.", "Create an Azure Resource Manager template."], "correct": [0], "multi": false, "explanation": [{"p": "Remove Microsoft.Compute/virtualMachines from the policy is the correct answer. The Not allowed resource types policy assigned to RG1 explicitly prevents the creation of resources with type Microsoft.Compute/virtualMachines, which includes any virtual machines. Since the goal is to create a new VM named VM2 in RG1, this policy must first be adjusted to allow VM creation. Otherwise, any deployment attempt for a VM (whether through portal, script, or ARM template) will be blocked due to the policy enforcement."}, {"p": "Add a subnet to VNET1 is incorrect because the presence or absence of a subnet does not address the core issue. Even if VNET1 had a valid subnet, the policy blocks VM creation entirely in RG1, making this step irrelevant at this point."}, {"p": "Remove Microsoft.Network/virtualNetworks from the policy is incorrect because there is no requirement to create a new virtual network—VNET1 already exists and is intended to be used. The VM can be connected to an existing VNet as long as the policy allows VM creation. Removing this restriction isn't necessary to create the VM."}, {"p": "Create an Azure Resource Manager template is incorrect because using an ARM template will still fail if the policy prohibits creating the specified resource types. Azure Policy enforcement blocks resource creation regardless of the method used—portal, CLI, PowerShell, or ARM templates."}], "refs": ["https://learn.microsoft.com/en-us/azure/templates/microsoft.compute/virtualmachines?pivots=deployment-language-bicep", "https://learn.microsoft.com/en-us/azure/governance/policy/concepts/definition-structure#policy-rule", "https://learn.microsoft.com/en-us/azure/governance/policy/concepts/effects#deny", "https://learn.microsoft.com/en-us/azure/governance/policy/samples/not-allowed-resource-types", "https://learn.microsoft.com/en-us/azure/virtual-machines/overview", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview"], "group": "G83"}, {"id": "T2-Q72", "test": 2, "num": 72, "domain": "network", "stem": [{"p": "An Azure subscription contains two resource groups with the following configurations:"}, {"p": "Resource group settings"}, {"p": "RG1"}, {"p": "Resource group lock: None"}, {"p": "RG2"}, {"p": "Resource group lock name: Lock"}, {"p": "Lock type: Delete"}, {"p": "Resources in RG1"}, {"p": "Storage1"}, {"p": "Type: Storage account"}, {"p": "Lock name: Lock1"}, {"p": "Lock type: Delete"}, {"p": "VNET1"}, {"p": "Type: Virtual network"}, {"p": "Lock name: Lock2"}, {"p": "Lock type: Read-only"}, {"p": "IP1"}, {"p": "Type: Public IP address"}, {"p": "Lock: None"}, {"p": "Resources in RG2"}, {"p": "Storage2"}, {"p": "Type: Storage account"}, {"p": "Lock name: Lock1"}, {"p": "Lock type: Delete"}, {"p": "VNET2"}, {"p": "Type: Virtual network"}, {"p": "Lock name: Lock2"}, {"p": "Lock type: Read-only"}, {"p": "IP2"}, {"p": "Type: Public IP address"}, {"p": "Lock: None"}, {"p": "Which resources can be moved from RG1 to RG2?"}], "options": ["None", "IP1 only", "IP1 and storage1 only", "IP1 and VNET1 only", "IP1, VNET1, and storage1"], "correct": [4], "multi": false, "explanation": [{"p": "IP1, VNET1, and storage1 is correct. Azure resource locks such as Read-only and Delete are designed to prevent deletion or modification of resources, but they do not block move operations. A Delete lock on a resource (such as storage1) or the target resource group (like RG2) does not prevent resources from being moved into or out of that group. Similarly, a Read-only lock (as applied to VNET1) restricts modifications but still permits the resource to be moved. IP1 has no lock, so it is fully eligible for movement. Since none of the listed locks prohibit the act of moving resources, all three resources — IP1, VNET1, and storage1 — can be moved from RG1 to RG2."}, {"p": "Resources created in RG1 (used name storage1shireen instead of storage1)"}, {"img": "az104/img/t2_image30.webp"}, {"p": "Lock on RG1: None"}, {"img": "az104/img/t2_image31.webp"}, {"p": "Locks on storage account and virtual network in RG1"}, {"img": "az104/img/t2_image32.webp"}, {"p": "Lock on RG2: Delete"}, {"img": "az104/img/t2_image33.webp"}, {"p": "Resources created in RG2 (used name storage2shireen instead of storage1)"}, {"img": "az104/img/t2_image34.webp"}, {"p": "Locks on RG2 and virtual network and storage account in RG2"}, {"img": "az104/img/t2_image35.webp"}, {"p": "Attempting to move IP1, VNet1, and storage1shireen to RG2"}, {"img": "az104/img/t2_image36.webp"}, {"p": "Sucessfully moved IP1, VNet1, and storage1shireen to RG2"}, {"img": "az104/img/t2_image37.webp"}, {"p": "Resources in RG1 after resource movement"}, {"img": "az104/img/t2_image38.webp"}, {"p": "Resources in RG2 after resource movement"}, {"img": "az104/img/t2_image39.webp"}], "refs": ["https://docs.microsoft.com/en-us/azure/azure-resource-manager/management/lock-resources"], "group": "G84"}, {"id": "T2-Q73", "test": 2, "num": 73, "domain": "network", "stem": [{"p": "An Azure subscription contains two resource groups with the following configurations:"}, {"p": "Resource group settings"}, {"p": "RG1"}, {"p": "Resource group lock: None"}, {"p": "RG2"}, {"p": "Resource group lock name: Lock"}, {"p": "Lock type: Delete"}, {"p": "Resources in RG1"}, {"p": "Storage1"}, {"p": "Type: Storage account"}, {"p": "Lock name: Lock1"}, {"p": "Lock type: Delete"}, {"p": "VNET1"}, {"p": "Type: Virtual network"}, {"p": "Lock name: Lock2"}, {"p": "Lock type: Read-only"}, {"p": "IP1"}, {"p": "Type: Public IP address"}, {"p": "Lock: None"}, {"p": "Resources in RG2"}, {"p": "Storage2"}, {"p": "Type: Storage account"}, {"p": "Lock name: Lock1"}, {"p": "Lock type: Delete"}, {"p": "VNET2"}, {"p": "Type: Virtual network"}, {"p": "Lock name: Lock2"}, {"p": "Lock type: Read-only"}, {"p": "IP2"}, {"p": "Type: Public IP address"}, {"p": "Lock: None"}, {"p": "Which resources can be moved from RG2 to RG1?"}], "options": ["None", "IP2 only", "IP2 and storage2 only", "IP2 and VNET2 only", "IP2, VNET2, and storage2"], "correct": [4], "multi": false, "explanation": [{"p": "IP2, VNET2, and storage2 is correct as Locks are designed for any update or removal. In this case, we want to move only, we are not deleting, and we are not changing anything in the resource."}, {"p": "In the previous question, we were able to move all resources from RG1 to RG2. Similarly, we will be able to move IP2, VNET2, and storage2 from RG2 to RG1."}, {"p": "Attempting to move resources from RG2 to RG1"}, {"img": "az104/img/t2_image40.webp"}, {"p": "After successful movement, RG2 resources"}, {"img": "az104/img/t2_image41.webp"}, {"p": "After successful movement, RG1 resources"}, {"img": "az104/img/t2_image42.webp"}], "refs": ["https://docs.microsoft.com/en-us/azure/azure-resource-manager/management/lock-resources"], "group": "G84"}, {"id": "T2-Q74", "test": 2, "num": 74, "domain": "storage", "stem": [{"p": "Refer to the Ironclad Manufacturing case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1KsF3wlRTNU8MfFDTFyswtTOs3axscynctGrm_mezY1A/edit?usp=sharing"}, {"p": "You need to determine the storage requirements for Ironclad."}, {"p": "True or False:"}, {"p": "“Ironclad requires a storage account that supports Blob storage.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer here. The case study states under Planned Changes that Ironclad plans to transfer the company's engineering design documents to Azure Blob Storage. Additionally, the Technical Requirements specify that the engineering design documents must be stored by using the Archive access tier. Therefore, Ironclad requires a storage account that supports Blob storage to meet these requirements."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blob-storage-tiers", "https://learn.microsoft.com/en-us/azure/storage/common/storage-account-overview"], "group": "G85"}, {"id": "T2-Q75", "test": 2, "num": 75, "domain": "storage", "stem": [{"p": "Refer to the Ironclad Manufacturing case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1KsF3wlRTNU8MfFDTFyswtTOs3axscynctGrm_mezY1A/edit?usp=sharing"}, {"p": "You need to determine the storage requirements for Ironclad."}, {"p": "True or False:"}, {"p": "“Ironclad requires a storage account that supports Azure Table storage.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer here. The case study does not specify any requirement to store structured NoSQL data or to use Azure Table storage."}, {"p": "The storage-related requirements state that Ironclad must:"}, {"p": "Transfer the engineering design documents to Azure Blob Storage."}, {"p": "Store the engineering design documents by using the Archive access tier."}, {"p": "Provide external partners with secure, temporary access to the engineering design documents."}, {"p": "These requirements relate to Azure Blob Storage, not Azure Table storage. Therefore, Ironclad does not require a storage account specifically to support Azure Table storage."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/tables/table-storage-overview", "https://learn.microsoft.com/en-us/azure/storage/common/storage-account-overview"], "group": "G85"}, {"id": "T2-Q76", "test": 2, "num": 76, "domain": "storage", "stem": [{"p": "Refer to the Ironclad Manufacturing case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1KsF3wlRTNU8MfFDTFyswtTOs3axscynctGrm_mezY1A/edit?usp=sharing"}, {"p": "You need to determine the storage requirements for Ironclad."}, {"p": "True or False:"}, {"p": "“Ironclad requires a storage account that supports Azure File Storage.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer here. The Ironclad Manufacturing case study explicitly requires that the engineering design documents be stored by using the Archive access tier. The Archive access tier is supported by Azure Blob Storage, not Azure File Storage. Since Azure File Storage does not support the Archive access tier, Ironclad's storage requirement, specifically the use of the Archive tier, cannot be fulfilled by a service that only supports file shares."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview", "https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction", "https://learn.microsoft.com/en-us/azure/storage/common/storage-account-overview"], "group": "G85"}, {"id": "T2-Q77", "test": 2, "num": 77, "domain": "storage", "stem": [{"p": "Refer to the Ironclad Manufacturing case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1KsF3wlRTNU8MfFDTFyswtTOs3axscynctGrm_mezY1A/edit?usp=sharing"}, {"p": "You need to migrate the blueprint files to Azure."}, {"p": "What action should you take?"}], "options": ["Use the Azure Import/Export service.", "Use Azure Storage Explorer to copy the files.", "Generate a shared access signature (SAS). Map a drive, and then copy the files by using File Explorer.", "Generate an access key. Map a drive, and then copy the files by using File Explorer."], "correct": [1], "multi": false, "explanation": [{"p": "Use Azure Storage Explorer to copy the files is the correct answer here. According to the Ironclad Manufacturing case study, under the Technical Requirements, it is stated that:"}, {"p": "The engineering design documents must be transferred to Azure by using the internet."}, {"p": "This rules out offline data transfer methods such as the Azure Import/Export service. The engineering design documents must also be stored in Azure Blob Storage. Azure Storage Explorer provides a GUI-based tool that can be used to upload, manage, and organize blob data in Azure Storage from a local computer."}, {"p": "Use the Azure Import/Export service is incorrect because because it is intended for large-scale offline data transfers using physical drives shipped to Azure datacenters. This does not meet the requirement to transfer the engineering design documents to Azure by using the internet."}, {"p": "Generate a shared access signature (SAS). Map a drive, and then copy the files by using File Explorer is incorrect because mapping a drive in this manner applies to Azure file shares, not Azure Blob Storage. Ironclad requires the engineering design documents to be stored in Azure Blob Storage by using the Archive access tier, which cannot be accessed as a mapped drive."}, {"p": "Generate an access key. Map a drive, and then copy the files by using File Explorer is incorrect for the same reason. Mapping a drive applies to Azure File Storage, not Azure Blob Storage, and does not meet the requirement to store the engineering design documents by using the Archive access tier."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/storage-explorer/vs-azure-tools-storage-manage-with-storage-explorer", "https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blob-storage-tiers", "https://learn.microsoft.com/en-us/azure/storage/common/storage-import-export-service", "https://learn.microsoft.com/en-us/azure/storage/files/storage-how-to-use-files-windows"], "group": "G85"}, {"id": "T2-Q78", "test": 2, "num": 78, "domain": "storage", "stem": [{"p": "Refer to the Ironclad Manufacturing case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1KsF3wlRTNU8MfFDTFyswtTOs3axscynctGrm_mezY1A/edit?usp=sharing"}, {"p": "You need to implement a backup solution for ProductionPortal after the application has been migrated."}, {"p": "What should you create first?"}], "options": ["a backup policy", "a Recovery Services vault", "an Azure Backup Server", "a recovery plan"], "correct": [1], "multi": false, "explanation": [{"p": "a Recovery Services vault is the correct answer here. According to the case study, under the Technical Requirements, it is stated that:"}, {"p": "\"All ProductionPortal virtual machines must be protected by backups.\""}, {"p": "In Azure, to back up virtual machines, the first step is to create a Recovery Services vault, which is used to store and manage backup data. Once the vault is created, you can then define backup policies, register virtual machines, and configure restore points."}, {"p": "a backup policy is incorrect because you cannot create or apply a backup policy until a Recovery Services vault exists to store and manage those backups."}, {"p": "an Azure Backup Server is incorrect because it is used primarily for on-premises backup scenarios. Ironclad is moving ProductionPortal to Azure, so this option is not applicable for protecting the Azure VMs.."}, {"p": "a recovery plan is incorrect because recovery plans are used with Azure Site Recovery, which focuses on disaster recovery rather than backup. It is unrelated to setting up regular backups for VMs."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-overview", "https://learn.microsoft.com/en-us/azure/backup/backup-configure-vault", "https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-first-look-arm", "https://learn.microsoft.com/en-us/azure/site-recovery/site-recovery-overview"], "group": "G85"}, {"id": "T2-Q79", "test": 2, "num": 79, "domain": "identity", "stem": [{"p": "Refer to the Ironclad Manufacturing case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1KsF3wlRTNU8MfFDTFyswtTOs3axscynctGrm_mezY1A/edit?usp=sharing"}, {"p": "You need to meet the user requirement for CloudAdmin."}, {"p": "What should you do?"}], "options": ["From the Subscriptions blade, select the subscription, and then modify the Access control (IAM) settings.", "From the Microsoft Entra ID blade, modify the Properties.", "From the Subscriptions blade, select the subscription, and then modify the Properties.", "From the Microsoft Entra ID blade, modify the Groups."], "correct": [0], "multi": false, "explanation": [{"p": "From the Subscriptions blade, select the subscription, and then modify the Access control (IAM) settings is the correct answer here. According to the case study, one of the user requirements is:"}, {"p": "\"A newly created user named CloudAdmin must be assigned as the service administrator for the Azure subscription.\""}, {"p": "In Azure, subscription-level access and administrative permissions are managed through Access control (IAM) for the subscription. Therefore, you should select the Azure subscription and use its Access control (IAM) settings to assign CloudAdmin the required permissions."}, {"p": "From the Microsoft Entra ID blade, modify the Properties is incorrect because this area is used to configure tenant-level properties (like branding, usage location), not subscription-level role assignments."}, {"p": "From the Subscriptions blade, select the subscription, and then modify the Properties is incorrect because the Properties section lets you view or rename the subscription but does not allow role assignment or access configuration."}, {"p": "From the Microsoft Entra ID blade, modify the Groups is incorrect because modifying Microsoft Entra ID groups does not directly assign subscription-level access to CloudAdmin. Subscription access is managed through Access control (IAM) at the subscription scope."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/role-assignments-portal", "https://learn.microsoft.com/en-us/azure/role-based-access-control/elevate-access-global-admin", "https://learn.microsoft.com/en-us/azure/role-based-access-control/overview"], "group": "G85"}, {"id": "T2-Q80", "test": 2, "num": 80, "domain": "network", "stem": [{"p": "Refer to the Ironclad Manufacturing case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1KsF3wlRTNU8MfFDTFyswtTOs3axscynctGrm_mezY1A/edit?usp=sharing"}, {"p": "You are planning to migrate ProductionPortal to Azure."}, {"p": "After creating a network security group (NSG), you need to recommend a solution that allows users to access ProductionPortal."}, {"p": "What should you recommend?"}], "options": ["Create an incoming security rule for port 443 from the Internet. Associate the NSG to the subnet that contains the web servers.", "Create an outgoing security rule for port 443 to the Internet. Associate the NSG to all the subnets.", "Create an outgoing security rule for port 443 to the Internet. Associate the NSG to the subnet that contains the web servers.", "Create an incoming security rule for port 443 from the Internet. Associate the NSG to all the subnets."], "correct": [0], "multi": false, "explanation": [{"p": "Create an incoming security rule for port 443 from the Internet. Associate the NSG to the subnet that contains the web servers is the correct answer here. According to the Ironclad Manufacturing case study, ProductionPortal is a public-facing application with a web front-end tier that users access exclusively by using HTTPS. HTTPS traffic uses port 443, so the web tier must accept incoming traffic on port 443 from the Internet."}, {"p": "By associating the NSG with the subnet that contains the web servers and creating an incoming rule that allows port 443 from the Internet, you allow users to access the web front end while minimizing unnecessary access to the other application tiers."}, {"p": "Create an outgoing security rule for port 443 to the Internet. Associate the NSG to all the subnets is incorrect because ProductionPortal must accept incoming HTTPS traffic from users. An outgoing rule controls traffic leaving the Azure resources and does not provide the required inbound access."}, {"p": "Create an outgoing security rule for port 443 to the Internet. Associate the NSG to the subnet that contains the web servers is incorrect for the same reason. The requirement is to allow incoming HTTPS traffic to the web front end, not outgoing traffic from the web servers."}, {"p": "Create an incoming security rule for port 443 from the Internet. Associate the NSG to all the subnets is incorrect because applying the NSG to all subnets is unnecessarily broad and violates the principle of least privilege. Only the subnet hosting the web servers needs to receive incoming traffic from the Internet."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/security-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/tutorial-restrict-network-access-to-resources"], "group": "G85"}, {"id": "T2-Q81", "test": 2, "num": 81, "domain": "identity", "stem": [{"p": "Refer to the Ironclad Manufacturing case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1KsF3wlRTNU8MfFDTFyswtTOs3axscynctGrm_mezY1A/edit?usp=sharing"}, {"p": "You need to modify the Microsoft Entra device settings to meet both the technical and user requirements."}, {"p": "The current device settings are as follows:"}, {"p": "Users may join devices to Microsoft Entra ID — All"}, {"p": "Additional local administrators on Microsoft Entra joined devices — None"}, {"p": "Users may register their devices with Microsoft Entra ID — All"}, {"p": "Require Multi-Factor Authentication (MFA) to join devices — No"}, {"p": "Maximum number of devices per user — 50"}, {"p": "Which two settings should you change?"}], "options": ["1", "2", "3", "4", "5"], "correct": [0, 3], "multi": true, "explanation": [{"p": "1 is correct because the user requirements in the Ironclad Manufacturing case study specify that only users who are members of a group named DevicePilot can join devices to Microsoft Entra. In the current configuration, the setting allows All users to join devices, which does not meet this requirement. To comply, the setting must be changed from All to Selected, and the DevicePilot group should be specified."}, {"p": "4 is correct because the technical requirements state that when users join devices to Microsoft Entra, they must verify their identity by using a mobile phone. This requires Multi-Factor Authentication (MFA) during the device join process. In the current configuration, this setting is set to No and must be changed to Yes to meet the requirement."}, {"p": "The remaining settings are not required to be changed based on the information provided in the case study."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/devices/concept-device-registration", "https://learn.microsoft.com/en-us/entra/identity/devices/concept-directory-join", "https://learn.microsoft.com/en-us/entra/identity/authentication/concept-mfa-howitworks"], "group": "G85"}, {"id": "T2-Q82", "test": 2, "num": 82, "domain": "network", "stem": [{"p": "Refer to the Ironclad Manufacturing case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1KsF3wlRTNU8MfFDTFyswtTOs3axscynctGrm_mezY1A/edit?usp=sharing"}, {"p": "You need to recommend a solution for ProductionPortal that satisfies the technical requirements."}, {"p": "For the following item, what should you include in the recommendation?"}, {"p": "\"Number of virtual networks\""}], "options": ["1", "2", "3"], "correct": [0], "multi": false, "explanation": [{"p": "1 is the correct answer here. Although the Ironclad Manufacturing case study mentions that ProductionPortal has a web tier, an application tier, and a data tier, and requires network segmentation, it does not explicitly require separate virtual networks for each tier. The technical requirements can be satisfied by placing the different tiers in separate subnets within a single virtual network, and using Network Security Groups (NSGs) to control traffic flow and limit open ports between subnets."}, {"p": "This approach follows best practices in Azure for deploying multi-tier applications by:"}, {"p": "Maintaining simplified routing and management,"}, {"p": "Allowing inter-subnet communication with controlled access,"}, {"p": "Avoiding the complexity and overhead of managing multiple VNets and VNet peering."}, {"p": "Therefore, a single virtual network with dedicated subnets and NSGs per tier meets the security and isolation requirements for ProductionPortal."}], "refs": ["https://learn.microsoft.com/en-us/azure/architecture/guide/architecture-styles/n-tier", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-vnet-plan-design-arm", "https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"], "group": "G85"}, {"id": "T2-Q83", "test": 2, "num": 83, "domain": "network", "stem": [{"p": "Refer to the Ironclad Manufacturing case study by opening the below link into a new tab. Answer the question based on this case study."}, {"p": "https://docs.google.com/document/d/1KsF3wlRTNU8MfFDTFyswtTOs3axscynctGrm_mezY1A/edit?usp=sharing"}, {"p": "You need to recommend a solution for ProductionPortal that satisfies the technical requirements."}, {"p": "For the following item, what should you include in the recommendation?"}, {"p": "“Number of subnets per virtual network”"}], "options": ["1", "2", "3"], "correct": [2], "multi": false, "explanation": [{"p": "3 is the correct answer here. The case study describes ProductionPortal as a three-tier application consisting of:"}, {"p": "A SQL database tier"}, {"p": "A web front-end tier"}, {"p": "A processing tier"}, {"p": "The technical requirements also state the need to minimize the number of open ports between the tiers. This kind of traffic segmentation and control is best achieved by placing each tier in its own subnet and using Network Security Groups (NSGs) to define strict access controls between them."}, {"p": "Using three subnets within a single virtual network, one per tier, allows you to:"}, {"p": "Segment traffic between the web, application, and data layers"}, {"p": "Apply tier-specific NSGs"}, {"p": "Keep the design scalable and secure"}, {"p": "Therefore, to meet both architectural and security requirements, the recommendation should include three subnets per virtual network."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-vnet-plan-design-arm", "https://learn.microsoft.com/en-us/azure/virtual-network/tutorial-restrict-network-access-to-resources"], "group": "G85"}, {"id": "T2-Q84", "test": 2, "num": 84, "domain": "network", "stem": [{"p": "You have a Microsoft Entra tenant that has the ironclad.onmicrosoft.com domain name."}, {"p": "You have a domain name of ironclad.com registered at a third-party registrar."}, {"p": "You need to ensure that you can create Microsoft Entra users that have names containing a suffix of @ironclad.com."}, {"p": "Which three actions should you perform in sequence?"}, {"p": "ACTIONS"}, {"p": "Verify the domain."}, {"p": "Add a record to the public ironclad.com DNS zone."}, {"p": "Create an Azure DNS zone."}, {"p": "Configure company branding."}, {"p": "Add a Microsoft Entra tenant."}, {"p": "Add a custom domain name."}], "options": ["2-3-6", "6-2-1", "3-2-6", "6-1-2"], "correct": [1], "multi": false, "explanation": [{"p": "6-2-1  is the CORRECT sequence of actions."}, {"p": "(Action 6) Add a custom domain name is correct. You begin by adding ironclad.com as a custom domain in your Microsoft Entra tenant. This tells Entra ID that you want to use this domain for user principal names (UPNs) and email addresses."}, {"p": "(Action 2) Add a record to the public ironclad.com DNS zone is correct. To prove ownership of the domain, Microsoft Entra ID provides a TXT or MX record that must be added to the public DNS zone where the domain (ironclad.com) is hosted. This is required for verification."}, {"p": "(Action 1) Verify the domain is correct. After adding the DNS record, you return to Microsoft Entra ID and complete the verification process. Once verified, the domain can be used to create users with UPNs like user@ironclad.com."}, {"p": "(Action 3) Create an Azure DNS zone is incorrect. Not required unless you're hosting DNS within Azure, which is not needed for verifying a third-party registered domain."}, {"p": "(Action 4) Configure company branding is incorrect. Not required to use a custom domain for user accounts."}, {"p": "(Action 5) Add a Microsoft Entra tenant is incorrect. Already provided in the question, so not needed."}], "refs": ["https://learn.microsoft.com/en-us/azure/dns/dns-web-sites-custom-domain", "https://learn.microsoft.com/en-us/entra/fundamentals/add-custom-domain"], "group": "G86"}, {"id": "T2-Q85", "test": 2, "num": 85, "domain": "identity", "stem": [{"p": "A Microsoft Entra hybrid environment contains the following user accounts:"}, {"p": "User1"}, {"p": "User type: Member"}, {"p": "On-premises synchronization enabled: No"}, {"p": "User2"}, {"p": "User type: Member"}, {"p": "On-premises synchronization enabled: Yes"}, {"p": "User3"}, {"p": "User type: Guest"}, {"p": "On-premises synchronization enabled: No"}, {"p": "You need to modify the JobTitle attribute for these users."}, {"p": "For which users can the attribute be updated directly within Microsoft Entra ID?"}], "options": ["User1 only", "User1 and User2 only", "User1 and User3 only", "User1, User2, and User3"], "correct": [2], "multi": false, "explanation": [{"p": "User1 and User3 only is the correct answer because their accounts are cloud-only (User1 is a member with no on-premises sync, and User3 is a guest user). This means their attributes—including JobTitle—can be modified directly in Microsoft Entra ID."}, {"p": "User2 is synchronized from on-premises Active Directory, so their attributes must be modified in the on-premises directory. Microsoft Entra ID does not allow attribute modification for synced users from the cloud interface."}], "refs": ["https://learn.microsoft.com/en-us/entra/fundamentals/how-to-manage-user-profile-info"], "group": "G87"}, {"id": "T2-Q86", "test": 2, "num": 86, "domain": "identity", "stem": [{"p": "A Microsoft Entra hybrid environment contains the following user accounts:"}, {"p": "User1"}, {"p": "User type: Member"}, {"p": "On-premises synchronization enabled: No"}, {"p": "User2"}, {"p": "User type: Member"}, {"p": "On-premises synchronization enabled: Yes"}, {"p": "User3"}, {"p": "User type: Guest"}, {"p": "On-premises synchronization enabled: No"}, {"p": "You need to modify the UsageLocation attribute for these users."}, {"p": "For which users can the attribute be updated directly within Microsoft Entra ID?"}], "options": ["User1 only", "User1 and User2 only", "User1 and User3 only", "User1, User2, and User3"], "correct": [3], "multi": false, "explanation": [{"p": "User1, User2, and User3 is the correct answer because the UsageLocation attribute is always stored and managed in Microsoft Entra ID, regardless of whether the user is cloud-only (User1 and User3) or synced from on-premises Active Directory (User2). This attribute is required for assigning Microsoft 365 licenses and can be directly edited from the Microsoft Entra portal or using PowerShell for all types of users."}], "refs": ["https://learn.microsoft.com/en-us/entra/fundamentals/how-to-manage-user-profile-info"], "group": "G87"}, {"id": "T2-Q87", "test": 2, "num": 87, "domain": "identity", "stem": [{"p": "An Azure subscription contains the following users:"}, {"p": "User1 – Member of Group1"}, {"p": "User2 – Member of Group2"}, {"p": "User3 – Member of Group3"}, {"p": "The groups are configured as follows:"}, {"p": "Group1 – Type: Security"}, {"p": "Group2 – Type: Security"}, {"p": "Group3 – Type: Microsoft 365"}, {"p": "All three groups are enabled for Microsoft Entra role assignments."}, {"p": "You also have a resource group named RG1. The access control (IAM) configuration for RG1 is shown in the exhibit."}, {"img": "az104/img/t2_image43.webp"}, {"p": "True or False:"}, {"p": "\"You can assign User2 the Owner role for RG1 by adding Group2 as a member of Group1.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is CORRECT because nesting is supported for groups that can be assigned a role."}, {"p": "In the screenshots pasted below, TestGroup is the Owner of the RG. And TestGroup3 is another group with a user User1, we want to be added as Owner of RG. So, as you can see, I can add TestGroup3 as the member of TestGroup. And this gives User1 the owner access of the RG."}, {"img": "az104/img/t2_image44.webp"}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/role-based-access-control/groups-concept#how-are-role-assignable-groups-protected"], "group": "G88"}, {"id": "T2-Q88", "test": 2, "num": 88, "domain": "identity", "stem": [{"p": "An Azure subscription contains the following users:"}, {"p": "User1 – Member of Group1"}, {"p": "User2 – Member of Group2"}, {"p": "User3 – Member of Group3"}, {"p": "The groups are configured as follows:"}, {"p": "Group1 – Type: Security"}, {"p": "Group2 – Type: Security"}, {"p": "Group3 – Type: Microsoft 365"}, {"p": "All three groups are enabled for Microsoft Entra role assignments."}, {"p": "You also have a resource group named RG1. The access control (IAM) configuration for RG1 is shown in the exhibit."}, {"img": "az104/img/t2_image43.webp"}, {"p": "True or False:"}, {"p": "\"You can assign User3 the Owner role for RG1 by adding Group3 as a member of Group1.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer because Azure role assignments do not support nested groups when the nested group is a Microsoft 365 group. In this scenario, Group3 is a Microsoft 365 group, and even though Group1 is assigned the Owner role for RG1, adding Group3 as a member of Group1 will not grant the Owner role to User3. This is because Microsoft Entra ID (Azure AD) does not support nested group evaluation for Microsoft 365 groups in role assignments."}, {"img": "az104/img/t2_image45.webp"}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/role-based-access-control/groups-concept#limitations-of-using-groups-in-azure-ad-roles", "https://learn.microsoft.com/en-us/entra/identity/users/directory-service-limits-restrictions"], "group": "G88"}, {"id": "T2-Q89", "test": 2, "num": 89, "domain": "identity", "stem": [{"p": "An Azure subscription contains the following users:"}, {"p": "User1 – Member of Group1"}, {"p": "User2 – Member of Group2"}, {"p": "User3 – Member of Group3"}, {"p": "The groups are configured as follows:"}, {"p": "Group1 – Type: Security"}, {"p": "Group2 – Type: Security"}, {"p": "Group3 – Type: Microsoft 365"}, {"p": "All three groups are enabled for Microsoft Entra role assignments."}, {"p": "You also have a resource group named RG1. The access control (IAM) configuration for RG1 is shown in the exhibit."}, {"img": "az104/img/t2_image43.webp"}, {"p": "True or False:"}, {"p": "\"You can assign User3 the Owner role for RG1 by assigning the Owner role to Group3 for RG1.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer because Group3 is configured to allow Microsoft Entra roles to be assigned to it (Microsoft Entra roles can be assigned to the group: Yes). This makes the group eligible for role-based access control (RBAC) assignments, such as assigning the Owner role for a specific resource group like RG1. Even though Group3 is a Microsoft 365 group, direct role assignments (not nested) are supported when the group is configured for role assignments. As a result, User3, a direct member of Group3, will inherit the Owner role for RG1."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/role-based-access-control/groups-concept#assign-azure-ad-roles-to-groups", "https://learn.microsoft.com/en-us/entra/identity/users/directory-service-limits-restrictions"], "group": "G88"}, {"id": "T2-Q90", "test": 2, "num": 90, "domain": "identity", "stem": [{"p": "You have an Azure subscription that contains 100 virtual machines."}, {"p": "You need to quickly identify virtual machines that are underutilized and could be moved to a lower-cost service tier."}, {"p": "Which Azure portal blade should you use?"}], "options": ["Monitor", "Advisor", "Metrics", "Customer insights"], "correct": [1], "multi": false, "explanation": [{"p": "Advisor is the correct answer because Azure Advisor provides personalized recommendations to optimize your Azure resources for cost, performance, security, and more. Specifically, it includes cost recommendations to help identify underutilized virtual machines that can be resized to a lower-cost SKU, thereby reducing unnecessary spend."}, {"p": "Monitor is incorrect because although it provides telemetry data and performance metrics, it doesn't offer built-in cost optimization recommendations."}, {"p": "Metrics is incorrect because it shows raw performance counters and charts but doesn't interpret or recommend changes based on utilization."}, {"p": "Customer insights is incorrect because it's related to customer data analytics (like Dynamics 365), and not relevant for Azure resource management or optimization."}], "refs": ["https://learn.microsoft.com/en-us/azure/advisor/advisor-cost-recommendations", "https://learn.microsoft.com/en-us/azure/advisor/advisor-overview"], "group": "G89"}, {"id": "T3-Q1", "test": 3, "num": 1, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes the virtual networks listed below:"}, {"p": "VNet1 in the West US region, peered with VNet2"}, {"p": "VNet2 in the West US region, peered with VNet1 and VNet3"}, {"p": "VNet3 in the East US region, peered with VNet2"}, {"p": "The subscription also contains the following virtual machines:"}, {"p": "VM1, connected to VNet1"}, {"p": "VM2, connected to VNet2"}, {"p": "VM3, connected to VNet3"}, {"p": "All virtual machines have private IP addresses only."}, {"p": "You deploy an Azure Bastion host named Bastion1 in VNet1."}, {"p": "Which virtual machines can you connect to by using Bastion1?"}], "options": ["VM1 only", "VM1 and VM2 only", "VM1 and VM3 only", "VM1, VM2, and VM3"], "correct": [1], "multi": false, "explanation": [{"p": "VM1 and VM2 only is the correct answer because Azure Bastion allows connections to virtual machines within the same virtual network or peered virtual networks. Since Bastion1 is deployed in VNet1, it can connect to VM1 (in VNet1) and VM2 (in VNet2), as VNet1 and VNet2 are peered. However, VM3 is in VNet3, which is peered only with VNet2 but not directly with VNet1, preventing Bastion1 from connecting to VM3."}, {"p": "VM1 only is incorrect because Bastion1 can also connect to VM2 in VNet2 through the peering with VNet1."}, {"p": "VM1 and VM3 only is incorrect because, while VM1 is accessible, VM3 is not reachable via Bastion1 due to the lack of direct peering between VNet1 and VNet3."}, {"p": "VM1, VM2, and VM3 is incorrect because Bastion1 cannot connect to VM3 since there is no direct peering between VNet1 and VNet3."}], "refs": ["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview", "https://learn.microsoft.com/en-us/azure/bastion/vnet-peering", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview"], "group": "G90"}, {"id": "T3-Q2", "test": 3, "num": 2, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes the following resources:"}, {"p": "A virtual network named VNET1 deployed in the East US region"}, {"p": "A public IP address named IP1 deployed in the West Europe region"}, {"p": "A route table named RT1 deployed in the North Europe region"}, {"p": "You are required to create a network interface named NIC1. The solution must use only existing resources, and no additional Azure resources can be created as part of the process."}, {"p": "In which Azure region can NIC1 be created?"}], "options": ["East US only", "East US and West Europe only", "East US and North Europe only", "East US, West Europe, and North Europe"], "correct": [0], "multi": false, "explanation": [{"p": "East US only is the correct answer because network interfaces (NICs) must be created in the same region as the virtual network (VNet) they are associated with. In this case, VNET1 is in the East US region, so NIC1 must also be created in East US to connect to VNET1 without requiring additional resources."}, {"p": "East US and West Europe only is incorrect because a NIC must be in the same region as its associated virtual network, and VNET1 is only in East US."}, {"p": "East US and North Europe only is incorrect for the same reason. NIC1 cannot be created in North Europe if it needs to connect to VNET1, which is located in East US."}, {"p": "East US, West Europe, and North Europe is incorrect because the NIC must be in the same region as the VNet, which is East US in this case."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-network-interface"], "group": "G91"}, {"id": "T3-Q3", "test": 3, "num": 3, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes three virtual networks: VNet-A, VNet-B, and VNet-C."}, {"p": "The current peering configuration is as follows:"}, {"p": "VNet-A"}, {"p": "Peered with VNet-B -> Status: Connected -> Gateway transit: Disabled"}, {"p": "Peered with VNet-C -> Status: Connected -> Gateway transit: Disabled"}, {"p": "VNet-B"}, {"p": "Peered with VNet-A -> Status: Connected -> Gateway transit: Disabled"}, {"p": "VNet-C"}, {"p": "Peered with VNet-A -> Status: Connected -> Gateway transit: Disabled"}, {"p": "Each peering shows a connected status."}, {"p": "Based on the information shown in the exhibits, complete the following statement by selecting the correct option:"}, {"p": "“Traffic originating from VNET-A can be routed to __________.”"}], "options": ["VNet-B only", "VNet-C only", "VNet-B and VNet-C"], "correct": [2], "multi": false, "explanation": [{"p": "VNet-B and VNet-C is the correct answer because VNet-A has peering connections established with both VNet-B and VNet-C. This setup allows packets from VNet-A to be routed directly to both VNet-B and VNet-C through the peering connections. The peering status is connected, and no additional configurations are needed since the gateway transit is disabled for all peering links, which does not impact routing between the peered networks."}, {"p": "VNET-B only is incorrect because packets can also be routed to VNet-C due to the established peering connection between VNet-A and VNet-C."}, {"p": "VNET-C only is incorrect because packets can also be routed to VNet-B due to the established peering connection between VNet-A and VNet-B."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview", "https://docs.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-peering-gateway-transit"], "group": "G92"}, {"id": "T3-Q4", "test": 3, "num": 4, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes three virtual networks: VNet-A, VNet-B, and VNet-C."}, {"p": "The current peering configuration is as follows:"}, {"p": "VNet-A"}, {"p": "Peered with VNet-B -> Status: Connected -> Gateway transit: Disabled"}, {"p": "Peered with VNet-C -> Status: Connected -> Gateway transit: Disabled"}, {"p": "VNet-B"}, {"p": "Peered with VNet-A -> Status: Connected -> Gateway transit: Disabled"}, {"p": "VNet-C"}, {"p": "Peered with VNet-A -> Status: Connected -> Gateway transit: Disabled"}, {"p": "Each peering shows a connected status."}, {"p": "Based on the information shown in the exhibits, complete the following statement by selecting the correct option:"}, {"p": "“Traffic originating from VNet-B can be routed to __________.”"}], "options": ["VNet-A only", "VNet-C only", "VNet-A and VNet-C"], "correct": [0], "multi": false, "explanation": [{"p": "VNet-A only is the correct answer because VNet-B has a direct peering connection with VNet-A, which allows routing of packets between these two virtual networks. Since gateway transit is disabled, VNet-B cannot leverage VNet-A as a transit network to reach other networks, such as VNet-C. This configuration restricts communication to only those virtual networks with direct peering links."}, {"p": "VNet-C only is incorrect because there is no direct peering connection between VNet-B and VNet-C, and VNet-B cannot route through VNet-A due to the disabled gateway transit."}, {"p": "VNet-A and VNet-C is incorrect because, without gateway transit enabled, VNet-B is restricted to direct communication only with VNet-A."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview", "https://docs.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-peering-gateway-transit"], "group": "G92"}, {"id": "T3-Q5", "test": 3, "num": 5, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes the following public IP address resources:"}, {"p": "IP1: IPv4, Standard SKU, Regional tier, Static assignment"}, {"p": "IP2: IPv4, Standard SKU, Global tier, Static assignment"}, {"p": "IP3: IPv4, Basic SKU, Regional tier, Dynamic assignment"}, {"p": "IP4: IPv4, Basic SKU, Regional tier, Static assignment"}, {"p": "IP5: IPv6, Basic SKU, Regional tier, Dynamic assignment"}, {"p": "You plan to deploy an Azure Bastion host named Bastion1 using the Basic SKU."}, {"p": "Which of the listed public IP addresses can be used for Bastion1?"}], "options": ["IP1 only", "IP1 and IP2 only", "IP3, IP4, and IP5 only", "IP1, IP2, IP4, and IP5 only", "IP1, IP2, IP3, IP4, and IP5"], "correct": [0], "multi": false, "explanation": [{"p": "IP1 only is the correct answer because Azure Bastion requires a Standard Public IP address for both the Basic and Standard SKUs. Additionally, the IP address must be IPv4, have a Regional tier, and use a Static assignment. Among the provided options, IP1 is the only address that satisfies all these conditions, making it suitable for Azure Bastion."}, {"img": "az104/img/t3_image1.webp"}, {"p": "Note: The Microsoft documentation does not explicitly list “Regional tier” as a Bastion requirement. However, in practice, Azure Bastion supports only Regional tier public IPs. Global tier public IPs are intended for cross-region load balancers and cannot be attached to Azure Bastion. This behavior is also confirmed when attempting deployment in the Azure portal, where attaching a Global tier public IP to Bastion results in an error."}, {"p": "IP2 is incorrect because it has a Global tier, while the requirement is for a Regional tier."}, {"p": "IP3 is incorrect due to its Basic SKU and Dynamic assignment, both of which are incompatible with Azure Bastion."}, {"p": "IP4 is incorrect because it also uses the Basic SKU, which does not meet the Standard SKU requirement."}, {"p": "IP5 is incorrect as it is an IPv6 address, and Azure Bastion supports only IPv4."}], "refs": ["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/configure-public-ip-bastion", "https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/public-ip-addresses"], "group": "G93"}, {"id": "T3-Q6", "test": 3, "num": 6, "domain": "network", "stem": [{"p": "You have an Azure subscription."}, {"p": "You plan to deploy a virtual network named VNET1 by using an Azure Resource Manager (ARM) template. The virtual network will be configured to support Azure Bastion."}, {"p": "You are provided with a partially completed ARM template that defines the virtual network, its address space, and two subnets. One subnet definition contains two placeholders that must be completed."}, {"img": "az104/img/t3_image2.webp"}, {"p": "What should you choose for Code Segment A?"}], "options": ["AzureBastionSubnet", "AzureFirewallSubnet", "LAN01", "RemoteAccessSubnet"], "correct": [0], "multi": false, "explanation": [{"p": "AzureBastionSubnet is the correct answer because, to use Azure Bastion, a subnet specifically named AzureBastionSubnet is required. This subnet name is reserved for Azure Bastion deployments and must be configured in the virtual network where Bastion is being deployed."}, {"img": "az104/img/t3_image3.webp"}, {"p": "AzureFirewallSubnet is incorrect because this is the reserved subnet name required for Azure Firewall, not Azure Bastion."}, {"p": "LAN01 is incorrect because it is a generic subnet name and does not meet the specific naming requirement for Azure Bastion."}, {"p": "RemoteAccessSubnet is incorrect because it does not align with the required naming convention for Azure Bastion."}], "refs": ["https://learn.microsoft.com/en-us/azure/bastion/configuration-settings", "https://learn.microsoft.com/en-us/azure/bastion/tutorial-create-host-portal#createhost"], "group": "G94"}, {"id": "T3-Q7", "test": 3, "num": 7, "domain": "network", "stem": [{"p": "You have an Azure subscription."}, {"p": "You plan to deploy a virtual network named VNET1 by using an Azure Resource Manager (ARM) template. The virtual network will be configured to support Azure Bastion."}, {"p": "You are provided with a partially completed ARM template that defines the virtual network, its address space, and two subnets. One subnet definition contains two placeholders that must be completed."}, {"img": "az104/img/t3_image2.webp"}, {"p": "What should you choose for Code Segment B?"}], "options": ["10.10.10.0/26", "10.10.10.0/28", "10.10.10.0/30"], "correct": [0], "multi": false, "explanation": [{"p": "10.10.10.0/26 is the correct answer because the AzureBastionSubnet for Azure Bastion requires a subnet prefix of at least /26 to function properly. This prefix size provides a sufficient number of IP addresses for Azure Bastion to manage connections and maintain operational capacity."}, {"img": "az104/img/t3_image4.webp"}, {"p": "10.10.10.0/28 is incorrect because a /28 subnet does not provide enough IP addresses for Azure Bastion, which requires a minimum of /26."}, {"p": "10.10.10.0/30 is incorrect because a /30 subnet provides only a very limited number of IP addresses, far below the requirements for Azure Bastion."}], "refs": ["https://learn.microsoft.com/en-us/azure/bastion/configuration-settings", "https://learn.microsoft.com/en-us/azure/bastion/tutorial-create-host-portal#createhost"], "group": "G94"}, {"id": "T3-Q8", "test": 3, "num": 8, "domain": "network", "stem": [{"p": "You have a Windows 11 computer named Device1 and an Azure subscription that includes the following resources:"}, {"p": "A virtual network named VNET1"}, {"p": "A virtual machine named VM1 that runs Windows Server 2022, has no public IP address, and is connected to VNET1"}, {"p": "An Azure Bastion Basic SKU host named Bastion1 that is connected to VNET1"}, {"p": "Device1 has both Azure PowerShell and the Azure CLI installed."}, {"p": "You need to establish a Remote Desktop (RDP) connection from Device1 to VM1."}, {"p": "Which three actions should you perform in sequence?"}, {"p": "ACTIONS"}, {"p": "From Bastion1, select Native Client Support."}, {"p": "On Device1, run mstsc.exe."}, {"p": "Upgrade Bastion1 to the Standard SKU."}, {"p": "From Bastion1, enable Kerberos authentication."}, {"p": "From VM1, enable just-in-time (JIT) VM access."}, {"p": "From Azure CLI on Device1, run az network bastion rdp."}], "options": ["3-6-1", "3-4-1", "3-2-6", "3-1-6"], "correct": [3], "multi": false, "explanation": [{"p": "(Action 3) Upgrade Bastion1 to the Standard SKU – To use the native client feature for Azure Bastion, which allows connecting via a local RDP client (such as mstsc.exe), Bastion1 must be upgraded to the Standard SKU, as this feature is not available with the Basic SKU."}, {"p": "(Action 1) From Bastion1, select Native Client Support – After upgrading, enable the native client support option within the Azure Bastion configuration. This feature allows Device1 to connect to VM1 through Bastion using an RDP client."}, {"p": "(Action 6) From Azure CLI on Device1, run az network bastion rdp – Use the az network bastion rdp command on Device1’s Azure CLI to initiate the RDP connection to VM1 through Bastion1. This command establishes the RDP session without requiring the direct use of mstsc.exe."}, {"p": "To connect via RDP, use the following command:"}, {"p": "az network bastion rdp --name \"<BastionName>\" --resource-group \"<ResourceGroupName>\" --target-resource-id \"<VMResourceId>\""}, {"p": "(Action 2) On Device1, run mstsc.exe is not necessary when using the Azure CLI command, as az network bastion rdp initiates the connection directly."}, {"p": "(Action 4) Enable Kerberos authentication and (Action 5) Enable just-in-time (JIT) VM access are not required for this setup."}], "refs": ["https://learn.microsoft.com/en-us/azure/bastion/bastion-connect-cli", "https://learn.microsoft.com/en-us/azure/bastion/native-client"], "group": "G95"}, {"id": "T3-Q9", "test": 3, "num": 9, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes the following resources:"}, {"p": "VMRG – Resource group"}, {"p": "VNet1 – Virtual network"}, {"p": "VNet2 – Virtual network"}, {"p": "VM5 – Virtual machine connected to VNet1"}, {"p": "VM6 – Virtual machine connected to VNet2"}, {"p": "You create an Azure private DNS zone named apexcore.com."}, {"p": "You then link the private DNS zone to VNet2 and enable auto-registration for the virtual network link."}, {"p": "The apexcore.com private DNS zone is configured with existing DNS records, as shown in the below exhibit."}, {"img": "az104/img/t3_image5.webp"}, {"p": "True or False:"}, {"p": "“The A record for VM5 will be registered automatically in the apexcore.com zone.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer. Azure DNS allows for the automatic registration of virtual machines from one designated virtual network linked to a private DNS zone as the registration network. In this case, VNet2 is set as the registration virtual network for the apexcore.com zone. However, VM5 is part of VNet1, not VNet2. Since VM5 does not belong to the registration virtual network, its DNS record will not be automatically registered in the apexcore.com zone."}, {"img": "az104/img/t3_image6.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/dns/private-dns-autoregistration", "https://learn.microsoft.com/en-us/azure/dns/private-dns-overview"], "group": "G96"}, {"id": "T3-Q10", "test": 3, "num": 10, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes the following resources:"}, {"p": "VMRG – Resource group"}, {"p": "VNet1 – Virtual network"}, {"p": "VNet2 – Virtual network"}, {"p": "VM5 – Virtual machine connected to VNet1"}, {"p": "VM6 – Virtual machine connected to VNet2"}, {"p": "You create an Azure private DNS zone named apexcore.com."}, {"p": "You then link the private DNS zone to VNet2 and enable auto-registration for the virtual network link."}, {"p": "The apexcore.com private DNS zone is configured with existing DNS records, as shown in the below exhibit."}, {"img": "az104/img/t3_image5.webp"}, {"p": "True or False:"}, {"p": "“VM5 can resolve VM9.apexcore.com.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct. VM5 cannot resolve VM9.apexcore.com because VM5 is connected to VNet1, while VM9 is connected to VNet2. Forward DNS resolution is only supported across virtual networks that are linked to the private DNS zone as resolution virtual networks. In this setup, VNet2 is linked to the apexcore.com private DNS zone, but VNet1 is not linked to this zone nor is it peered with VNet2. Since VNet1 is not configured as a resolution virtual network, VM5 cannot resolve the domain name VM9.apexcore.com."}, {"img": "az104/img/t3_image7.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/private-link/private-endpoint-dns", "https://learn.microsoft.com/en-us/azure/dns/private-dns-overview"], "group": "G96"}, {"id": "T3-Q11", "test": 3, "num": 11, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes the following resources:"}, {"p": "VMRG – Resource group"}, {"p": "VNet1 – Virtual network"}, {"p": "VNet2 – Virtual network"}, {"p": "VM5 – Virtual machine connected to VNet1"}, {"p": "VM6 – Virtual machine connected to VNet2"}, {"p": "You create an Azure private DNS zone named apexcore.com."}, {"p": "You then link the private DNS zone to VNet2 and enable auto-registration for the virtual network link."}, {"p": "The apexcore.com private DNS zone is configured with existing DNS records, as shown in the below exhibit."}, {"img": "az104/img/t3_image5.webp"}, {"p": "True or False:"}, {"p": "“VM6 can resolve VM9.apexcore.com.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct. VM6 can resolve VM9.apexcore.com because it belongs to VNet2, which is configured as the registration virtual network for the apexcore.com private DNS zone. Since VNet2 is the registration virtual network, it also serves as the resolution virtual network by default, allowing DNS resolution within this virtual network. An A (Host) record for VM9 exists in the DNS zone, enabling VM6 to successfully resolve the domain name VM9.apexcore.com from within VNet2."}], "refs": ["https://learn.microsoft.com/en-us/azure/private-link/private-endpoint-dns", "https://learn.microsoft.com/en-us/azure/dns/private-dns-overview"], "group": "G96"}, {"id": "T3-Q12", "test": 3, "num": 12, "domain": "network", "stem": [{"p": "You have two Azure virtual machines running Windows Server, configured as shown below:"}, {"img": "az104/img/t3_image8.webp"}, {"p": "You then create a private Azure DNS zone named apexcore.com and configure the zone to allow automatic DNS registration from VNet-A."}, {"p": "Which A record will be automatically created in the apexcore.com private DNS zone for VM-A?"}], "options": ["None", "Private IP address only", "Public IP address only", "Private IP address and public IP address"], "correct": [1], "multi": false, "explanation": [{"p": "Private IP address only is the correct answer because when a private Azure DNS zone (such as apexcore.com) is configured for auto-registration in a virtual network (VNet-A), only the private IP addresses of virtual machines in that network are automatically registered in the DNS zone. Public IP addresses are not registered in private DNS zones. Therefore, for VM-A, only the private IP address 10.1.0.4 will be added as an A record in the apexcore.com zone, while the public IP address 52.186.85.63 will not be included."}, {"p": "None is incorrect because VM-A is part of VNet-A, and VNet-A is configured for auto-registration in the apexcore.com DNS zone. Therefore, VM1’s private IP address will be registered in the zone."}, {"p": "Public IP address only is incorrect because public IP addresses are not registered in private DNS zones. Auto-registration only includes the private IP address."}, {"p": "Private IP address and public IP address is incorrect because only the private IP address will be registered in the apexcore.com zone. Public IP addresses are excluded from auto-registration."}], "refs": ["https://docs.microsoft.com/en-us/azure/dns/private-dns-overview", "https://docs.microsoft.com/en-us/azure/dns/private-dns-scenarios", "https://docs.microsoft.com/en-us/azure/dns/private-dns-scenarios#scenario-split-horizon-functionality"], "group": "G97"}, {"id": "T3-Q13", "test": 3, "num": 13, "domain": "network", "stem": [{"p": "You have two Azure virtual machines running Windows Server, configured as shown below:"}, {"img": "az104/img/t3_image8.webp"}, {"p": "You then create a private Azure DNS zone named apexcore.com and configure the zone to allow automatic DNS registration from VNet-A."}, {"p": "Which A record will be automatically created in the apexcore.com private DNS zone for VM-B?"}], "options": ["None", "Private IP address only", "Public IP address only", "Private IP address and public IP address"], "correct": [1], "multi": false, "explanation": [{"p": "Private IP address only is the correct answer because in Azure private DNS zones, DNS records are created based on the Virtual network links to the VNet rather than the DNS suffix configured on the VM itself. Since VNet-A is linked to the adatum.com private DNS zone and auto-registration is enabled, VM-B’s private IP address (10.1.0.5) will be automatically registered in the apexcore.com zone despite its DNS suffix being set to ironclad.com."}, {"p": "None is incorrect because the DNS name configured on the VM does not impact auto-registration; as long as the VNet is linked, VM-B’s private IP will be registered."}, {"p": "Public IP address only is incorrect because Azure private DNS zones do not register public IP addresses; they register only private IP addresses."}, {"p": "Private IP address and public IP address is incorrect because Azure private DNS zones only register private IP addresses, not public ones."}], "refs": ["https://learn.microsoft.com/en-us/azure/dns/private-dns-autoregistration", "https://docs.microsoft.com/en-us/azure/dns/private-dns-overview", "https://docs.microsoft.com/en-us/azure/dns/private-dns-scenarios", "https://docs.microsoft.com/en-us/azure/dns/private-dns-scenarios#scenario-split-horizon-functionality"], "group": "G97"}, {"id": "T3-Q14", "test": 3, "num": 14, "domain": "compute", "stem": [{"p": "You have an Azure subscription that includes the container images listed below:"}, {"p": "Image1: Built on Windows Server"}, {"p": "Image2: Built on Linux"}, {"p": "You plan to deploy containers by using the following Azure services:"}, {"p": "Azure Container Instances"}, {"p": "Azure Container Apps"}, {"p": "Azure App Service"}, {"p": "Based on the supported operating systems for each service,  which of the listed Azure services can be used to run Image1?"}], "options": ["Azure Container Instances only", "Azure Container Apps only", "Azure Container Instances and App Services only", "Azure Container Apps and App Services only", "Azure Container Instances, Azure Container Apps, and App Services"], "correct": [2], "multi": false, "explanation": [{"p": "Azure Container Instances and App Services only is the correct answer because Image1 is based on Windows Server, and Azure Container Instances (ACI) and Azure App Service support Windows-based containers. Azure Container Apps, however, only supports Linux-based containers, so it cannot be used to run Image1."}, {"img": "az104/img/t3_image9.webp"}, {"img": "az104/img/t3_image10.webp"}, {"img": "az104/img/t3_image11.webp"}, {"p": "Azure Container Instances only is incorrect because Azure App Service also supports Windows-based containers, making it a valid option for running Image1."}, {"p": "Azure Container Apps only is incorrect because Azure Container Apps does not support Windows-based containers; it only supports Linux-based containers."}, {"p": "Azure Container Apps and App Services only is incorrect because Azure Container Apps does not support Windows-based containers."}, {"p": "Azure Container Instances, Azure Container Apps, and App Services is incorrect because Azure Container Apps does not support Windows-based containers, so it cannot be used to run Image1."}], "refs": ["https://learn.microsoft.com/en-us/azure/container-instances/container-instances-overview", "https://learn.microsoft.com/en-us/azure/container-apps/containers", "https://learn.microsoft.com/en-us/azure/app-service/overview"], "group": "G98"}, {"id": "T3-Q15", "test": 3, "num": 15, "domain": "compute", "stem": [{"p": "You have an Azure subscription that includes the container images listed below:"}, {"p": "Image1: Built on Windows Server"}, {"p": "Image2: Built on Linux"}, {"p": "You plan to deploy containers by using the following Azure services:"}, {"p": "Azure Container Instances"}, {"p": "Azure Container Apps"}, {"p": "Azure App Service"}, {"p": "Based on the supported operating systems for each service,  which of the listed Azure services can be used to run Image2?"}], "options": ["Azure Container Instances only", "Azure Container Apps only", "Azure Container Instances and App Services only", "Azure Container Apps and App Services only", "Azure Container Instances, Azure Container Apps, and App Services"], "correct": [4], "multi": false, "explanation": [{"p": "Azure Container Instances, Azure Container Apps, and App Services is the correct answer because Image2 is based on Linux, and all three services — Azure Container Instances (ACI), Azure Container Apps, and Azure App Service — support Linux-based containers. Therefore, Image2 can run on any of these services."}, {"p": "Azure Container Instances only is incorrect because both Azure Container Apps and Azure App Service also support Linux-based containers, making them valid options for running Image2."}, {"p": "Azure Container Apps only is incorrect because Azure Container Instances and Azure App Service can also run Linux-based containers, so this option is too restrictive."}, {"p": "Azure Container Instances and App Services only is incorrect because Azure Container Apps also supports Linux-based containers, making it another valid option for Image2."}, {"p": "Azure Container Apps and App Services only is incorrect because Azure Container Instances is also capable of running Linux-based containers."}], "refs": ["https://learn.microsoft.com/en-us/azure/container-instances/container-instances-overview", "https://learn.microsoft.com/en-us/azure/container-apps/containers", "https://learn.microsoft.com/en-us/azure/app-service/overview"], "group": "G98"}, {"id": "T3-Q16", "test": 3, "num": 16, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant that contains the users listed in the following table, each assigned specific administrative roles."}, {"img": "az104/img/t3_image12.webp"}, {"p": "The tenant also contains the groups as shown in the below table, with different group types and membership configurations."}, {"img": "az104/img/t3_image13.webp"}, {"p": "Self-service password reset (SSPR) must be configured for the tenant."}, {"p": "Which of the listed users are permitted to configure SSPR?"}], "options": ["AdminA only", "AdminB only", "AdminC only", "AdminA and AdminB only", "AdminB and AdminC only", "AdminA, AdminB, and AdminC"], "correct": [3], "multi": false, "explanation": [{"p": "AdminA and AdminB only is correct because in order to configure Self-Service Password Reset (SSPR) in Microsoft Entra, a user must have at least the Authentication Policy Administrator role. In this case, AdminA is the user with the Global Administrator role and AdminA has Authentication Policy Admin role which grant them the necessary permissions to configure SSPR."}, {"p": "AdminA only is the incorrect answer because AdminB (Authentication Policy Administrator) also has the required permissions to configure SSPR."}, {"p": "AdminB only is incorrect  because AdminA (Global Administrator) also has permissions to configure SSPR, and AdminB cannot be the only one who can configure it."}, {"p": "AdminC only is incorrect because neither Authentication Administrator nor Security Administrator roles provide permissions to configure SSPR."}, {"p": "AdminB and AdminC only is incorrect because AdminC does not have the required role to configure SSPR. Only AdminA and AdminB have the necessary roles."}, {"p": "AdminA, AdminB, and AdminC is incorrect because AdminC does not hold a role that permits configuring SSPR. Only AdminA and AdminB meet the role requirements."}], "refs": ["https://learn.microsoft.com/en-us/azure/active-directory/authentication/tutorial-enable-sspr", "https://learn.microsoft.com/en-us/entra/identity/role-based-access-control/permissions-reference#authentication-policy-administrator"], "group": "G99"}, {"id": "T3-Q17", "test": 3, "num": 17, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant that contains the users listed in the following table, each assigned specific administrative roles."}, {"img": "az104/img/t3_image12.webp"}, {"p": "The tenant also contains the groups as shown in the below table, with different group types and membership configurations."}, {"img": "az104/img/t3_image13.webp"}, {"p": "Self-service password reset (SSPR) must be configured for the tenant."}, {"p": "For which group can SSPR be enabled?"}], "options": ["SecGroup only", "M365Group only", "SecGroup or M365Group only", "SecGroup or MailSecGroup only", "SecGroup, M365Group, or MailSecGroup"], "correct": [2], "multi": false, "explanation": [{"p": "SecGroup or M365Group only is the correct answer because Self-Service Password Reset (SSPR) can be enabled for security groups and Microsoft 365 groups. SecGroup is a Security group, and M365Group is a Microsoft 365 group, both of which are supported for SSPR."}, {"p": "MailSecGrou is a Mail-enabled security group, which does not support SSPR."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/authentication/concept-sspr-howitworks", "https://learn.microsoft.com/en-us/entra/identity/authentication/tutorial-enable-sspr#enable-self-service-password-reset"], "group": "G99"}, {"id": "T3-Q18", "test": 3, "num": 18, "domain": "compute", "stem": [{"p": "You have an Azure subscription and plan to create an Azure Container Registry named ContReg1."}, {"p": "You must ensure that container images pushed to and pulled from ContReg1 are cryptographically signed and that only trusted images are allowed."}, {"p": "What configuration should you apply to ContReg1 to meet this requirement?"}], "options": ["Enable encryption by using a customer-managed key.", "Create a connected registry.", "Add a token.", "Enable content trust."], "correct": [3], "multi": false, "explanation": [{"p": "Enable content trust is the correct answer here. To ensure that you can push and pull signed container images in ContReg1, you need to enable content trust. Content trust ensures that the integrity of the images is maintained by verifying that the images are signed and have not been tampered with. This allows only trusted and signed images to be pushed and pulled from the registry."}, {"p": "Enable encryption by using a customer-managed key is incorrect because encryption protects data at rest but does not address image signing."}, {"p": "Create a connected registry is incorrect because connected registries are used for geo-replication and scaling deployments but do not address signed images."}, {"p": "Add a token is incorrect because tokens are used to manage authentication for accessing the registry, not for image signing."}], "refs": ["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-content-trust", "https://learn.microsoft.com/en-us/azure/container-registry/container-registry-tasks-overview"], "group": "G100"}, {"id": "T3-Q19", "test": 3, "num": 19, "domain": "storage", "stem": [{"p": "You provision an Azure Storage account and plan to create 10 blob containers within the account. One of these containers must use a separate encryption key for data that is encrypted at rest."}, {"p": "What action should you take before creating that container?"}], "options": ["Rotate the access keys.", "Create an encryption scope.", "Change the minimum supported TLS version.", "Generate a shared access signature (SAS)."], "correct": [1], "multi": false, "explanation": [{"p": "Create an encryption scope is the correct answer because to use a different key for encrypting data at rest for a specific blob container, you need to create an encryption scope in Azure Storage. Once created, the encryption scope can be assigned to individual containers, allowing them to use a distinct encryption key."}, {"img": "az104/img/t3_image14.webp"}, {"p": "Rotate the access keys is incorrect because rotating access keys changes the authentication keys used to access the storage account but does not provide a way to use a different encryption key for a specific container."}, {"p": "Change the minimum supported TLS version is incorrect because modifying the TLS version affects the security protocol for data in transit, not the encryption of data at rest."}, {"p": "Generate a shared access signature (SAS) is incorrect because a SAS provides controlled access to the storage account resources but does not influence encryption settings for data at rest."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/encryption-scope-overview", "https://learn.microsoft.com/en-us/azure/storage/blobs/encryption-scope-manage?tabs=portal"], "group": "G101"}, {"id": "T3-Q20", "test": 3, "num": 20, "domain": "storage", "stem": [{"p": "You have an Azure subscription that contains the storage account shown in the following exhibit."}, {"img": "az104/img/t3_image15.webp"}, {"p": "Based on the information provided, select the answer choice that completes the following statement correctly."}, {"p": "“The maximum number of additional stored access policies that can be created for container1 is ________.”"}], "options": ["0", "1", "3", "5", "6"], "correct": [2], "multi": false, "explanation": [{"p": "3 is the correct answer because Azure Storage accounts support a maximum of 5 stored access policies per container. Since there are already 2 stored access policies (Policy1 and Policy2) defined for container1, you can add 3 more policies to reach the limit of 5."}, {"img": "az104/img/t3_image16.webp"}], "refs": ["https://learn.microsoft.com/en-us/rest/api/storageservices/define-stored-access-policy"], "group": "G102"}, {"id": "T3-Q21", "test": 3, "num": 21, "domain": "storage", "stem": [{"p": "You have an Azure subscription that contains the storage account shown in the following exhibit."}, {"img": "az104/img/t3_image15.webp"}, {"p": "Based on the information provided, select the answer choice that completes the following statement correctly."}, {"p": "“The maximum number of additional immutable blob storage policies that can be created for container1 is ________.”"}], "options": ["0", "1", "2", "4", "5"], "correct": [1], "multi": false, "explanation": [{"p": "1 is the correct answer because Azure Storage accounts support a maximum of 2 immutable blob storage policies per container. Since there is already 1 immutable blob storage policy configured for container1 (with a time-based retention of 14 days), you can add 1 more to reach the maximum limit of 2."}, {"img": "az104/img/t3_image17.webp"}, {"img": "az104/img/t3_image18.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/immutable-storage-overview"], "group": "G102"}, {"id": "T3-Q22", "test": 3, "num": 22, "domain": "storage", "stem": [{"p": "You have an on-premises server that contains a folder named at D:\\DataFolder."}, {"p": "You need to upload all the contents of D:\\DataFolder to the public blob container in an Azure Storage account named apexcoredata."}, {"p": "Which command should you run to complete this task?"}], "options": ["az storage blob copy start D:\\DataFolder https://apexcoredata.blob.core.windows.net/public", "azcopy copy D:\\DataFolder https://apexcoredata.blob.core.windows.net/public --recursive", "azcopy sync D:\\DataFolder https://apexcoredata.blob.core.windows.net/public --snapshot", "az storage blob copy start-batch D:\\DataFolder https://apexcoredata.blob.core.windows.net/public"], "correct": [1], "multi": false, "explanation": [{"p": "azcopy copy D:\\DataFolder https://apexcoredata.blob.core.windows.net/public --recursive is the correct answer because the azcopy copy command is used to upload files from an on-premises folder to an Azure Storage container. The --recursive option ensures that all files within D:\\Folder1 are copied to the destination container in Azure."}, {"p": "az storage blob copy start D:\\DataFolder https://apexcoredata.blob.core.windows.net/public is incorrect because az storage blob copy start is intended for copying blobs within Azure Storage, not for uploading files from an on-premises location."}, {"p": "azcopy sync D:\\DataFolder https://apexcoredata.blob.core.windows.net/public --snapshot is incorrect because azcopy sync is used to synchronize files between a local folder and a storage container, rather than a direct copy. The --snapshot parameter is not relevant for this task."}, {"p": "az storage blob copy start-batch D:\\DataFolder https://apexcoredata.blob.core.windows.net/public is incorrect because az storage blob copy start-batch is designed for batch copying blobs within Azure Storage, not from an on-premises location."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/storage-use-azcopy-blobs", "https://docs.microsoft.com/en-us/azure/storage/common/storage-ref-azcopy-copy"], "group": "G103"}, {"id": "T3-Q23", "test": 3, "num": 23, "domain": "storage", "stem": [{"p": "You have an Azure subscription named ProdSub01. In the subscription, you create an Azure file share named fileshare01. You then generate a shared access signature (SAS) named SASKey01 with the following configuration:"}, {"p": "Allowed services: File"}, {"p": "Allowed resource types: Service, Container, Object"}, {"p": "Allowed permissions: Read, Write, List"}, {"p": "Start date/time: September 1, 2018 at 2:00 PM"}, {"p": "End date/time: September 14, 2018 at 2:00 PM"}, {"p": "Allowed IP addresses: 193.77.134.10 – 193.77.134.50"}, {"p": "Allowed protocols: HTTPS only"}, {"p": "Signing key: key1"}, {"p": "Based on this configuration, complete the following statement:"}, {"p": "“If on September 2, 2018, you use Microsoft Azure Storage Explorer from a computer with the IP address 193.77.134.1, and connect to the storage account using SASKey01, you __________.”"}], "options": ["will be asked for credentials", "will have no access", "will have read, write, and list access", "will have read-only access"], "correct": [1], "multi": false, "explanation": [{"p": "will have no access is the correct answer because, as given, the SAS (Shared Access Signature) restricts access to IP addresses within the range 193.77.134.10 to 193.77.134.50. Although the date of September 2, 2018 is within the permitted time period (2018-09-01 2:00 PM to 2018-09-14 2:00 PM), the IP address 193.77.134.1 does not fall within the specified IP address range, resulting in no access to the storage account."}, {"p": "will be asked for credentials is incorrect because SAS tokens provide access based on the permissions and restrictions defined in the token itself, without requiring additional credentials."}, {"p": "will have read, write, and list access is incorrect because, while these permissions are specified in the SAS, the IP address restriction prevents any access."}, {"p": "will have read-only access is incorrect because the IP address falls outside the permitted range, so access will not be granted regardless of the permissions."}], "refs": ["https://docs.microsoft.com/en-us/azure/storage/common/storage-sas-overview", "https://docs.microsoft.com/en-us/azure/vs-azure-tools-storage-manage-with-storage-explorer?tabs=windows"], "group": "G104"}, {"id": "T3-Q24", "test": 3, "num": 24, "domain": "storage", "stem": [{"p": "You have an Azure subscription named ProdSub01. In the subscription, you create an Azure file share named fileshare01. You then generate a shared access signature (SAS) named SASKey01 with the following configuration:"}, {"p": "Allowed services: File"}, {"p": "Allowed resource types: Service, Container, Object"}, {"p": "Allowed permissions: Read, Write, List"}, {"p": "Start date/time: September 1, 2018 at 2:00 PM"}, {"p": "End date/time: September 14, 2018 at 2:00 PM"}, {"p": "Allowed IP addresses: 193.77.134.10 – 193.77.134.50"}, {"p": "Allowed protocols: HTTPS only"}, {"p": "Signing key: key1"}, {"p": "Based on this configuration, complete the following statement:"}, {"p": "If on September 10, 2018, you run the net use command on a computer that has an IP address of 193.77.134.50, and you use SASKey01 as the password to connect to fileshare01, you _________________________.”"}], "options": ["will be asked for credentials", "will have no access", "will have read, write, and list access", "will have read-only access"], "correct": [1], "multi": false, "explanation": [{"p": "will have no access is the correct answer here because the net use command relies on the SMB (Server Message Block) protocol, which only supports authentication using the Azure Storage account key for access to Azure File Shares. The SAS token cannot be used for authentication in this context, and attempting to use it will result in an error indicating invalid credentials. Therefore, the user will not gain any access to the file share with the net use command when using the SAS token."}, {"p": "will be asked for credentials is incorrect because the SAS token is not valid for SMB authentication, so no prompt for credentials will occur in a way that allows access."}, {"p": "will have read, write, and list access is incorrect because, without support for SAS authentication, the SMB protocol cannot grant any permissions in this scenario."}, {"p": "will have read-only access is incorrect because the net use command with SAS authentication will not provide any access due to the limitations of the SMB protocol, which requires the storage account key."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/storage-sas-overview", "https://learn.microsoft.com/en-us/azure/storage/storage-explorer/vs-azure-tools-storage-manage-with-storage-explorer?tabs=windows"], "group": "G104"}, {"id": "T3-Q25", "test": 3, "num": 25, "domain": "storage", "stem": [{"p": "You have an Azure subscription and plan to create a new Azure Storage account. You must configure encryption for the storage account and ensure that the solution meets the following criteria:"}, {"p": "Encryption must use a customer-managed key stored in an Azure Key Vault."}, {"p": "The key must use the highest supported bit length."}, {"p": "Which type of encryption key should you select?"}], "options": ["AES", "3DES", "RSA"], "correct": [2], "multi": false, "explanation": [{"p": "RSA is the correct answer here because when using customer-managed keys with Azure Storage, the service supports RSA keys for encryption stored in Azure Key Vault. For Azure Storage encryption, RSA keys support the maximum bit length of 4096 bits, which is currently the highest supported bit length in Azure Key Vault for customer-managed keys."}, {"p": "AES is incorrect because, while AES is commonly used for encryption, Azure Key Vault only supports RSA for customer-managed keys in this context. AES is not an option for customer-managed keys stored in Azure Key Vault."}, {"p": "3DES is incorrect because 3DES (Triple DES) is an older encryption standard and is not supported for customer-managed keys in Azure Key Vault. Azure Key Vault supports RSA keys for customer-managed storage account encryption."}], "refs": ["https://docs.microsoft.com/en-us/azure/storage/common/storage-service-encryption", "https://learn.microsoft.com/en-us/azure/storage/common/customer-managed-keys-overview", "https://learn.microsoft.com/en-us/azure/key-vault/keys/about-keys"], "group": "G105"}, {"id": "T3-Q26", "test": 3, "num": 26, "domain": "storage", "stem": [{"p": "You have an Azure subscription and plan to create a new Azure Storage account. You must configure encryption for the storage account and ensure that the solution meets the following criteria:"}, {"p": "Encryption must use a customer-managed key stored in an Azure Key Vault."}, {"p": "The key must use the highest supported bit length."}, {"p": "Which bit length should you use?"}], "options": ["2048", "3072", "4096", "8192"], "correct": [2], "multi": false, "explanation": [{"p": "4096 is the correct answer here because, for customer-managed keys stored in Azure Key Vault, the maximum supported bit length for RSA encryption keys is 4096 bits. This is the highest supported bit length in Azure Key Vault for customer-managed keys used for storage account encryption, meeting the requirement for maximum security."}, {"p": "2048 is incorrect because, although 2048-bit keys are secure, they do not meet the requirement to use the maximum supported bit length."}, {"p": "3072 is incorrect because, while 3072-bit keys offer stronger encryption than 2048-bit keys, they still do not meet the requirement to use the maximum supported bit length."}, {"p": "8192 is incorrect because Azure Key Vault does not support RSA keys with an 8192-bit length. The maximum supported bit length for customer-managed RSA keys in Azure Key Vault is 4096 bits."}], "refs": ["https://docs.microsoft.com/en-us/azure/storage/common/storage-service-encryption", "https://learn.microsoft.com/en-us/azure/storage/common/customer-managed-keys-overview"], "group": "G105"}, {"id": "T3-Q27", "test": 3, "num": 27, "domain": "storage", "stem": [{"p": "You create an Azure Storage account called apexcorestorage and plan to add an Azure file share named data. Users must be able to map a network drive to the data file share from their home computers running Windows 10."}, {"p": "Which outbound port must be allowed between the users’ computers and the Azure file share?"}], "options": ["80", "443", "445", "3389"], "correct": [2], "multi": false, "explanation": [{"p": "445 is the correct answer here because SMB (Server Message Block) protocol, which is used to access Azure file shares, operates over port 445. Windows clients need access to port 445 to map a drive to the Azure file share, which allows users to access the data remotely from their home computers."}, {"p": "80 is incorrect because port 80 is typically used for HTTP traffic, which is not used for SMB file share connections."}, {"p": "443 is incorrect because port 443 is commonly used for HTTPS traffic, which is not required for SMB file share connections."}, {"p": "3389 is incorrect because port 3389 is used for Remote Desktop Protocol (RDP) connections, not for mapping file shares."}], "refs": ["https://docs.microsoft.com/en-us/azure/storage/files/storage-troubleshoot-windows-file-connection"], "group": "G106"}, {"id": "T3-Q28", "test": 3, "num": 28, "domain": "network", "stem": [{"p": "You have an Azure web app named webapp1. You also have a virtual network named VNET1 and an Azure virtual machine named VM1 that hosts a MySQL database. VM1 is connected to VNET1."}, {"p": "You must ensure that webapp1 can access the data stored on VM1."}, {"p": "What action should you take?"}], "options": ["Connect webapp1 to VNET1.", "Set up an internal load balancer.", "Configure virtual network peering between VNET1 and another virtual network.", "Deploy an Azure Application Gateway."], "correct": [0], "multi": false, "explanation": [{"p": "Connect webapp1 to VNET1 is the correct answer because, to enable direct network communication between the Azure web app (webapp1) and the virtual machine (VM1) hosting the MySQL database, the web app needs to be integrated with the same virtual network (VNET1). This integration allows webapp1 to access VM1 over the private network, ensuring secure and seamless connectivity to the database."}, {"p": "Set up an internal load balancer is incorrect because a load balancer manages traffic distribution but does not enable direct network connectivity between web apps and VMs."}, {"p": "Configure virtual network peering between VNET1 and another virtual network is incorrect because peering with another virtual network does not directly enable webapp1 to access VM1; webapp1 must be connected to VNET1 itself."}, {"p": "Deploy an Azure Application Gateway is incorrect because an Application Gateway manages HTTP/S traffic to web applications, not private connectivity between a web app and a VM in a virtual network."}], "refs": ["https://docs.microsoft.com/en-us/azure/app-service/web-sites-integrate-with-vnet"], "group": "G107"}, {"id": "T3-Q29", "test": 3, "num": 29, "domain": "storage", "stem": [{"p": "You have an Azure App Service named AppService01 that includes two folders: LogsFolder and TempFolder."}, {"p": "You must configure a daily backup of AppService01, but ensure that TempFolder is excluded from the backup process."}, {"p": "What should you create first to meet this requirement?"}], "options": ["An Azure Storage account", "A Backup vault", "A Recovery Services vault", "A resource group"], "correct": [0], "multi": false, "explanation": [{"p": "An Azure Storage account is the correct answer because Azure App Service backups require an Azure Storage account to store the backup data. When configuring the backup, you can specify which files and folders to include or exclude, allowing you to exclude TempFolder from the backup of WebApp1."}, {"p": "A Backup vault is incorrect because App Service backups do not use Backup vaults. They rely on Azure Storage accounts."}, {"p": "A Recovery Services vault is incorrect because Recovery Services vaults are used for Azure Backup and Azure Site Recovery, not for App Service backups."}, {"p": "A resource group is incorrect because, while required for organizing resources, it is not specifically needed to configure backups for App Service."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/manage-backup"], "group": "G108"}, {"id": "T3-Q30", "test": 3, "num": 30, "domain": "storage", "stem": [{"p": "You have an Azure App Service named AppService01 that includes two folders: LogsFolder and TempFolder."}, {"p": "You must configure a daily backup of AppService01, but ensure that TempFolder is excluded from the backup process."}, {"p": "What should you use to exclude TempFolder?"}], "options": ["A _backup.filter file", "A backup policy", "A lock", "A WebJob"], "correct": [0], "multi": false, "explanation": [{"p": "A _backup.filter file is the correct answer because, in Azure App Service, you can exclude specific files or directories from a backup by creating a _backup.filter file in the root directory of the app. This file allows you to specify any files or directories that should be excluded from the backup, such as TempFolder."}, {"img": "az104/img/t3_image19.webp"}, {"p": "A backup policy is incorrect because Azure App Service does not use backup policies to exclude specific directories. It relies on the _backup.filter file."}, {"p": "A lock is incorrect because locks are used to prevent accidental modification or deletion of resources, not to control backup contents."}, {"p": "A WebJob is incorrect because WebJobs are used to run background tasks in Azure App Service, not to manage backup configurations or exclusions."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/manage-backup"], "group": "G108"}, {"id": "T3-Q31", "test": 3, "num": 31, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes the resources listed in the following table."}, {"img": "az104/img/t3_image20.webp"}, {"p": "You need to configure a proximity placement group for ScaleSet01."}, {"p": "Which proximity placement groups should you use?"}], "options": ["PPG-West-01 only", "PPG-West-01 and PPG-Central-02 only", "PPG-Central-01 only", "PPG-West-01, PPG-Central-01, and PPG-Central-02"], "correct": [0], "multi": false, "explanation": [{"p": "PPG-West-01 only is the correct answer because a virtual machine scale set can only use a proximity placement group that is located in the same Azure region. Proximity placement groups are used to ensure that compute resources are placed physically close to each other within an Azure datacenter to minimize latency."}, {"p": "In this scenario, ScaleSet01 is located in the West US region. Among the available proximity placement groups, only PPG-West-01 is also located in West US, making it the only valid option."}, {"p": "It is important to note that the proximity placement group and the virtual machine scale set do not need to be in the same resource group. They only need to exist in the same region."}, {"p": "PPG-West-01 and PPG-Central-02 only is incorrect because PPG-Central-02 is located in Central US, which does not match the West US region of ScaleSet01."}, {"p": "PPG-Central-01 only is incorrect because PPG-Central-01 is located in Central US, while ScaleSet01 is located in West US. Proximity placement groups must be in the same region as the compute resources that use them."}, {"p": "PPG-West-01, PPG-Central-01, and PPG-Central-02 is incorrect because only PPG-West-01 is located in the West US region required by ScaleSet01. The other proximity placement groups are located in Central US and therefore cannot be associated with the scale set."}], "refs": ["https://azure.microsoft.com/en-us/blog/introducing-proximity-placement-groups/"], "group": "G109"}, {"id": "T3-Q32", "test": 3, "num": 32, "domain": "network", "stem": [{"p": "You create an App Service plan named Plan1 and an Azure web app named webapp1. You notice that the option to create a staging slot is currently unavailable."}, {"p": "You need to create a staging slot for Plan1."}, {"p": "What should you do first?"}], "options": ["From Plan1, scale up the App Service plan.", "From Plan1, scale out the App Service plan.", "From webapp1, add a custom domain.", "From webapp1, modify the Application settings."], "correct": [0], "multi": false, "explanation": [{"p": "From Plan1, scale up the App Service plan is the correct answer here. To create a staging slot for an Azure App Service plan, it must be in the Standard, Premium, or higher pricing tier. Since staging slots are not available for the Free, Shared, or Basic tiers, the solution here is to scale up Plan1 to a tier that supports deployment slots. This will allow you to create a staging slot for testing or other purposes without affecting the production slot."}, {"img": "az104/img/t3_image21.webp"}, {"p": "From Plan1, scale out the App Service plan is incorrect because scaling out increases the number of instances within the same tier but does not change the tier itself. To enable staging slots, you need to change the tier by scaling up."}, {"p": "From webapp1, add a custom domain is incorrect because adding a custom domain does not impact the ability to create a staging slot."}, {"p": "From webapp1, modify the Application settings is incorrect because modifying application settings does not affect the availability of staging slots, which is determined by the App Service plan tier."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/deploy-staging-slots"], "group": "G110"}, {"id": "T3-Q33", "test": 3, "num": 33, "domain": "compute", "stem": [{"p": "You have an Azure subscription that includes a virtual machine named VM1, which hosts a line-of-business application that must remain available around the clock. VM1 has a single network interface, one managed disk, and is currently configured with the D4s v3 size."}, {"p": "You plan to apply the following modifications to VM1:"}, {"p": "Resize the virtual machine to D8s v3."}, {"p": "Attach an additional 500-GB managed disk."}, {"p": "Install the Puppet Agent virtual machine extension."}, {"p": "Enable Desired State Configuration (DSC) management."}, {"p": "Which of these changes will result in downtime for VM1?"}], "options": ["Adding the Puppet Agent extension.", "Attaching a 500-GB managed disk.", "Changing the size to D8s v3.", "Enabling Desired State Configuration Management."], "correct": [2], "multi": false, "explanation": [{"p": "Changing the size to D8s v3 is the correct answer here. Changing the size of a virtual machine in Azure requires it to be deallocated and then re-provisioned, which causes downtime. During the resizing process, VM1 will not be available, resulting in a temporary outage for the line-of-business application."}, {"p": "Adding the Puppet Agent extension is incorrect because adding an extension to a virtual machine does not require deallocation, so it does not cause downtime."}, {"p": "Attaching a 500-GB managed disk is incorrect because attaching an additional managed disk to a virtual machine can be done while the VM is running, and it does not cause downtime."}, {"p": "Enabling Desired State Configuration Management is incorrect because enabling Desired State Configuration (DSC) does not require the virtual machine to be stopped or deallocated, so it does not cause downtime."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-machines/resize-vm", "https://azure.microsoft.com/en-us/blog/resize-virtual-machines"], "group": "G111"}, {"id": "T3-Q34", "test": 3, "num": 34, "domain": "storage", "stem": [{"p": "You manage an Azure subscription that contains an existing Azure Storage account."}, {"p": "You plan to deploy an Azure Container Instance named sqlcontainer01, which runs a Docker image named mssqlimage01. The image includes a Microsoft SQL Server instance that requires persistent data storage beyond the lifecycle of the container."}, {"p": "You must configure a storage solution that ensures the SQL Server data remains available even if sqlcontainer01 is restarted or redeployed."}, {"p": "Which Azure storage service should you use to provide persistent storage for sqlcontainer01?"}], "options": ["Azure Queue storage", "Azure Blob storage", "Azure Table storage", "Azure Files"], "correct": [3], "multi": false, "explanation": [{"p": "Azure Files is the correct answer because it provides a fully managed SMB file share that can be mounted by Azure container instances as persistent storage. This is essential for scenarios like running Microsoft SQL Server in a container, where data needs to persist across container restarts. However, it is important to note that volume mounting, including Azure Files, is currently only supported for Linux-based Azure container instances. Therefore, this solution assumes that mssqlimage01 is a Linux container image running SQL Server for Linux (which is fully supported)."}, {"p": "Azure Queue storage is incorrect because it is designed for messaging between application components and does not provide file system-based persistent storage."}, {"p": "Azure Blob storage is incorrect because it is used for storing unstructured object data and cannot be mounted as a file system by container instances."}, {"p": "Azure Table storage is incorrect because it is a NoSQL key-value store intended for structured data and not suitable for use as a mounted persistent file system."}], "refs": ["https://learn.microsoft.com/en-us/azure/container-instances/container-instances-volume-azure-files", "https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction"], "group": "G112"}, {"id": "T3-Q35", "test": 3, "num": 35, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes a virtual network named VNET1 located in the East US 2 region. Two network interfaces, VM1-NI and VM2-NI, are connected to VNET1."}, {"p": "You successfully deploy the following Azure Resource Manager template."}, {"p": "{"}, {"p": "\"apiVersion\": \"2017-03-30\","}, {"p": "\"type\": \"Microsoft.Compute/virtualMachines\","}, {"p": "\"name\": \"VM1\","}, {"p": "\"zones\": \"1\","}, {"p": "\"location\": \"EastUS2\","}, {"p": "\"dependsOn\": ["}, {"p": "\"[resourceId('Microsoft.Network/networkInterfaces', 'VM1-NI')]\""}, {"p": "],"}, {"p": "\"properties\": {"}, {"p": "\"hardwareProfile\": {"}, {"p": "\"vmSize\": \"Standard_A2_v2\""}, {"p": "},"}, {"p": "\"osProfile\": {"}, {"p": "\"computerName\": \"VM1\","}, {"p": "\"adminUsername\": \"AzureAdmin\","}, {"p": "\"adminPassword\": \"[parameters('adminPassword')]\""}, {"p": "},"}, {"p": "\"storageProfile\": {"}, {"p": "\"imageReference\": \"[variables('image')]\","}, {"p": "\"osDisk\": {"}, {"p": "\"createOption\": \"FromImage\""}, {"p": "}"}, {"p": "},"}, {"p": "\"networkProfile\": {"}, {"p": "\"networkInterfaces\": ["}, {"p": "{"}, {"p": "\"id\": \"[resourceId('Microsoft.Network/networkInterfaces', 'VM1-NI')]\""}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "},"}, {"p": "{"}, {"p": "\"apiVersion\": \"2017-03-30\","}, {"p": "\"type\": \"Microsoft.Compute/virtualMachines\","}, {"p": "\"name\": \"VM2\","}, {"p": "\"zones\": \"2\","}, {"p": "\"location\": \"EastUS2\","}, {"p": "\"dependsOn\": ["}, {"p": "\"[resourceId('Microsoft.Network/networkInterfaces', 'VM2-NI')]\""}, {"p": "],"}, {"p": "\"properties\": {"}, {"p": "\"hardwareProfile\": {"}, {"p": "\"vmSize\": \"Standard_A2_v2\""}, {"p": "},"}, {"p": "\"osProfile\": {"}, {"p": "\"computerName\": \"VM2\","}, {"p": "\"adminUsername\": \"AzureAdmin\","}, {"p": "\"adminPassword\": \"[parameters('adminPassword')]\""}, {"p": "},"}, {"p": "\"storageProfile\": {"}, {"p": "\"imageReference\": \"[variables('image')]\","}, {"p": "\"osDisk\": {"}, {"p": "\"createOption\": \"FromImage\""}, {"p": "}"}, {"p": "},"}, {"p": "\"networkProfile\": {"}, {"p": "\"networkInterfaces\": ["}, {"p": "{"}, {"p": "\"id\": \"[resourceId('Microsoft.Network/networkInterfaces', 'VM2-NI')]\""}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "}"}, {"p": "True or False:"}, {"p": "“VM1 and VM2 can connect to VNET1.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer here. VM1 and VM2 can connect to VNET1 as they both have network interfaces (VM1-NI and VM2-NI) explicitly linked to VNET1 within the same location, \"East US 2.\" This configuration ensures that both virtual machines are part of VNET1 and can communicate within this virtual network."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-vnet-plan-design"], "group": "G113"}, {"id": "T3-Q36", "test": 3, "num": 36, "domain": "storage", "stem": [{"p": "You have an Azure subscription that includes a virtual network named VNET1 located in the East US 2 region. Two network interfaces, VM1-NI and VM2-NI, are connected to VNET1."}, {"p": "You successfully deploy the following Azure Resource Manager template."}, {"p": "{"}, {"p": "\"apiVersion\": \"2017-03-30\","}, {"p": "\"type\": \"Microsoft.Compute/virtualMachines\","}, {"p": "\"name\": \"VM1\","}, {"p": "\"zones\": \"1\","}, {"p": "\"location\": \"EastUS2\","}, {"p": "\"dependsOn\": ["}, {"p": "\"[resourceId('Microsoft.Network/networkInterfaces', 'VM1-NI')]\""}, {"p": "],"}, {"p": "\"properties\": {"}, {"p": "\"hardwareProfile\": {"}, {"p": "\"vmSize\": \"Standard_A2_v2\""}, {"p": "},"}, {"p": "\"osProfile\": {"}, {"p": "\"computerName\": \"VM1\","}, {"p": "\"adminUsername\": \"AzureAdmin\","}, {"p": "\"adminPassword\": \"[parameters('adminPassword')]\""}, {"p": "},"}, {"p": "\"storageProfile\": {"}, {"p": "\"imageReference\": \"[variables('image')]\","}, {"p": "\"osDisk\": {"}, {"p": "\"createOption\": \"FromImage\""}, {"p": "}"}, {"p": "},"}, {"p": "\"networkProfile\": {"}, {"p": "\"networkInterfaces\": ["}, {"p": "{"}, {"p": "\"id\": \"[resourceId('Microsoft.Network/networkInterfaces', 'VM1-NI')]\""}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "},"}, {"p": "{"}, {"p": "\"apiVersion\": \"2017-03-30\","}, {"p": "\"type\": \"Microsoft.Compute/virtualMachines\","}, {"p": "\"name\": \"VM2\","}, {"p": "\"zones\": \"2\","}, {"p": "\"location\": \"EastUS2\","}, {"p": "\"dependsOn\": ["}, {"p": "\"[resourceId('Microsoft.Network/networkInterfaces', 'VM2-NI')]\""}, {"p": "],"}, {"p": "\"properties\": {"}, {"p": "\"hardwareProfile\": {"}, {"p": "\"vmSize\": \"Standard_A2_v2\""}, {"p": "},"}, {"p": "\"osProfile\": {"}, {"p": "\"computerName\": \"VM2\","}, {"p": "\"adminUsername\": \"AzureAdmin\","}, {"p": "\"adminPassword\": \"[parameters('adminPassword')]\""}, {"p": "},"}, {"p": "\"storageProfile\": {"}, {"p": "\"imageReference\": \"[variables('image')]\","}, {"p": "\"osDisk\": {"}, {"p": "\"createOption\": \"FromImage\""}, {"p": "}"}, {"p": "},"}, {"p": "\"networkProfile\": {"}, {"p": "\"networkInterfaces\": ["}, {"p": "{"}, {"p": "\"id\": \"[resourceId('Microsoft.Network/networkInterfaces', 'VM2-NI')]\""}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "}"}, {"p": "True or False:"}, {"p": "“If an Azure datacenter becomes unavailable, VM1 or VM2 will be available.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer here. In the ARM template, VM1 is assigned to \"zones\": \"1\" and VM2 to \"zones\": \"2\", which places them in separate availability zones within the same Azure region. This configuration ensures that if one datacenter within the region becomes unavailable, the other virtual machine in a different zone remains operational. Azure's availability zones are designed to protect against datacenter-level failures, providing high availability by distributing resources across multiple zones within a region."}], "refs": ["https://learn.microsoft.com/en-us/azure/reliability/availability-zones-overview?tabs=azure-cli"], "group": "G113"}, {"id": "T3-Q37", "test": 3, "num": 37, "domain": "storage", "stem": [{"p": "You have an Azure subscription that includes a virtual network named VNET1 located in the East US 2 region. Two network interfaces, VM1-NI and VM2-NI, are connected to VNET1."}, {"p": "You successfully deploy the following Azure Resource Manager template."}, {"p": "{"}, {"p": "\"apiVersion\": \"2017-03-30\","}, {"p": "\"type\": \"Microsoft.Compute/virtualMachines\","}, {"p": "\"name\": \"VM1\","}, {"p": "\"zones\": \"1\","}, {"p": "\"location\": \"EastUS2\","}, {"p": "\"dependsOn\": ["}, {"p": "\"[resourceId('Microsoft.Network/networkInterfaces', 'VM1-NI')]\""}, {"p": "],"}, {"p": "\"properties\": {"}, {"p": "\"hardwareProfile\": {"}, {"p": "\"vmSize\": \"Standard_A2_v2\""}, {"p": "},"}, {"p": "\"osProfile\": {"}, {"p": "\"computerName\": \"VM1\","}, {"p": "\"adminUsername\": \"AzureAdmin\","}, {"p": "\"adminPassword\": \"[parameters('adminPassword')]\""}, {"p": "},"}, {"p": "\"storageProfile\": {"}, {"p": "\"imageReference\": \"[variables('image')]\","}, {"p": "\"osDisk\": {"}, {"p": "\"createOption\": \"FromImage\""}, {"p": "}"}, {"p": "},"}, {"p": "\"networkProfile\": {"}, {"p": "\"networkInterfaces\": ["}, {"p": "{"}, {"p": "\"id\": \"[resourceId('Microsoft.Network/networkInterfaces', 'VM1-NI')]\""}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "},"}, {"p": "{"}, {"p": "\"apiVersion\": \"2017-03-30\","}, {"p": "\"type\": \"Microsoft.Compute/virtualMachines\","}, {"p": "\"name\": \"VM2\","}, {"p": "\"zones\": \"2\","}, {"p": "\"location\": \"EastUS2\","}, {"p": "\"dependsOn\": ["}, {"p": "\"[resourceId('Microsoft.Network/networkInterfaces', 'VM2-NI')]\""}, {"p": "],"}, {"p": "\"properties\": {"}, {"p": "\"hardwareProfile\": {"}, {"p": "\"vmSize\": \"Standard_A2_v2\""}, {"p": "},"}, {"p": "\"osProfile\": {"}, {"p": "\"computerName\": \"VM2\","}, {"p": "\"adminUsername\": \"AzureAdmin\","}, {"p": "\"adminPassword\": \"[parameters('adminPassword')]\""}, {"p": "},"}, {"p": "\"storageProfile\": {"}, {"p": "\"imageReference\": \"[variables('image')]\","}, {"p": "\"osDisk\": {"}, {"p": "\"createOption\": \"FromImage\""}, {"p": "}"}, {"p": "},"}, {"p": "\"networkProfile\": {"}, {"p": "\"networkInterfaces\": ["}, {"p": "{"}, {"p": "\"id\": \"[resourceId('Microsoft.Network/networkInterfaces', 'VM2-NI')]\""}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "}"}, {"p": "True or False:"}, {"p": "“If the East US 2 region becomes unavailable, VM1 or VM2 will be available.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer here. Although VM1 and VM2 are placed in different availability zones within the East US 2 region, they are still limited to that specific region. If the entire East US 2 region becomes unavailable, both virtual machines will be affected, resulting in downtime for the application hosted on them. Availability zones provide resilience within a region, but they do not protect against a full regional outage."}], "refs": ["https://learn.microsoft.com/en-us/azure/reliability/availability-zones-overview?tabs=azure-cli"], "group": "G113"}, {"id": "T3-Q38", "test": 3, "num": 38, "domain": "compute", "stem": [{"p": "You have an Azure subscription in which a virtual machine scale set is deployed with the following scaling configuration:"}, {"p": "Initial instance count: 2"}, {"p": "Scaling policy: Custom"}, {"p": "Minimum number of instances: 1"}, {"p": "Maximumnumber of  instances: 10"}, {"p": "Scale-out settings:"}, {"p": "CPU Threshold: 75%"}, {"p": "Duration in minutes: 10 minutes"}, {"p": "Number of instances to increase by: 1"}, {"p": "Scale-in settings:"}, {"p": "CPU Threshold: 25%"}, {"p": "Number of instances to decrease by: 1"}, {"p": "Based on the configuration provided, select the answer choice that completes the following statement correctly."}, {"p": "“At 9:00 AM, the virtual machine scale set starts running, and CPU utilization remains at 90 percent for 15 minutes. How many virtual machine instances will be running at 9:15 AM?”"}], "options": ["2", "3", "4", "5"], "correct": [1], "multi": false, "explanation": [{"p": "3 is the correct answer here. Given that the CPU utilization is 90% for 15 minutes, which is above the scale-out threshold of 75%, the scale set will evaluate this sustained high CPU usage after the 10-minute duration set for scale-out. Since the threshold has been exceeded, the scale set will add 1 instance as specified in the \"Number of instances to increase by\" setting. Therefore, starting with two instances at 9:00 AM, the scale set will have three instances running by 9:15 AM."}], "refs": ["https://docs.microsoft.com/en-us/azure/virtual-machine-scale-sets/overview", "https://docs.microsoft.com/en-us/azure/virtual-machine-scale-sets/virtual-machine-scale-sets-autoscale-overview", "https://docs.microsoft.com/en-us/azure/virtual-machine-scale-sets/virtual-machine-scale-sets-autoscale-portal"], "group": "G114"}, {"id": "T3-Q39", "test": 3, "num": 39, "domain": "compute", "stem": [{"p": "You have an Azure subscription in which a virtual machine scale set is deployed with the following scaling configuration:"}, {"p": "Initial instance count: 2"}, {"p": "Scaling policy: Custom"}, {"p": "Minimum number of instances: 1"}, {"p": "Maximumnumber of  instances: 10"}, {"p": "Scale-out settings:"}, {"p": "CPU Threshold: 75%"}, {"p": "Duration in minutes: 10 minutes"}, {"p": "Number of instances to increase by: 1"}, {"p": "Scale-in settings:"}, {"p": "CPU Threshold: 25%"}, {"p": "Number of instances to descrease by: 1"}, {"p": "Based on the configuration provided, select the answer choice that completes the following statement correctly."}, {"p": "“At 10:00 AM, the scale set is running five virtual machine instances, and CPU utilization drops below 15 percent for 60 minutes. How many virtual machine instances will be running at 11:00 AM?”"}], "options": ["1", "2", "3", "4"], "correct": [0], "multi": false, "explanation": [{"p": "1 is the correct answer."}, {"p": "Based on this information, at 11:00 AM, there will be 1 virtual machine instance running."}, {"p": "At 10:00 AM, the scale set has five virtual machine instances running, and CPU utilization falls to less than 15% for 60 minutes, which is below the scale-in CPU threshold of 25%. With the default scale-in duration set to 10 minutes, the scale set will evaluate the CPU utilization every 10 minutes during the 60-minute period and determine that it is below the scale-in threshold."}, {"p": "If the CPU utilization remains below 15% continuously for 60 minutes, the autoscale mechanism will evaluate the conditions every 10 minutes. Each time the condition is met, it will decrease the instance count by 1, subject to the minimum instance limit.​"}, {"p": "Assuming the minimum number of instances is set to 1, the scaling would proceed as follows:"}, {"p": "10:10 AM: Decrease to 4 instances"}, {"p": "10:20 AM: Decrease to 3 instances"}, {"p": "10:30 AM: Decrease to 2 instances"}, {"p": "10:40 AM: Decrease to 1 instance"}, {"p": "10:50 AM: No further decrease (minimum limit reached)"}, {"p": "11:00 AM: No change​"}, {"p": "Therefore, at 11:00 AM, you will have 1 virtual machine instance running."}], "refs": ["https://docs.microsoft.com/en-us/azure/virtual-machine-scale-sets/overview", "https://docs.microsoft.com/en-us/azure/virtual-machine-scale-sets/virtual-machine-scale-sets-autoscale-overview", "https://docs.microsoft.com/en-us/azure/virtual-machine-scale-sets/virtual-machine-scale-sets-autoscale-portal"], "group": "G114"}, {"id": "T3-Q40", "test": 3, "num": 40, "domain": "compute", "stem": [{"p": "You have an Azure subscription and intend to deploy multiple Azure Container Instances, defined as follows:"}, {"p": "Instance1: Windows Server 2019 (Nano Server installation)"}, {"p": "Instance2: Windows Server 2019 (Server Core installation)"}, {"p": "Instance3: Linux"}, {"p": "Instance4: Linux"}, {"p": "Which of these instances are eligible to be deployed together within the same container group?"}], "options": ["Instance1 only", "Instance2 only", "Instance1 and Instance2 only", "Instance3 and Instance4 only"], "correct": [3], "multi": false, "explanation": [{"p": "Instance3 and Instance4 only is correct because Azure Container Instances (ACI) currently supports multi-container groups only for Linux containers. This means you can deploy multiple Linux-based containers (such as Instance3 and Instance4) together within a single container group that shares networking, storage volumes, and lifecycle."}, {"p": "Instance1 and Instance2 are Windows-based containers (Nano Server and Server Core). Azure Container Instances does not support deploying multiple Windows containers in a group. Windows containers can only be deployed as single-container instances. Therefore, even though both are Windows-based, they cannot be combined into a container group."}, {"p": "Instance1 only, Instance2 only, and Instance1 and Instance2 only are incorrect because these configurations would either use Windows containers (unsupported for container groups) or fail to meet the definition of a multi-container group."}], "refs": ["https://learn.microsoft.com/en-us/azure/container-instances/container-instances-overview", "https://learn.microsoft.com/en-us/azure/container-instances/container-instances-container-groups"], "group": "G115"}, {"id": "T3-Q41", "test": 3, "num": 41, "domain": "compute", "stem": [{"p": "You have an Azure subscription containing the following storage accounts:"}, {"p": "storage1 - General-purpose v2 (StorageV2), located in Central US"}, {"p": "storage2 - BlobStorage, located in West US"}, {"p": "storage3 - BlockBlobStorage, located in West US"}, {"p": "storage4 - FileStorage, located in East US"}, {"p": "You deploy a web application named App1 to the West US region. You must configure a backup solution for App1 while minimizing costs."}, {"p": "Which storage account should you choose as the backup target?"}], "options": ["storage1", "storage2", "storage3", "storage4"], "correct": [1], "multi": false, "explanation": [{"p": "storage2 is the correct answer here. This storage account is of the BlobStorage type and is located in the West US region, the same region as the web app, App1. Azure Backup uses block blobs to store backup data, making BlobStorage an appropriate type for this purpose. Additionally, placing backup data in the same region as the resource being backed up minimizes latency and avoids additional costs associated with cross-region data transfers."}, {"p": "storage1 is incorrect because it is located in Central US, a different region than the web app’s region (West US). While StorageV2 can also be used for backup, cross-region data transfers can lead to increased latency and additional costs, making it less ideal."}, {"p": "storage3 is incorrect despite being in the same region as App1 (West US). Although it is of the BlockBlobStorage type, which supports block blobs, it is generally more expensive than BlobStorage or StorageV2, due to its premium performance characteristics. Given the requirement to minimize costs, BlockBlobStorage is not the optimal choice."}, {"p": "storage4 is incorrect as it is of the FileStorage type, which is intended for Azure File Shares rather than backups. Furthermore, it is located in East US, which is a different region from the web app, leading to potential additional latency and transfer costs."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-overview", "https://docs.microsoft.com/en-us/azure/storage/common/storage-account-overview", "https://docs.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction", "https://docs.microsoft.com/en-us/azure/storage/blobs/premium-blob-faqs"], "group": "G116"}, {"id": "T3-Q42", "test": 3, "num": 42, "domain": "compute", "stem": [{"p": "You have an Azure environment that includes a virtual network named VNet1. The virtual machines deployed in VNet1 are configured to allow Remote Desktop access."}, {"p": "Several users will be working from home and must securely connect to these virtual machines over the internet. You are required to implement Point-to-Site (P2S) VPN connectivity so that each user can establish a private connection to the virtual network."}, {"p": "Which three actions should you perform in sequence?"}, {"p": "ACTIONS"}, {"p": "Provision a local network gateway resource."}, {"p": "Configure a public IP address for each virtual machine."}, {"p": "Create an additional subnet within VNet1."}, {"p": "Add an IP address pool."}, {"p": "Deploy a load balancer to VNet1."}, {"p": "Deploy a VPN gateway for the virtual network."}], "options": ["1-6-4", "2-4-6", "3-6-4", "4-6-3", "5-6-1"], "correct": [2], "multi": false, "explanation": [{"p": "(Action 3) Create an additional subnet within VNet1 – A specific subnet is needed for the VPN gateway within VNet1. This subnet is usually named the GatewaySubnet and is required to deploy the VPN gateway for a Point-to-Site (P2S) VPN connection."}, {"p": "(Action 6) Create a VPN gateway – After the subnet is created, you need to deploy a VPN gateway in VNet1. The VPN gateway provides the Point-to-Site (P2S) VPN functionality, allowing users to securely connect to the virtual network from a remote location."}, {"p": "(Action 4) Add an IP address pool – Once the VPN gateway is set up, you configure an IP address pool. This pool assigns IP addresses to users who connect through the P2S VPN, ensuring they can connect to resources within VNet1."}, {"p": "(Action 1) Provision a local network gateway resource is incorrect because a local network gateway is used for Site-to-Site (S2S) VPN connections to represent the on-premises VPN device, not for Point-to-Site connections."}, {"p": "(Action 2) Configure a public IP address for each virtual machine is incorrect  because with a P2S VPN, users can securely connect to the VMs over the VPN without needing public IPs on each VM, enhancing security."}, {"p": "(Action 5) Deploy a load balancer to VNet1 is incorrect because a load balancer is not required for P2S VPN connectivity. It’s typically used for distributing traffic across multiple VMs."}], "refs": ["https://learn.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-about-vpngateways"], "group": "G117"}, {"id": "T3-Q43", "test": 3, "num": 43, "domain": "compute", "stem": [{"p": "You have three Azure storage accounts configured as follows:"}, {"p": "storage1 — General-purpose v2 (StorageV2), Standard performance, Locally-redundant storage (LRS), Cool tier"}, {"p": "storage2 — General-purpose v2 (StorageV2), Standard performance, Read-access geo-redundant storage (RA-GRS), Hot tier"}, {"p": "storage3 — BlobStorage, Premium performance, Locally-redundant storage (LRS), Hot tier"}, {"p": "You must identify which storage account can be changed to use zone-redundant storage (ZRS) replication."}, {"p": "Which storage account meets this requirement?"}], "options": ["storage1 only", "storage2 only", "storage3 only", "storage2 and storage3", "storage1, storage2, and storage3"], "correct": [0], "multi": false, "explanation": [{"p": "storage1 only is correct because it is an LRS account that can directly be converted to a ZRS account."}, {"img": "az104/img/t3_image22.webp"}, {"p": "storage2 only is incorrect because RA-GRS account cannot be directly converted to ZRS. However, it can be converted to LRS and then finally converted to ZRS. So technically, both Storage1 and Storage2 accounts can be converted to ZRS, but since we do not have \"Storage1 and Storage2 only\" as an option in the question, we are assuming it to be asking about direct conversion only."}, {"p": "storage3 is incorrect because BlobStorage accounts are not eligible for ZRS replication, regardless of their performance or replication settings."}, {"p": "storage2 and storage3 only is  incorrect answer here. Storage2 account is RA-GRS which cannot be converted to ZRS directly. Storage3  being a BlobStorage account is not supported for ZRS replication."}, {"p": "storage1, storage2, and storage3 are incorrect because only storage1 meets the criteria for direct conversion to ZRS."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/redundancy-migration?tabs=portal#changing-redundancy-configurationstorage-redundancy"], "group": "G118"}, {"id": "T3-Q44", "test": 3, "num": 44, "domain": "identity", "stem": [{"p": "You have a registered DNS domain named apexcore.com. You then create a public Azure DNS zone with the same name (apexcore.com)."}, {"p": "You must ensure that any DNS records added to this Azure DNS zone can be successfully resolved by clients on the public internet."}, {"p": "What action should you take?"}], "options": ["Update the SOA record in the DNS domain registrar.", "Create the SOA record in apexcore.com.", "Update the NS records in the DNS domain registrar.", "Create NS records in apexcore.com."], "correct": [2], "multi": false, "explanation": [{"p": "Update the NS records in the DNS domain registrar is the correct answer here. To ensure that records created in the apexcore.com Azure DNS zone are resolvable from the internet, you need to update the NS (Name Server) records in your DNS domain registrar. These records should point to the Azure DNS name servers associated with the apexcore.com zone in Azure. This change directs external DNS queries for apexcore.com to Azure DNS, allowing them to be resolved by the public Azure DNS servers."}, {"p": "Update the SOA record in the DNS domain registrar is incorrect because the SOA (Start of Authority) record is managed by Azure DNS, and you do not need to modify it in the domain registrar to enable public resolution."}, {"p": "Create the SOA record in apexcore.com is incorrect because the SOA record is automatically created and managed by Azure DNS for the zone. No manual action is needed for this record to enable internet resolvability."}, {"p": "Create NS records in apexcore.com is incorrect because NS records within the Azure DNS zone are already created automatically. The critical step is to update the NS records at the DNS domain registrar, not within Azure DNS."}], "refs": ["https://learn.microsoft.com/en-us/azure/dns/dns-delegate-domain-azure-dns"], "group": "G119"}, {"id": "T3-Q45", "test": 3, "num": 45, "domain": "identity", "stem": [{"p": "You have an Azure subscription that includes a virtual network named VNet1. VNet1 is connected to two separate on-premises datacenters by using two ExpressRoute circuits."}, {"p": "You need to build a dashboard that provides in-depth network metrics and a graphical view of the network topology."}, {"p": "Which Azure service should you use?"}], "options": ["Azure Virtual Network Watcher", "Azure Monitor Network Insights", "a Data Collection Rule (DCR)", "Log Analytics"], "correct": [1], "multi": false, "explanation": [{"p": "Azure Monitor Network Insights is the correct answer here. Azure Monitor Network Insights provides a comprehensive view of your network’s health and performance. It includes detailed metrics, visualizations, and insights into the network topology, making it ideal for monitoring complex environments like the one described with multiple ExpressRoute circuits."}, {"img": "az104/img/t3_image23.webp"}, {"img": "az104/img/t3_image24.webp"}, {"p": "Azure Virtual Network Watcher is incorrect because, while it offers some monitoring and diagnostic tools for network resources, it does not provide an all-encompassing dashboard or a visual representation of network topology as effectively as Network Insights."}, {"p": "A Data Collection Rule (DCR) is incorrect because DCRs are primarily used to define data collection and ingestion rules for Azure Monitor. They do not provide a visual representation of network topology or a network-specific dashboard."}, {"p": "Log Analytics is incorrect because it is a tool for querying and analyzing logs. While you can use Log Analytics to query network data, it does not provide a pre-built dashboard or topology visualization as Network Insights does."}], "refs": ["https://learn.microsoft.com/en-us/azure/network-watcher/network-insights-overview", "https://learn.microsoft.com/en-us/azure/network-watcher/network-insights-topology?toc=%2Fazure%2Fazure-monitor%2Ftoc.json&bc=%2Fazure%2Fazure-monitor%2Fbreadcrumb%2Ftoc.json"], "group": "G120"}, {"id": "T3-Q46", "test": 3, "num": 46, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes the resources mentioned below:"}, {"p": "A virtual network named VNet1"}, {"p": "A subnet named Subnet1, which is part of VNet1"}, {"p": "Two virtual machines, VM1 and VM2, both deployed to Subnet1"}, {"p": "VM1 and VM2 were created from the same deployment template and host line-of-business applications."}, {"p": "You configure a network security group (NSG) as shown in the exhibit."}, {"img": "az104/img/t3_image25.webp"}, {"p": "You need to ensure that users on VM1 and VM2 are unable to browse websites on the internet by using TCP port 80."}, {"p": "What should you do?"}], "options": ["Modify the DenyWebSites outbound security rule.", "Update the Port_80 inbound security rule.", "Associate the network security group with Subnet1.", "Remove the network security group association from a network interface."], "correct": [2], "multi": false, "explanation": [{"p": "Associate the network security group with Subnet1 is the correct answer here. The question specifies the need to prevent users of VM1 and VM2 from accessing websites on the Internet over TCP port 80. In the exhibit, there is an outbound rule, DenyWebSites, configured to block traffic on TCP port 80. However, if you look at the \"Associated with\" section in the top right corner of the exhibit, it shows \"0 subnets, 0 network interfaces\", meaning this NSG is not currently associated with any subnet or network interface."}, {"p": "To apply this restriction to VM1 and VM2, which are located in Subnet1, it is necessary to associate the NSG with Subnet1. By doing so, the NSG rules, including the DenyWebSites rule, will take effect, blocking outbound access to websites on TCP port 80 for both VM1 and VM2. Therefore, Associate the NSG to Subnet1 is the correct choice here."}, {"p": "Modify the DenyWebSites outbound security rule is incorrect because modifying the rule itself won’t make any difference if the NSG is not associated with Subnet1 or the network interfaces of VM1 and VM2."}, {"p": "Update the Port_80 inbound security rule is incorrect because this rule manages inbound traffic on port 80, which is unrelated to the requirement to restrict outbound web access."}, {"p": "Remove the network security group association from a network interface is incorrect because there is no existing association to remove, as indicated by the \"0 subnets, 0 network interfaces\" status."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/manage-network-security-group?tabs=network-security-group-portal"], "group": "G121"}, {"id": "T3-Q47", "test": 3, "num": 47, "domain": "storage", "stem": [{"p": "You have an Azure virtual machine named VM1. You use Azure Backup to create a backup of VM1 called Backup1."}, {"p": "After Backup1 is created, you make the following changes to VM1:"}, {"p": "Change the virtual machine size."}, {"p": "Copy a file named Budget.xls into a folder named Data."}, {"p": "Reset the password for the built-in administrator account."}, {"p": "Attach an additional data disk to the virtual machine."}, {"p": "An administrator then restores VM1 from Backup1 by using the Replace existing restore option."}, {"p": "You need to ensure that all the changes made after the backup are present on VM1 again."}, {"p": "Which action must you perform again?"}], "options": ["Attach an additional data disk.", "Copy Budget.xls into the Data folder.", "Change the size of VM1.", "Reset the password for the built-in administrator account."], "correct": [1], "multi": false, "explanation": [{"p": "Copy Budget.xls into the Data folder is correct because the Replace existing restore option restores the virtual machine disks from the selected recovery point. Any changes made to the contents of the disks after Backup1 was created are reverted. Since the Budget.xls file was copied into the Data folder after the backup was taken, it will not exist after the restore and must be copied again."}, {"p": "Attach an additional data disk is incorrect because attaching a data disk is a configuration change to the Azure virtual machine resource itself. The Replace existing restore operation primarily restores the VM disks from the backup recovery point and does not necessarily remove VM-level configuration changes such as attached disk references."}, {"p": "Change the size of VM1 is incorrect because the VM size is a property of the Azure virtual machine resource and is not part of the disk contents restored from the recovery point. Restoring the VM disks does not typically revert the VM size configuration."}, {"p": "Reset the password for the built-in administrator account is incorrect because password reset operations are commonly managed through VM extensions and VM resource configuration rather than through the restored disk contents alone. The Replace existing operation does not necessarily revert these VM-level settings."}], "refs": ["https://docs.microsoft.com/en-us/azure/backup/backup-azure-restore-files-from-vm", "https://docs.microsoft.com/en-us/azure/backup/backup-azure-arm-restore-vms"], "group": "G122"}, {"id": "T3-Q48", "test": 3, "num": 48, "domain": "identity", "stem": [{"p": "You have an Azure subscription named Subscription1 that contains a resource group with the following characteristics:"}, {"p": "Name: RG1"}, {"p": "Region: West US"}, {"p": "Tags: \"tag1\": \"value1\""}, {"p": "You assign an Azure Policy named Policy1 at the Subscription1 scope with these settings:"}, {"p": "Exclusions: None"}, {"p": "Policy definition: Append a tag and its value to resources"}, {"p": "Assignment name: Policy1"}, {"p": "Parameters:"}, {"p": "Tag name: tag2"}, {"p": "Tag value: value2"}, {"p": "After assigning Policy1, you create a storage account with the following properties:"}, {"p": "Name: storage1"}, {"p": "Region: West US"}, {"p": "Resource group: RG1"}, {"p": "Tags: \"tag3\": \"value3\""}, {"p": "Which tags are applied to RG1?"}], "options": ["\"tag1\" : \"value1\" only", "\"tag2\" : \"value2\" only", "\"tag1\" : \"value1\" and \"tag2\" : \"value2\""], "correct": [0], "multi": false, "explanation": [{"p": "\"tag1\" : \"value1\" only is the correct answer here. The policy definition \"Append a tag and its value to resources\" is configured to apply to resources within Subscription1, not to the resource group RG1 itself. This policy assignment means that any new resources created under Subscription1 will have the specified tag2 : value2 appended if they do not already have this tag. However, it does not apply the tag to the resource group where the resources are created. Therefore, RG1 retains only the original tag, \"tag1\" : \"value1\". It should also be noted here that “Subscription” and “Policy1” are created at the initial stage itself and therefore the created policy would apply to the resource group – namely “RG1” within this subscription."}, {"img": "az104/img/t3_image26.webp"}, {"p": "\"tag2\" : \"value2\" only is incorrect because Policy1 does not add tag2 : value2 to the resource group itself, only to resources created within the scope of Subscription1."}, {"p": "\"tag1\" : \"value1\" and \"tag2\" : \"value2\" is incorrect because, as explained, Policy1 does not alter tags on the resource group RG1 directly. It only affects newly created resources within Subscription1."}], "refs": ["https://docs.microsoft.com/en-us/azure/azure-resource-manager/management/tag-policies", "https://docs.microsoft.com/en-us/azure/governance/policy/concepts/effects#append"], "group": "G123"}, {"id": "T3-Q49", "test": 3, "num": 49, "domain": "identity", "stem": [{"p": "You have an Azure subscription named Subscription1 that contains a resource group with the following characteristics:"}, {"p": "Name: RG1"}, {"p": "Region: West US"}, {"p": "Tags: \"tag1\": \"value1\""}, {"p": "You assign an Azure Policy named Policy1 at the Subscription1 scope with these settings:"}, {"p": "Exclusions: None"}, {"p": "Policy definition: Append a tag and its value to resources"}, {"p": "Assignment name: Policy1"}, {"p": "Parameters:"}, {"p": "Tag name: tag2"}, {"p": "Tag value: value2"}, {"p": "After assigning Policy1, you create a storage account with the following properties:"}, {"p": "Name: storage1"}, {"p": "Region: West US"}, {"p": "Resource group: RG1"}, {"p": "Tags: \"tag3\": \"value3\""}, {"p": "Which tags are assigned to storage1?"}], "options": ["\"tag3\" : \"value3\" only", "\"tag1\" : \"value1\" and \"tag3\" : \"value3\" only", "\"tag2\" : \"value2\" and \"tag3\" : \"value3\" only", "\"tag1\" : \"value1\", \"tag2\" : \"value2\", and \"tag3\" : \"value3\""], "correct": [2], "multi": false, "explanation": [{"p": "\"tag2\" : \"value2\" and \"tag3\" : \"value3\" only is the correct answer here. Tags are not inherited automatically from a resource group or subscription to the resources within them. However, in this case, Policy1 was applied to Subscription1 with the definition to append a specific tag to all new resources created in this subscription. The policy was configured with Exclusions: None and parameters Tag name: \"tag2\" and Tag value: \"value2\". This means that all resources created after this policy assignment will automatically have \"tag2\" : \"value2\" appended."}, {"p": "When storage1 was created in RG1 after the policy was assigned, it had \"tag3\" : \"value3\" specified. Since Policy1 was already in effect, \"tag2\" : \"value2\" was appended to storage1 due to the policy, resulting in storage1 having the tags \"tag2\" : \"value2\" and \"tag3\" : \"value3\" only."}, {"img": "az104/img/t3_image26.webp"}, {"p": "\"tag3\" : \"value3\" only is incorrect because the policy enforces \"tag2\" : \"value2\" on all new resources in the subscription."}, {"p": "\"tag1\" : \"value1\" and \"tag3\" : \"value3\" only is incorrect because \"tag1\" : \"value1\" is assigned only to RG1 and does not get inherited by resources within the group."}, {"p": "\"tag1\" : \"value1\", \"tag2\" : \"value2\", and \"tag3\" : \"value3\" is incorrect because storage1 does not inherit \"tag1\" : \"value1\" from RG1."}], "refs": ["https://docs.microsoft.com/en-us/azure/azure-resource-manager/management/tag-policies", "https://docs.microsoft.com/en-us/azure/governance/policy/concepts/effects#append"], "group": "G123"}, {"id": "T3-Q50", "test": 3, "num": 50, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant that contains the groups listed below, each with a specific group type and security setting."}, {"p": "Group1 - Security group (Security enabled: Yes)"}, {"p": "Group2 - Mail-enabled security group (Security enabled: Yes)"}, {"p": "Group3 - Microsoft 365 group (Security enabled: Yes)"}, {"p": "Group4 - Microsoft 365 group (Security enabled: No)"}, {"p": "You purchase Microsoft Entra ID P2 licenses and want to assign the licenses by using group-based licensing."}, {"p": "To which groups can you assign a license?"}], "options": ["Group1 only", "Group1 and Group3 only", "Group3 and Group4 only", "Group1, Group2, and Group3 only", "Group1, Group2, Group3, and Group4"], "correct": [3], "multi": false, "explanation": [{"p": "Group1, Group2, and Group3 only is correct because group-based licensing in Microsoft Entra ID supports security groups (including mail-enabled security groups) and Microsoft 365 groups that have securityEnabled=TRUE."}, {"p": "Group1 is a security group with security enabled, so it can be used."}, {"p": "Group2 is a mail-enabled security group, which is still a type of security group, and Microsoft documentation confirms that it is supported for license assignment."}, {"p": "Group3 is a Microsoft 365 group with security enabled, so it also qualifies."}, {"p": "Group1 only is incorrect because Group3 (a security-enabled Microsoft 365 group) and Group2 (a mail-enabled security group) are also supported."}, {"p": "Group1 and Group3 only is incorrect because Group2 is also eligible for license assignment, as mail-enabled security groups are supported."}, {"p": "Group3 and Group4 only is incorrect because Group4 is a Microsoft 365 group with security disabled, making it ineligible."}, {"p": "Group1, Group2, Group3, and Group4 is incorrect because Group4 is security-disabled and cannot be used for license assignment."}], "refs": ["https://learn.microsoft.com/en-us/microsoft-365/admin/manage/manage-group-licenses?view=o365-worldwide", "https://learn.microsoft.com/en-us/microsoft-365/admin/create-groups/compare-groups?view=o365-worldwide"], "group": "G124"}, {"id": "T3-Q51", "test": 3, "num": 51, "domain": "identity", "stem": [{"p": "You have a custom Azure role-based access control (RBAC) role named Role1, defined as shown below."}, {"p": "{"}, {"p": "\"id\": \"c47291ab-3f5e-4a11-b9d2-7e6c2f9a8b10\","}, {"p": "\"properties\": {"}, {"p": "\"roleName\": \"Role1\","}, {"p": "\"description\": \"\","}, {"p": "\"assignableScopes\": ["}, {"p": "\"/subscriptions/1a2b3c4d-55e6-47f8-9abc-0d1e2f3a4b5c\""}, {"p": "],"}, {"p": "\"permissions\": ["}, {"p": "{"}, {"p": "\"actions\": ["}, {"p": "\"Microsoft.Resources/subscriptions/resourceGroups/resources/read\","}, {"p": "\"Microsoft.Resources/subscriptions/resourceGroups/read\","}, {"p": "\"Microsoft.Resourcehealth/*\","}, {"p": "\"Microsoft.Authorization/*/read\","}, {"p": "\"Microsoft.Compute/*/read\","}, {"p": "\"Microsoft.Support/*\","}, {"p": "\"Microsoft.Network/virtualNetworks/read\","}, {"p": "\"Microsoft.Resources/deployments/*\","}, {"p": "\"Microsoft.Storage/storageAccounts/read\","}, {"p": "\"Microsoft.Compute/virtualMachines/start/action\","}, {"p": "\"Microsoft.Compute/virtualMachines/powerOff/action\","}, {"p": "\"Microsoft.Compute/virtualMachines/deallocate/action\","}, {"p": "\"Microsoft.Compute/virtualMachines/restart/action\","}, {"p": "\"Microsoft.Compute/virtualMachines/*\","}, {"p": "\"Microsoft.Compute/disks/*\","}, {"p": "\"Microsoft.Compute/availabilitySets/*\","}, {"p": "\"Microsoft.Network/virtualNetworks/subnets/join/action\","}, {"p": "\"Microsoft.Network/virtualNetworks/subnets/read\","}, {"p": "\"Microsoft.Network/virtualNetworks/subnets/virtualMachines/read\","}, {"p": "\"Microsoft.Network/networkInterfaces/*\","}, {"p": "\"Microsoft.Compute/snapshots/*\""}, {"p": "],"}, {"p": "\"notActions\": ["}, {"p": "\"Microsoft.Authorization/*/Delete\","}, {"p": "\"Microsoft.Authorization/*/Write\","}, {"p": "\"Microsoft.Authorization/elevateAccess/Action\""}, {"p": "]"}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "True or False:"}, {"p": "“Users who are assigned Role1 are able to assign Role1 to other users.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer here. The custom role \"Role1\" includes various permissions under the \"actions\" section, but the \"notActions\" section explicitly denies permissions related to Microsoft.Authorization/*/Delete, Microsoft.Authorization/*/Write, and Microsoft.Authorization/elevateAccess/Action. These restricted permissions prevent users assigned with \"Role1\" from performing role assignments or modifications, including the ability to assign \"Role1\" to other users."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G125"}, {"id": "T3-Q52", "test": 3, "num": 52, "domain": "identity", "stem": [{"p": "You have a custom Azure role-based access control (RBAC) role named Role1, defined as shown below."}, {"p": "{"}, {"p": "\"id\": \"c47291ab-3f5e-4a11-b9d2-7e6c2f9a8b10\","}, {"p": "\"properties\": {"}, {"p": "\"roleName\": \"Role1\","}, {"p": "\"description\": \"\","}, {"p": "\"assignableScopes\": ["}, {"p": "\"/subscriptions/1a2b3c4d-55e6-47f8-9abc-0d1e2f3a4b5c\""}, {"p": "],"}, {"p": "\"permissions\": ["}, {"p": "{"}, {"p": "\"actions\": ["}, {"p": "\"Microsoft.Resources/subscriptions/resourceGroups/resources/read\","}, {"p": "\"Microsoft.Resources/subscriptions/resourceGroups/read\","}, {"p": "\"Microsoft.Resourcehealth/*\","}, {"p": "\"Microsoft.Authorization/*/read\","}, {"p": "\"Microsoft.Compute/*/read\","}, {"p": "\"Microsoft.Support/*\","}, {"p": "\"Microsoft.Network/virtualNetworks/read\","}, {"p": "\"Microsoft.Resources/deployments/*\","}, {"p": "\"Microsoft.Storage/storageAccounts/read\","}, {"p": "\"Microsoft.Compute/virtualMachines/start/action\","}, {"p": "\"Microsoft.Compute/virtualMachines/powerOff/action\","}, {"p": "\"Microsoft.Compute/virtualMachines/deallocate/action\","}, {"p": "\"Microsoft.Compute/virtualMachines/restart/action\","}, {"p": "\"Microsoft.Compute/virtualMachines/*\","}, {"p": "\"Microsoft.Compute/disks/*\","}, {"p": "\"Microsoft.Compute/availabilitySets/*\","}, {"p": "\"Microsoft.Network/virtualNetworks/subnets/join/action\","}, {"p": "\"Microsoft.Network/virtualNetworks/subnets/read\","}, {"p": "\"Microsoft.Network/virtualNetworks/subnets/virtualMachines/read\","}, {"p": "\"Microsoft.Network/networkInterfaces/*\","}, {"p": "\"Microsoft.Compute/snapshots/*\""}, {"p": "],"}, {"p": "\"notActions\": ["}, {"p": "\"Microsoft.Authorization/*/Delete\","}, {"p": "\"Microsoft.Authorization/*/Write\","}, {"p": "\"Microsoft.Authorization/elevateAccess/Action\""}, {"p": "]"}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "True or False:"}, {"p": "“Users who are assigned Role1 are able to deploy new virtual machines.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer here."}, {"p": "Although Microsoft.Compute/virtualMachines/* alone is not always sufficient to deploy a new virtual machine, Role1 includes all the additional permissions required to create a VM and its associated resources."}, {"p": "The role grants the following key permissions:"}, {"p": "Microsoft.Compute/virtualMachines/* – Allows all operations on virtual machines, including creating (write), updating, deleting, starting, stopping, restarting, and deallocating VMs."}, {"p": "Microsoft.Compute/disks/* – Allows creation and management of managed disks required by the VM."}, {"p": "Microsoft.Network/networkInterfaces/* – Allows creation and management of network interfaces."}, {"p": "Microsoft.Network/virtualNetworks/subnets/join/action – Allows the network interface to be attached to a subnet."}, {"p": "Microsoft.Resources/deployments/* – Allows ARM template deployments, which are commonly used when deploying virtual machines."}, {"p": "Because Role1 includes permissions for both the virtual machine and its dependent resources, users assigned this role can successfully deploy new virtual machines."}, {"p": "The notActions section only prevents users from modifying Azure RBAC role assignments or elevating their own permissions. It does not restrict virtual machine deployment."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G125"}, {"id": "T3-Q53", "test": 3, "num": 53, "domain": "identity", "stem": [{"p": "You have a custom Azure role-based access control (RBAC) role named Role1, defined as shown below."}, {"p": "{"}, {"p": "\"id\": \"c47291ab-3f5e-4a11-b9d2-7e6c2f9a8b10\","}, {"p": "\"properties\": {"}, {"p": "\"roleName\": \"Role1\","}, {"p": "\"description\": \"\","}, {"p": "\"assignableScopes\": ["}, {"p": "\"/subscriptions/1a2b3c4d-55e6-47f8-9abc-0d1e2f3a4b5c\""}, {"p": "],"}, {"p": "\"permissions\": ["}, {"p": "{"}, {"p": "\"actions\": ["}, {"p": "\"Microsoft.Resources/subscriptions/resourceGroups/resources/read\","}, {"p": "\"Microsoft.Resources/subscriptions/resourceGroups/read\","}, {"p": "\"Microsoft.Resourcehealth/*\","}, {"p": "\"Microsoft.Authorization/*/read\","}, {"p": "\"Microsoft.Compute/*/read\","}, {"p": "\"Microsoft.Support/*\","}, {"p": "\"Microsoft.Network/virtualNetworks/read\","}, {"p": "\"Microsoft.Resources/deployments/*\","}, {"p": "\"Microsoft.Storage/storageAccounts/read\","}, {"p": "\"Microsoft.Compute/virtualMachines/start/action\","}, {"p": "\"Microsoft.Compute/virtualMachines/powerOff/action\","}, {"p": "\"Microsoft.Compute/virtualMachines/deallocate/action\","}, {"p": "\"Microsoft.Compute/virtualMachines/restart/action\","}, {"p": "\"Microsoft.Compute/virtualMachines/*\","}, {"p": "\"Microsoft.Compute/disks/*\","}, {"p": "\"Microsoft.Compute/availabilitySets/*\","}, {"p": "\"Microsoft.Network/virtualNetworks/subnets/join/action\","}, {"p": "\"Microsoft.Network/virtualNetworks/subnets/read\","}, {"p": "\"Microsoft.Network/virtualNetworks/subnets/virtualMachines/read\","}, {"p": "\"Microsoft.Network/networkInterfaces/*\","}, {"p": "\"Microsoft.Compute/snapshots/*\""}, {"p": "],"}, {"p": "\"notActions\": ["}, {"p": "\"Microsoft.Authorization/*/Delete\","}, {"p": "\"Microsoft.Authorization/*/Write\","}, {"p": "\"Microsoft.Authorization/elevateAccess/Action\""}, {"p": "]"}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "True or False:"}, {"p": "“Users who are assigned Role1 are able to configure a virtual machine to use a static IP address.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer here. The custom role \"Role1\" includes Microsoft.Network/networkInterfaces/* in the allowed actions, which grants users permissions to manage network interfaces, including the ability to set IP configurations on them. This permission allows users assigned \"Role1\" to configure settings such as static IP addresses on the network interface associated with a virtual machine."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G125"}, {"id": "T3-Q54", "test": 3, "num": 54, "domain": "identity", "stem": [{"p": "You have an Azure Load Balancer named LB1."}, {"p": "A user named User1 has the following role assignments:"}, {"p": "User Access Administrator assigned at the scope of LB1"}, {"p": "Virtual Machine Contributor assigned at the resource group level that contains LB1 (this assignment is inherited by LB1)"}, {"p": "Based on these role assignments and their scopes, select the answer choice that completes the following statement correctly."}, {"p": "“User 1 can __________________________.”"}], "options": ["delete LB1", "create a NAT rule for LB1", "assign access permissions to other users for LB1"], "correct": [2], "multi": false, "explanation": [{"p": "assign access permissions to other users for LB1 is the correct answer here. User1 has been assigned the User Access Administrator role on the specific resource, LB1. The User Access Administrator role allows User1 to manage access for other users on that resource, including assigning roles and permissions. This role provides the capability to delegate access without providing permissions to modify the resource itself."}, {"img": "az104/img/t3_image27.webp"}, {"p": "delete LB1 is incorrect because User1 does not have the Owner or Contributor role, which are required to delete resources in Azure. The assigned roles of User Access Administrator and Virtual Machine Contributor (at the resource group level) do not provide delete permissions for the Load Balancer."}, {"p": "create a NAT rule for LB1 is incorrect because configuring or modifying NAT rules on a load balancer requires the Network Contributor or Load Balancer Contributor role. The User Access Administrator role does not allow User1 to configure or modify network settings, and the Virtual Machine Contributor role (inherited at the resource group level) also does not include permissions for network configurations."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G126"}, {"id": "T3-Q55", "test": 3, "num": 55, "domain": "identity", "stem": [{"p": "You have an Azure Load Balancer named LB1."}, {"p": "A user named User1 has the following role assignments:"}, {"p": "User Access Administrator assigned at the scope of LB1"}, {"p": "Virtual Machine Contributor assigned at the resource group level that contains LB1 (this assignment is inherited by LB1)"}, {"p": "Based on these role assignments and their scopes, select the answer choice that completes the following statement correctly."}, {"p": "“User 1 can __________________________ the resource group.”"}], "options": ["delete a virtual machine from", "modify the load balancing rules in", "deploy an Azure Kubernetes Service (AKS) cluster to"], "correct": [0], "multi": false, "explanation": [{"p": "delete a virtual machine from is the correct answer here. User1 has been assigned the Virtual Machine Contributor role at the resource group level (inherited), which grants them permissions to manage virtual machines within that resource group. This includes creating, updating, and deleting virtual machines. Therefore, User1 can delete a virtual machine within the specified resource group. However, this role does not grant permissions to modify load balancing rules or deploy resources unrelated to virtual machines, such as an AKS cluster."}, {"p": "modify the load balancing rules in is incorrect because the Virtual Machine Contributor role does not include permissions to modify network settings or load balancing configurations. To modify load balancing rules, User1 would need the Network Contributor or Load Balancer Contributor role, which is not assigned in this scenario."}, {"p": "deploy an Azure Kubernetes Service (AKS) cluster to is incorrect because deploying an AKS cluster requires additional permissions beyond those granted by the Virtual Machine Contributor role. Typically, the Contributor role or specific permissions related to AKS deployment would be needed to create and manage AKS clusters in the resource group."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G126"}, {"id": "T3-Q56", "test": 3, "num": 56, "domain": "identity", "stem": [{"p": "You have an Azure subscription that follows the resource hierarchy shown in the diagram, which includes a Tenant Root Group, ManagementGroup1, Subscription1, a resource group named RG1, and a virtual machine named VM1."}, {"img": "az104/img/t3_image28.webp"}, {"p": "You create an Azure Policy definition named Policy1."}, {"p": "To which Azure resources in this hierarchy can Policy1 be assigned?"}], "options": ["Subscription1 and RG1 only", "ManagementGroup1 and Subscription1 only", "Tenant Root Group, ManagementGroup1, and Subscription1 only", "Tenant Root Group, ManagementGroup1, Subscription1, and RG1 only", "Tenant Root Group, ManagementGroup1, Subscription1, RG1, and VM1"], "correct": [4], "multi": false, "explanation": [{"p": "Tenant Root Group, ManagementGroup1, Subscription1, RG1, and VM1 is correct because Azure Policy definitions can be assigned at any level in the Azure hierarchy, including the tenant root group, management groups, subscriptions,  resource groups, and individual resource."}, {"p": "It should be noted that policy cannot be applied to an individual resource from the Azure Portal, however, it can be done via Azure CLI or PowerShell."}, {"p": "Since the question dosen't specifically state that the policy should be applied using Azure Portal only, we can safely assume  that using CLI/PowerShell, the policy can also be applied to an individual resource (VM1)."}, {"img": "az104/img/t3_image29.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/governance/policy/concepts/assignment-structure", "https://learn.microsoft.com/en-us/azure/governance/policy/concepts/scope#assignment-scopes", "https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/overview#understand-scope"], "group": "G127"}, {"id": "T3-Q57", "test": 3, "num": 57, "domain": "identity", "stem": [{"p": "You have an Azure subscription that follows the resource hierarchy shown in the diagram, which includes a Tenant Root Group, ManagementGroup1, Subscription1, a resource group named RG1, and a virtual machine named VM1."}, {"img": "az104/img/t3_image28.webp"}, {"p": "You create an Azure Policy definition named Policy1."}, {"p": "Which Azure resources can you specify as exclusions from Policy1?"}], "options": ["VM1 only", "RG1 and VM1 only", "Subscription1, RG1, and VM1 only", "ManagementGroup1, Subscription1, RG1, and VM1 only", "Tenant Root Group, ManagementGroup1, Subscription1, RG1, and VM1"], "correct": [3], "multi": false, "explanation": [{"p": "ManagementGroup1, Subscription1, RG1, and VM1 only is correct because when assigning a policy, you can exclude resources at any level in the hierarchy, including management groups, subscriptions, resource groups, and individual resources. Exclusions are designed to provide flexibility in policy enforcement by allowing specific resources or groups to be excluded from a policy's scope."}, {"p": "Tenant Root Group cannot be excluded from policy assignments. Exclusions are applicable to management groups, subscriptions, resource groups, and individual resources only."}], "refs": ["https://learn.microsoft.com/en-us/azure/governance/policy/concepts/assignment-structure", "https://learn.microsoft.com/en-us/azure/governance/policy/overview"], "group": "G127"}, {"id": "T3-Q58", "test": 3, "num": 58, "domain": "network", "stem": [{"p": "Your Azure environment contains 20 Windows Server virtual machines, an existing network security group called NSG1, and two virtual networks — VNET1 and VNET2 — that are connected through peering."}, {"p": "You intend to deploy an Azure Bastion host using the Basic SKU into VNET1. To ensure the Bastion service is reachable from external networks, you need to update NSG1 to allow incoming traffic from the internet."}, {"p": "When creating the inbound rule in NSG1, which destination port must be allowed?"}], "options": ["22", "443", "3389", "8080"], "correct": [1], "multi": false, "explanation": [{"p": "443 is correct because Azure Bastion uses HTTPS on port 443 for secure communication from the user's browser to the Azure Bastion host. This allows secure RDP or SSH access to virtual machines in the virtual network without exposing these VMs directly to the internet. When deploying Azure Bastion, an inbound rule must be added to the NSG for port 443 to allow this secure connection from the internet to the Bastion host."}, {"img": "az104/img/t3_image30.webp"}, {"p": "22 is incorrect because port 22 is used for SSH connections, but with Azure Bastion, the communication is tunneled over port 443 via HTTPS, making SSH directly over port 22 unnecessary."}, {"p": "3389 is incorrect because port 3389 is used for RDP connections. Azure Bastion tunnels RDP sessions over port 443, eliminating the need to open port 3389 in the NSG."}, {"p": "8080 is incorrect because port 8080 is not used by Azure Bastion for any connection."}], "refs": ["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview"], "group": "G128"}, {"id": "T3-Q59", "test": 3, "num": 59, "domain": "storage", "stem": [{"p": "You have an Azure subscription that includes a user named User1 and a storage account named storage1."}, {"p": "The storage account contains the following resources:"}, {"p": "A blob container named container1"}, {"p": "A file share named folder1"}, {"p": "A table named Table1"}, {"p": "User1 is assigned the following roles on storage1:"}, {"p": "Storage Blob Data Reader"}, {"p": "Storage Table Data Contributor"}, {"p": "Storage File Data SMB Share Contributor"}, {"p": "A shared access signature (SAS) named SAS1 is created for storage1 with the configuration shown in the exhibit."}, {"img": "az104/img/t3_image31.webp"}, {"p": "Which of the following resources can User1 write to by using SAS1?"}], "options": ["Table1 only", "Table1 and container1 only", "folder1 and Table1 only", "folder1 and container1 only", "Table1, folder1, and container1"], "correct": [0], "multi": false, "explanation": [{"p": "Table1 only is correct because the SAS policy shown in the exhibit explicitly grants permissions only for the Table service. This means that when connecting to the storage account using SAS1, the scope of access is restricted to Table-based resources, such as Table1. Other services, such as Blob or File (which include container1 and folder1, respectively), are not included in the SAS policy. Therefore, only Table1 is accessible for all permitted operations, including creating, reading, updating, and deleting (CRUD). Other services will not be visible or accessible when connecting using this SAS key."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/storage-configure-connection-string", "https://learn.microsoft.com/en-us/azure/storage/common/storage-account-keys-manage?tabs=azure-portal"], "group": "G129"}, {"id": "T3-Q60", "test": 3, "num": 60, "domain": "storage", "stem": [{"p": "You have an Azure subscription that includes a user named User1 and a storage account named storage1."}, {"p": "The storage account contains the following resources:"}, {"p": "A blob container named container1"}, {"p": "A file share named folder1"}, {"p": "A table named Table1"}, {"p": "User1 is assigned the following roles on storage1:"}, {"p": "Storage Blob Data Reader"}, {"p": "Storage Table Data Contributor"}, {"p": "Storage File Data SMB Share Contributor"}, {"p": "A shared access signature (SAS) named SAS1 is created for storage1 with the configuration shown in the exhibit."}, {"img": "az104/img/t3_image31.webp"}, {"p": "Which of the following resources can User1 write to by using key1?"}], "options": ["Table1 only", "Table1 and container1 only", "folder1 and Table1 only", "folder1 and container1 only", "Table1, folder1, and container1"], "correct": [4], "multi": false, "explanation": [{"p": "Table1, folder1, and container1 is the correct answer because access via key1 refers to the use of a storage account access key, not a SAS token. Storage account keys act like root-level credentials and grant unrestricted full access to all services and data types in the storage account, including blobs (containers), files (file shares), and tables, regardless of the user's Azure RBAC roles. This means that even though User1 has limited RBAC roles, once they connect using the key, those restrictions are bypassed and they can read/write to all three resources."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/storage-configure-connection-string", "https://learn.microsoft.com/en-us/azure/storage/common/storage-sas-overview"], "group": "G129"}, {"id": "T3-Q61", "test": 3, "num": 61, "domain": "storage", "stem": [{"p": "You have an Azure subscription that includes the storage accounts listed below:"}, {"p": "storage1: StorageV2 with geo-zone-redundant storage (GZRS)"}, {"p": "storage2: BlobStorage with read-access geo-redundant storage (RA-GRS)"}, {"p": "storage3: BlockBlobStorage with zone-redundant storage (ZRS)"}, {"p": "You need to determine which of these storage accounts support Azure Blob lifecycle management policies."}, {"p": "Which storage accounts meet this requirement?"}], "options": ["storage1 only", "storage2 only", "storage1 and storage3 only", "storage2 and storage3 only", "storage1, storage2, and storage3"], "correct": [4], "multi": false, "explanation": [{"p": "storage1, storage2, and storage3 is correct because all three storage account types—StorageV2, BlobStorage, and BlockBlobStorage—support lifecycle management policies for block blobs and append blobs. These policies enable automated tiering, deletion, and management of blob data to optimize costs and resource usage."}, {"img": "az104/img/t3_image32.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/lifecycle-management-overview"], "group": "G130"}, {"id": "T3-Q62", "test": 3, "num": 62, "domain": "storage", "stem": [{"p": "You have an Azure subscription that includes the storage accounts listed below:"}, {"p": "storage1: StorageV2 with geo-zone-redundant storage (GZRS)"}, {"p": "storage2: BlobStorage with read-access geo-redundant storage (RA-GRS)"}, {"p": "storage3: BlockBlobStorage with zone-redundant storage (ZRS)"}, {"p": "You need to determine which of these storage accounts support moving blob data to the Archive access tier."}, {"p": "Which storage accounts satisfy this requirement?"}], "options": ["storage1 only", "storage2 only", "storage1 and storage3 only", "storage2 and storage3 only", "storage1, storage2, and storage3"], "correct": [1], "multi": false, "explanation": [{"p": "storage2 only is correct because only storage accounts configured with LRS (Locally Redundant Storage), GRS (Geo-Redundant Storage), or RA-GRS (Read-Access Geo-Redundant Storage) support moving blob data to the Archive access tier."}, {"img": "az104/img/t3_image33.webp"}, {"p": "storage1 is incorrect because it is a StorageV2 account configured with GZRS (Geo-Zone-Redundant Storage), which does not support the Archive access tier."}, {"p": "storage3 is incorrect because it is a BlockBlobStorage account configured with ZRS (Zone-Redundant Storage), which does not support the Archive access tier."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview"], "group": "G130"}, {"id": "T3-Q63", "test": 3, "num": 63, "domain": "storage", "stem": [{"p": "You have an Azure Storage account named storage1."}, {"p": "You plan to use AzCopy to transfer data into storage1."}, {"p": "You need to determine which storage services within storage1 support data uploads by using AzCopy."}, {"p": "Which storage services should you identify?"}], "options": ["file storage only", "blob storage and file storage only", "file storage and table storage only", "blob storage, table storage, and queue storage only", "blob storage, file storage, table storage, and queue storage"], "correct": [1], "multi": false, "explanation": [{"p": "blob storage and file storage only is correct because AzCopy supports copying data to Blob storage and File storage, but not Table storage or Queue storage. AzCopy is specifically designed for transferring blob and file data efficiently within and across Azure storage accounts."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/storage-use-azcopy-v10?tabs=dnf"], "group": "G131"}, {"id": "T3-Q64", "test": 3, "num": 64, "domain": "storage", "stem": [{"p": "An Azure Storage account stores approximately 10,000 blob objects and is accessed by several different users."}, {"p": "You must implement a solution that restricts visibility so that each user can list and access only certain blobs according to their assigned blob index tags."}, {"p": "What component or configuration should you implement to meet this requirement?"}], "options": ["a stored access policy", "a role assignment condition", "just-in-time (JIT) virtual machine access", "a shared access signature (SAS)"], "correct": [1], "multi": false, "explanation": [{"p": "a role assignment condition is correct because role assignment conditions in Azure can enforce granular access control based on blob index tags. By using conditions in role assignments, you can ensure that users are restricted to viewing only the blobs that match specific index tags. This is an advanced Azure Role-Based Access Control (RBAC) feature designed for fine-grained access control scenarios."}, {"p": "a stored access policy is incorrect because stored access policies are used in conjunction with Shared Access Signatures (SAS) to manage shared access over time, but they cannot enforce access based on blob index tags."}, {"p": "just-in-time (JIT) virtual machine access is incorrect because JIT VM access is designed to provide temporary access to virtual machines and has no relevance to blob access control or index tags."}, {"p": "a shared access signature (SAS) is incorrect because while SAS can provide temporary access to blobs, it cannot enforce blob index tag-based conditions for granular access control."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/conditions-custom-security-attributes", "https://docs.microsoft.com/en-us/azure/role-based-access-control/conditions-overview", "https://docs.microsoft.com/en-us/azure/storage/blobs/storage-blob-index-how-to", "https://docs.microsoft.com/en-us/azure/security-center/just-in-time-explained"], "group": "G132"}, {"id": "T3-Q65", "test": 3, "num": 65, "domain": "network", "stem": [{"p": "In an Azure subscription named Subscription1, there is a resource group named RG1."}, {"p": "Inside RG1, two load balancers are deployed:"}, {"p": "LB1 – configured as an internal load balancer"}, {"p": "LB2 – configured as a public load balancer"}, {"p": "You need to grant a user named Admin1 the ability to add and configure a backend address pool for LB1 by using backend resources in RG1. The solution must follow the principle of least privilege."}, {"p": "To enable Admin1 to create and configure a backend address pool for LB1, which Azure RBAC role should be assigned?"}], "options": ["Contributor role assigned at the LB1 scope", "Network Contributor role assigned at the LB1 scope", "Network Contributor role assigned at the RG1 scope", "Owner role assigned at the LB1 scope"], "correct": [2], "multi": false, "explanation": [{"p": "Network Contributor role assigned at the RG1 scope is correct because adding a backend pool to a load balancer requires permissions not only on the load balancer itself but also on the resources (e.g., virtual machines or virtual machine scale sets) that will be added to the backend pool. The Network Contributor role at the resource group (RG1) level ensures Admin1 has the necessary permissions to manage network resources across RG1, including both the load balancer and the backend pool resources, while still adhering to the principle of least privilege."}, {"p": "Contributor role assigned at the LB1 scope is incorrect because this role grants overly broad permissions beyond just managing network resources. It does not align with the principle of least privilege."}, {"p": "Owner role assigned at the LB1 scope is incorrect because the Owner role allows full control, including assigning roles, which exceeds the requirements for adding a backend pool."}, {"p": "Network Contributor role assigned at the LB1 scope is incorrect because while this role provides permissions to manage the load balancer, it does not include permissions for managing the backend pool's underlying resources (e.g., virtual machines). These additional permissions are required to successfully add resources to the backend pool."}], "refs": ["https://learn.microsoft.com/en-us/azure/load-balancer/backend-pool-management", "https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#network-contributor", "https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview"], "group": "G133"}, {"id": "T3-Q66", "test": 3, "num": 66, "domain": "network", "stem": [{"p": "In an Azure subscription named Subscription1, there is a resource group named RG1."}, {"p": "Inside RG1, two load balancers are deployed:"}, {"p": "LB1 – configured as an internal load balancer"}, {"p": "LB2 – configured as a public load balancer"}, {"p": "You need to grant Admin1 the ability to create a health probe on LB2. The solution must follow the principle of least privilege."}, {"p": "Which Azure RBAC role should assignment be assigned to Admin1 to allow the creation of a health probe on LB2?"}], "options": ["Contributor role assigned at the LB2 scope", "Network Contributor role assigned at the LB2 scope", "Network Contributor role assigned at the RG1 scope", "Owner role assigned at the LB2 scope"], "correct": [1], "multi": false, "explanation": [{"p": "Network Contributor role assigned at the LB2 scope is correct because it adheres to the principle of least privilege. This role provides sufficient permissions to configure and manage health probes on the specific load balancer without granting unnecessary access to the entire resource group or other unrelated network resources. The Network Contributor role at the resource group level ensures Admin1 has the necessary access to both the load balancer and the related network resources, adhering to the principle of least privilege."}, {"p": "Network Contributor role assigned at the RG1 scope is incorrect because assigning this role at the resource group level grants broader permissions than necessary. While it enables the required operations, it goes against the principle of least privilege by providing access to all network resources within the resource group, not just LB2."}, {"p": "Contributor role assigned at the LB2 scope is incorrect because it grants excessive permissions, including access to non-network-related tasks, violating the principle of least privilege."}, {"p": "Owner role assigned at the LB2 scope is incorrect because the Owner role provides full administrative control, including the ability to assign roles, which far exceeds the permissions needed to add a health probe."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#network-contributor", "https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview"], "group": "G133"}, {"id": "T3-Q67", "test": 3, "num": 67, "domain": "monitor", "stem": [{"p": "You have an Azure subscription that includes 10 virtual machines running Windows Server. Each VM hosts a website using IIS, and the Azure Monitor Agent is already installed on all machines."}, {"p": "Your objective is to collect IIS log files from each virtual machine and store them in a Log Analytics workspace."}, {"p": "What should you configure as the initial step?"}], "options": ["a private endpoint", "Diagnostic settings", "a data collection endpoint", "VM insights", "an Azure Monitor Private Link Scope (AMPLS)"], "correct": [1], "multi": false, "explanation": [{"p": "Diagnostic settings is the correct answer because Diagnostic settings in Azure allow you to specify which logs and metrics should be collected from your virtual machines and where they should be sent, such as a Log Analytics workspace. To collect IIS logs from each virtual machine and store them in a Log Analytics workspace, you must configure Diagnostic settings on each virtual machine to enable and route IIS log data appropriately."}, {"p": "a private endpoint is incorrect because private endpoints are used to provide private access to Azure services via a private IP address, which is unrelated to configuring IIS log collection."}, {"p": "a data collection endpoint is incorrect because a Data Collection Endpoint (DCE) is only needed if Azure Monitor Private Links are in use, which is not specified in this scenario."}, {"p": "VM insights is incorrect because VM insights focuses on performance monitoring and dependency mapping for virtual machines. It does not handle IIS log collection and routing to a Log Analytics workspace."}, {"p": "an Azure Monitor Private Link Scope (AMPLS) is incorrect because AMPLS enables private access to Azure Monitor resources using Private Links. It is not a requirement for IIS log collection in this context."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-monitor/essentials/diagnostic-settings", "https://learn.microsoft.com/en-us/azure/azure-monitor/agents/data-collection-iis"], "group": "G134"}, {"id": "T3-Q68", "test": 3, "num": 68, "domain": "compute", "stem": [{"p": "You plan to deploy multiple Azure virtual machines running Windows Server 2022 as part of a virtual machine scale set by using an Azure Resource Manager template."}, {"p": "You must ensure that NGINX is installed and available on all virtual machines after the deployment completes."}, {"p": "Which two options should you use?"}], "options": ["a Desired State Configuration (DSC) extension", "Azure Application Insights", "the Publish-AzVMDscConfiguration cmdlet", "the New-AzConfigurationAssignment cmdlet"], "correct": [0, 2], "multi": true, "explanation": [{"p": "a Desired State Configuration (DSC) extension is the correct answer because the DSC extension allows you to define a desired state configuration for virtual machines in a scale set. This configuration can include installing and configuring software like NGINX on all virtual machines automatically after deployment."}, {"p": "the Publish-AzVMDscConfiguration cmdlet is also correct because this cmdlet is used to upload and publish a DSC configuration script to an Azure storage account. This script can then be used by the DSC extension to ensure NGINX is installed and configured on the virtual machines in the scale set."}, {"p": "Azure Application Insights is incorrect because Application Insights is a monitoring service used to track application performance and detect issues. It does not install or configure software like NGINX on virtual machines."}, {"p": "the New-AzConfigurationAssignment cmdlet is incorrect because this cmdlet is used to assign configurations in Azure Policy for governance, not for installing or configuring software on virtual machines."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-machines/extensions/dsc-overview", "https://learn.microsoft.com/en-us/powershell/module/az.compute/publish-azvmdscconfiguration?view=azps-13.0.0", "https://learn.microsoft.com/en-us/azure/azure-monitor/app/app-insights-overview", "https://learn.microsoft.com/en-us/powershell/module/az.maintenance/new-azconfigurationassignment?view=azps-13.0.0"], "group": "G135"}, {"id": "T3-Q69", "test": 3, "num": 69, "domain": "compute", "stem": [{"p": "You have a subnet named Subnet1 that hosts several Azure virtual machines. A network security group named NSG1 is associated with Subnet1, and NSG1 currently includes only the default security rules."}, {"p": "You must add a rule to NSG1 that blocks the virtual machines in Subnet1 from accessing the Azure portal. At the same time, the virtual machines must continue to have access to other destinations on the internet."}, {"p": "What value should you configure for the Destination setting in the rule?"}], "options": ["Application security group", "IP Addresses", "Any", "Service Tag"], "correct": [3], "multi": false, "explanation": [{"p": "Service Tag is the correct answer because Service Tags simplify network security group (NSG) rules by allowing you to reference a group of IP addresses associated with a specific Azure service. In this scenario, to block access to the Azure portal while still allowing access to other internet resources, you would use the AzureCloud service tag as the Destination in your NSG rule. This ensures that traffic specifically destined for the Azure portal is denied without impacting other internet traffic."}, {"p": "Application security group is incorrect because Application Security Groups (ASGs) are used to group virtual machines within the same virtual network to simplify NSG management. They cannot be used to target Azure services like the Azure portal."}, {"p": "IP Addresses is incorrect because blocking access to the Azure portal using IP addresses would require you to manually identify and maintain the list of Azure portal IP ranges, which is not practical or recommended."}, {"p": "Any is incorrect because setting the destination to \"Any\" would block all internet traffic, including non-Azure-related services, which does not meet the requirement of allowing access to other internet hosts."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/service-tags-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/network-security-group-how-it-works"], "group": "G136"}, {"id": "T3-Q70", "test": 3, "num": 70, "domain": "monitor", "stem": [{"p": "You have two Azure virtual machines named VM1 and VM2, and two Recovery Services vaults named RSV1 and RSV2."}, {"p": "Currently, VM2 is protected by backups stored in RSV1."}, {"p": "You want to configure backups for VM2 by using RSV2 instead."}, {"p": "What action should you perform first?"}], "options": ["From the RSV1 blade, click Backup items and stop the VM2 backup.", "From the RSV2 blade, click Backup. From the Backup blade, select the backup for the virtual machine, and then click Backup.", "From the VM2 blade, click Disaster recovery, click Replication settings, and then select RSV2 as the Recovery Services vault.", "From the RSV1 blade, click Backup Jobs and export the VM2 job."], "correct": [0], "multi": false, "explanation": [{"p": "From the RSV1 blade, click Backup items and stop the VM2 backup is the correct answer because an Azure virtual machine can only be backed up to one Recovery Services vault at a time. To back up VM2 to a different vault (RSV2), you must first stop the existing backup in RSV1. Once the backup is stopped and the backup data is removed, you can reconfigure the backup for VM2 in RSV2."}, {"p": "From the RSV2 blade, click Backup. From the Backup blade, select the backup for the virtual machine, and then click Backup is incorrect because you cannot directly configure VM2 to back up in RSV2 without first stopping the existing backup configuration in RSV1."}, {"p": "From the VM2 blade, click Disaster recovery, click Replication settings, and then select RSV2 as the Recovery Services vault is incorrect because Disaster Recovery settings are for replicating a VM to another region, not for configuring backup to a Recovery Services vault."}, {"p": "From the RSV1 blade, click Backup Jobs and export the VM2 job is incorrect because exporting backup jobs does not change the Recovery Services vault assigned to the virtual machine."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-support-matrix", "https://docs.microsoft.com/en-us/azure/backup/backup-azure-move-recovery-services-vault#must-preserve-previous-backed-up-data", "https://docs.microsoft.com/en-in/azure/backup/backup-azure-vms-first-look-arm"], "group": "G137"}, {"id": "T3-Q71", "test": 3, "num": 71, "domain": "monitor", "stem": [{"p": "You have an Azure subscription named Sub1 with the subscription ID 8f3a1c92-5d47-4b6e-a2f9-71c3d8e5ab40."}, {"p": "You want to create a custom Azure RBAC role named CustomRole1 that meets the following conditions:"}, {"p": "The role can be assigned only at the resource group scope within Sub1."}, {"p": "The role must not allow users to manage access permissions (RBAC) on the resource groups."}, {"p": "The role must allow users to view, create, update, and delete resources inside the resource groups."}, {"p": "You are defining the role by using a JSON definition that includes the assignableScopes and permissions sections."}, {"img": "az104/img/t3_image34.webp"}, {"p": "What value should you specify for Code Segment A in the definition of CustomRole1?"}, {"p": "\"/\""}], "options": ["\"/subscriptions/8f3a1c92-5d47-4b6e-a2f9-71c3d8e5ab40\"", "\"/subscriptions/8f3a1c92-5d47-4b6e-a2f9-71c3d8e5ab40/resourceGroups/\""], "correct": [0], "multi": false, "explanation": [{"p": "\"/subscriptions/8f3a1c92-5d47-4b6e-a2f9-71c3d8e5ab40\" is the correct answer here. The assignableScopes property defines where a custom role can be assigned, and it accepts scopes such as management groups, subscriptions, or specific resource groups. Since Subscription1 has a subscription ID of 8f3a1c92-5d47-4b6e-a2f9-71c3d8e5ab40, and the requirement is to allow assignment of the role only to resource groups within this subscription, the correct assignable scope is the subscription level. This ensures the custom role is available for assignment at the resource group level within that subscription without being overly permissive."}, {"img": "az104/img/t3_image35.webp"}, {"img": "az104/img/t3_image36.webp"}, {"p": "\"/\" is incorrect because the root scope is not supported in custom role definitions. AssignableScopes cannot be set to \"/\", and attempting to do so will result in a validation error."}, {"p": "\"/subscriptions/8f3a1c92-5d47-4b6e-a2f9-71c3d8e5ab40/resourceGroups\" is incorrect because this is not a valid scope. The string \"resourceGroups\" is a collection placeholder, and not a valid scope by itself. Using it will result in a validation error such as:"}, {"p": "\"Validation error: Invalid scope: /subscriptions/<SubscriptionID>/resourceGroups\"."}, {"p": "Additionally, the question does not reference any specific resource group. It refers broadly to “resource groups” within the subscription, and therefore the assignable scope must be set at the subscription level."}, {"img": "az104/img/t3_image37.webp"}], "refs": ["https://docs.microsoft.com/en-us/azure/role-based-access-control/custom-roles", "https://docs.microsoft.com/en-us/azure/role-based-access-control/role-definitions#assignablescopes"], "group": "G138"}, {"id": "T3-Q72", "test": 3, "num": 72, "domain": "monitor", "stem": [{"p": "You have an Azure subscription named Sub1 with the subscription ID 8f3a1c92-5d47-4b6e-a2f9-71c3d8e5ab40."}, {"p": "You want to create a custom Azure RBAC role named CustomRole1 that meets the following conditions:"}, {"p": "The role can be assigned only at the resource group scope within Sub1."}, {"p": "The role must not allow users to manage access permissions (RBAC) on the resource groups."}, {"p": "The role must allow users to view, create, update, and delete resources inside the resource groups."}, {"p": "You are defining the role by using a JSON definition that includes the assignableScopes and permissions sections."}, {"img": "az104/img/t3_image34.webp"}, {"p": "What value should you specify for Code Segment B in the definition of CustomRole1?"}], "options": ["\"Microsoft.Authorization/\"", "\"Microsoft.Resources/\"", "\"Microsoft.Security/*\""], "correct": [0], "multi": false, "explanation": [{"p": "\"Microsoft.Authorization/\" is the correct answer here. In the context of custom RBAC role definitions, the \"notActions\" element (Dropdown 2) is used to explicitly deny certain management operations, even if the \"actions\" list includes a wildcard like \"*\". In this scenario, the custom role CustomRole1 must allow full access to view, create, modify, and delete resources within resource groups, but it must prevent the user from managing access permissions (i.e., prevent role assignments)."}, {"p": "Role assignment and access control operations in Azure are managed through the Microsoft.Authorization namespace. Therefore, to block permission management, you need to specify \"Microsoft.Authorization/\" in the \"notActions\" array. This removes the ability to read, create, or delete role assignments, while still allowing other actions."}, {"img": "az104/img/t3_image38.webp"}, {"p": "\"Microsoft.Resources/\" is incorrect because this namespace is used for general resource management tasks like creating and managing resource groups or deployments, not for managing access control. Including it in \"notActions\" would block legitimate resource operations that the role should be allowed to perform."}, {"p": "\"Microsoft.Security/*\" is incorrect because it relates to security center operations such as policy management, security recommendations, and alerts. It is not relevant to access control and does not affect permissions related to RBAC."}], "refs": ["https://docs.microsoft.com/en-us/azure/role-based-access-control/custom-roles", "https://docs.microsoft.com/en-us/azure/role-based-access-control/resource-provider-operations#microsoftresources", "https://docs.microsoft.com/en-us/azure/role-based-access-control/resource-provider-operations#microsoftsecurity"], "group": "G138"}, {"id": "T3-Q73", "test": 3, "num": 73, "domain": "compute", "stem": [{"p": "You have an Azure web app named App1 that uses deployment slots, as shown below:"}, {"p": "webapp1-prod -> Production"}, {"p": "webapp1-test -> Staging"}, {"p": "You validate multiple updates to App1 in the webapp1-test slot."}, {"p": "After completing testing, you create a backup of App1."}, {"p": "You then swap the webapp1-test slot with webapp1-prod, after which the application starts showing performance problems."}, {"p": "You must roll back App1 to the earlier, stable version in the shortest possible time."}, {"p": "What action should you take?"}], "options": ["Restore App1 from the backup.", "Create a clone of App1.", "Redeploy the application to App1.", "Swap the deployment slots again."], "correct": [3], "multi": false, "explanation": [{"p": "Swap the deployment slots again is the correct answer here. Azure App Service deployment slots allow you to deploy and test changes in a staging slot (in this case, webapp1-test) and then swap the staging slot with the production slot (webapp1-prod) when ready. When a swap is performed, the content and configuration of the slots are exchanged, allowing for a quick rollback if needed."}, {"p": "Since you already swapped the test slot into production and discovered performance issues, the fastest way to revert is to swap the slots again. This will return the original production version (which is now in the test slot) back to its place, restoring the last working state almost instantly and with zero downtime."}, {"img": "az104/img/t3_image39.webp"}, {"p": "Restore App1 from the backup is incorrect because although it can restore the app to a previous state, it is a slower operation and involves data loss risk and manual effort, making it less ideal for quick recovery."}, {"p": "Create a clone of App1 is incorrect because cloning creates a new app instance, which is not a recovery mechanism and would not affect the current deployment state of App1."}, {"p": "Redeploy the application to App1 is incorrect because this would require rebuilding and redeploying the application code, which takes more time and may not exactly match the last known good state."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/deploy-staging-slots"], "group": "G139"}, {"id": "T3-Q74", "test": 3, "num": 74, "domain": "monitor", "stem": [{"p": "You have a pay-as-you-go Azure subscription with the following virtual machines:"}, {"p": "VM1 in resource group RG1, costing 20 euros per day"}, {"p": "VM2 in resource group RG2, costing 30 euros per day"}, {"p": "You create the budget shown in the following exhibit."}, {"img": "az104/img/t3_image40.webp"}, {"p": "The budget is set up with alert thresholds at 50%, 70%, and 100%, each linked to different action groups."}, {"p": "The action group AG1 contains only the user admin@apexcore.com."}, {"p": "Based on this configuration, complete the following statement:"}, {"p": "“When VM1 and VM2 reach the maximum budget limit, ___________________________________.”"}], "options": ["Both VM1 and VM2 are automatically shut down.", "VM1 and VM2 continue running.", "VM1 is stopped, while VM2 continues to run."], "correct": [1], "multi": false, "explanation": [{"p": "VM1 and VM2 continue running is the correct answer here. Azure budgets are a monitoring and alerting tool only. They do not enforce or take automatic action such as shutting down resources. In the case study:"}, {"p": "Budget1 is scoped to Resource Group RG1, which contains VM1."}, {"p": "VM2, which is in RG2, is not within the scope of the budget and is therefore not tracked or managed by this budget."}, {"p": "Even when the budget is fully consumed (100%), the configured action groups (AG1, AG2, AG3) only send notifications (via Email, SMS, or Azure app), but do not stop or deallocate any virtual machines."}, {"p": "Therefore, when both VM1 and VM2 reach their maximum cost, they continue to run, and no automatic shutdown occurs."}], "refs": ["https://learn.microsoft.com/en-us/azure/cost-management-billing/costs/tutorial-acm-create-budgets", "https://learn.microsoft.com/en-us/azure/cost-management-billing/manage/cost-management-budget-scenario", "https://learn.microsoft.com/en-us/azure/cost-management-billing/costs/cost-mgt-alerts-monitor-usage-spending"], "group": "G140"}, {"id": "T3-Q75", "test": 3, "num": 75, "domain": "monitor", "stem": [{"p": "You have a pay-as-you-go Azure subscription with the following virtual machines:"}, {"p": "VM1 in resource group RG1, costing 20 euros per day"}, {"p": "VM2 in resource group RG2, costing 30 euros per day"}, {"p": "You create the budget shown in the following exhibit."}, {"img": "az104/img/t3_image40.webp"}, {"p": "The budget is set up with alert thresholds at 50%, 70%, and 100%, each linked to different action groups."}, {"p": "The action group AG1 contains only the user admin@apexcore.com."}, {"p": "Based on this configuration, complete the following statement:"}, {"p": "“Given the existing usage costs of the virtual machines, _________________________.”"}], "options": ["no email notifications will be sent each month", "one email notification will be sent each month", "two email notifications will be sent each month", "three email notifications will be sent each month"], "correct": [1], "multi": false, "explanation": [{"p": "one email notification will be sent each month is the correct answer here. This is a common area of confusion, so let's clarify it step by step to avoid misinterpretation."}, {"p": "In the provided scenario:"}, {"p": "VM1 is the only virtual machine within the scope of Budget1 (since VM1 is in RG1, and the budget is scoped to RG1)."}, {"p": "VM1 costs €20 per day, which totals approximately €600 per month."}, {"p": "The budget thresholds are:"}, {"p": "50% of €1,000 → triggers Action Group AG1 (configured to send 1 email)"}, {"p": "70% of €1,000 → triggers AG2 (sends 1 SMS)"}, {"p": "100% of €1,000 → triggers AG3 (sends 1 Azure app notification)"}, {"p": "At €600, only the 50% threshold is crossed, which triggers AG1."}, {"p": "Why it’s not two emails:"}, {"p": "You may mistakenly think that:"}, {"p": "One email is sent because AG1 is triggered"}, {"p": "Another email is sent because admin@apexcore.com is listed as an alert recipient"}, {"p": "This is not correct."}, {"p": "In Azure Budgets, email alerts are sent only via Action Groups. The person listed (e.g., admin@apexcore.com) in the budget configuration is part of the Action Group (AG1) that is associated with the 50% threshold. They are not receiving a second, separate notification outside the Action Group."}, {"p": "So even though the name appears in the recipient list, it does not represent an additional notification beyond what AG1 is configured to send."}], "refs": ["https://learn.microsoft.com/en-us/azure/cost-management-billing/costs/tutorial-acm-create-budgets", "https://learn.microsoft.com/en-us/azure/cost-management-billing/manage/cost-management-budget-scenario", "https://learn.microsoft.com/en-us/azure/cost-management-billing/costs/cost-mgt-alerts-monitor-usage-spending"], "group": "G140"}, {"id": "T3-Q76", "test": 3, "num": 76, "domain": "compute", "stem": [{"p": "You have an Azure subscription that contains the following App Service plans:"}, {"p": "ASP1 runs on Linux and uses the Basic B1 pricing tier."}, {"p": "ASP2 runs on Windows and uses the Standard S1 pricing tier."}, {"p": "ASP3 runs on Linux and uses the Premium v3 pricing tier."}, {"p": "You plan to create an additional App Service plan with these settings:"}, {"p": "Name: ASP4"}, {"p": "Operating system: Windows"}, {"p": "Pricing tier: Premium v3"}, {"p": "You need to determine which of the App Service plans support rule-based scale-out."}, {"p": "Which App Service plans should you identify?"}], "options": ["ASP4 only", "ASP2 and ASP4 only", "ASP2, ASP3, and ASP4 only", "ASP1, ASP2, ASP3, and ASP4"], "correct": [2], "multi": false, "explanation": [{"p": "ASP2, ASP3, and ASP4 only is correct. The question asks which App Service plans support rule-based scale out, which refers specifically to autoscale—the ability to automatically increase or decrease the number of instances based on predefined rules, such as CPU usage, memory load, or a schedule."}, {"p": "According to Microsoft documentation:"}, {"p": "Autoscale is not supported in the Basic (B1) pricing tier. While Basic plans support manual scale-out (up to 3 instances), they do not support rule-based scaling."}, {"p": "Standard (S1) and Premium v3 plans do support autoscale, allowing automatic instance management based on defined rules and schedules."}, {"p": "Therefore, ASP2, ASP3, and ASP4 all support rule-based scale out, while ASP1 does not."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-monitor/autoscale/autoscale-get-started", "https://learn.microsoft.com/en-us/azure/app-service/manage-automatic-scaling?tabs=azure-portal", "https://learn.microsoft.com/en-us/azure/app-service/manage-scale-up", "https://learn.microsoft.com/en-us/azure/azure-monitor/autoscale/autoscale-overview"], "group": "G141"}, {"id": "T3-Q77", "test": 3, "num": 77, "domain": "compute", "stem": [{"p": "You have an Azure subscription that contains the following App Service plans:"}, {"p": "ASP1 runs on Linux and uses the Basic B1 pricing tier."}, {"p": "ASP2 runs on Windows and uses the Standard S1 pricing tier."}, {"p": "ASP3 runs on Linux and uses the Premium v3 pricing tier."}, {"p": "You plan to create an additional App Service plan with these settings:"}, {"p": "Name: ASP4"}, {"p": "Operating system: Windows"}, {"p": "Pricing tier: Premium v3"}, {"p": "You need to determine which of the App Service plans support zone redundancy."}, {"p": "Which App Service plans should you identify?"}], "options": ["ASP4 only", "ASP2 and ASP4 only", "ASP2, ASP3, and ASP4 only", "ASP1, ASP2, ASP3, and ASP4"], "correct": [0], "multi": false, "explanation": [{"p": "ASP4 only is the correct answer here. Azure App Service supports zone redundancy only on the Premium v2 and Premium v3 pricing tiers. This makes ASP3 and ASP4 eligible, since both are using the Premium v3 tier."}, {"p": "But since the correct combination (ASP3 and ASP4 only) is not available among the answer choices, we need to select the best possible correct option from the list."}, {"p": "Among the choices provided:"}, {"p": "ASP4 only is the most accurate, because while it omits ASP3, it is the only option that exclusively lists a supported plan."}, {"p": "Therefore, ASP4 only is the best and most appropriate answer based on the available options."}], "refs": ["https://learn.microsoft.com/en-us/azure/reliability/reliability-app-service?pivots=free-shared-basic#regions-supported", "https://learn.microsoft.com/en-us/azure/app-service/overview-hosting-plans#premiumv3-pricing-tier"], "group": "G141"}, {"id": "T3-Q78", "test": 3, "num": 78, "domain": "network", "stem": [{"p": "You have an Azure subscription with a virtual network named VNet1."}, {"p": "VNet1 includes four subnets named Gateway, Perimeter, NVA, and Production."}, {"p": "The NVA subnet hosts two network virtual appliances (NVAs)."}, {"p": "These NVAs are used to inspect network traffic flowing between the Perimeter subnet and the Production subnet."}, {"p": "You need to deploy an Azure Load Balancer in front of the NVAs."}, {"p": "The solution must meet the following conditions:"}, {"p": "The NVAs must operate in an active-active setup with automatic failover."}, {"p": "Traffic must be load balanced to two different services in the Production subnet, and each service uses a different IP address."}, {"p": "Which three actions should you take?"}], "options": ["Add a frontend IP configuration, two backend pools, and a health probe", "Add a frontend IP configuration, a backend pool, and a health probe", "Deploy a basic load balancer", "Deploy a standard load balancer", "Add two load balancing rules that have HA Ports enabled and Floating IP disabled", "Add two load balancing rules that have HA Ports and Floating IP enabled"], "correct": [0, 3, 5], "multi": true, "explanation": [{"p": "Add a frontend IP configuration, two backend pools, and a health probe is correct because the requirement involves load balancing traffic to two services on different IP addresses in the Production subnet. This necessitates two separate backend pools, each associated with one of the services. A frontend IP configuration is needed to receive incoming traffic, and a health probe is essential to determine the availability of the NVAs in the backend pool for failover."}, {"p": "Deploy a standard load balancer is correct because only the Standard SKU load balancer supports advanced features like HA Ports, Floating IP, and availability zones, all of which are needed for this high availability active-active NVA setup. The Basic SKU does not support multiple backend pools or advanced configurations required in this scenario."}, {"p": "Add two load balancing rules that have HA Ports and Floating IP enabled is correct because:"}, {"p": "HA Ports allows the load balancer to listen on all ports for the services, ensuring full connectivity through the NVAs."}, {"p": "Floating IP (also known as Direct Server Return) must be enabled for scenarios that involve high availability and active-active NVAs, because it ensures the return path of packets doesn't interfere with source NAT."}, {"p": "Add a frontend IP configuration, a backend pool, and a health probe is incorrect because a single backend pool cannot load balance traffic to two distinct IP addresses (services). This setup lacks the isolation needed for managing traffic across both services."}, {"p": "Deploy a basic load balancer is incorrect because Basic SKU does not support HA Ports or multiple backend pools, which are essential for this solution."}, {"p": "Add two load balancing rules that have HA Ports enabled and Floating IP disabled is incorrect because disabling Floating IP prevents the correct routing behavior necessary for high availability and direct server return, which is needed in an active-active NVA configuration."}], "refs": ["https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview", "https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-ha-ports-overview", "https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-floating-ip", "https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-outbound-connections#scenarios-for-floating-ip-enabled", "https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-multivip-overview"], "group": "G142"}, {"id": "T3-Q79", "test": 3, "num": 79, "domain": "network", "stem": [{"p": "You have the following Azure virtual networks configured:"}, {"p": "VNet1"}, {"p": "Address space: 10.11.0.0/16"}, {"p": "Subnet: 10.11.0.0/17"}, {"p": "Resource group Azure region: West US"}, {"p": "VNet2"}, {"p": "Address space: 10.11.0.0/17"}, {"p": "Subnet: 10.11.0.0/25"}, {"p": "Resource group Azure region: West US"}, {"p": "VNet3"}, {"p": "Address space: 10.10.0.0/22"}, {"p": "Subnet: 10.10.1.0/24"}, {"p": "Resource group Azure region: East US"}, {"p": "VNet4"}, {"p": "Address space: 192.168.16.0/22"}, {"p": "Subnet: 192.168.16.0/24"}, {"p": "Resource group Azure region: North Europe"}, {"p": "You want to configure virtual network peering for VNet1."}, {"p": "Which of the listed virtual networks can be peered with VNet1?"}], "options": ["VNet2 only", "VNet3 and VNet4 only", "VNet2 and VNet3 only", "VNet2, VNet3, and VNet4"], "correct": [1], "multi": false, "explanation": [{"p": "VNet3 and VNet4 only is the correct answer here. To peer virtual networks in Azure, one of the main requirements is that the address spaces must not overlap. In the case of VNet1 (10.11.0.0/16):"}, {"p": "VNet2 (10.11.0.0/17) has an address space that overlaps with VNet1. Peering is not allowed in this case due to the overlapping IP ranges, even though it’s in the same region."}, {"p": "VNet3 (10.10.0.0/22) has a non-overlapping address space and is in a different region (East US), which is still supported via global virtual network peering."}, {"p": "VNet4 (192.168.16.0/22) also has a non-overlapping address space and is in North Europe, which again supports global VNet peering."}, {"p": "Therefore, only VNet3 and VNet4 can be peered with VNet1."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-manage-peering"], "group": "G143"}, {"id": "T3-Q80", "test": 3, "num": 80, "domain": "compute", "stem": [{"p": "You have two Azure subscriptions named Sub1 and Sub2."}, {"p": "In Sub1, there is a virtual machine named VM1 and a storage account named storage1."}, {"p": "The virtual machine VM1 is associated with the following resources:"}, {"p": "Disk1, which is the operating system disk for VM1"}, {"p": "NetInt1, which is the network interface attached to VM1"}, {"p": "VNet1, which is the virtual network that VM1 connects to"}, {"p": "You need to move VM1 from Sub1 to Sub2."}, {"p": "Which of the associated resources must you move to Sub2 to complete this task?"}], "options": ["VM1, Disk1, and NetInt1 only", "VM1, Disk1, and VNet1 only", "VM1, Disk1, and storage1 only", "VM1, Disk1, NetInt1, and VNet1"], "correct": [3], "multi": false, "explanation": [{"p": "VM1, Disk1, NetInt1, and VNet1 is the correct answer here. When you move a virtual machine (VM1) to another subscription, all its associated dependent resources must be moved as well. This includes the OS disk (Disk1), the network interface (NetInt1), and the virtual network (VNet1). Azure requires that all dependent resources are part of the move operation to ensure the VM remains functional in the target subscription. If any dependency, like the NIC or virtual network, is left behind, the VM will lose connectivity or fail validation during the move."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/move-resource-group-and-subscription#virtual-machines", "https://learn.microsoft.com/en-us/azure/virtual-machines/network-overview"], "group": "G144"}, {"id": "T3-Q81", "test": 3, "num": 81, "domain": "identity", "stem": [{"p": "You manage two Azure subscriptions: Subscription1 and Subscription2."}, {"p": "In Subscription1, the following resource groups exist:"}, {"p": "RG1 – Region: West Europe – Lock: None"}, {"p": "RG2 – Region: West Europe – Lock: Read-only"}, {"p": "The resource group RG1 contains a web application named App1, which is deployed in the West Europe region."}, {"p": "In Subscription2, the following resource groups are configured:"}, {"p": "RG3 – Region: North Europe – Lock: Delete"}, {"p": "RG4 – Region: Central US – Lock: None"}, {"p": "True or False:"}, {"p": "“App1 can be moved to RG2.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer because RG2 has a Read Only lock applied. When a resource group is locked with Read Only, you cannot add or move any resources into it. This type of lock prevents all write operations, including the action of moving a resource (such as App1) into the locked resource group. Even though App1 and RG2 are in the same region and subscription, the lock on RG2 blocks the move."}, {"img": "az104/img/t3_image41.webp"}, {"img": "az104/img/t3_image42.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/lock-resources?tabs=json", "https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/move-resource-group-and-subscription"], "group": "G145"}, {"id": "T3-Q82", "test": 3, "num": 82, "domain": "identity", "stem": [{"p": "You manage two Azure subscriptions: Subscription1 and Subscription2."}, {"p": "In Subscription1, the following resource groups exist:"}, {"p": "RG1 – Region: West Europe – Lock: None"}, {"p": "RG2 – Region: West Europe – Lock: Read-only"}, {"p": "The resource group RG1 contains a web application named App1, which is deployed in the West Europe region."}, {"p": "In Subscription2, the following resource groups are configured:"}, {"p": "RG3 – Region: North Europe – Lock: Delete"}, {"p": "RG4 – Region: Central US – Lock: None"}, {"p": "True or False:"}, {"p": "“App1 can be moved to RG3.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer because Azure allows moving supported resources, such as an App Service web app, between resource groups and even between subscriptions within the same tenant. When a resource is moved between resource groups or subscriptions, the resource itself does not move to another region. Only the Azure Resource Manager metadata changes, and the resource continues to run in its original region."}, {"p": "In this scenario, App1 is deployed in the West Europe region, and moving it to RG3 does not change its location. Even though RG3 is associated with North Europe, resource groups can contain resources from different regions, so this does not prevent the move."}, {"p": "Additionally, if the web app depends on other resources, such as an App Service Plan, those dependent resources must be moved together in the same operation."}, {"p": "The Delete lock on RG3 does not block the move because a delete lock only prevents deletion of the resource group or its resources. It does not prevent adding or moving resources into the resource group."}, {"p": "Therefore, App1 can be moved to RG3, making the statement True."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/move-support-resources", "https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/lock-resources"], "group": "G145"}, {"id": "T3-Q83", "test": 3, "num": 83, "domain": "identity", "stem": [{"p": "You manage two Azure subscriptions: Subscription1 and Subscription2."}, {"p": "In Subscription1, the following resource groups exist:"}, {"p": "RG1 – Region: West Europe – Lock: None"}, {"p": "RG2 – Region: West Europe – Lock: Read-only"}, {"p": "The resource group RG1 contains a web application named App1, which is deployed in the West Europe region."}, {"p": "In Subscription2, the following resource groups are configured:"}, {"p": "RG3 – Region: North Europe – Lock: Delete"}, {"p": "RG4 – Region: Central US – Lock: None"}, {"p": "True or False:"}, {"p": "“App1 can be moved to RG4.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer because App1 can be moved to RG4, which is located in the Central US region, provided that RG4 does not contain any existing App Service resources such as web apps, App Service plans, or TLS/SSL certificates."}, {"p": "Although App1 is in West Europe, moving an app across resource groups or subscriptions does not change the region of the app. The app retains its original region (West Europe) after the move. The metadata such as resource group or subscription may change, but the physical location of the app stays the same."}, {"p": "There is no lock on RG4, so it won’t block the operation."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/manage-move-across-resources", "https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/move-support-resources"], "group": "G145"}, {"id": "T3-Q84", "test": 3, "num": 84, "domain": "identity", "stem": [{"p": "You have an Azure subscription that contains a virtual machine named VM1."}, {"p": "The virtual machine has two disks attached:"}, {"p": "An operating system disk named Disk1"}, {"p": "A data disk named Disk2"}, {"p": "You are required to back up only Disk2 by using Azure Backup."}, {"p": "Which three actions should you perform in sequence?"}, {"p": "ACTIONS"}, {"p": "Create a backup policy and configure the backup."}, {"p": "Create a Recovery Services vault."}, {"p": "Create an Azure Backup vault."}, {"p": "Configure a managed identity."}, {"p": "Delegate permissions for the vault."}], "options": ["1-3-4", "4-3-1", "3-1-4", "2-1-4", "4-2-1"], "correct": [2], "multi": false, "explanation": [{"p": "3-1-4 is the correct sequence of actions."}, {"p": "(Action 3) Create an Azure Backup vault is correct. For Azure Disk Backup (as opposed to full VM backup), you use an Azure Backup vault, which is a specific vault type designed for backing up individual managed disks. This is different from a Recovery Services vault, which is used for broader scenarios like VM, SQL, and file backups."}, {"p": "(Action 1) Create a backup policy and configure the backup is correct. After the vault is created, you define a backup policy that dictates the schedule and retention for the disk backup. You then associate Disk2 with this policy."}, {"p": "(Action 4) Configure a managed identity is correct. Azure Disk Backup uses Azure RBAC and managed identities for access. You must configure a user-assigned managed identity with appropriate roles (like Disk Backup Reader) to allow the vault to access and back up Disk2."}, {"p": "(Action 2) Create a Recovery Services vault is incorrect. This is used for VM-level backup and is not applicable to Azure Disk Backup, which requires a Backup vault."}, {"p": "(Action 5) Delegate permissions for the vault is incorrect. Disk Backup uses managed identity and RBAC instead of manual permission delegation. You assign roles to the managed identity instead of explicitly delegating permissions."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-managed-disks"], "group": "G146"}, {"id": "T3-Q85", "test": 3, "num": 85, "domain": "monitor", "stem": [{"p": "You have deployed Azure virtual machines across three different Azure regions."}, {"p": "In each region:"}, {"p": "There is one virtual network."}, {"p": "Each virtual network contains multiple subnets."}, {"p": "All virtual networks are connected using full-mesh VNet peering."}, {"p": "A user reports that they are unable to connect over TCP port 33000 from a virtual machine in one region to a virtual machine in another region."}, {"p": "Which two options can you use to investigate and troubleshoot this connectivity issue?"}], "options": ["Azure Monitor Network Insights", "IP flow verify", "effective security rules", "Azure Virtual Network Manager", "Connection troubleshoot"], "correct": [1, 4], "multi": true, "explanation": [{"p": "IP flow verify is correct because it allows you to test whether traffic is allowed to or from a virtual machine based on NSG (Network Security Group) rules. It specifically helps in identifying whether a particular port (like 33000) is blocked or allowed, which is essential for troubleshooting connectivity between VMs."}, {"p": "Connection troubleshoot is correct because it helps diagnose issues with connectivity between two endpoints. It checks DNS resolution, network latency, and whether TCP connections (like on port 33000) can be established, making it ideal for this scenario involving cross-region VM communication."}, {"p": "Azure Monitor Network Insights is incorrect because it gives you a high-level view of the health and topology of your network resources, but it doesn't perform port-level diagnostics or simulate connection attempts."}, {"p": "effective security rules is incorrect because it shows the final set of NSG rules applied to a NIC or subnet but doesn't actively test whether a specific port is blocked or allowed. It's useful for analysis, but not direct diagnostics."}, {"p": "Azure Virtual Network Manager is incorrect because it's used for centralized network management and policy enforcement across VNets, not for diagnosing connectivity issues like blocked ports."}], "refs": ["https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-ip-flow-verify-overview", "https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-connectivity-overview"], "group": "G147"}, {"id": "T3-Q86", "test": 3, "num": 86, "domain": "storage", "stem": [{"p": "You have an Azure subscription called Subscription1 that includes two virtual machines named VM1 and VM2, both running Windows Server 2016."}, {"p": "VM1 is protected with Azure Backup, configured to run daily backups without using the Azure Backup agent."}, {"p": "VM1 has been compromised by ransomware that encrypts data."}, {"p": "You need to restore data from the most recent backup of VM1."}, {"p": "To which of the following targets can you perform a file-level recovery for VM1?"}], "options": ["VM1 only", "VM1 or a new Azure virtual machine only", "VM1 and VM2 only", "A new Azure virtual machine only", "Any Windows computer that has Internet connectivity"], "correct": [4], "multi": false, "explanation": [{"p": "Any Windows computer that has Internet connectivity is the correct answer because Azure Backup supports file-level recovery from a VM backup even when the Azure Backup agent is not used. The recovery is performed by downloading and running a script provided by the portal, which mounts the backup snapshot as a virtual drive. This can be done on any supported Windows machine with internet access, allowing files to be copied to any desired location."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-azure-restore-files-from-vm", "https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-introduction"], "group": "G148"}, {"id": "T3-Q87", "test": 3, "num": 87, "domain": "storage", "stem": [{"p": "You have an Azure subscription called Subscription1 that includes two virtual machines named VM1 and VM2, both running Windows Server 2016."}, {"p": "VM1 is protected with Azure Backup, configured to run daily backups without using the Azure Backup agent."}, {"p": "VM1 has been compromised by ransomware that encrypts data."}, {"p": "You need to restore data from the most recent backup of VM1."}, {"p": "To which location can you restore the backup?"}], "options": ["VM1 only", "VM1 or a new Azure virtual machine only", "VM1 and VM2 only", "Any Windows computer that has Internet connectivity"], "correct": [1], "multi": false, "explanation": [{"p": "VM1 or a new Azure virtual machine only is the correct answer because when Azure Backup is used to back up a VM without using the Azure Backup agent, it performs a full image-level backup of the virtual machine. In the event of data loss (e.g., ransomware), the entire VM can be restored either to the original VM (VM1) or as a new Azure virtual machine from the latest recovery point. This method does not support file-level recovery to arbitrary machines unless the MARS agent is used, which is not applicable in this scenario."}, {"p": "VM1 only is incorrect because Azure Backup allows restoring the VM to a new VM as well, not just to the original one."}, {"p": "VM1 and VM2 only is incorrect because Azure Backup does not allow restoring a VM backup to a different existing VM like VM2. Restores are limited to the original VM or a new one."}, {"p": "Any Windows computer that has Internet connectivity is incorrect because that type of file-level restore is only supported when using the Azure Backup agent (MARS) or the System Center DPM/MABS, which is not being used in this scenario."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-azure-arm-restore-vms", "https://learn.microsoft.com/en-us/azure/backup/backup-support-matrix-iaas", "https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-introduction"], "group": "G148"}, {"id": "T3-Q88", "test": 3, "num": 88, "domain": "storage", "stem": [{"p": "You have an Azure subscription that contains the following resources:"}, {"img": "az104/img/t3_image43.webp"}, {"p": "You configure Azure Site Recovery to replicate VM1 from East US to West US."}, {"p": "You then initiate a test failover and choose VNET2 as the destination virtual network."}, {"p": "After the test failover completes, to which subnet in VNET2 will the test instance of VM1 be connected?"}], "options": ["RecoverySubnetB", "DemoSubnet1", "TestSubnet1", "RecoverySubnetA"], "correct": [1], "multi": false, "explanation": [{"p": "DemoSubnet1 is the correct answer because when performing a test failover in Azure Site Recovery and no matching subnet name exists in the target virtual network (VNET2), the test virtual machine is automatically connected to the first subnet in alphabetical order. In this case, the source subnet is Subnet2, which does not exist in VNET2. Among the available subnets in VNET2—DemoSubnet1, RecoverySubnetA, RecoverySubnetB, and TestSubnet1—the one that comes first alphabetically is DemoSubnet1, so the test VM is connected there."}, {"p": "RecoverySubnetA is incorrect because although it contains “Recovery” in the name, it comes after DemoSubnet1 alphabetically."}, {"p": "RecoverySubnetB is incorrect because it is not the first subnet in alphabetical order and does not match the source subnet name."}, {"p": "TestSubnet1 is incorrect because ASR does not prioritize subnets based on naming conventions like “Test”. It only looks for an exact match or falls back to the first subnet in alphabetical order."}], "refs": ["https://learn.microsoft.com/en-us/azure/site-recovery/azure-to-azure-network-mapping#specify-a-subnet"], "group": "G149"}, {"id": "T4-Q1", "test": 4, "num": 1, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant named apexcore.com."}, {"p": "There are two external partner organizations: ironclad.com and bluerock.com."}, {"p": "Only ironclad.com is configured as a connected organization in Microsoft Entra."}, {"p": "You create an access package as shown in the below exhibit."}, {"img": "az104/img/t4_image1.webp"}, {"p": "The external user lifecycle settings are configured so that when an external user loses their last access package assignment:"}, {"p": "The user is blocked from signing in."}, {"p": "The user is removed from the directory after 30 days."}, {"p": "True or False:"}, {"p": "“Users from bluerock.com can be assigned to package1.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer here. The access package package1 is configured to allow access requests from \"All configured connected organizations.\" Based on the information given, only ironclad.com is set up as a connected organization. Since bluerock.com is not configured as a connected organization, users from bluerock.com are not eligible to be assigned to package1."}], "refs": ["https://learn.microsoft.com/en-us/azure/active-directory/governance/entitlement-management-access-package-resources#add-a-group-or-team-resource-role", "https://learn.microsoft.com/en-us/azure/active-directory/governance/entitlement-management-external-users"], "group": "G150"}, {"id": "T4-Q2", "test": 4, "num": 2, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant named apexcore.com."}, {"p": "There are two external partner organizations: ironclad.com and bluerock.com."}, {"p": "Only ironclad.com is configured as a connected organization in Microsoft Entra."}, {"p": "You create an access package as shown in the below exhibit."}, {"img": "az104/img/t4_image1.webp"}, {"p": "The external user lifecycle settings are configured so that when an external user loses their last access package assignment:"}, {"p": "The user is blocked from signing in."}, {"p": "The user is removed from the directory after 30 days."}, {"p": "True or False:"}, {"p": "“After the 365-day assignment period ends, users from ironclad.com will be removed from Group1.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct. Group1 is included in package1 as a resource, with users receiving the Member role. The access package assignment is configured to expire after 365 days."}, {"p": "When a user's access package assignment expires, Microsoft Entra entitlement management removes the access granted through that package. Because membership in Group1 is provided through package1, users are removed from Group1 when the assignment expires, unless they have another access package assignment that also grants membership in Group1."}, {"p": "The external user lifecycle setting that specifies removal after an additional 30 days applies to the user's guest account in the Microsoft Entra directory, not to their Group1 membership. Therefore, the users are removed from Group1 when their access package assignment expires after 365 days, while their guest accounts can remain in the directory until the configured lifecycle removal occurs."}, {"p": "Timeline:"}, {"p": "Day 365: assignment expires, user is removed from Group1, sign-in gets blocked"}, {"p": "Day 395 (365 + 30): guest account is deleted from the directory"}], "refs": ["https://learn.microsoft.com/en-us/azure/active-directory/governance/entitlement-management-access-package-resources#add-a-group-or-team-resource-role", "https://learn.microsoft.com/en-us/azure/active-directory/governance/entitlement-management-external-users"], "group": "G150"}, {"id": "T4-Q3", "test": 4, "num": 3, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant named apexcore.com."}, {"p": "There are two external partner organizations: ironclad.com and bluerock.com."}, {"p": "Only ironclad.com is configured as a connected organization in Microsoft Entra."}, {"p": "You create an access package as shown in the below exhibit."}, {"img": "az104/img/t4_image1.webp"}, {"p": "The external user lifecycle settings are configured so that when an external user loses their last access package assignment:"}, {"p": "The user is blocked from signing in."}, {"p": "The user is removed from the directory after 30 days."}, {"p": "True or False:"}, {"p": "“Once 395 days have passed, users from ironclad.com will be removed from the apexcore.com tenant.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because, according to the external user lifecycle settings, after a ironclad.com user loses their last assignment to an access package, they are set to be removed from the apexcore.com tenant after 30 days. Given that the access package assignment expires after 365 days, ironclad.com users will be removed from the apexcore.com tenant 30 days later, totaling 395 days from the start of their assignment."}], "refs": ["https://learn.microsoft.com/en-us/azure/active-directory/governance/entitlement-management-access-package-resources#add-a-group-or-team-resource-role", "https://learn.microsoft.com/en-us/azure/active-directory/governance/entitlement-management-external-users"], "group": "G150"}, {"id": "T4-Q4", "test": 4, "num": 4, "domain": "identity", "stem": [{"p": "You have an Azure subscription that includes a resource group named ResGrp1."}, {"p": "ResGrp1 is located in the West Europe region and is used to host temporary resources for a project."}, {"p": "The resource group contains the following resources:"}, {"p": "VM1 is a virtual machine deployed in the North Europe region."}, {"p": "RGV1 is a Recovery Services vault located in North Europe."}, {"p": "SQLDB01 is a SQL Server running on an Azure virtual machine in North Europe."}, {"p": "sa001 is a storage account deployed in West Europe."}, {"p": "The virtual machine SQLDB01 is configured to be backed up to the Recovery Services vault RGV1."}, {"p": "After the project is completed, you attempt to delete ResGrp1 from the Azure portal, but the deletion operation fails."}, {"p": "You need to successfully remove ResGrp1."}, {"p": "What should you do first?"}], "options": ["Delete the VM1 virtual machine", "Delete the sa001 storage account", "Stop the backup of SQLDB01", "Stop the VM1 virtual machine"], "correct": [2], "multi": false, "explanation": [{"p": "Stop the backup of SQLDB01 is correct because the deletion of a resource group that contains a Recovery Services vault with active backup jobs or protected items will fail. In this scenario, SQLDB01 is backed up to RGV1, which means there are active backup items associated with it. To successfully delete ResGrp1, you first need to stop the backup for SQLDB01 and delete any protected items from the Recovery Services vault (RGV1). Once the backup is stopped and protected items are removed, ResGrp1 can be deleted."}, {"img": "az104/img/t4_image2.webp"}, {"p": "Delete the VM1 virtual machine is incorrect because deleting VM1 would not impact the active backup configuration associated with SQLDB01 in RGV1. The deletion of the resource group fails due to the active backup in the Recovery Services vault, not because of the presence of VM1."}, {"p": "Delete the sa001 storage account is incorrect because deleting the storage account in a different region (West Europe) does not address the active backup in RGV1. The storage account (sa001) is unrelated to the backup process of SQLDB01 and does not prevent the deletion of the resource group."}, {"p": "Stop the VM1 virtual machine is incorrect because stopping the virtual machine does not affect the backup status in the Recovery Services vault. The issue lies with the active backup of SQLDB01, not with the state of VM1."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-azure-delete-vault"], "group": "G151"}, {"id": "T4-Q5", "test": 4, "num": 5, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes two storage accounts named contoso101 and contoso102."}, {"p": "The subscription also contains two virtual machines with the following configurations:"}, {"p": "VM1 is connected to VNet1/Subnet1 and uses a Basic public IP address SKU."}, {"p": "VM2 is connected to VNet1/Subnet2 and uses a Standard public IP address SKU."}, {"p": "Within VNet1, service endpoints are configured as follows:"}, {"p": "Microsoft.AzureActiveDirectory is enabled on Subnet2."}, {"p": "Microsoft.Storage is enabled on Subnet1."}, {"p": "A service endpoint policy named Policy1 is created for the Microsoft.Storage service. The policy allows access only to the storage account contoso101. The policy is associated with subnets that have Microsoft.Storage service endpoints enabled."}, {"p": "True or False:"}, {"p": "“VM1 can access contoso102.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer here. According to the information provided, the service endpoint policy is configured to allow access only to the contoso101 storage account through the Microsoft.Storage service endpoint associated with Subnet1 in VNet1. Since VM1 is connected to Subnet1 and the policy only permits access to contoso101, VM1 cannot access contoso102 because it is not included in the endpoint policy."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoints-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies?tabs=portal"], "group": "G152"}, {"id": "T4-Q6", "test": 4, "num": 6, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes two storage accounts named contoso101 and contoso102."}, {"p": "The subscription also contains two virtual machines with the following configurations:"}, {"p": "VM1 is connected to VNet1/Subnet1 and uses a Basic public IP address SKU."}, {"p": "VM2 is connected to VNet1/Subnet2 and uses a Standard public IP address SKU."}, {"p": "Within VNet1, service endpoints are configured as follows:"}, {"p": "Microsoft.AzureActiveDirectory is enabled on Subnet2."}, {"p": "Microsoft.Storage is enabled on Subnet1."}, {"p": "A service endpoint policy named Policy1 is created for the Microsoft.Storage service. The policy allows access only to the storage account contoso101. The policy is associated with subnets that have Microsoft.Storage service endpoints enabled."}, {"p": "True or False:"}, {"p": "“VM2 can access contoso101.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer. Service endpoint policies are always scoped to the subnet where they are applied, meaning they only control traffic originating from that specific subnet. In this scenario, the Microsoft.Storage service endpoint and its associated policy are applied to Subnet1, which contains VM1. Subnet2, where VM2 resides, has only an Azure Active Directory service endpoint and no storage endpoint or policy applied. This means the policy on Subnet1 does not restrict VM2’s traffic. By default, subnets in the same virtual network can communicate freely unless explicit network security groups or custom routes block that communication, and no such restrictions are mentioned here."}, {"p": "Because the question also does not state that the storage account firewall is locked down to specific networks, we assume the default configuration of allowing traffic from all networks. Under these conditions, VM2 can still reach contoso101 using the storage account’s public endpoint, bypassing the need for a storage service endpoint or policy. The idea that Subnet1’s policy would block all other subnets even via public endpoints, is a common misconception; Microsoft’s documentation makes clear that service endpoint policies only affect traffic from the subnets to which they are applied. Therefore, the correct choice is that VM2 can indeed access contoso101."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoint-policies?tabs=portal#restrict-network-access-to-azure-storage-accounts"], "group": "G152"}, {"id": "T4-Q7", "test": 4, "num": 7, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes two storage accounts named contoso101 and contoso102."}, {"p": "The subscription also contains two virtual machines with the following configurations:"}, {"p": "VM1 is connected to VNet1/Subnet1 and uses a Basic public IP address SKU."}, {"p": "VM2 is connected to VNet1/Subnet2 and uses a Standard public IP address SKU."}, {"p": "Within VNet1, service endpoints are configured as follows:"}, {"p": "Microsoft.AzureActiveDirectory is enabled on Subnet2."}, {"p": "Microsoft.Storage is enabled on Subnet1."}, {"p": "A service endpoint policy named Policy1 is created for the Microsoft.Storage service. The policy allows access only to the storage account contoso101. The policy is associated with subnets that have Microsoft.Storage service endpoints enabled."}, {"p": "True or False:"}, {"p": "“VM2 uses a private IP address to access Microsoft Entra ID.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer here. While there is a service endpoint for Microsoft.AzureActiveDirectory on Subnet2, which VM2 is connected to, this does not mean that VM2 can use a private IP address to access Microsoft Entra ID. Microsoft Entra ID is a global service that is accessible only via public IP addresses. The service endpoint for Microsoft.AzureActiveDirectory allows secure access to Entra ID but does not provide connectivity via private IP addresses; it only restricts access to specific VNets and subnets to enhance security while still using public IPs for the actual connection."}], "refs": ["https://learn.microsoft.com/en-us/entra/fundamentals/whatis"], "group": "G152"}, {"id": "T4-Q8", "test": 4, "num": 8, "domain": "network", "stem": [{"p": "You have an Azure subscription that contains the following resources:"}, {"p": "A virtual network named VNET1, which includes two subnets."}, {"p": "subnet1 uses the IP address range 10.3.0.0/24."}, {"p": "subnet2 uses the IP address range 10.4.0.0/24."}, {"p": "A network security group named NSG1."}, {"p": "A virtual machine named vm1 that has the private IP address 10.3.0.15 and is deployed in subnet1."}, {"p": "A virtual machine named vm2 that has the private IP address 10.4.0.16 and is deployed in subnet2."}, {"p": "A storage account named storage1."}, {"p": "The network security group NSG1 is configured with custom security rules as follows:"}, {"img": "az104/img/t4_image3.webp"}, {"p": "True or False:"}, {"p": "“VM1 can access storage1.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer here. NSG1 has an outbound security rule named Storage_Access configured to allow TCP traffic on port 443 from the virtual network to resources tagged as Storage. This rule enables VM1 to access storage1 on port 443. Additionally, there is no inbound restriction on the Storage endpoint, so VM1 can successfully connect to storage1 as required."}], "refs": ["https://docs.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview", "https://docs.microsoft.com/en-us/azure/virtual-network/service-tags-overview"], "group": "G153"}, {"id": "T4-Q9", "test": 4, "num": 9, "domain": "network", "stem": [{"p": "You have an Azure subscription that contains the following resources:"}, {"p": "A virtual network named VNET1, which includes two subnets."}, {"p": "subnet1 uses the IP address range 10.3.0.0/24."}, {"p": "subnet2 uses the IP address range 10.4.0.0/24."}, {"p": "A network security group named NSG1."}, {"p": "A virtual machine named vm1 that has the private IP address 10.3.0.15 and is deployed in subnet1."}, {"p": "A virtual machine named vm2 that has the private IP address 10.4.0.16 and is deployed in subnet2."}, {"p": "A storage account named storage1."}, {"p": "The network security group NSG1 is configured with custom security rules as follows:"}, {"img": "az104/img/t4_image3.webp"}, {"p": "True or False:"}, {"p": "“VM2 can access VM1 by using the HTTPS protocol.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer here. The HTTPS_VM1_Deny rule with priority 110 specifically blocks HTTPS (TCP port 443) traffic only from the Internet to VM1. Since VM2 is within the same virtual network (VNet1), the default VNet-to-VNet communication rule will allow HTTPS traffic between VM2 and VM1. Therefore, VM2 can access VM1 using the HTTPS protocol."}], "refs": ["https://docs.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview", "https://docs.microsoft.com/en-us/azure/virtual-network/service-tags-overview"], "group": "G153"}, {"id": "T4-Q10", "test": 4, "num": 10, "domain": "network", "stem": [{"p": "You have an Azure subscription that contains the following resources:"}, {"p": "A virtual network named VNET1, which includes two subnets."}, {"p": "subnet1 uses the IP address range 10.3.0.0/24."}, {"p": "subnet2 uses the IP address range 10.4.0.0/24."}, {"p": "A network security group named NSG1."}, {"p": "A virtual machine named vm1 that has the private IP address 10.3.0.15 and is deployed in subnet1."}, {"p": "A virtual machine named vm2 that has the private IP address 10.4.0.16 and is deployed in subnet2."}, {"p": "A storage account named storage1."}, {"p": "The network security group NSG1 is configured with custom security rules as follows:"}, {"img": "az104/img/t4_image3.webp"}, {"p": "True or False:"}, {"p": "“The NSG1 security rules apply to all virtual machines on VNET1.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer here. NSG1 is attached to a subnet, and by examining the inbound rule, the destination is specified as the private IP of VM1, indicating that NSG1 is likely connected to subnet1. Network Security Group (NSG) rules apply only to the resources within the scope to which the NSG is associated. Therefore, these rules will apply only to the virtual machines in subnet1 and not to all virtual machines on VNET1."}], "refs": ["https://docs.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview", "https://docs.microsoft.com/en-us/azure/virtual-network/service-tags-overview"], "group": "G153"}, {"id": "T4-Q11", "test": 4, "num": 11, "domain": "network", "stem": [{"p": "Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You have an Azure subscription that contains the virtual machines shown in the following table."}, {"img": "az104/img/t4_image4.webp"}, {"p": "You deploy a load balancer with the following characteristics:"}, {"p": "The load balancer is named LB1."}, {"p": "It is an internal load balancer."}, {"p": "It uses the Standard SKU."}, {"p": "It is deployed in VNET1."}, {"p": "You need to ensure that both VM1 and VM2 can be added to the backend pool of LB1."}, {"p": "Proposed solution: You create a Basic SKU public IP address, associate it with the network interface of VM1, and then start VM1."}, {"p": "Does this solution meet the requirement?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is the correct answer here. For a Standard SKU load balancer, all virtual machines in the backend pool must be within the same region and connected to the same virtual network (VNET) as the load balancer itself. Additionally, they must either have a Standard SKU public IP address or no public IP address at all. In this scenario, associating a Basic SKU public IP address to VM1 does not meet the requirements for the Standard SKU load balancer. Therefore, this configuration does not allow VM1 and VM2 to be added to the backend pool of LB1."}, {"img": "az104/img/t4_image5.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/load-balancer/backend-pool-management#limitations"], "group": "G154"}, {"id": "T4-Q12", "test": 4, "num": 12, "domain": "network", "stem": [{"p": "Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You have an Azure subscription that contains the virtual machines shown in the following table."}, {"img": "az104/img/t4_image4.webp"}, {"p": "You deploy a load balancer with the following characteristics:"}, {"p": "The load balancer is named LB1."}, {"p": "It is an internal load balancer."}, {"p": "It uses the Standard SKU."}, {"p": "It is deployed in VNET1."}, {"p": "You need to ensure that both VM1 and VM2 can be added to the backend pool of LB1."}, {"p": "Proposed solution: You create two public IP addresses using the Standard SKU, and you assign one Standard SKU public IP address to the network interface of each virtual machine."}, {"p": "Does this solution meet the requirement?"}], "options": ["Yes", "No"], "correct": [0], "multi": false, "explanation": [{"p": "Yes is the correct answer here. The load balancer in question has a Standard SKU, which requires any associated virtual machines in the backend pool to either have no public IP or a Standard SKU public IP. In this scenario, by creating Standard SKU public IP addresses and associating them with VM1 and VM2, you meet the requirement for compatibility with the Standard SKU load balancer."}, {"p": "For Standard SKU load balancers, virtual machines added to the backend pool must be within the same virtual network and location. Moreover, it’s important that, if public IPs are present, they are also of the Standard SKU type to ensure compatibility with the Standard SKU load balancer."}, {"img": "az104/img/t4_image5.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/load-balancer/backend-pool-management#limitations"], "group": "G154"}, {"id": "T4-Q13", "test": 4, "num": 13, "domain": "network", "stem": [{"p": "Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You have an Azure subscription that contains the virtual machines shown in the following table."}, {"img": "az104/img/t4_image4.webp"}, {"p": "You deploy a load balancer with the following characteristics:"}, {"p": "The load balancer is named LB1."}, {"p": "It is an internal load balancer."}, {"p": "It uses the Standard SKU."}, {"p": "It is deployed in VNET1."}, {"p": "You need to ensure that both VM1 and VM2 can be added to the backend pool of LB1."}, {"p": "Proposed solution: You remove the public IP address association from VM2’s network interface."}, {"p": "Does this solution meet the requirement?"}], "options": ["Yes", "No"], "correct": [0], "multi": false, "explanation": [{"p": "Yes is the correct answer because a Standard Load Balancer can only attach virtual machines that:"}, {"p": "Are in the same location and same virtual network as the Load Balancer."}, {"p": "Have either a Standard SKU public IP or no public IP."}, {"p": "In this scenario:"}, {"p": "VM1 has no public IP attached, which makes it eligible for the backend pool."}, {"p": "VM2 has a Basic SKU public IP, which is not compatible with a Standard Load Balancer."}, {"p": "By removing the Basic SKU Public IP from VM2, the virtual machine aligns with the requirements of a Standard Load Balancer and can be added to the backend pool alongside VM1."}], "refs": ["https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-standard-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/ip-services/virtual-network-public-ip-addresses", "https://learn.microsoft.com/en-us/azure/load-balancer/quickstart-load-balancer-standard-internal-portal"], "group": "G154"}, {"id": "T4-Q14", "test": 4, "num": 14, "domain": "network", "stem": [{"p": "Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You have an Azure subscription that contains the virtual machines shown in the following table."}, {"img": "az104/img/t4_image4.webp"}, {"p": "You deploy a load balancer with the following characteristics:"}, {"p": "The load balancer is named LB1."}, {"p": "It is an internal load balancer."}, {"p": "It uses the Standard SKU."}, {"p": "It is deployed in VNET1."}, {"p": "You need to ensure that both VM1 and VM2 can be added to the backend pool of LB1."}, {"p": "Proposed solution: You create a Standard SKU public IP address, attach it to VM1’s network interface, and then shut down VM2."}, {"p": "Does this solution meet the requirement?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is the correct answer here. To add VM1 and VM2 to the backend pool of a Standard SKU internal load balancer, both virtual machines need to be configured to meet the requirements for a Standard SKU load balancer. Specifically, both VMs must have Standard SKU public IP addresses or no public IP at all. VM2 currently has a Basic SKU public IP, which is incompatible with the Standard SKU load balancer."}, {"img": "az104/img/t4_image5.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/load-balancer/backend-pool-management#limitations"], "group": "G154"}, {"id": "T4-Q15", "test": 4, "num": 15, "domain": "identity", "stem": [{"p": "Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You have an Azure subscription that contains 10 virtual networks, each deployed in its own resource group."}, {"p": "Another administrator intends to create multiple network security groups (NSGs) within the subscription."}, {"p": "You must ensure that every newly created NSG automatically blocks TCP traffic on port 8080 between the virtual networks."}, {"p": "Proposed solution: Assign a built-in Azure Policy definition at the subscription scope."}, {"p": "Does this solution satisfy the requirement?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is the correct answer here. To meet the specific requirement of automatically blocking TCP port 8080 between virtual networks when an NSG is created, you would need to create a custom Azure policy. Built-in policies provided by Microsoft focus on general compliance and best practices and do not cover specific, custom configurations such as blocking a specific port across all new NSGs. Creating a custom policy allows you to define specific actions, such as blocking or allowing certain ports, tailored to your Azure environment's unique needs."}], "refs": ["https://docs.microsoft.com/en-us/azure/azure-policy/policy-definition", "https://learn.microsoft.com/en-us/azure/governance/policy/tutorials/create-custom-policy-definition"], "group": "G155"}, {"id": "T4-Q16", "test": 4, "num": 16, "domain": "identity", "stem": [{"p": "Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You have an Azure subscription that contains 10 virtual networks, each deployed in its own resource group."}, {"p": "Another administrator intends to create multiple network security groups (NSGs) within the subscription."}, {"p": "You must ensure that every newly created NSG automatically blocks TCP traffic on port 8080 between the virtual networks."}, {"p": "Proposed solution: You create a custom Azure Policy definition and assign it at the subscription level."}, {"p": "Does this solution satisfy the requirement?"}], "options": ["Yes", "No"], "correct": [0], "multi": false, "explanation": [{"p": "Yes is the correct answer here. By configuring a custom policy definition and assigning it to the subscription, you can enforce specific rules on NSGs, such as automatically blocking TCP port 8080 between virtual networks. Custom policies allow you to specify detailed compliance requirements and enforce specific configurations, which in this case include blocking a particular port across newly created NSGs within the subscription."}, {"img": "az104/img/t4_image6.webp"}, {"img": "az104/img/t4_image7.webp"}], "refs": ["https://docs.microsoft.com/en-us/azure/governance/policy/concepts/definition-structure"], "group": "G155"}, {"id": "T4-Q17", "test": 4, "num": 17, "domain": "identity", "stem": [{"p": "Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You have an Azure subscription that contains 10 virtual networks, each deployed in its own resource group."}, {"p": "Another administrator intends to create multiple network security groups (NSGs) within the subscription."}, {"p": "You must ensure that every newly created NSG automatically blocks TCP traffic on port 8080 between the virtual networks."}, {"p": "Proposed solution: You go to the Resource providers blade and unregister the Microsoft.ClassicNetwork provider."}, {"p": "Does this solution satisfy the requirement?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is the correct answer here. Unregistering the Microsoft.ClassicNetwork provider has no effect on network security groups (NSGs) created in the Azure Resource Manager (ARM) model, as it is associated with the classic deployment model in Azure. The requirement here is to automatically block TCP port 8080 between virtual networks in the ARM model, which cannot be achieved by unregistering a provider. Instead, you would need to implement a custom policy or directly configure NSG rules."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/overview"], "group": "G155"}, {"id": "T4-Q18", "test": 4, "num": 18, "domain": "identity", "stem": [{"p": "Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You have an Azure subscription that contains 10 virtual networks, each deployed in its own resource group."}, {"p": "Another administrator intends to create multiple network security groups (NSGs) within the subscription."}, {"p": "You must ensure that every newly created NSG automatically blocks TCP traffic on port 8080 between the virtual networks."}, {"p": "Proposed solution: You create a resource lock and apply it at the subscription scope."}, {"p": "Does this solution satisfy the requirement?"}], "options": ["Yes", "No"], "correct": [1], "multi": false, "explanation": [{"p": "No is the correct answer here. A resource lock is used to prevent accidental deletion or modification of Azure resources, but it does not enforce security rules or configurations, such as network access control. Resource locks are intended to protect resources from changes, not to configure their behavior."}, {"p": "To meet the stated goal of automatically blocking TCP port 8080 between virtual networks whenever a network security group (NSG) is created, you should use Azure Policy. You can create a policy definition that audits or enforces the presence of specific inbound or outbound security rules (such as blocking port 8080) in NSGs and assign that policy at the subscription level."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/lock-resources", "https://learn.microsoft.com/en-us/azure/governance/policy/overview"], "group": "G155"}, {"id": "T4-Q19", "test": 4, "num": 19, "domain": "storage", "stem": [{"p": "You have an Azure subscription with the following resources in the same resource group (RG1):"}, {"p": "Vault1: A Recovery Services vault located in the East US region"}, {"p": "VM1: A virtual machine running Windows Server in the East US region"}, {"p": "VM2: A virtual machine running Windows Server in the West US region"}, {"p": "On VM1, you configure Azure Backup to protect a folder named Folder1 using a scheduled file-and-folder backup policy. The backup schedule is configured as follows:"}, {"p": "Backup frequency: Daily"}, {"p": "Backup times: 6:00 AM and 10:00 PM"}, {"p": "You plan to restore this backup to a different virtual machine and want the data to be recovered on VM2."}, {"p": "What is the first action you must take?"}], "options": ["On VM2, install the Windows Server Backup feature.", "On VM1, install the Microsoft Azure Recovery Services Agent.", "On VM1, install the Windows Server Backup feature.", "On VM2, install the Microsoft Azure Recovery Services Agent."], "correct": [3], "multi": false, "explanation": [{"p": "On VM2, install the Microsoft Azure Recovery Services Agent is correct because in order to restore a backup from the Recovery Services vault to a different virtual machine (in this case, VM2), you need to have the Microsoft Azure Recovery Services (MARS) Agent installed on the destination VM. This agent enables the VM to communicate with the Recovery Services vault, allowing it to access and restore backups stored in Azure."}, {"img": "az104/img/t4_image8.webp"}, {"p": "On VM2, install the Windows Server Backup feature is incorrect because the Windows Server Backup feature alone does not provide the necessary integration with Azure Recovery Services. The MARS Agent is required to retrieve backups from Azure."}, {"p": "On VM1, install the Microsoft Azure Recovery Services Agent is incorrect as the MARS Agent is already installed on VM1 to perform the initial backup. The task here is to restore the backup to VM2."}, {"p": "On VM1, install the Windows Server Backup feature is incorrect because this feature does not assist in restoring a backup to another VM. The backup is already configured on VM1, and the requirement is to restore it to VM2, which requires the MARS Agent on VM2."}], "refs": ["https://learn.microsoft.com/en-us/azure/backup/backup-azure-restore-windows-server"], "group": "G156"}, {"id": "T4-Q20", "test": 4, "num": 20, "domain": "identity", "stem": [{"p": "You have an Azure subscription named Subscription1 that is shared across multiple departments. The subscription currently includes the following resources:"}, {"p": "storage1 - Azure Storage account"}, {"p": "RG1 - Resource group"}, {"p": "container1 - Blob container"}, {"p": "share1 - Azure file share"}, {"p": "Another administrator deploys two new resources, a virtual machine named VM1 and a storage account named storage2, by using a single Azure Resource Manager (ARM) template."}, {"p": "You want to review the ARM template that was used for this deployment."}, {"p": "From which Azure portal blade can you view the template associated with the deployment?"}], "options": ["container1", "RG1", "storage1", "VM1"], "correct": [1], "multi": false, "explanation": [{"p": "RG1 is correct because to view the Azure Resource Manager (ARM) template used for a deployment, you need to access the Resource Group (in this case, RG1) where the deployment was made. The Resource Group blade in the Azure portal includes an option to view the deployment history and allows you to access the templates used in those deployments."}, {"img": "az104/img/t4_image9.webp"}, {"p": "container1 is incorrect because a Blob container does not have deployment information or templates associated with it directly. It is a storage object within a storage account and lacks deployment-level insights."}, {"p": "storage1 is incorrect as it is the storage account itself, and the ARM template used for deployments would not be accessible from the storage account blade. Templates are accessible through the Resource Group level."}, {"p": "VM1 is incorrect because while you can see configuration and settings specific to VM1, the VM blade does not provide access to the ARM template used in the original deployment. The Resource Group blade is needed for viewing deployment templates."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/deployment-history"], "group": "G157"}, {"id": "T4-Q21", "test": 4, "num": 21, "domain": "network", "stem": [{"p": "You have a public load balancer that distributes traffic on ports 80 and 443 across three virtual machines named VM1, VM2, and VM3."}, {"p": "You want all Remote Desktop Protocol (RDP) connections to be routed exclusively to VM3."}, {"p": "What configuration should you apply?"}], "options": ["Create a separate public load balancer dedicated to VM3", "Configure an additional frontend IP configuration", "Configure an inbound NAT rule", "Configure a load balancing rule"], "correct": [2], "multi": false, "explanation": [{"p": "Configure an inbound NAT rule is correct because an inbound NAT rule allows you to direct specific traffic, such as RDP, to a particular virtual machine (VM3 in this case) behind the load balancer. By setting up an inbound NAT rule for port 3389 (RDP), you ensure that all RDP connections go directly to VM3 instead of balancing across all VMs."}, {"img": "az104/img/t4_image10.webp"}, {"p": "Create a separate public load balancer dedicated to VM3 is incorrect because creating a separate load balancer is unnecessary for directing RDP connections to VM3. An inbound NAT rule is sufficient to achieve this without additional load balancers."}, {"p": "Configure an additional frontend IP configuration is incorrect as a frontend IP configuration is used to define the IP address on which the load balancer is accessible. It does not control how RDP traffic is directed to specific VMs."}, {"p": "Configure a load balancing rule is incorrect because load balancing rules are intended for distributing traffic across multiple VMs based on specific ports, which is not the goal here. The objective is to direct all RDP traffic to VM3 specifically, not balance it across VMs."}], "refs": ["https://learn.microsoft.com/en-us/azure/load-balancer/tutorial-load-balancer-port-forwarding-portal"], "group": "G158"}, {"id": "T4-Q22", "test": 4, "num": 22, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes several virtual networks deployed across different regions and resource groups."}, {"p": "The virtual networks are configured as follows:"}, {"p": "VNET1 is deployed in the West US region and belongs to resource group RG1."}, {"p": "VNET2 is deployed in the Central US region and belongs to resource group RG1."}, {"p": "VNET3 is deployed in the Central US region and belongs to resource group RG2."}, {"p": "VNET4 is deployed in the West US region and belongs to resource group RG2."}, {"p": "You plan to deploy an Azure Firewall named AF1 in resource group RG1, located in the West US region."}, {"p": "Which virtual networks are valid targets for deploying AF1?"}], "options": ["VNET1 only", "VNET1 and VNET2 only", "VNET1 and VNET4 only", "VNET1, VNET2, and VNET4 only", "VNET1, VNET2, VNET3, and VNET4"], "correct": [0], "multi": false, "explanation": [{"p": "VNET1 only is correct because Azure Firewall can connect to a virtual network within the same region and resource group. In this scenario, AF1 is deployed in RG1 in the West US region. While VNET4 is also in the West US region, it is in a different resource group (RG2), which prevents AF1 from connecting to it. Therefore, VNET1 is the only virtual network eligible for connection to AF1."}, {"img": "az104/img/t4_image11.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/firewall/firewall-faq#are-there-any-firewall-resource-group-restrictions"], "group": "G159"}, {"id": "T4-Q23", "test": 4, "num": 23, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes the following resources:"}, {"p": "VM1 - a virtual machine"}, {"p": "App1 - an Azure web app"}, {"p": "apexcore.com, which is a Microsoft Entra Domain Services domain"}, {"p": "All of these resources are connected to the same virtual network, VNet1."}, {"p": "You plan to deploy an Azure Bastion host named Bastion1 into VNet1."}, {"p": "Which of these resources can be secured by using Bastion1?"}], "options": ["VM1 only", "apexcore.com only", "App1 and apexcore.com only", "VM1 and apexcore.com only", "VM1, App1, and apexcore.com"], "correct": [0], "multi": false, "explanation": [{"p": "VM1 only is correct because Azure Bastion is designed to provide secure and seamless RDP and SSH connectivity to virtual machines within a virtual network. In this scenario, VM1 is the only virtual machine listed in the table, and thus the only resource that can be accessed and protected via Bastion1. Azure Bastion does not support direct connectivity to web apps (such as App1) or to Microsoft Entra Domain Services domains (like apexcore.com)."}, {"img": "az104/img/t4_image12.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/bastion/bastion-overview"], "group": "G160"}, {"id": "T4-Q24", "test": 4, "num": 24, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant that is linked to the Azure subscriptions shown in the following table."}, {"img": "az104/img/t4_image13.webp"}, {"p": "Within these subscriptions, the following resource groups exist:"}, {"p": "RG1 is in SubA and contains a storage account named storage1."}, {"p": "RG2 is in SubB and contains a web app named App1."}, {"p": "RG3 is in SubC and contains a virtual machine named VM1."}, {"p": "Role assignments are configured as follows:"}, {"p": "User1 is assigned the Contributor role at the MG2 management group scope."}, {"p": "User2 is assigned the Storage Account Contributor role scoped specifically to storage1."}, {"p": "User3 is assigned the User Access Administrator role at the Tenant Root Group scope."}, {"p": "True or False:"}, {"p": "\"User1 can resize VM1.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because User1 has the Contributor role assigned at the scope of MG2. Since MG2 is the management group that contains the subscription SubC, which in turn contains the resource group RG3 (where VM1 is located), User1 has Contributor permissions on VM1. The Contributor role provides permissions to manage resources, including resizing virtual machines."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G161"}, {"id": "T4-Q25", "test": 4, "num": 25, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant that is linked to the Azure subscriptions shown in the following table."}, {"img": "az104/img/t4_image13.webp"}, {"p": "Within these subscriptions, the following resource groups exist:"}, {"p": "RG1 is in SubA and contains a storage account named storage1."}, {"p": "RG2 is in SubB and contains a web app named App1."}, {"p": "RG3 is in SubC and contains a virtual machine named VM1."}, {"p": "Role assignments are configured as follows:"}, {"p": "User1 is assigned the Contributor role at the MG2 management group scope."}, {"p": "User2 is assigned the Storage Account Contributor role scoped specifically to storage1."}, {"p": "User3 is assigned the User Access Administrator role at the Tenant Root Group scope."}, {"p": "True or False:"}, {"p": "\"User2 can create a new storage account in RG1.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because User2’s Storage Account Contributor role is assigned only at the scope of the existing storage account (storage1). Although this role includes permissions to create storage accounts when assigned at the resource group or subscription level, permissions granted at an individual resource scope do not allow the creation of new sibling resources. Since User2 has no role assignment at the RG1 or subscription scope, they cannot create a new storage account in RG1."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G161"}, {"id": "T4-Q26", "test": 4, "num": 26, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant that is linked to the Azure subscriptions shown in the following table."}, {"img": "az104/img/t4_image13.webp"}, {"p": "Within these subscriptions, the following resource groups exist:"}, {"p": "RG1 is in SubA and contains a storage account named storage1."}, {"p": "RG2 is in SubB and contains a web app named App1."}, {"p": "RG3 is in SubC and contains a virtual machine named VM1."}, {"p": "Role assignments are configured as follows:"}, {"p": "User1 is assigned the Contributor role at the MG2 management group scope."}, {"p": "User2 is assigned the Storage Account Contributor role scoped specifically to storage1."}, {"p": "User3 is assigned the User Access Administrator role at the Tenant Root Group scope."}, {"p": "True or False:"}, {"p": "\"User3 can assign User1 the Owner role for RG3.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because User3 has the User Access Administrator role assigned at the scope of the Tenant Root Group. This role grants User3 permission to manage user access to Azure resources at or below the assigned scope. Since the Tenant Root Group is the highest level in the hierarchy, User3 has permission to assign roles, including the Owner role, to any resource within the tenant, including RG3."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles"], "group": "G161"}, {"id": "T4-Q27", "test": 4, "num": 27, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant named apexcore.onmicrosoft.com that contains the following users:"}, {"p": "User1 is a member of Group1 and has no directory role assigned."}, {"p": "User2 is a member of Group2 and has no directory role assigned."}, {"p": "User3 is a member of Group1 and Group2, and is assigned the User Administrator role."}, {"p": "You enable password reset for apexcore.onmicrosoft.com as below:"}, {"p": "SSPR is enabled for Selected users only."}, {"p": "The selected group is Group2."}, {"p": "Authentication method settings for password reset are configured with these options:"}, {"p": "Number of methods required to reset: 2"}, {"p": "Enabled methods:"}, {"p": "Mobile phone"}, {"p": "Security questions"}, {"p": "The following methods are not enabled:"}, {"p": "Mobile app notification"}, {"p": "Mobile app code"}, {"p": "Email"}, {"p": "Office phone"}, {"p": "Number of security questions required to register: 5"}, {"p": "Number of security questions required to reset: 3"}, {"p": "A total of 10 security questions are available."}, {"p": "True or False:"}, {"p": "\"After User2 answers three security questions correctly, he can reset his password immediately.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because, based on the password reset settings, two methods are required for a successful password reset. Although User2 can use security questions as one of the authentication methods, they would still need to provide a second method (such as a mobile phone verification) to reset their password. Answering only three security questions alone is insufficient as per the configured policy, which mandates two authentication methods."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/authentication/tutorial-enable-sspr", "https://learn.microsoft.com/en-us/entra/identity/authentication/passwords-faq"], "group": "G162"}, {"id": "T4-Q28", "test": 4, "num": 28, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant named apexcore.onmicrosoft.com that contains the following users:"}, {"p": "User1 is a member of Group1 and has no directory role assigned."}, {"p": "User2 is a member of Group2 and has no directory role assigned."}, {"p": "User3 is a member of Group1 and Group2, and is assigned the User Administrator role."}, {"p": "You enable password reset for apexcore.onmicrosoft.com as below:"}, {"p": "SSPR is enabled for Selected users only."}, {"p": "The selected group is Group2."}, {"p": "Authentication method settings for password reset are configured with these options:"}, {"p": "Number of methods required to reset: 2"}, {"p": "Enabled methods:"}, {"p": "Mobile phone"}, {"p": "Security questions"}, {"p": "The following methods are not enabled:"}, {"p": "Mobile app notification"}, {"p": "Mobile app code"}, {"p": "Email"}, {"p": "Office phone"}, {"p": "Number of security questions required to register: 5"}, {"p": "Number of security questions required to reset: 3"}, {"p": "A total of 10 security questions are available."}, {"p": "True or False:"}, {"p": "\"If User1 forgets her password, she can reset the password by using the mobile phone app.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because User1 is a member of Group1, and self-service password reset (SSPR) has been enabled only for Group2. Since User1 is not part of Group2, she does not have access to the self-service password reset feature, regardless of the authentication methods configured."}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/authentication/tutorial-enable-sspr", "https://learn.microsoft.com/en-us/entra/identity/authentication/passwords-faq"], "group": "G162"}, {"id": "T4-Q29", "test": 4, "num": 29, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant named apexcore.onmicrosoft.com that contains the following users:"}, {"p": "User1 is a member of Group1 and has no directory role assigned."}, {"p": "User2 is a member of Group2 and has no directory role assigned."}, {"p": "User3 is a member of Group1 and Group2, and is assigned the User Administrator role."}, {"p": "You enable password reset for apexcore.onmicrosoft.com as below:"}, {"p": "SSPR is enabled for Selected users only."}, {"p": "The selected group is Group2."}, {"p": "Authentication method settings for password reset are configured with these options:"}, {"p": "Number of methods required to reset: 2"}, {"p": "Enabled methods:"}, {"p": "Mobile phone"}, {"p": "Security questions"}, {"p": "The following methods are not enabled:"}, {"p": "Mobile app notification"}, {"p": "Mobile app code"}, {"p": "Email"}, {"p": "Office phone"}, {"p": "Number of security questions required to register: 5"}, {"p": "Number of security questions required to reset: 3"}, {"p": "A total of 10 security questions are available."}, {"p": "True or False:"}, {"p": "\"User3 can add security questions to the password reset process.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because although User3 has the User Administrator role, this role does not include permissions to modify the security questions configured for self-service password reset (SSPR). Only users with the Global Administrator or Authentication Administrator roles have the necessary permissions to modify security questions in the SSPR settings."}, {"img": "az104/img/t4_image14.webp"}], "refs": ["https://docs.microsoft.com/en-us/azure/active-directory/authentication/quickstart-sspr", "https://docs.microsoft.com/en-us/azure/active-directory/authentication/active-directory-passwords-faq", "https://docs.microsoft.com/en-us/azure/active-directory/authentication/concept-sspr-policy", "https://docs.microsoft.com/en-us/azure/active-directory/authentication/tutorial-enable-sspr", "https://docs.microsoft.com/en-us/azure/active-directory/authentication/howto-sspr-authenticationdata", "https://docs.microsoft.com/en-us/azure/active-directory/roles/permissions-reference#user-administrator"], "group": "G162"}, {"id": "T4-Q30", "test": 4, "num": 30, "domain": "identity", "stem": [{"p": "You manage a Microsoft Entra tenant that contains approximately 7,000 user accounts."}, {"p": "You create a new user named AdminUsr1."}, {"p": "You must assign the User Administrator administrative role to AdminUsr1."}, {"p": "Which action should you take from the user account properties to complete this task?"}], "options": ["From the Licenses blade, assign a new license.", "From the Groups blade, invite the user account to a new group.", "From the Directory role blade, modify the directory role."], "correct": [2], "multi": false, "explanation": [{"p": "From the Directory role blade, modify the directory role is correct because to assign an administrative role, such as the User Administrator role, to AdminUsr1, you need to navigate to the Directory role blade in the user account properties. From there, you can modify the directory role and assign the appropriate administrative role."}, {"img": "az104/img/t4_image15.webp"}, {"p": "From the Licenses blade, assign a new license is incorrect because assigning a license is unrelated to assigning an administrative role. Licenses are used for service access, not role-based access control."}, {"p": "From the Groups blade, invite the user account to a new group is incorrect because adding the user to a group does not assign the User Administrator role. Role assignments are handled through the Directory role settings."}], "refs": ["https://learn.microsoft.com/en-us/entra/fundamentals/how-subscriptions-associated-directory"], "group": "G163"}, {"id": "T4-Q31", "test": 4, "num": 31, "domain": "identity", "stem": [{"p": "You have the following Azure resources:"}, {"p": "Tenant Root Group - tenant root management group"}, {"p": "MG1 - management group"}, {"p": "Sub1 - subscription"}, {"p": "RG1 - resource group"}, {"p": "VM1 - virtual machine"}, {"p": "You want to monitor resource usage and ensure that resources cannot be accidentally deleted."}, {"p": "To which resources can you apply locks?"}], "options": ["RG1 and VM1 only", "Sub1 and RG1 only", "Sub1, RG1, and VM1 only", "MG1, Sub1, RG1, and VM1 only", "Tenant Root Group, MG1, Sub1, RG1, and VM1"], "correct": [2], "multi": false, "explanation": [{"p": "Sub1, RG1, and VM1 only is correct because locks can be applied at the subscription, resource group, and resource (such as a virtual machine) levels to prevent accidental deletion or modification. In this case, Sub1 (the subscription), RG1 (the resource group), and VM1 (the virtual machine) are valid targets for applying locks to track usage and prevent deletion."}, {"img": "az104/img/t4_image16.webp"}, {"p": "RG1 and VM1 only is incorrect because locks can also be applied at the subscription level (Sub1), not just at the resource group and resource levels."}, {"p": "Sub1 and RG1 only is incorrect because locks can also be applied directly to resources like VM1."}, {"p": "MG1, Sub1, RG1, and VM1 only is incorrect because locks cannot be applied to management groups (MG1)."}, {"p": "Tenant Root Group, MG1, Sub1, RG1, and VM1 is incorrect because locks cannot be applied to the Tenant Root Group or management groups."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/lock-resources?tabs=json"], "group": "G164"}, {"id": "T4-Q32", "test": 4, "num": 32, "domain": "identity", "stem": [{"p": "You have the following Azure resources:"}, {"p": "Tenant Root Group - tenant root management group"}, {"p": "MG1 - management group"}, {"p": "Sub1 - subscription"}, {"p": "RG1 - resource group"}, {"p": "VM1 - virtual machine"}, {"p": "You want to monitor resource usage and ensure that resources cannot be accidentally deleted."}, {"p": "To which resources can you apply tags?"}], "options": ["RG1 and VM1 only", "Sub1 and RG1 only", "Sub1, RG1, and VM1 only", "MG1, Sub1, RG1, and VM1 only", "Tenant Root Group, MG1, Sub1, RG1, and VM1"], "correct": [2], "multi": false, "explanation": [{"p": "Sub1, RG1, and VM1 only is correct because tags can be applied to subscriptions (Sub1), resource groups (RG1), and resources (such as VM1) in Azure. Tags cannot be applied to management groups (MG1) or the Tenant Root Group."}, {"img": "az104/img/t4_image17.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-resource-manager/management/tag-resources?tabs=json"], "group": "G164"}, {"id": "T4-Q33", "test": 4, "num": 33, "domain": "identity", "stem": [{"p": "You are provided with a JSON file that lists several Azure role assignments at different scopes as shown below."}, {"p": "["}, {"p": "{"}, {"p": "\"RoleAssignmentId\": \"f1a9c2d4-8b35-4e71-9c2a-6d5e7f8a9012\","}, {"p": "\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10\","}, {"p": "\"DisplayName\": \"User1\","}, {"p": "\"SignInName\": \"User1@apexcore.onmicrosoft.com\","}, {"p": "\"RoleDefinitionName\": \"Owner\""}, {"p": "},"}, {"p": "{"}, {"p": "\"RoleAssignmentId\": \"a7c4e1b2-5d93-4f60-8a1e-2b6c9d7f3e44\","}, {"p": "\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10/resourceGroups/RG2\","}, {"p": "\"DisplayName\": \"User2\","}, {"p": "\"SignInName\": \"User2@apexcore.onmicrosoft.com\","}, {"p": "\"RoleDefinitionName\": \"Owner\""}, {"p": "},"}, {"p": "{"}, {"p": "\"RoleAssignmentId\": \"d3e8f7a1-2c44-4b9e-91fa-5c6d8e2b7a33\","}, {"p": "\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10/resourceGroups/RG1/providers/Microsoft.Compute/virtualMachines/VM1\","}, {"p": "\"DisplayName\": \"User3\","}, {"p": "\"SignInName\": \"User3@apexcore.onmicrosoft.com\","}, {"p": "\"RoleDefinitionName\": \"Owner\""}, {"p": "},"}, {"p": "{"}, {"p": "\"RoleAssignmentId\": \"b6d2a9f8-1e73-4c55-8b0d-9f2e6a4c7d88\","}, {"p": "\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10/resourceGroups/RG1\","}, {"p": "\"DisplayName\": \"User4\","}, {"p": "\"SignInName\": \"User4@apexcore.onmicrosoft.com\","}, {"p": "\"RoleDefinitionName\": \"Contributor\""}, {"p": "}"}, {"p": "]"}, {"p": "Using the details in the role assignment file, choose the option that correctly completes the following statement:"}, {"p": "“____________________________ assigned the Owner role for VM1.”"}], "options": ["User3 is", "User3 and User4 are", "User1 and User3 are", "User1, User3, and User4 are", "User1, User2, User3, and User4 are"], "correct": [2], "multi": false, "explanation": [{"p": "User1 and User3 are is correct because in the provided role assignment file, User3 is specifically assigned the Owner role at the scope of VM1 (/subscriptions/.../resourceGroups/RG1/providers/Microsoft.Compute/virtualMachines/VM1)."}, {"p": "And User1 is the owner of the subscription, which inherently makes it the owner of VM inside that subscription as well."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles", "https://learn.microsoft.com/en-us/azure/role-based-access-control/rbac-and-directory-admin-roles"], "group": "G165"}, {"id": "T4-Q34", "test": 4, "num": 34, "domain": "identity", "stem": [{"p": "You are provided with a JSON file that lists several Azure role assignments at different scopes as shown below."}, {"p": "["}, {"p": "{"}, {"p": "\"RoleAssignmentId\": \"f1a9c2d4-8b35-4e71-9c2a-6d5e7f8a9012\","}, {"p": "\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10\","}, {"p": "\"DisplayName\": \"User1\","}, {"p": "\"SignInName\": \"User1@apexcore.onmicrosoft.com\","}, {"p": "\"RoleDefinitionName\": \"Owner\""}, {"p": "},"}, {"p": "{"}, {"p": "\"RoleAssignmentId\": \"a7c4e1b2-5d93-4f60-8a1e-2b6c9d7f3e44\","}, {"p": "\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10/resourceGroups/RG2\","}, {"p": "\"DisplayName\": \"User2\","}, {"p": "\"SignInName\": \"User2@apexcore.onmicrosoft.com\","}, {"p": "\"RoleDefinitionName\": \"Owner\""}, {"p": "},"}, {"p": "{"}, {"p": "\"RoleAssignmentId\": \"d3e8f7a1-2c44-4b9e-91fa-5c6d8e2b7a33\","}, {"p": "\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10/resourceGroups/RG1/providers/Microsoft.Compute/virtualMachines/VM1\","}, {"p": "\"DisplayName\": \"User3\","}, {"p": "\"SignInName\": \"User3@apexcore.onmicrosoft.com\","}, {"p": "\"RoleDefinitionName\": \"Owner\""}, {"p": "},"}, {"p": "{"}, {"p": "\"RoleAssignmentId\": \"b6d2a9f8-1e73-4c55-8b0d-9f2e6a4c7d88\","}, {"p": "\"Scope\": \"/subscriptions/9b2d7f41-6c8e-4a55-b1d9-3e7f2a6c4b10/resourceGroups/RG1\","}, {"p": "\"DisplayName\": \"User4\","}, {"p": "\"SignInName\": \"User4@apexcore.onmicrosoft.com\","}, {"p": "\"RoleDefinitionName\": \"Contributor\""}, {"p": "}"}, {"p": "]"}, {"p": "Using the details in the role assignment file, choose the option that correctly completes the following statement:"}, {"p": "“____________________________ can create a virtual machine in RG1.”"}], "options": ["User1 and User4", "User1, User2, and User3", "User1, User2, and User4", "User1, User3, and User4", "User1, User2, User3, and User4"], "correct": [0], "multi": false, "explanation": [{"p": "User1 and User4 is correct because creating a virtual machine in RG1 requires permissions at the RG1 level or higher within the subscription."}, {"p": "User1 has the Owner role at the subscription level, which grants full access to manage resources within the entire subscription, including RG1."}, {"p": "User4 has the Contributor role specifically on RG1, which allows them to manage resources within RG1, including creating and deleting virtual machines. However, as a Contributor, User4 cannot modify Role-Based Access Control (RBAC) settings."}, {"p": "User2 is incorrect because their Owner role is limited to RG2, and they do not have permissions in RG1."}, {"p": "User3 is incorrect because their Owner role applies only to VM1, so they do not have permissions to create new resources in RG1."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles", "https://learn.microsoft.com/en-us/azure/role-based-access-control/rbac-and-directory-admin-roles"], "group": "G165"}, {"id": "T4-Q35", "test": 4, "num": 35, "domain": "identity", "stem": [{"p": "You have a Microsoft Entra tenant named bluerock.com that includes the following group hierarchy:"}, {"p": "Group1 is not a member of any other group."}, {"p": "Group2 is a member of Group1."}, {"p": "Group3 is a member of Group2."}, {"p": "The tenant also contains the following users and their group memberships:"}, {"p": "User1 is a member of Group1."}, {"p": "User2 is a member of Group2."}, {"p": "User3 is a member of Group3."}, {"p": "User4 is not a member of any group."}, {"p": "You assign the Microsoft Entra ID P2 license directly to Group1 and also directly to User4."}, {"p": "Which users receive the Microsoft Entra ID P2 license as a result of this configuration?"}], "options": ["User4 only", "User1 and User4 only", "User1, User2, and User4 only", "User1, User2, User3, and User4"], "correct": [1], "multi": false, "explanation": [{"p": "User1 and User4 only is correct because group-based licensing in Microsoft Entra ID does not support nested groups. When a license is assigned to Group1, only the direct members of Group1 receive the license. This means User1 (direct member of Group1) and User4 (who received the license directly) are the only users assigned the Microsoft Entra ID P2 license. User2 and User3 do not receive the license because they are members through nested groups (Group2 and Group3)."}, {"img": "az104/img/t4_image18.webp"}], "refs": ["https://learn.microsoft.com/en-us/entra/identity/users/licensing-group-advanced#limitations-and-known-issues"], "group": "G166"}, {"id": "T4-Q36", "test": 4, "num": 36, "domain": "network", "stem": [{"p": "You have several virtual networks in your Azure environment. The peering settings for vNET6 are configured as follows:"}, {"p": "A peering connection Peering1 to vNET1 exists, but its Peering status is Disconnected and Gateway transit is Enabled."}, {"p": "A peering connection Peering2 to vNET2 exists, but its Peering status is Disconnected and Gateway transit is Disabled."}, {"p": "Based on this configuration, complete the statement:"}, {"p": "“Virtual machines hosted in vNET6 are able to communicate with virtual machines hosted in ____________________.”"}], "options": ["vNET6 only", "vNET6 and vNET1 only", "vNET6, vNET1, and vNET2 only", "all the virtual networks in the subscription"], "correct": [0], "multi": false, "explanation": [{"p": "vNET6 only is correct because the peering status for vNET6 with both vNET1 and vNET2 is mentioned as Disconnected. This means there is no active peering connection between vNET6 and any other virtual network. As a result, hosts on vNET6 can only communicate within vNET6 itself and cannot reach vNET1, vNET2, or any other virtual network in the subscription."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview"], "group": "G167"}, {"id": "T4-Q37", "test": 4, "num": 37, "domain": "network", "stem": [{"p": "You have several virtual networks in your Azure environment. The peering settings for vNET6 are configured as follows:"}, {"p": "A peering connection Peering1 to vNET1 exists, but its Peering status is Disconnected and Gateway transit is Enabled."}, {"p": "A peering connection Peering2 to vNET2 exists, but its Peering status is Disconnected and Gateway transit is Disabled."}, {"p": "Based on this configuration, complete the statement:"}, {"p": "“To change the peering connection between vNET6 and vNET1 to a Connected state, you must first _____________________.”"}], "options": ["add a service endpoint", "add a subnet", "delete peering1", "modify the address space"], "correct": [2], "multi": false, "explanation": [{"p": "delete peering1 is the correct answer because a peering connection in the Disconnected state indicates that the peering relationship is broken or missing from one side. To restore connectivity between vNET6 and vNET1, the disconnected peering must first be deleted and then recreated."}, {"p": "Although Azure now supports modifying the address space of peered virtual networks without deleting the peering, that functionality applies to active peerings that can be synchronized afterward. In this scenario, the issue is the Disconnected peering state itself, not an address-space update."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-manage-peering"], "group": "G167"}, {"id": "T4-Q38", "test": 4, "num": 38, "domain": "compute", "stem": [{"p": "You have an Azure subscription that includes the following resources:"}, {"p": "VM1 - a virtual machine"}, {"p": "VM2 - a virtual machine"}, {"p": "LB1 - a load balancer that uses the Basic SKU"}, {"p": "You install the Web Server (IIS) role on both VM1 and VM2. After the installation, you add both virtual machines to the backend pool of LB1."}, {"p": "LB1 is configured as shown below."}, {"img": "az104/img/t4_image19.webp"}, {"p": "Rule1 is configured as shown below."}, {"img": "az104/img/t4_image20.webp"}, {"p": "True or False:"}, {"p": "\"VM1 is in the same availability set as VM2.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because a Basic SKU load balancer requires that all network interfaces (NICs) connected to it be part of the same availability set. This restriction means that both VM1 and VM2 must be in the same availability set to be added to LB1 (a Basic SKU load balancer). The Basic SKU does not support flexibility across multiple availability sets, enforcing that all associated VMs are within the same availability set."}, {"img": "az104/img/t4_image21.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-overview", "https://learn.microsoft.com/en-us/azure/load-balancer/skus"], "group": "G168"}, {"id": "T4-Q39", "test": 4, "num": 39, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes the following resources:"}, {"p": "VM1 - a virtual machine"}, {"p": "VM2 - a virtual machine"}, {"p": "LB1 - a load balancer that uses the Basic SKU"}, {"p": "You install the Web Server (IIS) role on both VM1 and VM2. After the installation, you add both virtual machines to the backend pool of LB1."}, {"p": "LB1 is configured as shown below."}, {"img": "az104/img/t4_image19.webp"}, {"p": "Rule1 is configured as shown below."}, {"img": "az104/img/t4_image20.webp"}, {"p": "True or False:"}, {"p": "\"If Probe1.htm is present on VM1 and VM2, LB1 will balance traffic for TCP port 80 between VM1 and VM2.\""}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because Probe1 is configured as an HTTP probe on port 80, checking for the presence of Probe1.htm on both VM1 and VM2. If Probe1.htm is present on both virtual machines, the health probe will mark both VMs as healthy, enabling LB1 (the Basic SKU load balancer) to balance incoming traffic on TCP port 80 across VM1 and VM2. The load balancer will distribute traffic only to VMs that pass the health probe check, so the presence of Probe1.htm ensures load balancing between the two VMs."}, {"img": "az104/img/t4_image22.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-custom-probe-overview"], "group": "G168"}, {"id": "T4-Q40", "test": 4, "num": 40, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes the following resources:"}, {"p": "VM1 - a virtual machine"}, {"p": "VM2 - a virtual machine"}, {"p": "LB1 - a load balancer that uses the Basic SKU"}, {"p": "You install the Web Server (IIS) role on both VM1 and VM2. After the installation, you add both virtual machines to the backend pool of LB1."}, {"p": "LB1 is configured as shown below."}, {"img": "az104/img/t4_image19.webp"}, {"p": "Rule1 is configured as shown below."}, {"img": "az104/img/t4_image20.webp"}, {"p": "True or False:"}, {"p": "\"If you delete Rule1, LB1 will balance all the requests between VM1 and VM2 for all the ports.\""}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because if Rule1 is deleted, LB1 will lack the configuration needed to balance traffic for any ports between VM1 and VM2. Additionally, if all health probes fail for all instances in the backend pool, no new flows will be directed to the backend pool, and the Basic Load Balancer will terminate any existing TCP flows to the backend pool. Therefore, deleting Rule1 would prevent LB1 from balancing any requests across VM1 and VM2."}], "refs": ["https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-custom-probe-overview"], "group": "G168"}, {"id": "T4-Q41", "test": 4, "num": 41, "domain": "network", "stem": [{"p": "You have an Azure subscription named Subscription1 that contains a virtual machine named VM1."}, {"p": "On VM1, you install and configure the following services:"}, {"p": "A web server"}, {"p": "A DNS server"}, {"p": "VM1 has the effective network security rules shown in the following exhibit."}, {"img": "az104/img/t4_image23.webp"}, {"p": "Based on this configuration, select the option that correctly completes the following statement:"}, {"p": "“Internet users _________________________________________.”"}], "options": ["can connect to only the DNS server on VM1", "can connect to only the web server on VM1", "can connect to the web server and the DNS server on VM1", "cannot connect to the web server and the DNS server on VM1"], "correct": [1], "multi": false, "explanation": [{"p": "can connect to only the web server on VM1 is correct because the web server uses port 80, which is not blocked by any of the inbound security rules. However, Rule2 (with priority 100) explicitly denies access to ports 50-60 for all protocols, including port 53, which is used by the DNS service. Since port 53 is blocked by Rule2, internet users cannot connect to the DNS server on VM1 but can still connect to the web server."}, {"p": "Can connect to only the DNS server on VM1 is incorrect because port 53 for DNS is blocked by Rule2."}, {"p": "Can connect to the web server and the DNS server on VM1 is incorrect because the DNS port (53) is blocked."}, {"p": "Cannot connect to the web server and the DNS server on VM1 is incorrect because the web server on port 80 is still accessible."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"], "group": "G169"}, {"id": "T4-Q42", "test": 4, "num": 42, "domain": "network", "stem": [{"p": "You have an Azure subscription named Subscription1 that contains a virtual machine named VM1."}, {"p": "On VM1, you install and configure the following services:"}, {"p": "A web server"}, {"p": "A DNS server"}, {"p": "VM1 has the effective network security rules shown in the following exhibit."}, {"img": "az104/img/t4_image23.webp"}, {"p": "Based on this configuration, select the option that correctly completes the following statement:"}, {"p": "“If you delete Rule2, Internet users _________________________________________.”"}], "options": ["can connect to only the DNS server on VM1", "can connect to only the web server on VM1", "can connect to the web server and the DNS server on VM1", "cannot connect to the web server and the DNS server on VM1"], "correct": [2], "multi": false, "explanation": [{"p": "can connect to the web server and the DNS server on VM1 is correct because if Rule2 is deleted, the restriction on ports 50-60 is removed, allowing port 53 (used by DNS) to be accessible. The web server on port 80 is already accessible, as it falls outside the range that was blocked by Rule2. Therefore, with Rule2 deleted, internet users would be able to connect to both the web server (on port 80) and the DNS server (on port 53)."}, {"p": "Can connect to only the DNS server on VM1 is incorrect because port 80 for the web server is also accessible."}, {"p": "Can connect to only the web server on VM1 is incorrect because port 53 for DNS would also be accessible once Rule2 is deleted."}, {"p": "Cannot connect to the web server and the DNS server on VM1 is incorrect because deleting Rule2 allows access to both port 80 and port 53."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview"], "group": "G169"}, {"id": "T4-Q43", "test": 4, "num": 43, "domain": "network", "stem": [{"p": "You have two Azure subscriptions named Subscription1 and Subscription2."}, {"p": "Each subscription is associated with a different Microsoft Entra tenant."}, {"p": "The resources are configured as follows:"}, {"p": "Subscription1"}, {"p": "Contains a virtual network named VNet1"}, {"p": "VNet1 has an address space of 10.0.0.0/16"}, {"p": "VNet1 contains a virtual machine named VM1"}, {"p": "Subscription2"}, {"p": "Contains a virtual network named VNet2"}, {"p": "VNet2 has an address space of 10.10.0.0/24"}, {"p": "VNet2 contains a virtual machine named VM2"}, {"p": "You need to establish network connectivity between VNet1 and VNet2."}, {"p": "What should you do first?"}], "options": ["Move the virtual machine VM1 from Subscription1 to Subscription2.", "Create and configure virtual network gateways for the virtual networks.", "Move the virtual network VNet1 into Subscription2.", "Change the IP address range assigned to VNet2."], "correct": [1], "multi": false, "explanation": [{"p": "Create and configure virtual network gateways for the virtual networks is correct because to connect VNet1 in Subscription1 to VNet2 in Subscription2, you need to set up VNet-to-VNet connectivity across different subscriptions and tenants. The recommended approach for achieving this connection is to provision virtual network gateways in each virtual network and establish a VPN connection between them. This approach supports cross-subscription and cross-tenant connections."}, {"p": "Move the virtual machine VM1 from Subscription1 to Subscription2 is incorrect because moving the VM does not address the need to connect the virtual networks across different subscriptions and tenants."}, {"p": "Move the virtual network VNet1 into Subscription2 is incorrect because moving the entire virtual network to the same subscription is unnecessary when you can achieve connectivity through virtual network gateways."}, {"p": "Change the IP address range assigned to VNet2 is incorrect because there is no overlapping IP address space that would prevent connectivity; both address spaces are already compatible."}], "refs": ["https://learn.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-howto-vnet-vnet-resource-manager-portal"], "group": "G170"}, {"id": "T4-Q44", "test": 4, "num": 44, "domain": "network", "stem": [{"p": "You have an Azure subscription and plan to deploy the below Bicep file named File01.bicep."}, {"p": "param location string = resourceGroup().location"}, {"p": "resource virtualNetwork 'Microsoft.Network/virtualNetworks@2025-01-01' = {"}, {"p": "name: 'VNET1'"}, {"p": "location: location"}, {"p": "properties: {"}, {"p": "addressSpace: {"}, {"p": "addressPrefixes: ["}, {"p": "'10.0.0.0/16'"}, {"p": "]"}, {"p": "}"}, {"p": "subnets: ["}, {"p": "{"}, {"p": "name: 'Subnet-1'"}, {"p": "properties: {"}, {"p": "addressPrefix: '10.0.0.0/24'"}, {"p": "}"}, {"p": "}"}, {"p": "{"}, {"p": "name: 'Subnet-2'"}, {"p": "properties: {"}, {"p": "addressPrefix: '10.0.1.0/24'"}, {"p": "}"}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "True or False:"}, {"p": "“The virtual network will be named using the same value as the resource group’s location.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because the name of the virtual network in the provided Bicep file is explicitly set as 'VNET1'. The location parameter is assigned based on the location of the resource group, but this value only determines where the virtual network is deployed, not its name. Therefore, the name of the virtual network will be 'VNET1', regardless of the resource group's location."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-resource-manager/bicep/bicep-functions-resourcegroup"], "group": "G171"}, {"id": "T4-Q45", "test": 4, "num": 45, "domain": "network", "stem": [{"p": "You have an Azure subscription and plan to deploy the below Bicep file named File01.bicep."}, {"p": "param location string = resourceGroup().location"}, {"p": "resource virtualNetwork 'Microsoft.Network/virtualNetworks@2025-01-01' = {"}, {"p": "name: 'VNET1'"}, {"p": "location: location"}, {"p": "properties: {"}, {"p": "addressSpace: {"}, {"p": "addressPrefixes: ["}, {"p": "'10.0.0.0/16'"}, {"p": "]"}, {"p": "}"}, {"p": "subnets: ["}, {"p": "{"}, {"p": "name: 'Subnet-1'"}, {"p": "properties: {"}, {"p": "addressPrefix: '10.0.0.0/24'"}, {"p": "}"}, {"p": "}"}, {"p": "{"}, {"p": "name: 'Subnet-2'"}, {"p": "properties: {"}, {"p": "addressPrefix: '10.0.1.0/24'"}, {"p": "}"}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "True or False:"}, {"p": "“Both subnet objects will be created successfully without any deployment errors.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct because both Subnet-1 and Subnet-2 in the Bicep file have unique address prefixes (10.0.0.0/24 for Subnet-1 and 10.0.1.0/24 for Subnet-2) that fall within the address space of VNET1 (10.0.0.0/16). Since the subnets have non-overlapping address ranges within the virtual network's address space, they will be provisioned successfully."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-manage-subnet"], "group": "G171"}, {"id": "T4-Q46", "test": 4, "num": 46, "domain": "network", "stem": [{"p": "You have an Azure subscription and plan to deploy the below Bicep file named File01.bicep."}, {"p": "param location string = resourceGroup().location"}, {"p": "resource virtualNetwork 'Microsoft.Network/virtualNetworks@2025-01-01' = {"}, {"p": "name: 'VNET1'"}, {"p": "location: location"}, {"p": "properties: {"}, {"p": "addressSpace: {"}, {"p": "addressPrefixes: ["}, {"p": "'10.0.0.0/16'"}, {"p": "]"}, {"p": "}"}, {"p": "subnets: ["}, {"p": "{"}, {"p": "name: 'Subnet-1'"}, {"p": "properties: {"}, {"p": "addressPrefix: '10.0.0.0/24'"}, {"p": "}"}, {"p": "}"}, {"p": "{"}, {"p": "name: 'Subnet-2'"}, {"p": "properties: {"}, {"p": "addressPrefix: '10.0.1.0/24'"}, {"p": "}"}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "True or False:"}, {"p": "“Deploying File1.bicep multiple times will result in a deployment error.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is correct because deploying File01.bicep more than once will not inherently cause an error, as Azure Resource Manager is designed to perform idempotent deployments. This means that if you deploy the same Bicep file multiple times without changing the parameters, Azure will recognize that the resources already exist and will not attempt to recreate them, avoiding any conflict or error. Any subsequent deployments would simply update the existing resources if there are changes; otherwise, the deployment will succeed without modification."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/overview"], "group": "G171"}, {"id": "T4-Q47", "test": 4, "num": 47, "domain": "network", "stem": [{"p": "You have an on-premises environment that includes a VPN gateway."}, {"p": "Your Azure subscription contains the following resources:"}, {"p": "vgw1 – a virtual network gateway configured for a site-to-site VPN connection to the on-premises network"}, {"p": "storage1 – a storage account using the Standard performance tier"}, {"p": "Vnet1 – a virtual network with forced tunneling enabled"}, {"p": "VM1 – a virtual machine connected to Vnet1"}, {"p": "You must guarantee that any traffic originating from VM1 and destined for storage1 travels only across the Microsoft backbone network, and not through the public internet or the on-premises network."}, {"p": "What configuration should you implement?"}], "options": ["Azure Peering Service", "service endpoints", "Microsoft Entra Application Proxy", "Azure Application Gateway"], "correct": [1], "multi": false, "explanation": [{"p": "service endpoints is correct because configuring service endpoints for storage1 will ensure that traffic from VM1 to storage1 travels across the Microsoft backbone network. Service endpoints allow private access to Azure services over the Azure backbone network by extending a virtual network's identity to the Azure service. This setup secures the traffic from VM1 to storage1 by keeping it within Microsoft’s network infrastructure."}, {"p": "Azure Peering Service is incorrect because it is designed for optimizing internet traffic but does not ensure that traffic stays within the Microsoft backbone for specific resources like storage1."}, {"p": "Microsoft Entra Application Proxy is incorrect because it provides secure remote access to on-premises applications, not for managing internal Azure network traffic between resources."}, {"p": "Azure Application Gateway is incorrect as it is a layer 7 load balancer for managing HTTP/HTTPS traffic and does not direct traffic over the Microsoft backbone for a virtual machine accessing a storage account."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoints-overview"], "group": "G172"}, {"id": "T4-Q48", "test": 4, "num": 48, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes a storage account named storacc1."}, {"p": "The storacc1 account contains blob data stored in a container named cont1."}, {"p": "You plan to share access to storacc1 by generating a shared access signature (SAS)."}, {"p": "The SAS must meet the following requirements:"}, {"p": "Ensure that the SAS can only be used to enumerate and download blobs stored in cont1."}, {"p": "Use the principle of least privilege."}, {"p": "Which three settings should you enable?"}], "options": ["File", "Container", "Object", "Read", "List", "Filter"], "correct": [1, 3, 4], "multi": true, "explanation": [{"p": "Container is correct.  This level of access limits the scope to container-level operations, specifically allowing access to cont1 where the blobs are stored."}, {"p": "Read and List are correct. Enabling Read and List permissions ensures that the SAS can only enumerate and download blobs within container1. Read permission allows downloading the blobs, and List permission allows enumerating the blobs within the container."}], "refs": ["https://learn.microsoft.com/en-us/rest/api/storageservices/create-user-delegation-sas#specify-the-signed-resource-field", "https://learn.microsoft.com/en-us/rest/api/storageservices/create-user-delegation-sas#specify-permissions"], "group": "G173"}, {"id": "T4-Q49", "test": 4, "num": 49, "domain": "storage", "stem": [{"p": "You have an Azure Storage account named storage1."}, {"p": "You also have two Azure App Service applications named App1 and App2. Both applications run in Azure container instances and both use managed identities."}, {"p": "You must ensure that both App1 and App2 can read blobs stored in storage1. The solution must meet the following requirements:"}, {"p": "Use the fewest possible secrets."}, {"p": "Ensure that App2 is allowed to read data from storage1 for only the next 30 days."}, {"p": "What should you configure in storage1 for App1?"}], "options": ["Configure storage account access keys.", "Enable advanced security settings on the storage account.", "Configure role-based access control (RBAC) by using Access control (IAM).", "Generate Shared access signatures (SAS)"], "correct": [2], "multi": false, "explanation": [{"p": "Configure role-based access control (RBAC) by using Access control (IAM) is correct because Azure Role-Based Access Control (RBAC) enables you to assign the Storage Blob Data Reader role to App1’s managed identity, allowing it to read blobs in storage1 without using secrets like keys or tokens. This meets the requirement to minimize the number of secrets used. RBAC is the most secure and manageable approach for long-term access and works seamlessly with managed identities. While RBAC does not natively support automatic expiration of access after a specific period, that requirement only applies to App2."}, {"img": "az104/img/t4_image24.webp"}, {"p": "Configure storage account access keys is incorrect because access keys grant full access to the storage account and must be stored and rotated as secrets, violating the principle of least privilege."}, {"p": "Enable advanced security settings on the storage account is incorrect because it enhances storage account protection (e.g., firewalls or encryption), but it is not used to control identity-based read permissions."}, {"p": "Generate Shared access signatures (SAS) is incorrect for App1 because it involves generating and managing a token (a secret) and is better suited for time-limited access scenarios. While SAS does support expiration, it requires more overhead compared to RBAC for apps with managed identities."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/overview", "https://learn.microsoft.com/en-us/azure/azure-resource-manager/managed-applications/publish-managed-identity#granting-access-to-azure-resources"], "group": "G174"}, {"id": "T4-Q50", "test": 4, "num": 50, "domain": "storage", "stem": [{"p": "You have an Azure Storage account named storage1."}, {"p": "You also have two Azure App Service applications named App1 and App2. Both applications run in Azure container instances and both use managed identities."}, {"p": "You must ensure that both App1 and App2 can read blobs stored in storage1. The solution must meet the following requirements:"}, {"p": "Use the fewest possible secrets."}, {"p": "Ensure that App2 is allowed to read data from storage1 for only the next 30 days."}, {"p": "What should you configure in storage1 for App2?"}], "options": ["Configure storage account access keys.", "Enable advanced security settings on the storage account.", "Configure role-based access control (RBAC) by using Access control (IAM).", "Generate Shared access signatures (SAS)."], "correct": [3], "multi": false, "explanation": [{"p": "Generate Shared access signatures (SAS) is correct because it enables time-bound access by allowing you to generate a token that grants App2 read access to blobs in storage1 with an exact expiration, such as 30 days. This satisfies the requirement to limit App2’s access duration. While a SAS token is considered a secret, it’s the most practical built-in option for temporary access enforcement. It avoids the need for manual revocation logic that would be required with IAM-based roles."}, {"img": "az104/img/t4_image25.webp"}, {"p": "Configure storage account access keys is incorrect because they provide full control over the storage account and are not time-limited, making them unsuitable for scoped or temporary access."}, {"p": "Enable advanced security settings on the storage account is incorrect as it does not control time-limited access and does not apply to managed identity permissions."}, {"p": "Configure role-based access control (RBAC) by using Access control (IAM) is incorrect for App2 because RBAC does not natively support automated expiration of permissions. You would need external tooling like scripts or Azure PIM to revoke access after 30 days, which is less direct than a SAS token with an expiration."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/common/storage-sas-overview", "https://learn.microsoft.com/en-us/azure/storage/common/authorize-data-access?tabs=blobs"], "group": "G174"}, {"id": "T4-Q51", "test": 4, "num": 51, "domain": "storage", "stem": [{"p": "You have a Microsoft Entra user named User1 and an Azure Storage account named contoso2026 that uses read-access geo-redundant storage (RA-GRS)."}, {"p": "You must meet the following requirements:"}, {"p": "User1 must be able to write blob data to contoso2026."}, {"p": "The contoso2026 storage account must be able to fail over to its secondary endpoint."}, {"p": "Which two settings should you configure?"}], "options": ["Access Control (IAM)", "Access Keys", "Shared access signature", "Redundancy"], "correct": [0, 3], "multi": true, "explanation": [{"p": "Access Control (IAM) is correct because to enable User1 to write blob data to contoso2026, you can assign the Storage Blob Data Contributor role to User1 through Access Control (IAM). This role provides the necessary permissions for writing blob data without using account keys or SAS tokens, aligning with best practices for managing access in Azure."}, {"p": "Redundancy is correct because to configure contoso2026 to fail over to its secondary endpoint, you need to adjust the Redundancy setting. This setting allows you to manage the geo-redundant failover behavior for the storage account, enabling automatic or manual failover to the secondary region when needed."}, {"p": "Access Keys is incorrect because using access keys would not meet the principle of least privilege and would grant full access rather than just write permissions."}, {"p": "Shared access signature is incorrect because while it can provide specific permissions, using IAM roles is a more secure and manageable way to provide User1 with write access."}], "refs": ["https://docs.microsoft.com/en-us/azure/storage/common/storage-redundancy#read-access-geo-redundant-storage", "https://docs.microsoft.com/en-us/azure/storage/common/storage-initiate-account-failover?tabs=azure-portal", "https://docs.microsoft.com/en-us/azure/role-based-access-control/overview", "https://docs.microsoft.com/en-us/azure/storage/common/storage-sas-overview", "https://docs.microsoft.com/en-us/azure/storage/common/storage-account-keys-manage"], "group": "G175"}, {"id": "T4-Q52", "test": 4, "num": 52, "domain": "compute", "stem": [{"p": "You have the following App Service plans:"}, {"p": "ASP1"}, {"p": "OS: Windows"}, {"p": "Region: West US"}, {"p": "ASP2"}, {"p": "OS: Windows"}, {"p": "Region: Central US"}, {"p": "ASP3"}, {"p": "OS: Linux"}, {"p": "Region: West US"}, {"p": "You plan to create the following Azure web apps:"}, {"p": "WebApp1"}, {"p": "Runtime stack: .NET 8 (LTS)"}, {"p": "Location: West US"}, {"p": "WebApp2"}, {"p": "Runtime stack: ASP.NET 4.8"}, {"p": "Location: West US"}, {"p": "Which App Service plan can be used to host WebApp1?"}], "options": ["ASP1 only", "ASP3 only", "ASP1 and ASP2 only", "ASP1 and ASP3 only", "ASP1, ASP2, and ASP3"], "correct": [3], "multi": false, "explanation": [{"p": "ASP1 and ASP3 only is correct because WebApp1 requires a .NET 8 (LTS) runtime stack, which is supported on both Windows and Linux platforms. ASP1 is a Windows-based App Service plan in the West US region, which aligns with the requirements for WebApp1. ASP3 is a Linux-based App Service plan, also located in the West US region, which is compatible with .NET 8. Therefore, both ASP1 and ASP3 can host WebApp1."}, {"img": "az104/img/t4_image26.webp"}, {"p": "ASP1 only is incorrect because ASP3 can also support .NET 8 (LTS) on Linux."}, {"p": "ASP3 only is incorrect because ASP1 also supports .NET 8 (LTS) on Windows."}, {"p": "ASP1 and ASP2 only is incorrect because ASP2 is in the Central US region, which does not align with the West US requirement for WebApp1."}, {"p": "ASP1, ASP2, and ASP3 is incorrect because ASP2 is not in the West US region."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/overview"], "group": "G176"}, {"id": "T4-Q53", "test": 4, "num": 53, "domain": "compute", "stem": [{"p": "You have the following App Service plans:"}, {"p": "ASP1"}, {"p": "OS: Windows"}, {"p": "Region: West US"}, {"p": "ASP2"}, {"p": "OS: Windows"}, {"p": "Region: Central US"}, {"p": "ASP3"}, {"p": "OS: Linux"}, {"p": "Region: West US"}, {"p": "You plan to create the following Azure web apps:"}, {"p": "WebApp1"}, {"p": "Runtime stack: .NET 8 (LTS)"}, {"p": "Location: West US"}, {"p": "WebApp2"}, {"p": "Runtime stack: ASP.NET 4.8"}, {"p": "Location: West US"}, {"p": "Which App Service plan can be used to host WebApp2?"}], "options": ["ASP1 only", "ASP3 only", "ASP1 and ASP2 only", "ASP1 and ASP3 only", "ASP1, ASP2, and ASP3"], "correct": [0], "multi": false, "explanation": [{"p": "ASP1 only is correct because WebApp2 requires the ASP.NET 4.8 runtime stack, which is supported only on Windows-based App Service plans. ASP1 is a Windows-based App Service plan in the West US region, matching the requirements for WebApp2."}, {"p": "In the screenshot below, you can see that the Linux option for the Operating System is greyed out when the Runtime stack is selected as ASP.NET 4.8."}, {"img": "az104/img/t4_image27.webp"}, {"p": "ASP3 only is incorrect because ASP3 is a Linux-based plan, which does not support the ASP.NET 4.8 runtime stack."}, {"p": "ASP1 and ASP2 only is incorrect because, although ASP2 is a Windows-based plan, it is in the Central US region, whereas WebApp2 requires a plan in the West US region."}, {"p": "ASP1 and ASP3 only is incorrect because ASP3 does not support ASP.NET 4.8."}, {"p": "ASP1, ASP2, and ASP3 is incorrect because ASP2 and ASP3 do not meet the requirements for WebApp2 due to either region mismatch or OS incompatibility."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/"], "group": "G176"}, {"id": "T4-Q54", "test": 4, "num": 54, "domain": "network", "stem": [{"p": "Your on-premises network hosts an Active Directory Domain Services (AD DS) domain named apexcore.com. The domain includes the following servers:"}, {"img": "az104/img/t4_image28.webp"}, {"p": "You are planning to migrate the apexcore.com domain to Azure."}, {"p": "You create an Azure virtual network named VNET1 with these configurations:"}, {"p": "Address space: 10.0.0.0/16"}, {"p": "Subnet configuration:"}, {"p": "Subnet name: Subnet1"}, {"p": "IPv4 address range: 10.0.1.0/24"}, {"p": "You need to move DC1 into VNET1. The configuration must ensure that all member servers in apexcore.com can continue to resolve Active Directory DNS records correctly."}, {"p": "How should the IP address be configured?"}], "options": ["Obtain an IP address automatically.", "Use 10.0.1.3", "Use 10.0.2.1", "Use 192.168.2.1"], "correct": [0], "multi": false, "explanation": [{"p": "Obtain an IP address automatically is correct because, out of the options given, this is the most feasible solution. While it's generally best practice to assign a static IP to a Domain Controller (DC) to ensure consistent DNS resolution, obtaining an IP automatically can work as long as DC1 remains active. If DC1 is shut down, it may receive a different IP upon restart, which could disrupt DNS resolution."}, {"p": "Use 10.0.1.3 is incorrect because the first four IP addresses within a subnet range (like 10.0.1.0/24) are reserved by Azure, making 10.0.1.3 unavailable for assignment."}, {"p": "Use 10.0.2.1 is incorrect because, although it’s within the overall VNET1 address space, it falls outside of Subnet1’s range (10.0.1.0/24), which would prevent proper network connectivity."}, {"p": "Use 192.168.2.1 is incorrect as this IP is part of the on-premises network and does not exist within VNET1’s address space, making it unusable in the Azure virtual network."}], "refs": ["https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/ready/azure-best-practices/dns-for-on-premises-and-azure-resources"], "group": "G177"}, {"id": "T4-Q55", "test": 4, "num": 55, "domain": "network", "stem": [{"p": "Your on-premises network hosts an Active Directory Domain Services (AD DS) domain named apexcore.com. The domain includes the following servers:"}, {"img": "az104/img/t4_image28.webp"}, {"p": "You are planning to migrate the apexcore.com domain to Azure."}, {"p": "You create an Azure virtual network named VNET1 with these configurations:"}, {"p": "Address space: 10.0.0.0/16"}, {"p": "Subnet configuration:"}, {"p": "Subnet name: Subnet1"}, {"p": "IPv4 address range: 10.0.1.0/24"}, {"p": "You need to move DC1 into VNET1. The configuration must ensure that all member servers in apexcore.com can continue to resolve Active Directory DNS records correctly."}, {"p": "How should the Name resolution be configured?"}], "options": ["Configure VNET1 to use a custom DNS server.", "Configure VNET1 to use the default Azure-provided DNS server.", "Create an Azure Private DNS zone named apexcore.com.", "Create an Azure public DNS zone named apexcore.com."], "correct": [0], "multi": false, "explanation": [{"p": "Configure VNET1 to use a custom DNS server is correct because to ensure that the member servers in apexcore.com can resolve Active Directory Domain Services (AD DS) DNS names, VNET1 should be configured to use the IP address of DC1 (acting as the DNS server) as a custom DNS server. This configuration will allow resources within VNET1 to resolve DNS queries for apexcore.com using DC1's DNS service, which is essential for Active Directory domain name resolution."}, {"p": "Configure VNET1 to use the default Azure-provided DNS server is incorrect because Azure’s default DNS server does not support resolving on-premises or custom domain names like apexcore.com."}, {"p": "Create an Azure Private DNS zone named apexcore.com is incorrect because, while a private DNS zone could theoretically support name resolution, it would not integrate seamlessly with AD DS DNS requirements. Using DC1 as the DNS server directly provides better compatibility with AD DS."}, {"p": "Create an Azure public DNS zone named apexcore.com is incorrect because a public DNS zone is intended for resolving internet-facing names and is not suitable for internal AD DS name resolution within VNET1."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-name-resolution-for-vms-and-role-instances#name-resolution-that-uses-your-own-dns-server", "https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/ready/azure-best-practices/dns-for-on-premises-and-azure-resources"], "group": "G177"}, {"id": "T4-Q56", "test": 4, "num": 56, "domain": "storage", "stem": [{"p": "You have an Azure subscription that includes a virtual machine named VM1."}, {"p": "You plan to attach a 1 TB data disk to VM1. The disk must meet the following requirements:"}, {"p": "It must remain available if an entire datacenter becomes unavailable."}, {"p": "It must deliver the lowest possible latency and the highest performance."}, {"p": "It must prevent data loss in the event that the host fails."}, {"p": "Which storage type should you choose?"}], "options": ["Premium SSD that uses locally-redundant storage (LRS)", "Premium SSD that uses zone-redundant storage (ZRS)", "Standard SSD that uses locally-redundant storage (LRS)", "Standard SSD that uses zone-redundant storage (ZRS)"], "correct": [1], "multi": false, "explanation": [{"p": "Premium SSD that uses zone-redundant storage (ZRS) is correct because it provides data resiliency by replicating data across multiple availability zones, ensuring that data remains available in the event of a datacenter outage. Additionally, Premium SSDs offer the lowest latency and highest performance compared to Standard SSDs. The use of ZRS ensures that data is also protected against potential failures within a specific zone, meeting the requirement of no data loss in case of a host or datacenter failure."}, {"p": "Premium SSD that uses locally-redundant storage (LRS) is incorrect because while it provides high performance and low latency, LRS only replicates data within a single datacenter, which does not provide resiliency in the event of a datacenter outage."}, {"p": "Standard SSD that uses locally-redundant storage (LRS) is incorrect because Standard SSDs do not meet the requirement for the highest performance and low latency, and LRS does not protect against datacenter outages."}, {"p": "Standard SSD that uses zone-redundant storage (ZRS) is incorrect because, while ZRS provides data resiliency across zones, Standard SSDs lack the performance and low latency required."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-machines/overview", "https://learn.microsoft.com/en-us/azure/architecture/example-scenario/identity/adds-extend-domain#vm-recommendations"], "group": "G178"}, {"id": "T4-Q57", "test": 4, "num": 57, "domain": "storage", "stem": [{"p": "You have an Azure subscription that includes a virtual machine named VM1."}, {"p": "You plan to attach a 1 TB data disk to VM1. The disk must meet the following requirements:"}, {"p": "It must remain available if an entire datacenter becomes unavailable."}, {"p": "It must deliver the lowest possible latency and the highest performance."}, {"p": "It must prevent data loss in the event that the host fails."}, {"p": "Which host caching would you recommend?"}], "options": ["None", "Read-only", "Read/Write"], "correct": [1], "multi": false, "explanation": [{"p": "Read-only is correct because it provides a balance between performance and data durability. Enabling Read-only caching on a Premium SSD with zone-redundant storage (ZRS) allows frequently accessed data to be cached, which enhances read performance without risking significant data loss. In the event of a host failure, data is read from the redundant storage across zones, ensuring data resiliency. Since only read operations are cached, the data stored on disk remains consistent and resilient to host failures, addressing the requirement of no data loss."}, {"p": "Although None caching eliminates any risk of data loss, Read-only caching is acceptable for workloads that prioritize high performance and data resiliency, as it does not impact data integrity during writes."}, {"p": "None is incorrect because, while it prevents any risk of data loss, it does not utilize the performance benefits of read caching, which may be desirable for high-performance workloads with Premium SSD storage."}, {"p": "Read/Write is incorrect as it caches both read and write operations on the host, which can result in data loss in the event of a host failure. This does not meet the requirement to ensure that no data loss occurs if a host fails."}], "refs": ["https://learn.microsoft.com/en-us/azure/architecture/example-scenario/identity/adds-extend-domain#vm-recommendations"], "group": "G178"}, {"id": "T4-Q58", "test": 4, "num": 58, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes the following resources:"}, {"p": "VNet1 - Virtual network located in West US, in RG2"}, {"p": "VNet2 - Virtual network located in West US, in RG1"}, {"p": "VNet3 - Virtual network located in East US, in RG1"}, {"p": "NSG1 - Network security group located in East US, in RG2"}, {"p": "To which subnets can you apply NSG1?"}], "options": ["the subnets on VNet1 only", "the subnets on VNet2 only", "the subnets on VNet3 only", "the subnets on VNet2 and VNet3 only", "the subnets on VNet1, VNet2, and VNet3"], "correct": [2], "multi": false, "explanation": [{"p": "the subnets on VNet3 only is correct because a network security group (NSG) must be in the same region as the virtual network or subnets to which it is applied. NSG1 is in the East US region, and therefore it can only be applied to the subnets within VNet3, as VNet3 is also in the East US region."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview", "https://learn.microsoft.com/en-us/azure/security/fundamentals/network-best-practices"], "group": "G179"}, {"id": "T4-Q59", "test": 4, "num": 59, "domain": "identity", "stem": [{"p": "Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You have a Microsoft Entra tenant named ironclad.com and an Azure subscription named Subscription1. The tenant contains a group called Developers. The subscription contains a resource group named Dev."}, {"p": "You need to allow the Developers group to create Azure Logic Apps in the Dev resource group."}, {"p": "Proposed Solution: You assign the Contributor role to the Developers group at the Dev resource group scope."}, {"p": "Does this configuration satisfy the requirement?"}], "options": ["Yes", "No"], "correct": [0], "multi": false, "explanation": [{"p": "Yes is correct because assigning the Contributor role to the Developers group at the Dev resource group level allows the group members to manage all resources within the resource group, including the ability to create Azure Logic Apps. The Contributor role provides full access to manage resources without granting permissions to assign roles or manage access, which fulfills the requirement stated in the question."}, {"img": "az104/img/t4_image29.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#contributor"], "group": "G180"}, {"id": "T4-Q60", "test": 4, "num": 60, "domain": "identity", "stem": [{"p": "Note: This question is part of a series that uses the same overall scenario. Each question in the series proposes a different solution that may or may not satisfy the stated requirement."}, {"p": "You have a Microsoft Entra tenant named ironclad.com and an Azure subscription named Subscription1. The tenant contains a group called Developers. The subscription contains a resource group named Dev."}, {"p": "You need to allow the Developers group to create Azure Logic Apps in the Dev resource group."}, {"p": "Proposed Solution: On the Dev resource group, you grant the Logic App Contributor role to the Developers group."}, {"p": "Does this configuration satisfy the requirement?"}], "options": ["Yes", "No"], "correct": [0], "multi": false, "explanation": [{"p": "Yes is correct because the Logic App Contributor role provides the necessary permissions to manage Azure Logic Apps within the assigned scope, which includes creating, updating, and deleting logic apps. Assigning this role to the Developers group at the Dev resource group level fulfills the requirement to allow the group to create Azure Logic Apps in the Dev resource group without granting broader permissions."}, {"img": "az104/img/t4_image30.webp"}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#logic-app-contributor"], "group": "G180"}, {"id": "T4-Q61", "test": 4, "num": 61, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes a virtual network named VNet1."}, {"p": "VNet1 uses the IP address space 10.0.0.0/16 and contains the following subnets:"}, {"p": "Subnet0 (IP address range: 10.0.0.0/24)"}, {"p": "Subnet1 (IP address range: 10.0.1.0/24)"}, {"p": "Subnet2 (IP address range: 10.0.2.0/24)"}, {"p": "GatewaySubnet (IP address range: 10.0.254.0/24)"}, {"p": "Subnet1 hosts a virtual appliance named VM1, which functions as a router."}, {"p": "You create a route table named RT1."}, {"p": "You need to ensure that all inbound traffic arriving from the VPN gateway into VNet1 is routed through VM1."}, {"p": "You plan to configure RT1 accordingly."}, {"p": "What value should you specify for the address prefix?"}], "options": ["10.0.0.0/16", "10.0.1.0/24", "10.0.254.0/24"], "correct": [0], "multi": false, "explanation": [{"p": "10.0.0.0/16 is correct because it represents the entire IP address range of VNet1, including all its subnets (Subnet0, Subnet1, Subnet2, and GatewaySubnet). Configuring this address prefix in the route table ensures that all traffic arriving at the VPN gateway and destined for any subnet in VNet1 is routed through the virtual appliance (VM1) in Subnet1."}, {"p": "10.0.1.0/24 is incorrect because this prefix only applies to Subnet1. Configuring RT1 with this prefix will not ensure that all traffic from the VPN gateway to the other subnets passes through VM1."}, {"p": "10.0.254.0/24 is incorrect because this prefix refers specifically to the GatewaySubnet. It does not cover the entire VNet, and traffic to other subnets will not be routed through VM1."}], "refs": ["https://azure.microsoft.com/en-in/solutions/network-appliances", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview"], "group": "G181"}, {"id": "T4-Q62", "test": 4, "num": 62, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes a virtual network named VNet1."}, {"p": "VNet1 uses the IP address space 10.0.0.0/16 and contains the following subnets:"}, {"p": "Subnet0 (IP address range: 10.0.0.0/24)"}, {"p": "Subnet1 (IP address range: 10.0.1.0/24)"}, {"p": "Subnet2 (IP address range: 10.0.2.0/24)"}, {"p": "GatewaySubnet (IP address range: 10.0.254.0/24)"}, {"p": "Subnet1 hosts a virtual appliance named VM1, which functions as a router."}, {"p": "You create a route table named RT1."}, {"p": "You need to ensure that all inbound traffic arriving from the VPN gateway into VNet1 is routed through VM1."}, {"p": "You plan to configure RT1 accordingly."}, {"p": "What value should you specify for the next hop type?"}], "options": ["Virtual appliance", "Virtual network", "Virtual network gateway"], "correct": [0], "multi": false, "explanation": [{"p": "Virtual appliance is correct because the virtual appliance next-hop type is used when traffic needs to be routed through a specific virtual machine or network virtual appliance (NVA). In this scenario, VM1 in Subnet1 acts as a router for all inbound traffic from the VPN gateway. The routing table RT1 should use the \"Virtual appliance\" next-hop type to direct traffic to the virtual machine."}, {"p": "Virtual network is incorrect because it refers to routing traffic within the virtual network itself, not specifically through a virtual machine or appliance acting as a router."}, {"p": "Virtual network gateway is incorrect because it refers to routing traffic to or through an Azure VPN Gateway. In this case, the traffic has already reached the VPN Gateway and needs to be routed through the virtual appliance (VM1)."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview", "https://azure.microsoft.com/en-in/solutions/network-appliances"], "group": "G181"}, {"id": "T4-Q63", "test": 4, "num": 63, "domain": "network", "stem": [{"p": "You have an Azure subscription that includes a virtual network named VNet1."}, {"p": "VNet1 uses the IP address space 10.0.0.0/16 and contains the following subnets:"}, {"p": "Subnet0 (IP address range: 10.0.0.0/24)"}, {"p": "Subnet1 (IP address range: 10.0.1.0/24)"}, {"p": "Subnet2 (IP address range: 10.0.2.0/24)"}, {"p": "GatewaySubnet (IP address range: 10.0.254.0/24)"}, {"p": "Subnet1 hosts a virtual appliance named VM1, which functions as a router."}, {"p": "You create a route table named RT1."}, {"p": "You need to ensure that all inbound traffic arriving from the VPN gateway into VNet1 is routed through VM1."}, {"p": "You plan to configure RT1 accordingly."}, {"p": "Which option should you select for the Assigned to setting?"}], "options": ["GatewaySubnet", "Subnet0", "Subnet1 and Subnet2"], "correct": [0], "multi": false, "explanation": [{"p": "GatewaySubnet is correct because the routing table RT1 must be associated with the GatewaySubnet to ensure that all traffic coming from the VPN Gateway is routed through the virtual appliance (VM1) in Subnet1. The GatewaySubnet is a dedicated subnet for VPN Gateway and requires proper routing configuration to direct traffic appropriately."}, {"p": "Subnet0 is incorrect because associating the route table with Subnet0 would not ensure that traffic from the VPN Gateway is routed through the virtual appliance in Subnet1."}, {"p": "Subnet1 and Subnet2 is incorrect because associating the route table with these subnets does not target the GatewaySubnet, which is the entry point for VPN traffic. Routing must start from the GatewaySubnet."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-udr-overview", "https://learn.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-about-vpn-gateway-settings", "https://azure.microsoft.com/en-in/solutions/network-appliances"], "group": "G181"}, {"id": "T4-Q64", "test": 4, "num": 64, "domain": "network", "stem": [{"p": "You have a virtual network named VNET1 that includes the following subnets:"}, {"img": "az104/img/t4_image31.webp"}, {"p": "You also have the following Azure virtual machines with the listed network configurations:"}, {"img": "az104/img/t4_image32.webp"}, {"p": "For NSG1, you configure the following inbound security rule:"}, {"p": "Priority: 101"}, {"p": "Source: 10.10.2.0/24"}, {"p": "Destination: 10.10.1.0/24"}, {"p": "Destination port: TCP 1433"}, {"p": "Action: Allow"}, {"p": "For NSG2, you configure the following inbound security rule:"}, {"p": "Priority: 125"}, {"p": "Source: 10.10.2.5"}, {"p": "Destination: 10.10.1.5"}, {"p": "Destination port: TCP 1433"}, {"p": "Action: Block"}, {"p": "True or False:"}, {"p": "“VM2 can connect to the TCP port 1433 services on VM1.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer because the traffic from VM2 to VM1 on TCP port 1433 must be allowed by both NSGs in the inbound path. For inbound traffic to VM1, Azure evaluates the subnet-level NSG first and then the NIC-level NSG. NSG1 allows TCP 1433 traffic from 10.10.2.0/24 to 10.10.1.0/24, so the traffic is allowed at the subnet level. However, NSG2, which is associated with VM1’s NIC, explicitly blocks TCP 1433 traffic from 10.10.2.5 to 10.10.1.5. Since the traffic is denied at the NIC level, the connection from VM2 to VM1 fails."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/network-security-group-how-it-works"], "group": "G182"}, {"id": "T4-Q65", "test": 4, "num": 65, "domain": "network", "stem": [{"p": "You have a virtual network named VNET1 that includes the following subnets:"}, {"img": "az104/img/t4_image31.webp"}, {"p": "You also have the following Azure virtual machines with the listed network configurations:"}, {"img": "az104/img/t4_image32.webp"}, {"p": "For NSG1, you configure the following inbound security rule:"}, {"p": "Priority: 101"}, {"p": "Source: 10.10.2.0/24"}, {"p": "Destination: 10.10.1.0/24"}, {"p": "Destination port: TCP 1433"}, {"p": "Action: Allow"}, {"p": "For NSG2, you configure the following inbound security rule:"}, {"p": "Priority: 125"}, {"p": "Source: 10.10.2.5"}, {"p": "Destination: 10.10.1.5"}, {"p": "Destination port: TCP 1433"}, {"p": "Action: Block"}, {"p": "True or False:"}, {"p": "“VM1 can connect to the TCP port 1433 services on VM2.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer because there are no Network Security Groups (NSGs) applied to Subnet2, where VM2 resides, or directly to VM2's network interface. NSG1 is applied at Subnet1, allowing traffic from Subnet2 to Subnet1 on TCP port 1433. NSG2 is applied at VM1's network interface, but it explicitly blocks inbound traffic from 10.10.2.5 (VM2) to 10.10.1.5 (VM1) on TCP port 1433. However, the direction of traffic in this question is from VM1 to VM2, not the other way around. Therefore, the NSG rules blocking inbound traffic on VM1 do not apply in this scenario, and the outbound connection from VM1 to VM2 is not blocked."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/network-security-group-how-it-works"], "group": "G182"}, {"id": "T4-Q66", "test": 4, "num": 66, "domain": "network", "stem": [{"p": "You have a virtual network named VNET1 that includes the following subnets:"}, {"img": "az104/img/t4_image31.webp"}, {"p": "You also have the following Azure virtual machines with the listed network configurations:"}, {"img": "az104/img/t4_image32.webp"}, {"p": "For NSG1, you configure the following inbound security rule:"}, {"p": "Priority: 101"}, {"p": "Source: 10.10.2.0/24"}, {"p": "Destination: 10.10.1.0/24"}, {"p": "Destination port: TCP 1433"}, {"p": "Action: Allow"}, {"p": "For NSG2, you configure the following inbound security rule:"}, {"p": "Priority: 125"}, {"p": "Source: 10.10.2.5"}, {"p": "Destination: 10.10.1.5"}, {"p": "Destination port: TCP 1433"}, {"p": "Action: Block"}, {"p": "True or False:"}, {"p": "“VM2 can connect to the TCP port 1433 services on VM3.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer because there are no Network Security Groups (NSGs) applied to Subnet2, where VM3 resides, or directly to VM3's network interface. NSG1, applied to Subnet1, allows traffic from Subnet2 (10.10.2.0/24) to Subnet1 (10.10.1.0/24) on TCP port 1433."}, {"p": "The rule in NSG2 that blocks inbound traffic specifically applies to traffic from VM2 (10.10.2.5) to VM1 (10.10.1.5), but not to VM3 (10.10.2.6). Therefore, VM2 can successfully connect to TCP port 1433 services on VM3 without restriction."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/network-security-group-how-it-works"], "group": "G182"}, {"id": "T4-Q67", "test": 4, "num": 67, "domain": "network", "stem": [{"p": "You have four Azure virtual machines with the following configurations:"}, {"p": "VM1 – IP address 10.1.0.4, connected to VNET1/Subnet1"}, {"p": "VM2 – IP address 10.1.10.4, connected to VNET1/Subnet2"}, {"p": "VM3 – IP address 172.16.0.4, connected to VNET2/SubnetA"}, {"p": "VM4 – IP address 10.2.0.8, connected to VNET3/SubnetB"}, {"p": "A DNS service is installed on VM1."}, {"p": "You configure the DNS server settings on each virtual network to use a custom DNS server with the IP address 10.1.0.4."}, {"p": "You need to ensure that all the virtual machines can resolve DNS names by using the DNS service on VM1."}, {"p": "What action should you take?"}], "options": ["Add service endpoints on VNET2 and VNET3.", "Configure peering between VNET1, VNET2, and VNET3.", "Add service endpoints on VNET1.", "Configure a conditional forwarder on VM1."], "correct": [1], "multi": false, "explanation": [{"p": "Configure peering between VNET1, VNET2, and VNET3 is the correct option because DNS queries sent to a custom DNS server (VM1 in this case) require network connectivity between the virtual networks. Virtual network peering allows resources in different VNets to communicate seamlessly. Once peering is configured, all DNS traffic can route correctly through VM1."}, {"img": "az104/img/t4_image33.webp"}, {"p": "Add service endpoints on VNET2 and VNET3 is incorrect because service endpoints are used for secure connections to Azure services like Storage or SQL, not for enabling DNS resolution between VNets."}, {"p": "Add service endpoints on VNET1 is incorrect for the same reason, as service endpoints don't facilitate cross-VNet DNS resolution."}, {"p": "Configure a conditional forwarder on VM1 is incorrect because a conditional forwarder directs DNS queries to specific DNS servers based on domain names. However, without VNet peering, the DNS traffic wouldn't route between VNets."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-networks-name-resolution-for-vms-and-role-instances", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-service-endpoints-overview", "https://learn.microsoft.com/en-us/azure/dns/private-dns-overview"], "group": "G183"}, {"id": "T4-Q68", "test": 4, "num": 68, "domain": "monitor", "stem": [{"p": "You intend to use Azure Network Watcher to perform the following activity:"}, {"p": "Test and confirm outbound network connectivity from an Azure virtual machine to an external destination."}, {"p": "Which feature should you use for the above task?"}], "options": ["Connection troubleshoot", "IP flow verify", "Next hop", "NSG flow logs", "Traffic Analytics"], "correct": [0], "multi": false, "explanation": [{"p": "Connection troubleshoot is the correct option because it is specifically designed to validate outbound connectivity from an Azure virtual machine (VM) to an external host. This feature checks the end-to-end connection and identifies if the connection succeeds or fails, providing insights into network latency, packet loss, and the point of failure."}, {"p": "IP flow verify is incorrect because it checks whether a specific packet is allowed or denied by security rules, but it does not validate the entire outbound connection path."}, {"p": "Next hop is incorrect because it shows the next hop a packet will take to reach its destination but does not validate the outbound connection itself."}, {"p": "NSG flow logs is incorrect because it provides a record of traffic through network security groups (NSGs) but does not validate outbound connectivity."}, {"p": "Traffic Analytics is incorrect because it analyzes traffic patterns and usage but does not validate specific outbound connections."}], "refs": ["https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-connectivity-overview", "https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-overview"], "group": "G184"}, {"id": "T4-Q69", "test": 4, "num": 69, "domain": "monitor", "stem": [{"p": "You intend to use Azure Network Watcher to perform the following activity:"}, {"p": "Determine which security rule is blocking a network packet from reaching an Azure virtual machine."}, {"p": "Which feature should you use for the above task?"}], "options": ["IP flow verify", "Next hop", "Packet capture", "Traffic Analytics"], "correct": [0], "multi": false, "explanation": [{"p": "IP flow verify is the correct option because this feature in Azure Network Watcher is specifically designed to identify whether a network packet is allowed or denied to or from an Azure virtual machine (VM). It evaluates the effective security rules applied to the VM's network interface and identifies the rule responsible for blocking or allowing the traffic."}, {"p": "Next hop is incorrect because it helps determine the route a packet takes to reach its destination but does not identify security rules blocking traffic."}, {"p": "Packet capture is incorrect because it captures live packet data for network traffic but does not identify which security rule is affecting the traffic."}, {"p": "Traffic Analytics is incorrect because it provides insights into traffic flow patterns and network resource usage, but it does not identify the specific security rule blocking traffic."}], "refs": ["https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-ip-flow-verify-overview", "https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-overview"], "group": "G185"}, {"id": "T4-Q70", "test": 4, "num": 70, "domain": "identity", "stem": [{"p": "You have an Azure subscription named Subscription1 that includes a virtual network called VNet1, which resides in a resource group named RG1."}, {"p": "A user named User1 has been assigned the following roles at the Subscription1 scope:"}, {"p": "Reader"}, {"p": "Security Admin"}, {"p": "Security Reader"}, {"p": "You must ensure that User1 is able to assign the Reader role on VNet1 to other users."}, {"p": "What action should you take?"}], "options": ["Remove User1 from the Security Reader and Reader roles at the Subscription1 level, and then assign User1 the Contributor role for Subscription1.", "Remove User1 from the Security Reader and Reader roles at the Subscription1 level.", "Assign User1 the User Access Administrator role at the VNet1 scope.", "Remove User1 from the Security Reader role at the Subscription1 level, and then assign User1 the Contributor role for the RG1 resource group."], "correct": [2], "multi": false, "explanation": [{"p": "Assign User1 the User Access Administrator role at the VNet1 scope is the correct answer because the User Access Administrator role allows a user to manage user access to resources, including assigning RBAC roles such as Reader to other users. While User1 already has the Reader, Security Admin, and Security Reader roles, none of these roles grant the ability to assign RBAC roles to other users. Assigning the User Access Administrator role at the scope of VNet1 ensures that User1 has the necessary permissions to assign roles without granting broader privileges at the subscription or resource group level, adhering to the principle of least privilege."}, {"p": "Remove User1 from the Security Reader and Reader roles at the Subscription1 level, and then assign User1 the Contributor role for Subscription1 is incorrect because the Contributor role allows managing resources but does not grant role assignment capabilities."}, {"p": "Remove User1 from the Security Reader and Reader roles at the Subscription1 level is incorrect because simply removing existing roles does not grant any permissions for role assignment."}, {"p": "Remove User1 from the Security Reader role at the Subscription1 level, and then assign User1 the Contributor role for the RG1 resource group is incorrect because the Contributor role at the resource group level (RG1) does not allow assigning roles for VNet1."}], "refs": ["https://learn.microsoft.com/en-us/azure/role-based-access-control/built-in-roles", "https://learn.microsoft.com/en-us/azure/role-based-access-control/role-definitions", "https://learn.microsoft.com/en-us/azure/role-based-access-control/overview"], "group": "G186"}, {"id": "T4-Q71", "test": 4, "num": 71, "domain": "monitor", "stem": [{"p": "You have an Azure subscription that includes the following resources:"}, {"p": "Ten network security groups (NSGs)"}, {"p": "Ten virtual machines"}, {"p": "One Log Analytics workspace named Workspace1"}, {"p": "Each network security group is associated with the network interface of a virtual machine."}, {"p": "You want to configure an Azure Monitor Network Insights alert that triggers when suspicious network traffic is detected."}, {"p": "What action should you perform first?"}], "options": ["Deploy Connection Monitor.", "Configure NSG flow logs.", "Configure data collection endpoints.", "Configure a private link."], "correct": [1], "multi": false, "explanation": [{"p": "Configure NSG flow logs is the correct answer because Azure Monitor Network Insights relies on NSG flow logs to analyze and detect suspicious network traffic. NSG flow logs capture detailed information about IP traffic flowing through network security groups, including source and destination IPs, ports, and protocols."}, {"p": "Enabling NSG flow logs is a prerequisite for Azure Monitor to process network traffic data and identify anomalies or suspicious activities. These logs are sent to a Log Analytics workspace (e.g., Workspace1) for further analysis."}, {"p": "Deploy Connection Monitor is incorrect because Connection Monitor is used for monitoring network connectivity and performance between Azure resources or between Azure and on-premises resources. It does not directly facilitate alerting based on suspicious network traffic."}, {"p": "Configure data collection endpoints is incorrect because data collection endpoints (DCEs) are primarily used for routing Azure Monitor Agent data. They are not directly related to enabling NSG flow logs or configuring Network Insights alerts."}, {"p": "Configure a private link is incorrect because private links are used to securely access Azure services over a private IP address. They do not play a role in enabling network traffic analysis or triggering alerts for suspicious traffic."}], "refs": ["https://learn.microsoft.com/en-us/azure/network-watcher/nsg-flow-logs-overview", "https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-overview", "https://learn.microsoft.com/en-us/azure/network-watcher/network-insights-overview"], "group": "G187"}, {"id": "T4-Q72", "test": 4, "num": 72, "domain": "storage", "stem": [{"p": "You have an Azure Storage account named storage1 that has the Blob service properties shown in the following exhibit."}, {"img": "az104/img/t4_image34.webp"}, {"p": "On January 1, the following blobs are uploaded to storage1:"}, {"p": "File1 is stored in the Hot access tier"}, {"p": "File2 is stored in the Cool access tier"}, {"p": "File3 is stored in the Archive access tier"}, {"p": "You then perform these actions:"}, {"p": "On January 5, File1 is deleted"}, {"p": "On January 15, File2 is moved to the Archive access tier"}, {"p": "On April 5, File3 is rehydrated"}, {"p": "True or False:"}, {"p": "“You are charged an early deletion penalty for File1.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer here. File1 was uploaded to the storage account under the Hot access tier on January 1 and then deleted on January 5. The Hot tier does not have an early deletion penalty, regardless of the deletion time."}, {"p": "For reference, the access tiers and their minimum retention periods for avoiding early deletion charges are as follows:"}, {"p": "Hot: No minimum retention period; early deletion penalty does not apply."}, {"p": "Cool: 30 days minimum retention period."}, {"p": "Cold: 90 days minimum retention period."}, {"p": "Archive: 180 days minimum retention period."}, {"img": "az104/img/t4_image35.webp"}, {"p": "Since File1 was stored in the Hot tier, it incurs no early deletion penalty even if it is deleted within days of upload."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview", "https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview#early-deletion-charge"], "group": "G188"}, {"id": "T4-Q73", "test": 4, "num": 73, "domain": "storage", "stem": [{"p": "You have an Azure Storage account named storage1 that has the Blob service properties shown in the following exhibit."}, {"img": "az104/img/t4_image34.webp"}, {"p": "On January 1, the following blobs are uploaded to storage1:"}, {"p": "File1 is stored in the Hot access tier"}, {"p": "File2 is stored in the Cool access tier"}, {"p": "File3 is stored in the Archive access tier"}, {"p": "You then perform these actions:"}, {"p": "On January 5, File1 is deleted"}, {"p": "On January 15, File2 is moved to the Archive access tier"}, {"p": "On April 5, File3 is rehydrated"}, {"p": "True or False:"}, {"p": "“You are charged an early deletion penalty for File2.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer here. File2 was added on January 1 with the Cool access tier and was moved to the Archive access tier on January 15; just 14 days after it was created. The Cool tier has a minimum retention period of 30 days, meaning that if a blob is deleted, overwritten, or moved to another tier before 30 days, an early deletion penalty applies."}, {"p": "Since File2 was moved from Cool to Archive after 14 days, Azure will apply a prorated early deletion charge for 16 days (i.e., 30 - 14). This charge reflects the unused portion of the required minimum retention period in the Cool tier."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview"], "group": "G188"}, {"id": "T4-Q74", "test": 4, "num": 74, "domain": "storage", "stem": [{"p": "You have an Azure Storage account named storage1 that has the Blob service properties shown in the following exhibit."}, {"img": "az104/img/t4_image34.webp"}, {"p": "On January 1, the following blobs are uploaded to storage1:"}, {"p": "File1 is stored in the Hot access tier"}, {"p": "File2 is stored in the Cool access tier"}, {"p": "File3 is stored in the Archive access tier"}, {"p": "You then perform these actions:"}, {"p": "On January 5, File1 is deleted"}, {"p": "On January 15, File2 is moved to the Archive access tier"}, {"p": "On April 5, File3 is rehydrated"}, {"p": "True or False:"}, {"p": "“You are charged an early deletion penalty for File3.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer here. File3 was uploaded on January 1 and placed in the Archive access tier. It was then rehydrated (i.e., restored to an online tier such as Hot or Cool) on April 5, which is 94 days after it was archived."}, {"p": "The Archive tier has a minimum retention period of 180 days. If a blob is rehydrated, deleted, or moved before 180 days, Azure applies a prorated early deletion fee for the remaining days."}, {"p": "In this case, File3 remained in the Archive tier for only 94 days, so an early deletion charge equivalent to 86 days (180 - 94) will be incurred."}], "refs": ["https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview#early-deletion-charge"], "group": "G188"}, {"id": "T4-Q75", "test": 4, "num": 75, "domain": "network", "stem": [{"p": "You manage two Azure subscriptions named Subscription1 and Subscription2."}, {"p": "Subscription1 has the following virtual networks:"}, {"img": "az104/img/t4_image36.webp"}, {"p": "The virtual networks contain the following subnets:"}, {"img": "az104/img/t4_image37.webp"}, {"p": "Subscription 2 contains the following virtual network:"}, {"p": "Name: VNETA"}, {"p": "Address space: 10.10.128.0/17"}, {"p": "Location: Canada Central"}, {"p": "VNETA contains the following subnets:"}, {"img": "az104/img/t4_image38.webp"}, {"p": "True or False:"}, {"p": "“A Site-to-site connection can be established between VNET1 and VNET2.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer here. A Site-to-Site connection in Azure requires a gateway subnet to be present in each virtual network that participates in the connection. However, in this case, VNet1 uses the entire address space 10.10.10.0/24 for Subnet11, leaving no free IP range available to define a gateway subnet within VNet1."}, {"p": "Since Azure requires a dedicated subnet named GatewaySubnet with available IPs in the address space for a VPN gateway to function, and VNet1 does not have any spare address space, you cannot deploy a gateway there."}, {"p": "Because of this, a Site-to-Site connection cannot be established between VNet1 and VNet2, even though their address spaces do not overlap."}], "refs": ["https://learn.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-howto-site-to-site-resource-manager-portal", "https://learn.microsoft.com/en-us/azure/vpn-gateway/vpn-gateway-about-vpngateways", "https://learn.microsoft.com/en-us/azure/vpn-gateway/tutorial-site-to-site-portal"], "group": "G189"}, {"id": "T4-Q76", "test": 4, "num": 76, "domain": "network", "stem": [{"p": "You manage two Azure subscriptions named Subscription1 and Subscription2."}, {"p": "Subscription1 has the following virtual networks:"}, {"img": "az104/img/t4_image36.webp"}, {"p": "The virtual networks contain the following subnets:"}, {"img": "az104/img/t4_image37.webp"}, {"p": "Subscription 2 contains the following virtual network:"}, {"p": "Name: VNETA"}, {"p": "Address space: 10.10.128.0/17"}, {"p": "Location: Canada Central"}, {"p": "VNETA contains the following subnets:"}, {"img": "az104/img/t4_image38.webp"}, {"p": "True or False:"}, {"p": "“VNET1 and VNET2 can be peered.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer here. Azure virtual network peering supports connections between virtual networks under the following conditions:"}, {"p": "The address spaces of the VNets must not overlap"}, {"p": "The VNets can be in the same or different Azure regions"}, {"p": "The VNets can belong to the same or different subscriptions"}, {"p": "In this case:"}, {"p": "VNET1 has an address space of 10.10.10.0/24"}, {"p": "VNET2 has an address space of 172.16.0.0/16"}, {"p": "These address spaces do not overlap, which satisfies the IP requirement."}, {"p": "Additionally:"}, {"p": "VNET1 is located in West US"}, {"p": "VNET2 is located in West Europe"}, {"p": "Azure supports global virtual network peering, which allows peering between virtual networks in different Azure regions."}, {"p": "Therefore, VNET1 and VNET2 can be peered using global VNet peering, and no technical limitation prevents this configuration."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-manage-peering"], "group": "G189"}, {"id": "T4-Q77", "test": 4, "num": 77, "domain": "network", "stem": [{"p": "You manage two Azure subscriptions named Subscription1 and Subscription2."}, {"p": "Subscription1 has the following virtual networks:"}, {"img": "az104/img/t4_image36.webp"}, {"p": "The virtual networks contain the following subnets:"}, {"img": "az104/img/t4_image37.webp"}, {"p": "Subscription 2 contains the following virtual network:"}, {"p": "Name: VNETA"}, {"p": "Address space: 10.10.128.0/17"}, {"p": "Location: Canada Central"}, {"p": "VNETA contains the following subnets:"}, {"img": "az104/img/t4_image38.webp"}, {"p": "True or False:"}, {"p": "“VNET1 and VNETA can be peered.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is the correct answer here."}, {"p": "Azure allows peering between VNets as long as the following conditions are met:"}, {"p": "No overlapping address ranges"}, {"p": "VNets can be in the same or different subscriptions"}, {"p": "VNets can be in the same or different regions"}, {"p": "Since VNET1 and VNETA are in different regions but have non-overlapping IP ranges, they can be peered using global VNet peering."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-peering-overview", "https://learn.microsoft.com/en-us/azure/virtual-network/virtual-network-manage-peering"], "group": "G189"}, {"id": "T4-Q78", "test": 4, "num": 78, "domain": "network", "stem": [{"p": "You have an Azure virtual machine named VM1 that is connected to a virtual network called VNet1. VM1 has the following configuration:"}, {"p": "Subnet: 10.0.0.0/24"}, {"p": "Availability set: AVSet"}, {"p": "Network security group (NSG): None"}, {"p": "Private IP address: 10.0.0.4 (dynamic)"}, {"p": "Public IP address: 40.90.219.6 (dynamic)"}, {"p": "You deploy a Standard, internet-facing Azure Load Balancer named slb1."}, {"p": "You need to configure slb1 to allow inbound traffic to VM1, and you are permitted to make any required changes to VM1 during the configuration."}, {"p": "Complete the following statement:"}, {"p": "“Before creating a backend pool on slb1, you must ____________________.”"}], "options": ["Create and assign an NSG to VM1", "Remove the public IP address from VM1", "Change the private IP address of VM1 to static"], "correct": [1], "multi": false, "explanation": [{"p": "Remove the public IP address from VM1 is the correct answer here. When using a Standard, Internet-facing Azure Load Balancer, virtual machines that are part of the backend pool should not have individual public IP addresses assigned. Instead, all inbound traffic should be directed to the load balancer’s frontend public IP, and the load balancer will distribute that traffic to the VMs in the backend pool."}, {"p": "In this case, VM1 currently has a dynamic public IP address. For proper configuration with Standard SKU Load Balancer, this dynamic public IP should be removed, and the VM should receive traffic only through the load balancer. The Standard Load Balancer also requires a Standard SKU public IP to be assigned to its frontend configuration—not to the individual VM."}, {"p": "Create and assign an NSG to VM1 is incorrect because NSGs control traffic flow at the subnet or NIC level but are not required to add a VM to a Standard Load Balancer backend pool. While NSGs can be used for security, they are not relevant to this prerequisite."}, {"p": "Change the private IP address of VM1 to static is incorrect in this specific scenario because the VM is being added to a Standard Load Balancer in an Internet-facing configuration. In such cases, the VM’s private IP does not need to be static—only the load balancer’s public IP needs to be static and Standard SKU. The private IP requirement typically applies when the load balancer is internal, not Internet-facing."}], "refs": ["https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-standard-overview", "https://learn.microsoft.com/en-us/azure/load-balancer/quickstart-load-balancer-standard-public-portal", "https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-troubleshoot#vms-in-backend-pool-need-to-have-no-public-ip-or-use-standard-public-ip-only"], "group": "G190"}, {"id": "T4-Q79", "test": 4, "num": 79, "domain": "network", "stem": [{"p": "You have an Azure virtual machine named VM1 that is connected to a virtual network called VNet1. VM1 has the following configuration:"}, {"p": "Subnet: 10.0.0.0/24"}, {"p": "Availability set: AVSet"}, {"p": "Network security group (NSG): None"}, {"p": "Private IP address: 10.0.0.4 (dynamic)"}, {"p": "Public IP address: 40.90.219.6 (dynamic)"}, {"p": "You deploy a Standard, internet-facing Azure Load Balancer named slb1."}, {"p": "You need to configure slb1 to allow inbound traffic to VM1, and you are permitted to make any required changes to VM1 during the configuration."}, {"p": "Complete the following statement:"}, {"p": "“Before you can connect to VM1 from slb1, you must______________________.”"}], "options": ["Create and configure an NSG", "Remove the public IP address from VM1", "Change the private IP address of VM1 to static"], "correct": [0], "multi": false, "explanation": [{"p": "Create and configure an NSG is the correct answer here. In the context of an Internet-facing Standard Load Balancer, after configuring the load balancer and assigning a static, standard public IP to the frontend, you must ensure that traffic is allowed through to the VM. A Network Security Group (NSG) is required to define and permit inbound traffic (such as TCP on port 80 or 443) to the VM or subnet where the VM resides."}, {"p": "By default, no inbound traffic is allowed unless explicitly permitted via an NSG. Without an NSG rule allowing the required traffic, even if the frontend IP and backend pool are configured correctly, the connection to VM1 through slb1 would fail due to traffic being denied at the network layer."}, {"p": "Remove the public IP address from VM1 is incorrect because this step is only relevant if the VM had a dynamic public IP that conflicted with the Standard Load Balancer setup. Since the public IP has already been properly configured in the prior step, there's no need to remove it again. The focus now is on allowing traffic through to the VM, not modifying its IP configuration."}, {"p": "Change the private IP address of VM1 to static is incorrect because this is only required in the context of an internal load balancer or when backend pools rely on consistent internal addressing. For Internet-facing load balancers, private IP settings are not critical for enabling frontend communication. What’s essential is that the NSG allows the traffic to reach the backend VM."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-network/network-security-groups-overview", "https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-standard-overview", "https://learn.microsoft.com/en-us/azure/load-balancer/load-balancer-troubleshoot#ensure-nsgs-allow-traffic-to-vms-in-the-backend-pool"], "group": "G190"}, {"id": "T4-Q80", "test": 4, "num": 80, "domain": "monitor", "stem": [{"p": "You have an Azure virtual network named VNet1 that is connected to an on-premises network by using a site-to-site VPN. VNet1 includes a single subnet named Subnet1."}, {"p": "Subnet1 is associated with a network security group (NSG) called NSG1. The subnet hosts a basic internal load balancer named ILB1, which has three Azure virtual machines configured in its backend pool."}, {"p": "You need to collect information about the IP addresses that establish connections to ILB1. The collected data must be available for interactive querying directly from the Azure portal."}, {"p": "Which resource should you create to meet this requirement?"}], "options": ["An Azure Event Grid", "An Azure Log Analytics workspace", "An Azure Storage account"], "correct": [1], "multi": false, "explanation": [{"p": "An Azure Log Analytics workspace is the correct answer here. To collect and analyze data about incoming IP addresses connecting to resources like an internal load balancer (ILB1), and to run interactive queries via the Azure portal, the data must be sent to a Log Analytics workspace."}, {"p": "By enabling NSG flow logs on NSG1 (which is associated with Subnet1), you can capture information such as source and destination IP addresses, ports, protocols, and whether traffic was allowed or denied. These logs can be sent to a Log Analytics workspace, where they are indexed and made available for querying using Kusto Query Language (KQL)."}, {"p": "An Azure Event Grid is incorrect because it is used for event-based messaging and automation—not for storing or querying traffic flow data."}, {"p": "An Azure Storage account is incorrect in this context because although NSG flow logs can be stored in a storage account, you cannot run interactive queries on the data from the Azure portal unless the data is also sent to a Log Analytics workspace."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-monitor/logs/quick-create-workspace?tabs=azure-portal", "https://learn.microsoft.com/en-us/azure/azure-monitor/logs/log-analytics-workspace-overview", "https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-nsg-flow-logging-portal", "https://learn.microsoft.com/en-us/azure/event-grid/overview", "https://learn.microsoft.com/en-us/azure/storage/common/storage-introduction"], "group": "G191"}, {"id": "T4-Q81", "test": 4, "num": 81, "domain": "monitor", "stem": [{"p": "You have an Azure virtual network named VNet1 that is connected to an on-premises network by using a site-to-site VPN. VNet1 includes a single subnet named Subnet1."}, {"p": "Subnet1 is associated with a network security group (NSG) called NSG1. The subnet hosts a basic internal load balancer named ILB1, which has three Azure virtual machines configured in its backend pool."}, {"p": "You need to collect information about the IP addresses that establish connections to ILB1. The collected data must be available for interactive querying directly from the Azure portal."}, {"p": "On which resource should you enable diagnostics?"}], "options": ["ILB1", "NSG1", "The Azure virtual machines"], "correct": [1], "multi": false, "explanation": [{"p": "NSG1 is the correct answer here. To collect data about the IP addresses that connect to ILB1, you must monitor network traffic, and the correct way to do this in Azure is by enabling NSG flow logs on the Network Security Group (NSG) associated with the subnet or network interface."}, {"p": "In this case:"}, {"p": "NSG1 is associated with Subnet1, which contains ILB1 and its backend virtual machines."}, {"p": "Enabling diagnostic settings (NSG flow logs) on NSG1 captures detailed flow-level information such as source IP, destination IP, port, protocol, and action (allow/deny)."}, {"p": "The logs can be sent to a Log Analytics workspace, where you can run interactive queries using Kusto Query Language (KQL) directly from the Azure portal."}, {"p": "ILB1 is incorrect because while you can enable diagnostics on a load balancer, it captures metrics like health probe status and data throughput, not connection-level details like source IP addresses."}, {"p": "The Azure virtual machines is incorrect because enabling diagnostics on the VMs focuses on performance and system logs (e.g., CPU, disk, guest OS), but not on the network flow data you need for this scenario."}], "refs": ["https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-nsg-flow-logging-overview", "https://learn.microsoft.com/en-us/azure/network-watcher/network-watcher-nsg-flow-logging-portal"], "group": "G191"}, {"id": "T4-Q82", "test": 4, "num": 82, "domain": "compute", "stem": [{"p": "You manage an Azure subscription in which you create an Azure Container Registry (ACR) and build a container image locally."}, {"p": "You plan to upload the container image to the Azure Container Registry by using the Azure Command-Line Interface (CLI)."}, {"p": "After successfully signing in to the container registry, what should you do next to prepare the image for upload?"}], "options": ["Assign a tag to the container image that includes the container registry’s login server name.", "Display a list of container images that already exist in the container registry.", "Deploy a container group.", "Configure a YAML file."], "correct": [0], "multi": false, "explanation": [{"p": "Assign a tag to the container image that includes the container registry’s login server name is the correct answer here. After signing in to an Azure Container Registry (ACR), the next required step to push a container image is to tag the image using the registry’s login server URL. This tag identifies the destination registry and repository for the image. The format typically looks like:"}, {"p": "az acr login --name <registryName>"}, {"p": "docker tag <localImageName> <registryName>.azurecr.io/<repositoryName>:<tag>"}, {"p": "docker push <registryName>.azurecr.io/<repositoryName>:<tag>"}, {"p": "This step is necessary because Docker uses the tag to determine where the image should be pushed. Without tagging the image with the correct registry address, the docker push command will not know the target location."}, {"p": "Display a list of container images that already exist in the container registry is incorrect because it does not help in preparing an image for upload."}, {"p": "Deploy a container group is incorrect because this step would come after the image is already pushed and available in the container registry."}, {"p": "Configure a YAML file is incorrect because YAML files are typically used for defining deployments in Kubernetes or other orchestration platforms, not for pushing container images."}], "refs": ["https://learn.microsoft.com/en-us/azure/container-registry/container-registry-get-started-azure-cli", "https://learn.microsoft.com/en-us/azure/container-registry/container-registry-authentication"], "group": "G192"}, {"id": "T4-Q83", "test": 4, "num": 83, "domain": "compute", "stem": [{"p": "You have an application named App1 that will be deployed on two Azure virtual machines, VM1 and VM2."}, {"p": "You plan to use an Azure Availability Set for App1. The solution must ensure that App1 remains available when Azure performs planned maintenance on the physical hardware hosting VM1 and VM2."}, {"p": "What configuration should you include when creating the Availability Set?"}], "options": ["one update domain", "two update domains", "one fault domain", "two fault domains"], "correct": [1], "multi": false, "explanation": [{"p": "two update domains is the correct answer here. Update domains in an Availability Set ensure that not all virtual machines are rebooted at the same time during planned maintenance events, such as OS patching or Azure platform updates. By placing VM1 and VM2 in two separate update domains, Azure ensures that only one VM is rebooted at a time, keeping App1 available during maintenance."}, {"p": "This satisfies the requirement to maintain availability of App1 during planned maintenance, which is exactly what update domains are designed to protect against."}, {"img": "az104/img/t4_image39.webp"}, {"p": "one update domain is incorrect because placing both VMs in the same update domain would allow both to be rebooted simultaneously during planned maintenance, causing downtime for App1."}, {"p": "one fault domain and two fault domains are incorrect in this context because fault domains deal with unplanned hardware failures, not planned maintenance. While fault domains enhance resilience to physical failures, they do not ensure availability during platform maintenance activities."}], "refs": ["https://learn.microsoft.com/en-us/azure/virtual-machines/availability-set-overview", "https://learn.microsoft.com/en-us/azure/virtual-machines/availability"], "group": "G193"}, {"id": "T4-Q84", "test": 4, "num": 84, "domain": "monitor", "stem": [{"p": "You have an Azure subscription that includes an Azure Storage account named storage1."}, {"p": "The subscription has the following users and group memberships:"}, {"p": "User1 is a member of Group1."}, {"p": "User2 is a member of Group2."}, {"p": "User3 is a member of Group1."}, {"p": "You plan to monitor storage1 and configure email notifications for specific monitoring signals."}, {"p": "The notification requirements are as follows:"}, {"img": "az104/img/t4_image40.webp"}], "options": ["How many Alert rules are required to meet all the monitoring and notification requirements.", "1", "2", "3", "4"], "correct": [4], "multi": false, "explanation": [{"p": "4 is correct. Four alert rules are required because alert rules are based on unique combinations of signal type (Metric vs. Activity log) and conditions."}, {"p": "Here we have 4 different signals, so each rule will monitor a distinct event."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview", "https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/action-groups"], "group": "G194"}, {"id": "T4-Q85", "test": 4, "num": 85, "domain": "monitor", "stem": [{"p": "You have an Azure subscription that includes an Azure Storage account named storage1."}, {"p": "The subscription has the following users and group memberships:"}, {"p": "User1 is a member of Group1."}, {"p": "User2 is a member of Group2."}, {"p": "User3 is a member of Group1."}, {"p": "You plan to monitor storage1 and configure email notifications for specific monitoring signals."}, {"p": "The notification requirements are as follows:"}, {"img": "az104/img/t4_image40.webp"}], "options": ["How many Action groups are required to meet all the monitoring and notification requirements.", "1", "2", "3", "4"], "correct": [3], "multi": false, "explanation": [{"p": "3 is correct. An Action Group defines who gets notified and how. You need a separate Action Group only when the set of recipients (users) is different. Looking at the notification requirements:"}, {"p": "Ingress: Notifies User1 and User3 - Action Group 1"}, {"p": "Egress: Notifies User1 only - Action Group 2"}, {"p": "Delete storage account: Notifies User1, User2, and User3 - Action Group 3"}, {"p": "Restore blob ranges: Notifies User1 and User3 - Same as Ingress - reuse Action Group 1"}, {"p": "So, only three distinct sets of recipients, hence 3 Action Groups are required."}], "refs": ["https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/action-groups", "https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview"], "group": "G194"}, {"id": "T4-Q86", "test": 4, "num": 86, "domain": "monitor", "stem": [{"p": "You manage two Azure App Service apps named App1 and App2. Each app contains:"}, {"p": "A production deployment slot"}, {"p": "A test deployment slot"}, {"p": "The backup settings for the production slots are configured as follows:"}, {"p": "App1"}, {"p": "Backup frequency: Every 1 day"}, {"p": "Schedule start date: January 6, 2024"}, {"p": "Retention period: 0 days"}, {"p": "Keep at least one backup: Yes"}, {"p": "App2"}, {"p": "Backup frequency: Every 1 day"}, {"p": "Schedule start date: January 6, 2024"}, {"p": "Retention period: 30 days"}, {"p": "Keep at least one backup: Yes"}, {"p": "Based on this configuration, determine the effect of the backup and retention settings."}, {"p": "True or False:"}, {"p": "“On January 15, 2024, App1 will have only one backup in storage.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer because the backup configuration for App1 specifies a retention period of 0 days with “Keep at least one backup” set to Yes. In Azure App Service, setting the retention to 0 means backups are retained indefinitely unless manually deleted. Additionally, the “keep at least one backup” option ensures that even if retention policies are applied, at least one backup is preserved."}, {"p": "Since App1 is backed up daily starting from January 6, 2024, by January 15, 2024, there would be multiple backups retained unless manually removed. Therefore, App1 would not have only one backup in storage on that date."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/manage-backup", "https://learn.microsoft.com/en-us/cli/azure/webapp/config/backup?view=azure-cli-latest"], "group": "G195"}, {"id": "T4-Q87", "test": 4, "num": 87, "domain": "monitor", "stem": [{"p": "You manage two Azure App Service apps named App1 and App2. Each app contains:"}, {"p": "A production deployment slot"}, {"p": "A test deployment slot"}, {"p": "The backup settings for the production slots are configured as follows:"}, {"p": "App1"}, {"p": "Backup frequency: Every 1 day"}, {"p": "Schedule start date: January 6, 2024"}, {"p": "Retention period: 0 days"}, {"p": "Keep at least one backup: Yes"}, {"p": "App2"}, {"p": "Backup frequency: Every 1 day"}, {"p": "Schedule start date: January 6, 2024"}, {"p": "Retention period: 30 days"}, {"p": "Keep at least one backup: Yes"}, {"p": "Based on this configuration, determine the effect of the backup and retention settings."}, {"p": "True or False:"}, {"p": "“On February 6, 2024, you can access the backup of the App2 test slot from January 15, 2024.”"}], "options": ["True", "False"], "correct": [1], "multi": false, "explanation": [{"p": "False is the correct answer because the backup configuration applies only to the production slot of App2, not the test slot. The table provided shows backup settings for the production slots of App1 and App2, and there is no mention of backups being configured for the test slot of App2."}, {"p": "Since Azure App Service does not automatically back up deployment slots other than the production slot unless explicitly configured, no backup of the App2 test slot from January 15, 2024 would exist by February 6, 2024."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/manage-backup", "https://learn.microsoft.com/en-us/azure/app-service/deploy-staging-slots"], "group": "G195"}, {"id": "T4-Q88", "test": 4, "num": 88, "domain": "monitor", "stem": [{"p": "You manage two Azure App Service apps named App1 and App2. Each app contains:"}, {"p": "A production deployment slot"}, {"p": "A test deployment slot"}, {"p": "The backup settings for the production slots are configured as follows:"}, {"p": "App1"}, {"p": "Backup frequency: Every 1 day"}, {"p": "Schedule start date: January 6, 2024"}, {"p": "Retention period: 0 days"}, {"p": "Keep at least one backup: Yes"}, {"p": "App2"}, {"p": "Backup frequency: Every 1 day"}, {"p": "Schedule start date: January 6, 2024"}, {"p": "Retention period: 30 days"}, {"p": "Keep at least one backup: Yes"}, {"p": "Based on this configuration, determine the effect of the backup and retention settings."}, {"p": "True or False:"}, {"p": "“On January 15, 2024, you can restore the App2 production slot backup from January 6 to the App2 test slot.”"}], "options": ["True", "False"], "correct": [0], "multi": false, "explanation": [{"p": "True is correct  because Azure App Service allows you to restore a backup taken from the production slot to any other slot of the same app, including a test slot. The backup of the App2 production slot from January 6, 2024 would still be available on January 15, 2024 because the retention policy is set to 30 days and the \"Keep at least one backup\" option is enabled."}, {"p": "This means that the backup from January 6 is retained and can be used to restore not only to the production slot but also to the test slot, assuming the restore operation is initiated within the retention period."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/manage-backup#restore-an-app", "https://learn.microsoft.com/en-us/azure/app-service/web-sites-staged-publishing"], "group": "G195"}, {"id": "T4-Q89", "test": 4, "num": 89, "domain": "compute", "stem": [{"p": "You are creating an Azure Resource Manager (ARM) template (shown below) that performs the following actions:"}, {"p": "Creates a new resource group."}, {"p": "Deploys an Azure Storage account into that resource group by using a nested deployment."}, {"p": "{"}, {"p": "\"$schema\": \"https://schema.management.azure.com/schemas/2023-04-01/deploymentTemplate.json#\","}, {"p": "\"contentVersion\": \"1.0.0.0\","}, {"p": "\"resources\": ["}, {"p": "{"}, {"p": "\"type\": \"Microsoft.Resources/resourceGroups\","}, {"p": "\"apiVersion\": \"2025-11-01\","}, {"p": "\"location\": \"eastus\","}, {"p": "\"name\": \"RG1\""}, {"p": "},"}, {"p": "{"}, {"p": "\"type\": \"Microsoft.Resources/deployments\","}, {"p": "\"apiVersion\": \"2025-11-01\","}, {"p": "\"name\": \"storageDeployment\","}, {"p": "\"resourceGroup\": \"RG1\","}, {"p": "\"dependsOn\": ["}, {"p": "\"[resourceId('Microsoft.Resources/resourceGroups/', 'RG1')]\""}, {"p": "],"}, {"p": "\"properties\": {"}, {"p": "\"mode\": \"Incremental\","}, {"p": "\"template\": {"}, {"p": "\"$schema\": \"https://schema.management.azure.com/schemas/2015-01-01/deploymentTemplate.json#\","}, {"p": "\"contentVersion\": \"1.0.0.0\","}, {"p": "\"resources\": ["}, {"p": "{"}, {"p": "\"type\": \"Microsoft.Storage/storageAccounts\","}, {"p": "\"apiVersion\": \"2025-05-01\","}, {"p": "\"name\": \"storage1\","}, {"p": "\"location\": \"eastus\","}, {"p": "\"kind\": \"StorageV2\","}, {"p": "\"sku\": {"}, {"p": "\"name\": \"Standard_LRS\""}, {"p": "}"}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "}"}, {"p": "}"}, {"p": "]"}, {"p": "}"}, {"p": "Which PowerShell cmdlet should you run to deploy the template?"}], "options": ["New-AzDeployment", "New-AzResource", "New-AzResourceGroupDeployment", "New-AzTenantDeployment"], "correct": [0], "multi": false, "explanation": [{"p": "New-AzDeployment is the correct cmdlet to use when your ARM template includes a nested deployment of a resource group, as shown in the image. This cmdlet allows you to deploy resources at the subscription level, which is necessary here because the template first creates a resource group (RG1) and then deploys a storage account into that group."}, {"p": "The nested deployment structure in the ARM template includes:"}, {"p": "A Microsoft.Resources/resourceGroups resource to create the resource group."}, {"p": "A Microsoft.Resources/deployments resource that deploys the storage account into the newly created group using a nested template."}, {"p": "Since the deployment targets multiple scopes (subscription and resource group), you must use a subscription-level deployment cmdlet like New-AzDeployment."}, {"p": "New-AzResourceGroupDeployment is incorrect because it's used to deploy resources within an existing resource group. It cannot be used when your template includes the creation of a new resource group."}, {"p": "New-AzSubscriptionDeployment is an alias for New-AzDeployment, but the preferred cmdlet name is New-AzDeployment, which works consistently across all scopes in newer versions of the Az PowerShell module."}], "refs": ["https://learn.microsoft.com/en-us/powershell/module/az.resources/new-azdeployment", "https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/deploy-to-subscription"], "group": "G196"}, {"id": "T4-Q90", "test": 4, "num": 90, "domain": "compute", "stem": [{"p": "You have an Azure subscription that includes a web app named webapp1."}, {"p": "You want to associate a custom domain, www.apexcore.com, with webapp1."}, {"p": "Before you can complete the custom domain configuration, what is the first action you must take?"}], "options": ["Upload a certificate.", "Stop webapp1.", "Create a DNS record.", "Add a connection string."], "correct": [2], "multi": false, "explanation": [{"p": "Create a DNS record is the correct answer because before you can map a custom domain (like www.apexcore.com) to an Azure Web App (e.g., webapp1), you must prove ownership of the domain. This is done by creating a CNAME or A record in the public DNS zone for the domain, pointing to the web app's default Azure domain (e.g., webapp1.azurewebsites.net). This step allows Azure to validate that you control the domain name."}, {"p": "Upload a certificate is incorrect because uploading an SSL certificate is only required if you plan to enable HTTPS for the custom domain. It’s not required as the first step in domain assignment."}, {"p": "Stop webapp1 is incorrect because there's no need to stop the app when adding or validating a custom domain. The app can stay running throughout the process."}, {"p": "Add a connection string is incorrect because this relates to configuring access to backend services like databases. It has nothing to do with custom domain configuration."}], "refs": ["https://learn.microsoft.com/en-us/azure/app-service/app-service-web-tutorial-custom-domain", "https://learn.microsoft.com/en-us/Azure/app-service/app-service-web-tutorial-custom-domain?tabs=root%2Cazurecli"], "group": "G197"}]};
